/* 자동 생성: tools/build_towns_q.js — 직접 수정하지 마세요.
 * 마을 2~10 문제 (PCIe 7.0 / CXL 4.0 전문가 의역 문제). 형식:
 * [id, rule, 난이도, tag(P=PCIe X=CXL C=공통), q.ko, q.en, choices.ko[4], choices.en[4], answer, expl.ko, expl.en, ref] */
var TOWN_Q = {"2":[["p2q01","p2_1",1,"C","PAM4가 의미하는 시그널링은 무엇이며, 어느 Data Rate에서 쓰이나?","What does PAM4 signaling mean, and at which data rates is it used?",["Pulse Amplitude Modulation 4-levels: 한 UI에 4개 전압 레벨(2 bit)을 실어 3개의 eye가 생기며, 64.0 GT/s 이상에서만 사용한다.","Pulse Amplitude Modulation 4-levels: 한 UI에 4개 전압 레벨을 실으나, 32.0 GT/s Non-Flit Mode에서도 사용한다.","Phase Amplitude Modulation 4-levels: 위상 4단계를 쓰며 8.0 GT/s부터 사용한다.","Pulse Amplitude Modulation 4-levels: NRZ와 동일하게 레벨 2개만 쓰고, 64.0 GT/s에서 선택 사항이다."],["Pulse Amplitude Modulation 4-levels: 4 voltage levels (2 bits) are encoded in the same UI, resulting in 3 eyes, and it is deployed only for 64.0 GT/s or higher data rates.","Pulse Amplitude Modulation 4-levels: 4 voltage levels per UI, but it is also used in 32.0 GT/s Non-Flit Mode.","Phase Amplitude Modulation 4-levels: four phase steps, used from 8.0 GT/s upward.","Pulse Amplitude Modulation 4-levels: still only two levels like NRZ, and optional at 64.0 GT/s."],0,"정답 요지: Pulse Amplitude Modulation 4-levels: 한 UI에 4개 전압 레벨(2 bit)을 실어 3개의 eye가 생기며, 64.0 GT/s 이상에서만 사용한다.","Key point: Pulse Amplitude Modulation 4-levels: 4 voltage levels (2 bits) are encoded in the same UI, resulting in 3 eyes, and it is deployed only for 64.0 GT/s or higher data rates.","§4.2.3.1.1"],["p2q02","p2_1",2,"C","64.0 GT/s PAM4의 Nyquist 주파수는 32.0 GT/s NRZ와 비교해 어떤가?","How does the Nyquist frequency of 64.0 GT/s PAM4 compare with 32.0 GT/s NRZ?",["64.0 GT/s PAM4가 두 배인 32 GHz이다.","64.0 GT/s PAM4가 절반인 8 GHz이다.","같다. 둘 다 16 GHz이다 (PAM4가 NRZ의 절반 Nyquist를 갖기 때문).","비교할 수 없다. Nyquist는 PAM4에 정의되지 않는다."],["64.0 GT/s PAM4 is twice as high, at 32 GHz.","64.0 GT/s PAM4 is half as high, at 8 GHz.","They are the same: both are 16 GHz, because PAM4 has half the Nyquist frequency of NRZ.","They cannot be compared; Nyquist is not defined for PAM4."],2,"정답 요지: 같다. 둘 다 16 GHz이다 (PAM4가 NRZ의 절반 Nyquist를 갖기 때문).","Key point: They are the same: both are 16 GHz, because PAM4 has half the Nyquist frequency of NRZ.","§4.2.3.1.1"],["p2q03","p2_1",2,"C","PAM4 전압 레벨 0, 1, 2, 3에 대응하는 Gray code (little-endian)는?","What Gray-code values (little-endian) correspond to PAM4 voltage levels 0, 1, 2, and 3?",["각각 00b, 01b, 10b, 11b (일반 이진 코드)","각각 00b, 01b, 11b, 10b","각각 00b, 10b, 11b, 01b","각각 11b, 10b, 01b, 00b"],["00b, 01b, 10b, and 11b respectively (ordinary binary)","00b, 01b, 11b, and 10b respectively","00b, 10b, 11b, and 01b respectively","11b, 10b, 01b, and 00b respectively"],1,"표준은 레벨 0, 1, 2, 3이 공칭 -400/-133/+133/+400 mV에 대응하고, Gray code는 각각 00b, 01b, 11b, 10b라고 한다. 인접 레벨이 1 bit만 달라진다.","Levels 0, 1, 2, and 3 nominally map to −400/−133/+133/+400 mV and to Gray codes 00b, 01b, 11b, and 10b. Adjacent levels differ by only one bit.","§4.2.3.1.1"],["p2q04","p2_1",3,"C","1b/1b에서 Symbol ‘S7S6S5S4S3S2S1S0’을 Lane에 실을 때 전송 순서는?","In 1b/1b encoding, in what order is a Symbol ‘S7S6S5S4S3S2S1S0’ placed on a Lane?",["128b/130b와 같이 ‘S0’부터 시작해 ‘S7’로 끝난다.","MSB인 ‘S7S6’부터 시작해 ‘S1S0’으로 끝난다.","Byte 단위로만 정의되고 UI 순서는 구현 의존이다.","전압 인코딩 ‘S1S0’부터 시작해 ‘S7S6’으로 끝난다 (2-bit aligned, PAM4)."],["As in 128b/130b, it starts with ‘S0’ and ends with ‘S7’.","It starts with the MSB pair ‘S7S6’ and ends with ‘S1S0’.","Only the byte order is defined; UI order is implementation-specific.","It starts with the voltage encoding of ‘S1S0’ and ends with ‘S7S6’ (2-bit aligned PAM4)."],3,"정답 요지: 전압 인코딩 ‘S1S0’부터 시작해 ‘S7S6’으로 끝난다 (2-bit aligned, PAM4).","Key point: It starts with the voltage encoding of ‘S1S0’ and ends with ‘S7S6’ (2-bit aligned PAM4).","§4.2.3.1"],["p2q05","p2_1",2,"C","64.0 GT/s 이상에서 Tx 경로의 처리 순서로 올바른 것은?","At 64.0 GT/s and higher, which Transmit-side processing order is correct?",["Gray Coding → Scrambling → Precoding → PAM4 전압 변환","Precoding → Gray Coding → Scrambling → PAM4 전압 변환","Scrambling → Gray Coding (스크램블된 2-bit) → Precoding(enabled인 경우) → PAM4 전압 변환","Scrambling → Precoding → Gray Coding → PAM4 전압 변환"],["Gray coding, then scrambling, then precoding, then PAM4 voltage translation","Precoding, then Gray coding, then scrambling, then PAM4 voltage translation","Scrambling, then Gray coding of scrambled 2-bit pairs, then precoding (if enabled), then PAM4 voltage translation","Scrambling, then precoding, then Gray coding, then PAM4 voltage translation"],2,"정답 요지: Scrambling → Gray Coding (스크램블된 2-bit) → Precoding(enabled인 경우) → PAM4 전압 변환","Key point: Scrambling, then Gray coding of scrambled 2-bit pairs, then precoding (if enabled), then PAM4 voltage translation","§4.2.3.1.3"],["p2q06","p2_2",1,"C","64.0 GT/s 및 128.0 GT/s에서 허용되는 Encoding과 Data Stream mode는?","What encoding and Data Stream mode are valid at 64.0 GT/s and 128.0 GT/s?",["1b/1b Encoding, Flit Mode (mandatory)","128b/130b Encoding, Flit Mode 또는 Non-Flit Mode","1b/1b Encoding, Non-Flit Mode도 선택 가능","8b/10b Encoding, Flit Mode"],["1b/1b encoding and Flit Mode (mandatory)","128b/130b encoding, with either Flit Mode or Non-Flit Mode","1b/1b encoding, with Non-Flit Mode also permitted","8b/10b encoding and Flit Mode"],0,"Table 4-1에서 64.0/128.0 GT/s는 Flit Mode Negotiated가 “Yes (mandatory)”, Encoding 1b/1b, Data Stream이 Flit Mode이다.","Table 4-1 lists 64.0 and 128.0 GT/s with Flit Mode Negotiated = Yes (mandatory), encoding 1b/1b, and Data Stream = Flit Mode.","§4.2, Table 4-1"],["p2q07","p2_2",2,"P","2.5 GT/s 또는 5.0 GT/s에서도 Flit Mode로 동작할 수 있는가?","Can a Link operate in Flit Mode at 2.5 GT/s or 5.0 GT/s?",["불가능하다. Flit Mode는 64.0 GT/s 이상에서만 허용된다.","불가능하다. Flit Mode는 8.0 GT/s 이상에서만 허용된다.","가능하지만 그 경우 Encoding은 1b/1b로 바뀐다.","가능하다. 이 속도에서는 8b/10b Encoding을 쓰며, Flit Mode와 Non-Flit Mode가 모두 Table 4-1에 정의되어 있다."],["No. Flit Mode is allowed only at 64.0 GT/s and above.","No. Flit Mode is allowed only at 8.0 GT/s and above.","Yes, but the encoding then changes to 1b/1b.","Yes. Those rates still use 8b/10b encoding, and Table 4-1 lists both Flit Mode and Non-Flit Mode."],3,"Table 4-1은 2.5/5.0 GT/s에 대해 Flit Mode Negotiated No→8b/10b Non-Flit, Yes→8b/10b Flit을 모두 나열한다. Flit Mode는 “Gen6 전용”이 아니다.","Table 4-1 lists both 8b/10b Non-Flit and 8b/10b Flit combinations at 2.5 and 5.0 GT/s. Flit Mode is not Gen6-only.","§4.2, Table 4-1"],["p2q08","p2_2",1,"C","8.0, 16.0, 32.0 GT/s에서 쓰는 Lane-level Encoding은 Flit Mode 여부에 따라 어떻게 달라지나?","At 8.0, 16.0, and 32.0 GT/s, does Flit Mode change the lane-level encoding?",["Flit Mode이면 1b/1b, Non-Flit Mode이면 128b/130b이다.","달라지지 않는다. 두 모드 모두 128b/130b Encoding을 쓴다.","Flit Mode이면 8b/10b를 유지한다.","32.0 GT/s Flit Mode만 1b/1b이고 8.0/16.0은 항상 128b/130b이다."],["Flit Mode uses 1b/1b; Non-Flit Mode uses 128b/130b.","It does not change: both modes use 128b/130b encoding.","Flit Mode keeps 8b/10b.","Only 32.0 GT/s Flit Mode uses 1b/1b; 8.0 and 16.0 GT/s always use 128b/130b."],1,"Table 4-1에서 8.0/16.0/32.0 GT/s는 Flit 협상 여부와 관계없이 Encoding이 128b/130b이고, Data Stream만 Non-Flit 또는 Flit으로 갈린다. 1b/1b는 64.0 GT/s 이상이다.","Table 4-1 uses 128b/130b at 8.0/16.0/32.0 GT/s regardless of whether Flit Mode is negotiated; only the Data Stream mode changes. 1b/1b is for 64.0 GT/s and above.","§4.2, Table 4-1"],["p2q09","p2_2",2,"C","128b/130b에서 Sync Header 10b와 01b는 각각 무엇을 나타내는가?","In 128b/130b encoding, what do Sync Headers 10b and 01b indicate?",["10b는 Ordered Set Block, 01b는 Data Block이다.","10b는 Data Block, 01b는 Ordered Set Block이다. 00b와 11b는 유효하지 않다.","둘 다 Data Block이며, Ordered Set는 Sync Header가 없다.","01b는 Data Block, 10b는 SKP 전용이다. TS OS는 00b를 쓴다."],["10b indicates an Ordered Set Block and 01b a Data Block.","10b indicates a Data Block and 01b an Ordered Set Block. 00b and 11b are not valid Sync Headers.","Both indicate Data Blocks; Ordered Sets have no Sync Header.","01b indicates a Data Block and 10b is only for SKP; TS Ordered Sets use 00b."],1,"정답 요지: 10b는 Data Block, 01b는 Ordered Set Block이다. 00b와 11b는 유효하지 않다.","Key point: 10b indicates a Data Block and 01b an Ordered Set Block. 00b and 11b are not valid Sync Headers.","§4.2.2.1"],["p2q10","p2_2",1,"C","8.0 GT/s 이상으로 올리기 전, Link는 어떤 속도와 Encoding으로 먼저 L0까지 훈련하는가?","Before changing to 8.0 GT/s or higher, how does the Link first train to L0?",["지원하는 최고 속도로 바로 훈련한다.","5.0 GT/s, 8b/10b로 먼저 훈련한다.","Flit Mode가 협상되면 처음부터 1b/1b로 훈련한다.","항상 2.5 GT/s, 8b/10b Encoding으로 L0까지 간 뒤 속도를 바꾼다."],["It trains immediately at the highest supported data rate.","It first trains at 5.0 GT/s with 8b/10b encoding.","If Flit Mode is negotiated, it trains from the start with 1b/1b encoding.","It always first trains to L0 at 2.5 GT/s using 8b/10b encoding, then changes data rate."],3,"정답 요지: 항상 2.5 GT/s, 8b/10b Encoding으로 L0까지 간 뒤 속도를 바꾼다.","Key point: It always first trains to L0 at 2.5 GT/s using 8b/10b encoding, then changes data rate.","§4.2.2"],["p2q11","p2_3",1,"P","Flit Mode에서 한 Flit의 크기와 Byte 할당은?","In Flit Mode, what is the size of a Flit and how are its bytes allocated?",["256 Bytes: TLP 236 (Bytes 0–235), DLP 6 (236–241), CRC 8 (242–249), ECC 6 (250–255).","256 Bytes: TLP 242, DLP 8, CRC 6, ECC 0 (FEC는 별도 Block).","248 Bytes: TLP 236, DLP 4, CRC 4, ECC 4.","130 Bits의 Data Block과 동일하며, Flit 크기는 Link width에 따라 변한다."],["256 bytes: 236 TLP (bytes 0–235), 6 DLP (236–241), 8 CRC (242–249), and 6 ECC (250–255).","256 bytes: 242 TLP, 8 DLP, 6 CRC, and no ECC (FEC is a separate block).","248 bytes: 236 TLP, 4 DLP, 4 CRC, and 4 ECC.","It equals a 130-bit Data Block, and Flit size varies with Link width."],0,"정답 요지: 256 Bytes: TLP 236 (Bytes 0–235), DLP 6 (236–241), CRC 8 (242–249), ECC 6 (250–255).","Key point: 256 bytes: 236 TLP (bytes 0–235), 6 DLP (236–241), 8 CRC (242–249), and 6 ECC (250–255).","§4.2.3.3"],["p2q12","p2_3",1,"C","Flit은 여러 Lane에 어떻게 배치되는가?","How is a Flit placed across the Lanes of a Link?",["한 Flit 전체가 한 Lane에 실리고, 다음 Flit이 다음 Lane에 실린다.","bit 단위로 라운드로빈하며, Byte 경계는 보장되지 않는다.","Byte aligned 방식으로 Lane들에 interleave(stripe)된다.","x16에서만 interleave되고, x1/x2/x4/x8에서는 한 Lane에 연속 배치된다."],["An entire Flit is placed on one Lane, then the next Flit on the next Lane.","It is bit-wise round-robin, and byte alignment is not guaranteed.","It is interleaved across the Lanes in a byte-aligned fashion.","It is interleaved only on x16; on x1/x2/x4/x8 a Flit occupies one Lane contiguously."],2,"정답 요지: Byte aligned 방식으로 Lane들에 interleave(stripe)된다.","Key point: It is interleaved across the Lanes in a byte-aligned fashion.","§4.2.3.3"],["p2q13","p2_3",2,"P","Table 4-16이 정의하는 세 가지 Flit Type은?","What three Flit Types does Table 4-16 define?",["Ack Flit, Nak Flit, Data Flit","SOP Flit, EOP Flit, Idle Flit","TLP Flit, DLLP Flit, Ordered Set Flit","IDLE Flit, NOP Flit, Payload Flit"],["Ack Flit, Nak Flit, and Data Flit","SOP Flit, EOP Flit, and Idle Flit","TLP Flit, DLLP Flit, and Ordered Set Flit","IDLE Flit, NOP Flit, and Payload Flit"],3,"정답 요지: IDLE Flit, NOP Flit, Payload Flit","Key point: IDLE Flit, NOP Flit, and Payload Flit","§4.2.3.4.2, Table 4-16"],["p2q14","p2_3",2,"P","IDLE Flit의 TLP Bytes와 DLP 핵심 필드 값은?","What values must an IDLE Flit use in its TLP bytes and key DLP fields?",["TLP Bytes는 Logical Idle Token(IDL)으로 채워지고 Sequence Number는 1부터 증가한다.","TLP 236 Byte는 모두 00h, DLP Bytes 0,1도 00h (Flit Usage 00b, Sequence Number 0, Replay Command 00b), DLP 2..5는 NOP2 DLLP.","TLP Bytes는 don’t care이고 Flit Usage만 00b이면 된다.","IDLE Flit은 TLP 대신 Ordered Set을 실으며 DLP는 생략된다."],["The TLP bytes are filled with Logical Idle (IDL) Tokens and the Sequence Number increments from 1.","All 236 TLP bytes are 00h, DLP bytes 0 and 1 are 00h (Flit Usage 00b, Sequence Number 0, Replay Command 00b), and DLP bytes 2..5 carry a NOP2 DLLP.","TLP bytes are don’t-care; only Flit Usage must be 00b.","An IDLE Flit carries Ordered Sets instead of TLP bytes, and the DLP is omitted."],1,"Table 4-16과 본문은 IDLE Flit을 Flit Usage 00b, Sequence Number 0, Replay Command 00b로 정의하고, Transmitter는 TLP 236 Byte와 DLP 0,1에 00h를, DLP 2..5에 NOP2를 넣어야 한다.","Table 4-16 and the accompanying text define an IDLE Flit as Flit Usage 00b, Sequence Number 0, and Replay Command 00b; transmitters must place 00h in all 236 TLP bytes and in DLP bytes 0 and 1, with a NOP2 DLLP in DLP 2..5.","§4.2.3.4.2, Table 4-16"],["p2q15","p2_3",2,"C","128b/130b 또는 1b/1b에서 Data Stream의 Flit 경계는 언제 시작하나?","With 128b/130b or 1b/1b encoding, when does the Flit boundary of a Data Stream start?",["SDS Ordered Set의 첫 Symbol부터.","EIEOS를 수신한 즉시 (Aligned Phase 진입 시).","SDS Ordered Set 다음의 Control SKP Ordered Set이 끝난 직후.","첫 Payload Flit의 STP Token을 본 이후."],["From the first Symbol of the SDS Ordered Set.","As soon as an EIEOS is received (entry to the Aligned Phase).","Immediately after the Control SKP Ordered Set that follows the SDS Ordered Set.","After the STP Token of the first Payload Flit is observed."],2,"정답 요지: SDS Ordered Set 다음의 Control SKP Ordered Set이 끝난 직후.","Key point: Immediately after the Control SKP Ordered Set that follows the SDS Ordered Set.","§4.2.3.1.6, §4.2.3.4.2"],["p2q16","p2_4",1,"C","Flit FEC(ECC)의 기본 구조는?","What is the basic structure of Flit FEC (ECC)?",["3-way interleaved ECC이며, 각 ECC code는 1 Byte 오류를 정정할 수 있다.","단일 Reed-Solomon codeword가 Flit 전체의 최대 6 Byte를 정정한다.","Lane마다 독립적인 parity bit 1개만 붙는다.","CRC 8 Byte가 FEC를 겸하므로 별도 ECC는 없다."],["It is a 3-way interleaved ECC, and each ECC code can correct a single-byte error.","A single Reed-Solomon codeword can correct up to 6 bytes across the whole Flit.","Each Lane gets only one independent parity bit.","The 8-byte CRC also serves as FEC, so there is no separate ECC."],0,"정답 요지: 3-way interleaved ECC이며, 각 ECC code는 1 Byte 오류를 정정할 수 있다.","Key point: It is a 3-way interleaved ECC, and each ECC code can correct a single-byte error.","§4.2.3.3"],["p2q17","p2_4",2,"C","FEC interleaving이 보장하려는 버스트 오류 내성은?","What burst-error immunity is the FEC interleaving designed to provide?",["어느 Lane에서든 길이 16 bit 이하의 버스트가 각 interleaved ECC code word에서 1 Byte를 초과해 손상하지 않는다.","어느 Lane에서든 길이 8 bit(1 Symbol) 버스트만 정정 가능하다.","Link 전체에서 동시에 최대 3 Lane의 임의 오류를 정정한다.","32 UI 버스트까지 각 code word에서 2 Byte를 정정한다."],["A burst of length ≤ 16 bits on any Lane is guaranteed not to affect more than one byte in each interleaved ECC code word.","Only an 8-bit (1 Symbol) burst on a Lane can be corrected.","Arbitrary errors on up to 3 Lanes at once can be corrected.","A burst of up to 32 UI can have 2 bytes corrected in each code word."],0,"정답 요지: 어느 Lane에서든 길이 16 bit 이하의 버스트가 각 interleaved ECC code word에서 1 Byte를 초과해 손상하지 않는다.","Key point: A burst of length ≤ 16 bits on any Lane is guaranteed not to affect more than one byte in each interleaved ECC code word.","§4.2.3.3, §4.2.3.4.5"],["p2q18","p2_4",2,"C","6 Byte ECC가 보호하는 범위와, 낮은 Data Rate에서의 사용은?","What does the 6-byte ECC protect, and is it used at data rates below 64.0 GT/s?",["TLP Bytes만 보호하며, 8.0 GT/s 이상에서만 사용한다.","DLP와 CRC만 보호하며, 2.5/5.0 GT/s에서는 생략된다.","Flit 전체(CRC 포함)를 보호하며, PAM4의 높은 FBER 때문에 64.0 GT/s 이상에서만 필요하지만 일관성을 위해 낮은 속도에서도 사용한다.","ECC는 64.0 GT/s 이상에서만 존재하고, 그 아래 Flit에는 CRC만 있다."],["It protects only TLP bytes, and only at 8.0 GT/s and above.","It protects only the DLP and CRC, and is omitted at 2.5/5.0 GT/s.","It protects the entire Flit, including the CRC. It is needed for the high FBER of PAM4 at 64.0 GT/s and higher, but it is also used at lower data rates for consistency.","ECC exists only at 64.0 GT/s and above; lower-rate Flits have CRC only."],2,"정답 요지: Flit 전체(CRC 포함)를 보호하며, PAM4의 높은 FBER 때문에 64.0 GT/s 이상에서만 필요하지만 일관성을 위해 낮은 속도에서도 사용한다.","Key point: It protects the entire Flit, including the CRC. It is needed for the high FBER of PAM4 at 64.0 GT/s and higher, but it is also used at lower data rates for consistency.","§4.2.3.3"],["p2q19","p2_4",2,"P","Receiver가 Flit의 CRC를 검사하는 시점은?","When does a Receiver check a Flit’s CRC?",["CRC를 먼저 검사하고, 실패할 때만 FEC를 적용한다.","FEC decode/correction을 수행한 뒤에 CRC를 비교한다. 불일치면 uncorrectable error이다.","CRC와 FEC는 독립적으로 동시에 검사하며 순서는 구현 의존이다.","Payload Flit만 CRC를 검사하고 IDLE/NOP는 FEC만 검사한다."],["It checks CRC first and applies FEC only if that check fails.","It compares CRC after performing FEC decode/correction. A mismatch is an uncorrectable error.","CRC and FEC are checked independently; order is implementation-specific.","Only Payload Flits check CRC; IDLE/NOP Flits check FEC only."],1,"정답 요지: FEC decode/correction을 수행한 뒤에 CRC를 비교한다. 불일치면 uncorrectable error이다.","Key point: It compares CRC after performing FEC decode/correction. A mismatch is an uncorrectable error.","§4.2.3.4.4, §4.2.3.4.2"],["p2q20","p2_5",1,"P","8 Byte Flit CRC가 보호하는 범위는?","What does the 8-byte Flit CRC protect?",["Flit 전체 256 Bytes (ECC 포함).","TLP Bytes만 (Bytes 0–235). DLP는 자체 16-bit CRC를 쓴다.","DLP와 ECC만. TLP는 각 TLP의 LCRC로 보호된다.","TLP Bytes와 DLP Bytes (Bytes 0–241). ECC Bytes는 보호하지 않는다."],["The entire 256-byte Flit, including ECC.","Only the TLP bytes (0–235). The DLP has its own 16-bit CRC.","Only the DLP and ECC. TLPs are protected by each TLP’s LCRC.","The TLP and DLP bytes (bytes 0–241). It does not protect the ECC bytes."],3,"정답 요지: TLP Bytes와 DLP Bytes (Bytes 0–241). ECC Bytes는 보호하지 않는다.","Key point: The TLP and DLP bytes (bytes 0–241). It does not protect the ECC bytes.","§4.2.3.3, §4.2.3.4.4"],["p2q21","p2_5",3,"P","Flit CRC 생성 시 Data 크기와 CRC 폭은?","When generating the Flit CRC, what are the data size and CRC width?",["Data는 256 Bytes = 2048 bits이고, CRC는 32 bits이다.","Data는 236 Bytes = 1888 bits이고, CRC는 16 bits이다.","Data는 242 Bytes = 1936 bits이고, generator matrix는 1936×64 bits (8-byte CRC)이다.","Data는 250 Bytes이고, CRC는 6-byte ECC와 동일한 48 bits이다."],["Data is 256 bytes = 2048 bits, and the CRC is 32 bits.","Data is 236 bytes = 1888 bits, and the CRC is 16 bits.","Data is 242 bytes = 1936 bits, and the generator matrix is 1936×64 bits (an 8-byte CRC).","Data is 250 bytes, and the CRC is 48 bits, the same width as the ECC."],2,"정답 요지: Data는 242 Bytes = 1936 bits이고, generator matrix는 1936×64 bits (8-byte CRC)이다.","Key point: Data is 242 bytes = 1936 bits, and the generator matrix is 1936×64 bits (an 8-byte CRC).","§4.2.3.4.4"],["p2q22","p2_5",2,"P","다음 중 ‘valid Flit’의 조건이 아닌 것은?","Which of the following is NOT a required condition for a ‘valid Flit’?",["DLP 안의 모든 Reserved 비트가 0b이어야 한다.","FEC correction 후 CRC check가 통과해야 한다.","FEC의 어떤 ECC group도 uncorrectable error를 보고하지 않아야 한다.","Flit Usage와 Flit_Status 필드가 Reserved encoding이 아니어야 한다."],["All Reserved bits in the DLP must be 0b.","The CRC check must pass after FEC correction.","No ECC group of the FEC may report an uncorrectable error.","The Flit Usage and Flit_Status fields must not have a Reserved encoding."],0,"valid Flit 조건은 CRC 통과(FEC 후), ECC uncorrectable 없음, Flit Usage/Flit_Status가 Reserved가 아닌 것이다. Reserved 필드 값이 non-zero여도 그 자체로 invalid로 정의되지는 않았고, Receivers는 Reserved 값 검사를 할 수 있다(하면 Data Link Protocol Error로 로그).","A valid Flit requires a passing CRC after FEC, no uncorrectable ECC group, and non-reserved Flit Usage and Flit_Status encodings. Non-zero Reserved bits are not part of that definition; Receivers may check Reserved encodings and, if they do, log a Data Link Protocol Error.","§4.2.3.4.2, Table 4-17, Table 4-19"],["p2q23","p2_6",1,"C","Precoding을 요청·적용할 수 있는 최소 Data Rate는?","What is the lowest data rate at which precoding may be requested and applied?",["16.0 GT/s. 128b/130b를 쓰는 모든 속도에서 허용된다.","64.0 GT/s. PAM4에서만 의미가 있다.","8.0 GT/s. Equalization이 있는 모든 속도에서 허용된다.","32.0 GT/s. Transmitter는 32.0 GT/s 미만에서 precoding을 켜서는 안 된다."],["16.0 GT/s. It is allowed at every 128b/130b rate.","64.0 GT/s. It is meaningful only with PAM4.","8.0 GT/s. It is allowed at every rate that has equalization.","32.0 GT/s. A Transmitter must not turn on precoding for any data rate lower than 32.0 GT/s."],3,"정답 요지: 32.0 GT/s. Transmitter는 32.0 GT/s 미만에서 precoding을 켜서는 안 된다.","Key point: 32.0 GT/s. A Transmitter must not turn on precoding for any data rate lower than 32.0 GT/s.","§4.2.2.5"],["p2q24","p2_6",2,"C","Precoding 요청은 어떻게, 어느 시점에 이루어지나?","How and when is a precoding request made?",["L0에 들어온 뒤 Data Stream의 첫 Flit DLP에 Precode Request 비트를 실어 보낸다.","해당 Data Rate로 들어가기 전, Recovery.RcvrCfg에서 EQ TS2(또는 128b/130b·1b/1b EQ TS2)의 Transmitter Precode Request 비트를 연속 8개에서 1b로 설정한다.","Polling.Active의 TS1 Symbol 0에 Precoding On 비트를 설정한다.","소프트웨어가 32.0 GT/s Status Register만 Set하면 Link partner가 즉시 적용한다."],["After entering L0, the first Flit’s DLP carries a Precode Request bit.","Before entering that data rate, during Recovery.RcvrCfg, the Transmitter Precode Request bit is Set in eight consecutive EQ TS2 (or 128b/130b or 1b/1b EQ TS2) Ordered Sets.","The Precoding On bit is set in Symbol 0 of TS1 in Polling.Active.","Software Sets a bit in the 32.0 GT/s Status Register, and the link partner applies precoding immediately."],1,"정답 요지: 해당 Data Rate로 들어가기 전, Recovery.RcvrCfg에서 EQ TS2(또는 128b/130b·1b/1b EQ TS2)의 Transmitter Precode Request 비트를 연속 8개에서 1b로 설정한다.","Key point: Before entering that data rate, during Recovery.RcvrCfg, the Transmitter Precode Request bit is Set in eight consecutive EQ TS2 (or 128b/130b or 1b/1b EQ TS2) Ordered Sets.","§4.2.2.5"],["p2q25","p2_6",2,"C","Precoding 요청의 Port/Lane 범위와 Detect에서의 동작은?","What is the Port/Lane scope of a precoding request, and what happens in Detect?",["Lane마다 자유롭게 on/off할 수 있고, Detect를 거쳐도 마지막 설정이 유지된다.","한 Port(또는 Pseudo-Port)는 구성된 모든 Lane에 대해 요청해야 하며, 다른 Port와는 독립이다. Detect에서는 모든 속도의 precoding이 꺼진다.","양방향 Port가 동시에 같은 설정이어야 하며, Detect에서는 64.0 GT/s만 끈다.","Retimer가 있는 Link에서는 항상 모든 segment에서 동시에 켜지거나 꺼진다."],["Each Lane may be turned on or off independently, and the last setting survives Detect.","A Port or Pseudo-Port must request precoding on all configured Lanes, independently of other Ports. Precoding is turned off for all data rates when the LTSSM is in Detect.","Both directions must use the same setting, and Detect turns precoding off only for 64.0 GT/s.","On a Link with Retimers, every segment is always turned on or off together."],1,"정답 요지: 한 Port(또는 Pseudo-Port)는 구성된 모든 Lane에 대해 요청해야 하며, 다른 Port와는 독립이다. Detect에서는 모든 속도의 precoding이 꺼진다.","Key point: A Port or Pseudo-Port must request precoding on all configured Lanes, independently of other Ports. Precoding is turned off for all data rates when the LTSSM is in Detect.","§4.2.2.5"],["p2q26","p2_6",3,"C","32.0 GT/s에서 precoding이 켜진 경우, 어느 비트에 적용되고 block 경계의 ‘previous bit’은?","When precoding is on at 32.0 GT/s, which bits are precoded and what is the ‘previous bit’ at a block boundary?",["Block의 모든 비트(Sync Header 포함)가 precoding되고, previous bit는 0b로 리셋된다.","TS1/TS2의 모든 Symbol이 precoding되고, Data Block은 적용하지 않는다.","스크램블되지 않은 비트만 precoding되고, previous bit는 이전 Block의 마지막 비트를 유지한다.","스크램블된 비트만 precoding되고, 매 block 경계에서 previous bit는 1b로 설정된다."],["Every bit of the Block, including the Sync Header, is precoded, and the previous bit is reset to 0b.","All Symbols of TS1/TS2 are precoded, and Data Blocks are not.","Only unscrambled bits are precoded, and the previous bit holds the last bit of the previous Block.","Only scrambled bits are precoded, and the previous bit is set to 1b on every block boundary."],3,"정답 요지: 스크램블된 비트만 precoding되고, 매 block 경계에서 previous bit는 1b로 설정된다.","Key point: Only scrambled bits are precoded, and the previous bit is set to 1b on every block boundary.","§4.2.2.5.1"],["p2q27","p2_7",2,"C","2.5/5.0 GT/s (8b/10b) 스크램블러 LFSR 다항식은?","What is the 8b/10b scrambler LFSR polynomial at 2.5/5.0 GT/s?",["G(X) = X^16 + X^5 + X^4 + X^3 + 1","G(X) = X^23 + X^21 + X^16 + X^8 + X^5 + X^2 + 1","G(X) = X^16 + X^15 + X^2 + 1","G(X) = X^8 + X^4 + X^3 + X^2 + 1 (FEC와 동일)"],["G(X) = X^16 + X^5 + X^4 + X^3 + 1","G(X) = X^23 + X^21 + X^16 + X^8 + X^5 + X^2 + 1","G(X) = X^16 + X^15 + X^2 + 1","G(X) = X^8 + X^4 + X^3 + X^2 + 1 (the same as the FEC polynomial)"],0,"정답 요지: G(X) = X^16 + X^5 + X^4 + X^3 + 1","Key point: G(X) = X^16 + X^5 + X^4 + X^3 + 1","§4.2.1.3"],["p2q28","p2_7",2,"C","128b/130b 스크램블링에서 Sync Header와 Data Block에 대한 규칙은?","In 128b/130b scrambling, what are the rules for the Sync Header and for Data Blocks?",["Sync Header도 스크램블되지만 LFSR은 Data payload에서만 진행한다.","Sync Header와 첫 Symbol은 bypass하고, 나머지 15 Symbol만 스크램블한다.","Sync Header 2 bit는 스크램블되지 않고 LFSR도 진행하지 않는다. Data Block의 16 Symbol은 모두 스크램블되며 LFSR을 진행한다.","모든 130 bit가 스크램블되며, Sync Header도 LFSR을 2 step 진행한다."],["The Sync Header is scrambled, but the LFSR advances only on the data payload.","The Sync Header and the first Symbol bypass scrambling; only the remaining 15 Symbols are scrambled.","The two Sync Header bits are not scrambled and do not advance the LFSR. All 16 Symbols of a Data Block are scrambled and advance the scrambler.","All 130 bits are scrambled, and the Sync Header advances the LFSR by two steps."],2,"정답 요지: Sync Header 2 bit는 스크램블되지 않고 LFSR도 진행하지 않는다. Data Block의 16 Symbol은 모두 스크램블되며 LFSR을 진행한다.","Key point: The two Sync Header bits are not scrambled and do not advance the LFSR. All 16 Symbols of a Data Block are scrambled and advance the scrambler.","§4.2.2.4"],["p2q29","p2_7",2,"C","64.0 GT/s 이상(1b/1b)의 Data Stream 스크램블링은 8.0/16.0/32.0 GT/s와 비교해 어떤가?","How does 1b/1b Data Stream scrambling at 64.0 GT/s and above compare with 8.0/16.0/32.0 GT/s?",["1b/1b는 스크램블링을 쓰지 않고 Gray coding만 사용한다.","1b/1b는 8b/10b와 같은 16-bit LFSR을 사용한다.","1b/1b는 Lane 0만 스크램블하고 나머지 Lane은 bypass한다.","동일하다. 차이점은 TS0/TS1/TS2/SKP Ordered Set 규칙뿐이다."],["1b/1b does not use scrambling; it uses only Gray coding.","1b/1b uses the same 16-bit LFSR as 8b/10b.","1b/1b scrambles only Lane 0 and bypasses the other Lanes.","It is identical, except for the TS0/TS1/TS2/SKP Ordered Set rules."],3,"정답 요지: 동일하다. 차이점은 TS0/TS1/TS2/SKP Ordered Set 규칙뿐이다.","Key point: It is identical, except for the TS0/TS1/TS2/SKP Ordered Set rules.","§4.2.3.1.2, §4.2.3.1.3"],["p2q30","p2_7",3,"C","TS0 Ordered Set의 NRZ-based scrambling이 하는 일과 그 결과는?","What does NRZ-based scrambling of a TS0 Ordered Set do, and what is the result?",["스크램블을 bypass하고 고정 패턴 00b/11b만 보내 클록만 전달한다.","8 bit를 스크램블한 뒤 even bit 2i를 odd bit (2i+1)과 같게 만들어, 전압 레벨 0과 3만 보내게 한다.","Gray coding을 두 번 적용해 중간 레벨(1, 2)만 사용한다.","Symbol 0과 8만 스크램블하고 나머지는 평문으로 보낸다."],["It bypasses scrambling and sends only the fixed pattern 00b/11b, as a clock reference.","It scrambles all 8 bits and then forces even bit 2i equal to odd bit (2i+1), so only voltage levels 0 and 3 are sent.","It applies Gray coding twice so that only the middle levels (1 and 2) are used.","It scrambles only Symbols 0 and 8 and sends the rest in the clear."],1,"정답 요지: 8 bit를 스크램블한 뒤 even bit 2i를 odd bit (2i+1)과 같게 만들어, 전압 레벨 0과 3만 보내게 한다.","Key point: It scrambles all 8 bits and then forces even bit 2i equal to odd bit (2i+1), so only voltage levels 0 and 3 are sent.","§4.2.3.1.2"],["p2q31","p2_7",2,"C","128b/130b에서 Configuration.Complete 동안 스크램블링을 disable할 수 있는가?","When using 128b/130b encoding, can scrambling be disabled in Configuration.Complete?",["있다. 8b/10b와 같이 TS2의 Scrambling Disable 비트로 끌 수 있다.","Downstream Port만 disable할 수 있다.","없다. “Scrambling cannot be disabled in Configuration.Complete when using 128b/130b encoding.”","Flit Mode에서만 disable할 수 있다."],["Yes. As with 8b/10b, it can be turned off with the Scrambling Disable bit in TS2.","Only a Downstream Port may disable it.","No. “Scrambling cannot be disabled in Configuration.Complete when using 128b/130b encoding.”","It may be disabled only in Flit Mode."],2,"표준 문장 그대로 Configuration.Complete에서 128b/130b 스크램블링을 disable할 수 없다. 8b/10b의 Scrambling Disable 관행을 그대로 적용하면 안 된다.","The specification states that scrambling cannot be disabled in Configuration.Complete when using 128b/130b encoding. The 8b/10b Scrambling Disable convention does not apply here.","§4.2.2.4"],["p2q32","p2_8",2,"P","8b/10b Non-Flit Mode에서 STP, SDP, END, EDB의 K-code는?","In 8b/10b Non-Flit Mode, which K-codes are STP, SDP, END, and EDB?",["STP=K27.7, SDP=K28.2, END=K29.7, EDB=K30.7","STP=K28.5, SDP=K28.2, END=K29.7, EDB=K30.7","STP=K27.7, SDP=K23.7, END=K29.7, EDB=K28.3","STP=K28.0, SDP=K28.2, END=K27.7, EDB=K29.7"],["STP=K27.7, SDP=K28.2, END=K29.7, EDB=K30.7","STP=K28.5, SDP=K28.2, END=K29.7, EDB=K30.7","STP=K27.7, SDP=K23.7, END=K29.7, EDB=K28.3","STP=K28.0, SDP=K28.2, END=K27.7, EDB=K29.7"],0,"Table 4-3: STP=K27.7, SDP=K28.2, END=K29.7, EDB=K30.7. K28.5는 COM, K23.7은 PAD, K28.0은 SKP, K28.3은 IDL이다. 이 네 framing Symbol은 Flit Mode에서 Reserved이다.","Table 4-3: STP=K27.7, SDP=K28.2, END=K29.7, EDB=K30.7. K28.5 is COM, K23.7 is PAD, K28.0 is SKP, and K28.3 is IDL. Those four framing Symbols are Reserved in Flit Mode.","§4.2.1.1.2, Table 4-3"],["p2q33","p2_8",1,"C","Flit Mode에서 STP/SDP/END/EDB 또는 128b/130b Framing Token을 쓰는가?","Does Flit Mode use STP/SDP/END/EDB or 128b/130b Framing Tokens?",["쓰지 않는다. TLP/DLP 배치가 Flit 안에 고정되어 있으므로 packet marker와 Framing Token이 사용되지 않는다.","쓴다. Non-Flit과 동일한 framing으로 Flit 안의 TLP 경계를 표시한다.","STP/SDP만 쓰고 END/EDB는 Flit_Marker로 대체한다.","64.0 GT/s 이상에서만 Framing Token을 쓰고, 그 아래 Flit은 8b/10b K-code를 쓴다."],["No. TLP and DLP placement is fixed inside the Flit, so packet markers and Framing Tokens are not used.","Yes. The same framing as Non-Flit Mode marks TLP boundaries inside the Flit.","Only STP/SDP are used; END/EDB are replaced by Flit_Marker.","Framing Tokens are used only at 64.0 GT/s and above; lower-rate Flits use 8b/10b K-codes."],0,"정답 요지: 쓰지 않는다. TLP/DLP 배치가 Flit 안에 고정되어 있으므로 packet marker와 Framing Token이 사용되지 않는다.","Key point: No. TLP and DLP placement is fixed inside the Flit, so packet markers and Framing Tokens are not used.","§4.2.3"],["p2q34","p2_8",2,"C","Non-Flit 128b/130b에서 STP Framing Token의 길이와 그 안에 포함되는 정보는?","In Non-Flit 128b/130b encoding, how long is the STP Framing Token and what does it include?",["2 Symbols이며, 8-bit Sequence Number만 포함한다.","1 Symbol이며, 다음 Token 위치만 암시한다.","4 Symbols이며, 12-bit TLP Sequence Number를 포함한다.","4 Symbols이며, 32-bit LCRC를 포함한다."],["It is 2 Symbols long and includes only an 8-bit Sequence Number.","It is 1 Symbol and only implies the location of the next Token.","It is 4 Symbols long and includes the 12-bit TLP Sequence Number.","It is 4 Symbols long and includes the 32-bit LCRC."],2,"정답 요지: 4 Symbols이며, 12-bit TLP Sequence Number를 포함한다.","Key point: It is 4 Symbols long and includes the 12-bit TLP Sequence Number.","§4.2.2.3.1, Table 4-4"],["p2q35","p2_8",3,"C","SKP Ordered Set 종류(Standard vs Control)에 대한 다음 설명 중 옳은 것은?","Which statement about Standard versus Control SKP Ordered Sets is correct?",["모든 Data Rate에서 Standard SKP와 Control SKP를 항상 교대한다.","8.0 GT/s Non-Flit는 SKP가 필요할 때 Standard SKP만 보낸다. 8.0 GT/s Flit와 16.0/32.0 GT/s(모드 무관)는 Standard와 Control을 교대한다. 64.0/128.0 GT/s는 Control SKP만 보낸다.","Flit Mode는 항상 Control SKP만, Non-Flit Mode는 항상 Standard SKP만 사용한다.","64.0 GT/s 이상에서는 Standard SKP만 사용하고, Control SKP는 8.0 GT/s 전용이다."],["Standard and Control SKP always alternate at every data rate.","At 8.0 GT/s Non-Flit, only Standard SKP is sent when a SKP OS is needed. At 8.0 GT/s Flit and at 16.0/32.0 GT/s (either mode), Standard and Control SKP alternate. At 64.0/128.0 GT/s only Control SKP is sent.","Flit Mode always uses only Control SKP, and Non-Flit Mode always uses only Standard SKP.","At 64.0 GT/s and above only Standard SKP is used; Control SKP is only for 8.0 GT/s."],1,"정답 요지: 8.0 GT/s Non-Flit는 SKP가 필요할 때 Standard SKP만 보낸다. 8.0 GT/s Flit와 16.0/32.0 GT/s(모드 무관)는 Standard와 Control을 교대한다. 64.0/128.0 GT/s는 Control SKP만 보낸다.","Key point: At 8.0 GT/s Non-Flit, only Standard SKP is sent when a SKP OS is needed. At 8.0 GT/s Flit and at 16.0/32.0 GT/s (either mode), Standard and Control SKP alternate. At 64.0/128.0 GT/s only Control SKP is sent.","§4.2, Table 4-2"],["p2q36","p2_8",2,"C","8.0 GT/s 이상 Flit Mode Data Stream 시작 시 Control SKP에 대한 규칙은?","At 8.0 GT/s and above in Flit Mode, what is required of Control SKP at the start of a Data Stream?",["직전 SKP 간격이 아직 남아 있으면 SDS 직후 SKP를 생략한다.","SDS 직후에는 EIEOS를 보내고, Control SKP는 첫 Payload Flit 뒤에 넣는다.","2.5/5.0 GT/s와 같이 SKP는 Flit 중간에도 자유롭게 삽입된다.","이전 Control SKP를 언제 보냈는지와 관계없이, SDS Ordered Set sequence 직후에 Control SKP Ordered Set를 보내야 한다."],["If the previous SKP interval has not expired, SKP after SDS is omitted.","An EIEOS is sent immediately after SDS, and Control SKP is placed after the first Payload Flit.","As at 2.5/5.0 GT/s, SKP may be inserted freely in the middle of a Flit.","A Control SKP Ordered Set must immediately follow the SDS Ordered Set sequence, regardless of when the prior Control SKP Ordered Set was transmitted."],3,"정답 요지: 이전 Control SKP를 언제 보냈는지와 관계없이, SDS Ordered Set sequence 직후에 Control SKP Ordered Set를 보내야 한다.","Key point: A Control SKP Ordered Set must immediately follow the SDS Ordered Set sequence, regardless of when the prior Control SKP Ordered Set was transmitted.","§4.2.3.4.6"],["c2q01","c2_1",1,"X","Flex Bus physical layer의 electrical sub-block은 어떤 규격을 따르나요?","Which specification does the electrical sub-block of the Flex Bus physical layer follow?",["PCIe Base Specification","CXL 전용 전기 규격(PCIe와 별도)","IEEE 802.3 Ethernet PHY 규격","DDR5 메모리 인터페이스 규격"],["The PCIe Base Specification","A CXL-only electrical spec separate from PCIe","The IEEE 802.3 Ethernet PHY spec","The DDR5 memory interface spec"],0,"Flex Bus는 PCIe 전기 규격을 그대로 쓰고, CXL 차이는 logical PHY 쪽에 있습니다.","Flex Bus reuses PCIe electricals; the CXL deltas live in the logical PHY.","§6.1"],["c2q02","c2_1",2,"X","Flex Bus logical PHY는 언제 PCIe mode에서 CXL mode로 넘어가나요?","When does the Flex Bus logical PHY move from PCIe mode to CXL mode?",["Detect 직후 항상 CXL mode로 시작한다","소프트웨어가 L0 이후 Configuration write로 전환한다","2.5 GT/s로 학습한 뒤 Recovery에서, alternate protocol negotiation 결과에 따라","128 GT/s equalization이 끝난 뒤에만 전환한다"],["It always starts in CXL mode right after Detect","Software switches it with a Configuration write after L0","During Recovery after training to 2.5 GT/s, based on the alternate protocol negotiation result","Only after 128 GT/s equalization completes"],2,"링크는 처음에 PCIe처럼 학습하고, alternate protocol negotiation이 CXL로 결정되면 2.5 GT/s 학습 후 Recovery에서 CXL mode로 바뀝니다.","The link first trains like PCIe; if alternate protocol negotiation picks CXL, it switches in Recovery after the 2.5 GT/s training.","§6.1"],["c2q03","c2_2",1,"X","CXL 4.0에서 새로 정의된 최고 link speed는?","What is the new top link speed defined in CXL 4.0?",["64 GT/s","128 GT/s","32 GT/s","256 GT/s"],["64 GT/s","128 GT/s","32 GT/s","256 GT/s"],1,"CXL 4.0은 PCIe 7.0 Base Specification을 활용해 데이터 레이트를 64에서 128 GT/s로 두 배로 올렸습니다.","CXL 4.0 doubles the rate from 64 to 128 GT/s by leveraging the PCIe 7.0 Base Specification.","§1.4"],["c2q04","c2_2",2,"X","CXL mode에서 128 GT/s일 때 추가로 지원되는 native link width는?","In CXL mode, which native link width is additionally supported at 128 GT/s?",["x1","x32","x12","x2"],["x1","x32","x12","x2"],3,"32/64 GT/s의 native width는 x16/x8/x4이고, 128 GT/s에서는 x2 native도 지원됩니다. x1은 degraded mode로만 나옵니다.","At 32/64 GT/s native widths are x16/x8/x4; at 128 GT/s x2 native is also supported. x1 appears only as a degraded mode.","§6.1"],["c2q05","c2_2",1,"C","64 GT/s와 128 GT/s에서 쓰는 신호 방식은? (PCIe 6.0 이후와 CXL 공통)","Which signaling is used at 64 GT/s and 128 GT/s? (shared by PCIe 6.0+ and CXL)",["NRZ","PAM3","PAM4","QAM16"],["NRZ","PAM3","PAM4","QAM16"],2,"64/128 GT/s는 PAM4 신호를 씁니다. 32 GT/s 이하에서는 NRZ입니다.","64/128 GT/s use PAM4 signaling; 32 GT/s and below are NRZ.","§1.5"],["c2q06","c2_2",1,"X","CXL mode에서 x1 link width는 어떤 위치인가요?","In CXL mode, what is the status of a x1 link width?",["degraded mode로만 지원된다","native width로 항상 권장된다","CXL에서는 x1이 전혀 허용되지 않는다","x1은 128 GT/s에서만 native로 지원된다"],["Supported only as a degraded mode","Always recommended as a native width","x1 is never allowed in CXL","x1 is native only at 128 GT/s"],0,"CXL mode는 x16/x8/x4/x2를 쓰고 x1은 degraded mode로 둡니다.","CXL mode uses x16/x8/x4/x2, with x1 as a degraded mode.","§1.5"],["c2q07","c2_3",1,"X","링크가 5 GT/s에서 PCIe Flit mode로 학습했다면 CXL mode는?","If a link trained at 5 GT/s with PCIe Flit mode, what about CXL mode?",["256B flit으로 동작한다","68B flit으로 동작한다","Latency-optimized flit만 쓴다","지원되지 않는다"],["It runs with 256B flits","It runs with 68B flits","It uses only latency-optimized flits","It is not supported"],3,"CXL은 8 GT/s 이상에서만 동작합니다. 2.5/5 GT/s에서는 PCIe Flit mode 여부와 관계없이 CXL이 없습니다.","CXL runs only at 8 GT/s and above; at 2.5/5 GT/s there is no CXL regardless of PCIe Flit mode.","§6.2.3"],["c2q08","c2_3",1,"X","16 GT/s에서 PCIe Flit mode가 꺼져 있으면 CXL은 어떤 flit과 encoding을 쓰나요?","At 16 GT/s with PCIe Flit mode off, which flit and encoding does CXL use?",["256B flit, 1b/1b","68B flit, 128b/130b","256B flit, 128b/130b","68B flit, 8b/10b"],["256B flit, 1b/1b","68B flit, 128b/130b","256B flit, 128b/130b","68B flit, 8b/10b"],1,"8/16/32 GT/s에서 PCIe Flit mode가 꺼져 있으면 68B, 켜져 있으면 256B이고 둘 다 128b/130b입니다.","At 8/16/32 GT/s, Flit mode off means 68B and on means 256B, both with 128b/130b.","§6.2.3"],["c2q09","c2_3",2,"C","64 GT/s와 128 GT/s에서 쓰는 encoding은? (PCIe Flit mode와 CXL 공통)","Which encoding is used at 64 GT/s and 128 GT/s? (shared by PCIe Flit mode and CXL)",["128b/130b","1b/1b","8b/10b","64b/66b"],["128b/130b","1b/1b","8b/10b","64b/66b"],1,"64/128 GT/s는 PCIe Flit mode가 필수이고 1b/1b encoding을 씁니다. CXL은 여기서 256B flit만 씁니다.","64/128 GT/s require PCIe Flit mode and use 1b/1b; CXL uses only 256B flits there.","§6.2.3"],["c2q10","c2_3",3,"X","CXL 256B Flit mode는 어떻게 협상되나요?","How is CXL 256B Flit mode negotiated?",["Modified TS1의 전용 256B 비트로 협상한다","L0 진입 후 ALMP로 협상한다","소프트웨어가 DVSEC 레지스터로 켠다","전용 비트가 없고, PCIe link training에서 PCIe Flit mode가 켜지면 함의된다"],["Through a dedicated 256B bit in Modified TS1","Through ALMPs after entering L0","Software enables it through a DVSEC register","There is no dedicated bit; it is implied when PCIe Flit mode is enabled during PCIe link training"],3,"PCIe Flit mode는 alternate protocol negotiation 전에 이미 정해지므로, 256B Flit mode를 따로 알리는 비트가 없습니다.","PCIe Flit mode is settled before alternate protocol negotiation, so no separate 256B bit exists.","§6.4.1.3.1"],["c2q11","c2_4",1,"X","68B flit의 '68B'는 어떻게 구성되나요?","How is the '68B' of a 68B flit made up?",["Link layer의 66B + ARB/MUX의 2B","Payload 64B + FEC 4B","Header 4B + Data 64B","TLP 60B + DLLP 8B"],["66B from the link layer + 2B from the ARB/MUX","64B payload + 4B FEC","4B header + 64B data","60B TLP + 8B DLLP"],0,"Link layer가 66B(528 bit)를 만들고 ARB/MUX 쪽에서 2B(Protocol ID)가 붙어 68B가 됩니다.","The link layer defines 66B (528 bits) and 2B (the Protocol ID) is added at the ARB/MUX level, giving 68B.","§4.2.1"],["c2q12","c2_4",2,"X","68B Flit mode의 528-bit CXL.cachemem flit 구성은?","What is inside the 528-bit CXL.cachemem flit in 68B Flit mode?",["32B slot 2개 + 8B CRC + 6B FEC","16B slot 15개 + 2B CRD","16B slot 4개 + 2B CRC","64B data + 4B LCRC"],["Two 32B slots + 8B CRC + 6B FEC","Fifteen 16B slots + 2B CRD","Four 16B slots + 2B CRC","64B data + 4B LCRC"],2,"68B 모드 flit은 고정 528 bit이고 16B slot 4개(header slot 1 + generic 3)와 2B CRC로 되어 있습니다.","The 68B-mode flit is a fixed 528 bits: four 16B slots (one header slot, three generic) plus a 2B CRC.","§4.2.2"],["c2q13","c2_4",1,"X","68B Flit mode에서 Protocol ID 5555h는 무엇을 뜻하나요?","In 68B Flit mode, what does Protocol ID 5555h mean?",["CXL.io flit","ALMP","Physical Layer가 넣은 NULL flit","CXL.cachemem flit"],["A CXL.io flit","An ALMP","A NULL flit inserted by the Physical Layer","A CXL.cachemem flit"],3,"Protocol ID 예: CXL.io=FFFFh, CXL.cachemem=5555h, NULL=9999h, ALMP=CCCCh.","Protocol ID examples: CXL.io=FFFFh, CXL.cachemem=5555h, NULL=9999h, ALMP=CCCCh.","§6.2.2.1"],["c2q14","c2_4",3,"X","68B Flit mode에서 Data block에서 Ordered Set block으로 넘어감을 알리는 방식이 PCIe와 다른 점은?","In 68B Flit mode, how does signaling the move from a data block to an Ordered Set block differ from PCIe?",["EDS token을 매 flit마다 두 번 보낸다","EDS를 별도 token 대신 Protocol ID 값에 담는다(implied EDS)","Sync Header 11b로 알린다","ALMP로 미리 예고한다"],["The EDS token is sent twice per flit","EDS is folded into the Protocol ID value instead of a separate token (implied EDS)","It is signaled with Sync Header 11b","It is announced ahead with an ALMP"],1,"PCIe는 명시적 EDS token을 쓰지만 68B Flit mode는 'implied EDS'가 포함된 Protocol ID 인코딩을 씁니다.","PCIe uses an explicit EDS token; 68B Flit mode uses Protocol ID encodings that include an implied EDS.","§6.2.1"],["c2q15","c2_4",3,"X","16-bit Protocol ID의 두 8-bit 그룹 중 하나만 틀렸다면 수신기는?","If only one of the two 8-bit groups in a 16-bit Protocol ID is wrong, what does the receiver do?",["flit을 버리고 즉시 Recovery로 간다","Link Layer Retry를 요청한다","correctable 오류로 기록하고 맞는 그룹으로 계속 처리한다","링크를 LinkError 상태로 보낸다"],["Drops the flit and goes to Recovery at once","Requests a Link Layer Retry","Logs a correctable error and keeps processing with the good group","Sends the link to LinkError"],2,"8-bit 인코딩을 두 번 복제해 보호합니다. 한쪽만 틀리면 correctable, 둘 다 틀리면 uncorrectable로 flit을 버리고 Recovery로 갑니다.","The 8-bit code is duplicated. One bad copy is correctable; both bad is uncorrectable, the flit is dropped and the link retrains.","§6.2.2.1"],["c2q16","c2_5",1,"C","Standard 256B flit의 CRC와 FEC 크기는? (PCIe Flit mode와 같은 값)","What are the CRC and FEC sizes in a standard 256B flit? (same values as PCIe Flit mode)",["CRC 8B, FEC 6B","CRC 2B, FEC 없음","CRC 4B, FEC 4B","CRC 6B, FEC 8B"],["8B CRC, 6B FEC","2B CRC, no FEC","4B CRC, 4B FEC","6B CRC, 8B FEC"],0,"Standard 256B flit은 2B Flit Header, 240B Flit Data, 8B CRC, 6B FEC로 되어 있고 CRC/FEC 계산은 PCIe 정의를 따릅니다.","The standard 256B flit has a 2B header, 240B data, 8B CRC, and 6B FEC; CRC/FEC follow the PCIe definitions.","§6.2.3.1.1"],["c2q17","c2_5",1,"X","256B flit의 Flit Type[1:0]이 11b이면?","In a 256B flit, what does Flit Type[1:0] = 11b indicate?",["ALMP","CXL.io Payload","CXL.cachemem Payload","Physical Layer IDLE"],["An ALMP","CXL.io Payload","CXL.cachemem Payload","Physical Layer IDLE"],0,"Flit Type: 00b=IDLE/NOP, 01b=CXL.io Payload, 10b=CXL.cachemem(Payload/Empty), 11b=ALMP.","Flit Type: 00b=IDLE/NOP, 01b=CXL.io Payload, 10b=CXL.cachemem (Payload/Empty), 11b=ALMP.","§6.2.3.1.1"],["c2q18","c2_5",3,"X","CXL.cachemem standard 256B flit에는 slot이 몇 개 있나요?","How many slots does a CXL.cachemem standard 256B flit have?",["4개 (16B slot)","16개 (모두 16B)","15개 (14B H-slot 1개 + 16B G-slot 14개)","8개 (32B slot)"],["4 (16B slots)","16 (all 16B)","15 (one 14B H-slot + fourteen 16B G-slots)","8 (32B slots)"],2,"2B HDR 뒤에 14B H-slot, 이어서 16B G-slot 14개가 있고, 끝에 2B CRD, 8B CRC, 6B FEC가 옵니다.","After the 2B HDR come a 14B H-slot and fourteen 16B G-slots, then 2B CRD, 8B CRC and 6B FEC.","§4.3.2"],["c2q19","c2_6",2,"X","Latency-optimized 256B flit의 주된 이점은?","What is the main benefit of the latency-optimized 256B flit?",["FEC를 없애 대역폭을 늘린다","128B half마다 CRC가 있어 FEC를 기다리지 않고 앞 half를 먼저 쓸 수 있다","재전송을 128B 단위로 줄인다","68B flit과 섞어서 보낼 수 있다"],["It removes FEC to gain bandwidth","Each 128B half has its own CRC, so the first half can be used before FEC decode","It shrinks retries to 128B units","It can be mixed with 68B flits"],1,"각 half가 6B CRC로 따로 보호되어 CRC가 통과하면 바로 소비할 수 있어 flit 누적 지연이 줄어듭니다. FEC는 여전히 256B 전체를 보호합니다.","Each half has its own 6B CRC, so a passing half can be consumed early, cutting accumulation latency; FEC still covers all 256B.","§6.2.3.1.2"],["c2q20","c2_6",2,"X","Standard 256B flit과 latency-optimized 256B flit 사이의 전환은?","How does switching between the standard and latency-optimized 256B flit formats work?",["트래픽 양에 따라 flit마다 바꿀 수 있다","L1 진입 때마다 다시 고른다","ALMP로 언제든 바꿀 수 있다","alternate protocol negotiation에서 한 번 정하고, 동적 전환은 안 된다"],["It can change per flit with traffic load","It is re-chosen on every L1 entry","It can be changed at any time via ALMP","It is chosen once during alternate protocol negotiation; dynamic switching is not supported"],3,"Latency-optimized 형식은 선택 사항이며, 협상 때 한 번 결정되고 동작 중에 바꾸지 않습니다.","The latency-optimized format is optional, fixed once at negotiation, and never switched at runtime.","§6.2.3.1.2"],["c2q21","c2_7",1,"X","ARB/MUX의 역할로 맞는 것은? (PCIe 계층에는 없는 블록)","What does the ARB/MUX do? (a block with no PCIe counterpart)",["TLP의 ordering 규칙을 바꾼다","PAM4 equalization을 수행한다","CXL.io와 CXL.cachemem link layer 트래픽을 중재·다중화해 PHY로 보낸다","HDM 주소를 디코딩한다"],["Changes TLP ordering rules","Performs PAM4 equalization","Arbitrates and multiplexes CXL.io and CXL.cachemem link-layer traffic onto the PHY","Decodes HDM addresses"],2,"ARB/MUX는 두 link layer 사이를 중재하고, PM 요청을 정리하며, vLSM과 ALMP를 관리합니다.","The ARB/MUX arbitrates between the two link layers, resolves PM requests, and manages vLSMs and ALMPs.","§5.0"],["c2q22","c2_7",1,"X","Flex Bus 링크가 PCIe mode로 동작하면 ARB/MUX는?","When a Flex Bus link runs in PCIe mode, what happens to the ARB/MUX?",["bypass되고 ALMP 생성이 꺼진다","CXL.io만 다중화하며 ALMP는 계속 보낸다","PCIe DLLP를 ALMP로 바꿔 보낸다","PCIe TLP에 Protocol ID를 붙인다"],["It is bypassed and ALMP generation is disabled","It muxes CXL.io only and keeps sending ALMPs","It converts PCIe DLLPs into ALMPs","It adds a Protocol ID to PCIe TLPs"],0,"PCIe mode에서는 ARB/MUX가 우회되므로 ALMP를 만들지 않습니다.","In PCIe mode the ARB/MUX is bypassed, so no ALMPs are generated.","§5.2.1"],["c2q23","c2_7",2,"X","ARB/MUX가 서로 다른 CXL 프로토콜 트래픽을 섞는 단위는?","At what boundary does the ARB/MUX interleave traffic of different CXL protocols?",["항상 1 DWORD 경계","항상 TLP 경계","항상 128B half 경계","68B 모드는 528-bit flit 경계, 256B 모드는 256B flit 경계"],["Always a 1-DWORD boundary","Always a TLP boundary","Always a 128B half boundary","The 528-bit flit boundary in 68B mode, the 256B flit boundary in 256B mode"],3,"중재 정책 자체는 구현 자유지만, 프로토콜 간 interleave는 flit 경계에서 일어납니다. CXL.io와 cachemem의 가중치는 프로그래밍할 수 있어야 합니다.","The arbitration policy is implementation-specific, but interleaving happens at flit boundaries, and CXL.io vs cachemem weights must be programmable.","§5.3"],["c2q24","c2_7",2,"X","vLSM[0]이 L1.0이고 vLSM[1]이 Active일 때 ARB/MUX가 PHY에 보내는 결정 요청은?","If vLSM[0] is L1.0 and vLSM[1] is Active, what resolved request does the ARB/MUX send to the PHY?",["L1.0","Active","SLEEP_L2","Retrain"],["L1.0","Active","SLEEP_L2","Retrain"],1,"한 인터페이스라도 Active면 링크 전체는 Active로 결정됩니다. 더 깊은 절전은 모든 vLSM이 동의할 때만 갑니다.","If any interface is Active, the link resolves to Active; deeper power states need every vLSM to agree.","§5.1"],["c2q25","c2_8",2,"X","ALMP 한 개의 크기와, 68B Flit mode에서의 보호 방식은?","What size is an ALMP, and how is it protected in 68B Flit mode?",["1 DWORD이고, 16-bit CRC를 따로 붙인다","1 DWORD이고, flit의 하위 16B에 네 번 복제한다","4 DWORD이고, FEC로 보호한다","2 DWORD이고, 보호가 없다"],["1 DWORD with its own 16-bit CRC","1 DWORD, replicated four times in the low 16B of the flit","4 DWORDs protected by FEC","2 DWORDs with no protection"],1,"68B에서는 복제로 무결성을 확보하고 오류가 보이면 retrain합니다. 256B에서는 CRC·FEC가 있으므로 복제하지 않습니다.","In 68B mode, replication provides integrity and an error triggers retrain; in 256B mode CRC/FEC protect it, so no replication.","§5.2"],["c2q26","c2_8",2,"X","vLSM ALMP의 Byte 3 Virtual LSM Instance Number가 0010b이면 대상은?","In a vLSM ALMP, what does Byte 3 Virtual LSM Instance Number 0010b target?",["CXL.io vLSM","L0p 협상","모든 vLSM 동시","CXL.cache와 CXL.mem vLSM"],["The CXL.io vLSM","L0p negotiation","All vLSMs at once","The CXL.cache and CXL.mem vLSM"],3,"0001b는 CXL.io, 0010b는 CXL.cache+CXL.mem용입니다.","0001b targets CXL.io and 0010b targets CXL.cache + CXL.mem.","§5.2"],["c2q27","c2_8",3,"X","PM 진입 요청 ALMP를 받았는데 받아들일 수 없을 때, 256B Flit mode에서의 동작은?","In 256B Flit mode, what happens when a received PM entry request ALMP cannot be accepted?",["Active.PMNAK Status ALMP를 보낸다","아무 Status ALMP도 보내지 않는다","링크를 LinkError로 보낸다","PCIe PM_NAK DLLP를 보낸다"],["An Active.PMNAK Status ALMP is sent","No Status ALMP is sent at all","The link goes to LinkError","A PCIe PM_NAK DLLP is sent"],0,"68B에서는 거절 시 Status ALMP를 보내지 않고 양쪽이 현재 상태에 머뭅니다. 256B에서는 Active.PMNAK Status ALMP로 거절을 알립니다.","In 68B mode a rejected request gets no Status ALMP; in 256B mode the rejection is signaled with an Active.PMNAK Status ALMP.","§5.2"],["c2q28","c2_9",2,"X","Sync Header bypass 최적화가 적용되는 속도는?","At which speeds does the Sync Header bypass optimization apply?",["64, 128 GT/s","모든 CXL 속도","8, 16, 32 GT/s","2.5, 5 GT/s"],["64 and 128 GT/s","All CXL speeds","8, 16, and 32 GT/s","2.5 and 5 GT/s"],2,"64/128 GT/s는 1b/1b encoding이라 Sync Header가 원래 없으므로 이 최적화가 의미가 없습니다.","64/128 GT/s use 1b/1b encoding with no Sync Header, so the optimization does not apply.","§6.8"],["c2q29","c2_9",3,"X","128 GT/s에서 Upstream Port가 CXL.io throttling을 알렸다면 Downstream Port가 지켜야 할 것은?","At 128 GT/s, if the Upstream Port advertises CXL.io throttling, what must the Downstream Port respect?",["연속 2 flit 창마다 CXL.io flit을 최대 1개만 보낸다","CXL.io flit을 전혀 보내지 않는다","CXL.cachemem flit을 4개 중 1개로 제한한다","연속 4 flit 창마다 CXL.io flit을 최대 1개만 보낸다"],["At most one CXL.io flit in any window of two consecutive flits","No CXL.io flits at all","Limit CXL.cachemem flits to one in four","At most one CXL.io flit in any window of four consecutive flits"],3,"CXL.mem 대역폭은 크게 필요하지만 CXL.io는 적은 Type 3 장치가 버퍼·전력을 줄이도록 한 기능입니다. 64 GT/s에서는 연속 CXL.io flit 수신 불가를 알리는 형태입니다.","It lets Type 3 devices with heavy CXL.mem but light CXL.io traffic save buffers and power; at 64 GT/s it signals no back-to-back CXL.io flits.","§6.4.1.3.2"]],"3":[["p3q01","p3_1",1,"C","Data Link Control and Management State Machine(DLCMSM)의 상태 집합은?","What are the states of the Data Link Control and Management State Machine (DLCMSM)?",["DL_Inactive, DL_Feature (optional), DL_Init, DL_Active","DL_Down, DL_Up, DL_Retrain, DL_Active","DL_Inactive, DL_Training, DL_Active, DL_Sleep","FC_INIT1, FC_INIT2, DL_Active, DL_Replay"],["DL_Inactive, DL_Feature (optional), DL_Init, and DL_Active","DL_Down, DL_Up, DL_Retrain, and DL_Active","DL_Inactive, DL_Training, DL_Active, and DL_Sleep","FC_INIT1, FC_INIT2, DL_Active, and DL_Replay"],0,"DLCMSM 상태는 DL_Inactive, 선택적 DL_Feature, DL_Init, DL_Active이다. DL_Down/DL_Up은 상태 출력이고, FC_INIT1/2는 DL_Init 안의 VC 초기화 상태이다.","The DLCMSM states are DL_Inactive, optional DL_Feature, DL_Init, and DL_Active. DL_Down/DL_Up are status outputs; FC_INIT1/2 are VC initialization states inside DL_Init.","§3.2"],["p3q02","p3_1",2,"C","VC0 Flow Control 초기화 동안 Transaction Layer에 보고되는 DL_Up/DL_Down은?","During VC0 Flow Control initialization, when are DL_Up and DL_Down reported to the Transaction Layer?",["InitFC1을 한 번이라도 보내면 즉시 DL_Up이다.","DL_Init 전체에 걸쳐 DL_Down이고, DL_Active에 들어가서야 DL_Up이다.","FC_INIT1에서는 DL_Down, FC_INIT2에서는 DL_Up을 보고한다.","Physical LinkUp=1b이면 DL_Init 진입과 동시에 DL_Up이다."],["DL_Up is reported as soon as a single InitFC1 has been transmitted.","DL_Down is reported for all of DL_Init; DL_Up only after entry to DL_Active.","DL_Down is reported in FC_INIT1, and DL_Up is reported in FC_INIT2.","DL_Up is reported as soon as DL_Init is entered if Physical LinkUp=1b."],2,"정답 요지: FC_INIT1에서는 DL_Down, FC_INIT2에서는 DL_Up을 보고한다.","Key point: DL_Down is reported in FC_INIT1, and DL_Up is reported in FC_INIT2.","§3.2.1, §3.4.1"],["p3q03","p3_1",2,"C","Data Link Feature Exchange protocol이 required인 경우는?","When is the Data Link Feature Exchange protocol required?",["모든 PCI Express Port에서 필수이다.","Flit Mode를 지원하는 Port, 그리고 16.0 GT/s 이상을 지원하는 Port. 그 외 Port에서는 optional이다.","64.0 GT/s 이상을 지원하는 Port에서만 필수이다.","Downstream Port에서만 필수이고 Upstream Port에서는 금지된다."],["It is required on every PCI Express Port.","It is required for Ports that support Flit Mode and for Ports that support 16.0 GT/s and higher. It is optional for other Ports.","It is required only on Ports that support 64.0 GT/s and higher.","It is required only on Downstream Ports and is prohibited on Upstream Ports."],1,"정답 요지: Flit Mode를 지원하는 Port, 그리고 16.0 GT/s 이상을 지원하는 Port. 그 외 Port에서는 optional이다.","Key point: It is required for Ports that support Flit Mode and for Ports that support 16.0 GT/s and higher. It is optional for other Ports.","§3.3"],["p3q04","p3_1",2,"C","Function Level Reset(FLR)은 DLCMSM 상태에 어떤 영향을 주나?","How does a Function Level Reset (FLR) affect DLCMSM state?",["DL_Inactive로 돌아가 Retry Buffer를 비운다.","DL_Feature부터 Feature Exchange를 다시 수행한다.","VC0만 다시 FC_INIT1로 들어가고 나머지 VC는 유지한다.","영향을 주지 않는다. DL states는 FLR의 영향을 받지 않는다."],["The DLCMSM returns to DL_Inactive and discards the Retry Buffer.","It restarts Feature Exchange from DL_Feature.","Only VC0 re-enters FC_INIT1; other VCs are left unchanged.","It has no effect. DL states are unaffected by an FLR."],3,"정답 요지: 영향을 주지 않는다. DL states는 FLR의 영향을 받지 않는다.","Key point: It has no effect. DL states are unaffected by an FLR.","§3.2.1"],["p3q05","p3_1",1,"C","DL_Inactive에서 Data Link Layer의 동작으로 옳은 것은?","Which statement about Data Link Layer behavior in DL_Inactive is correct?",["이미 열린 VC에 한해 UpdateFC와 Ack DLLP는 계속 보낸다.","Physical LinkUp=0b여도 마지막으로 받은 Ack 시점의 Retry Buffer는 유지한다.","DL_Down을 보고하고, Retry Buffer를 버리며, DLLP를 생성하거나 받아들이지 않는다.","TLP는 버리지만 DLLP CRC만 맞으면 Feature DLLP는 수락한다."],["It continues to send UpdateFC and Ack DLLPs for VCs that were already initialized.","It keeps the Retry Buffer as of the last received Ack even if Physical LinkUp=0b.","It reports DL_Down, discards the Retry Buffer, and does not generate or accept DLLPs.","It discards TLPs but still accepts Feature DLLPs if their CRC is correct."],2,"정답 요지: DL_Down을 보고하고, Retry Buffer를 버리며, DLLP를 생성하거나 받아들이지 않는다.","Key point: It reports DL_Down, discards the Retry Buffer, and does not generate or accept DLLPs.","§3.2.1"],["p3q06","p3_2",1,"C","DLLP가 전송 중 손실되거나 CRC에 실패해도 재전송하지 않는 이유는?","Why are DLLPs not retried if they are lost or fail their CRC check?",["DLLP를 사용하는 메커니즘이 self-repairing이라, 다음 DLLP가 잃어버린 정보를 대체한다. 성능 손해는 있을 수 있다.","DLLP는 LCRC와 Sequence Number로 보호되어 손실이 원천적으로 불가능하다.","손실된 DLLP는 항상 다음 TLP의 header에 piggyback되어 재전송된다.","DLLP 손실은 즉시 Recovery를 유발하므로 재전송 루프가 필요 없다."],["The mechanisms that use DLLPs are self-repairing: a later DLLP supersedes any information that was lost. There may be a performance penalty.","DLLPs are protected by LCRC and a Sequence Number, so loss is impossible.","A lost DLLP is always piggybacked on the next TLP header and resent.","DLLP loss immediately causes Recovery, so a retry loop is unnecessary."],0,"정답 요지: DLLP를 사용하는 메커니즘이 self-repairing이라, 다음 DLLP가 잃어버린 정보를 대체한다. 성능 손해는 있을 수 있다.","Key point: The mechanisms that use DLLPs are self-repairing: a later DLLP supersedes any information that was lost. There may be a performance penalty.","§3.1"],["p3q07","p3_2",2,"C","Non-Flit Mode와 Flit Mode에서 DLLP가 실리는 형식의 차이는?","How does DLLP format differ between Non-Flit Mode and Flit Mode?",["Flit Mode DLLP는 32-bit LCRC를 사용하고 Sequence Number를 포함한다.","Non-Flit DLLP는 8 Byte, Flit DLLP는 항상 6 Byte 전체 Flit을 차지한다.","형식은 완전히 동일하고, Flit Mode에서도 각 DLLP 뒤에 16-bit CRC가 온다.","둘 다 DLLP Type + 24 bit type-specific 정보를 가진다. Non-Flit만 추가로 16-bit CRC를 붙이고, Flit에서는 Flit의 DLP Bytes에 실리며 per-DLLP CRC는 없다."],["A Flit Mode DLLP uses a 32-bit LCRC and includes a Sequence Number.","A Non-Flit DLLP is 8 bytes, and a Flit DLLP always occupies an entire 6-byte-less Flit.","The format is identical, and Flit Mode also appends a 16-bit CRC after each DLLP.","Both have a DLLP Type and 24 bits of type-specific information. Only Non-Flit Mode appends a 16-bit CRC; in Flit Mode the DLLP is carried in the Flit’s DLP bytes with no per-DLLP CRC."],3,"§3.5.1: NFM은 Type + 24 bit + 16-bit CRC. FM은 Type + 24 bit를 Flit DLP에 실으며 per-DLLP CRC가 없다. Flit 무결성은 Flit CRC/FEC로 검사한다.","In Non-Flit Mode a DLLP is Type + 24 bits + a 16-bit CRC. In Flit Mode it is Type + 24 bits in the Flit DLP, with no per-DLLP CRC; Flit integrity is checked by the Flit CRC and FEC.","§3.5.1, §3.6.2.3"],["p3q08","p3_2",2,"C","DLLP Type encoding 0000 0000b의 Non-Flit Mode와 Flit Mode 의미는?","What does DLLP Type encoding 0000 0000b mean in Non-Flit Mode versus Flit Mode?",["두 모드 모두 Ack이다.","Non-Flit Mode에서는 Ack, Flit Mode에서는 NOP2이다.","Non-Flit Mode에서는 NOP, Flit Mode에서는 Ack이다.","두 모드 모두 Reserved이다."],["Ack in both modes.","Ack in Non-Flit Mode, and NOP2 in Flit Mode.","NOP in Non-Flit Mode, and Ack in Flit Mode.","Reserved in both modes."],1,"정답 요지: Non-Flit Mode에서는 Ack, Flit Mode에서는 NOP2이다.","Key point: Ack in Non-Flit Mode, and NOP2 in Flit Mode.","§3.5.1, Table 3-5"],["p3q09","p3_2",1,"C","수신한 DLLP의 Type이 Receiver가 지원하지 않는 encoding이면?","What should a Receiver do with a DLLP whose Type encoding it does not support?",["Bad DLLP로 보고하고 AER에 기록한다.","조용히 무시(discard)하며, 이는 에러로 간주하지 않는다.","Nak을 보내 재전송을 요청한다.","Malformed TLP로 처리한다."],["Report a Bad DLLP and log it in AER.","Silently ignore (discard) it. This is not considered an error.","Send a Nak to request retransmission.","Handle it as a Malformed TLP."],1,"정답 요지: 조용히 무시(discard)하며, 이는 에러로 간주하지 않는다.","Key point: Silently ignore (discard) it. This is not considered an error.","§3.5.1, Table 3-5, §3.6.2.2, §3.6.2.3"],["p3q10","p3_3",1,"P","Flit Mode에서 Non-Flit의 Ack/Nak DLLP 대신 쓰는 메커니즘은?","In Flit Mode, what is used instead of Non-Flit Ack/Nak DLLPs?",["여전히 Ack/Nak DLLP를 DLP Bytes 2..5에 그대로 실어 보낸다.","FEC가 모든 오류를 정정하므로 Ack/Nak이 필요 없다.","UpdateFC DLLP의 예약 비트로 누적 Ack를 표시한다.","각 Flit DLP의 Replay Command 필드(2 bit)와 10-bit Flit Sequence Number."],["Ack/Nak DLLPs are still sent, placed unchanged in DLP bytes 2..5.","FEC corrects all errors, so Ack/Nak is unnecessary.","A reserved bit in the UpdateFC DLLP carries a cumulative Ack.","The 2-bit Replay Command field in each Flit’s DLP, plus the 10-bit Flit Sequence Number."],3,"정답 요지: 각 Flit DLP의 Replay Command 필드(2 bit)와 10-bit Flit Sequence Number.","Key point: The 2-bit Replay Command field in each Flit’s DLP, plus the 10-bit Flit Sequence Number.","§3.6.2.3, §4.2.3.4.2, Table 4-17"],["p3q11","p3_3",2,"C","Flit Replay Command 10b와 11b의 차이는?","What is the difference between Flit Replay Command encodings 10b and 11b?",["10b는 아직 Ack되지 않은 모든 Flit의 Replay를 요청하는 Standard Nak이고, 11b는 (포함된 Seq + 1)인 한 Flit만 재요청하는 Selective Nak이다. 둘 다 포함된 Seq는 마지막으로 수신한 valid Flit의 번호이다.","10b는 Ack, 11b는 모든 Flit의 재전송을 요청한다.","10b와 11b는 동일하며, Receiver 구현이 선택한다.","11b는 Standard Nak, 10b는 다음 10개 Flit만 재요청한다."],["10b is a Standard Nak requesting replay of all unacknowledged Flits; 11b is a Selective Nak requesting replay of the single Flit (Sequence Number + 1). In both cases the included Sequence Number is that of the last valid Flit received.","10b is an Ack, and 11b requests replay of every Flit.","10b and 11b are equivalent; the Receiver implementation may choose either.","11b is a Standard Nak, and 10b requests replay of only the next 10 Flits."],0,"정답 요지: 10b는 아직 Ack되지 않은 모든 Flit의 Replay를 요청하는 Standard Nak이고, 11b는 (포함된 Seq + 1)인 한 Flit만 재요청하는 Selective Nak이다. 둘 다 포함된 Seq는 마지막으로 수신한 valid Flit의 번호이다.","Key point: 10b is a Standard Nak requesting replay of all unacknowledged Flits; 11b is a Selective Nak requesting replay of the single Flit (Sequence Number + 1). In both cases the included Sequence Number is that of the last valid Flit received.","§4.2.3.4.2, Table 4-17"],["p3q12","p3_3",2,"C","Non-Flit Mode Ack/Nak DLLP의 AckNak_Seq_Num에 들어가는 값은?","In Non-Flit Mode, what value is placed in the AckNak_Seq_Num field of an Ack or Nak DLLP?",["NEXT_TRANSMIT_SEQ (다음에 보낼 TLP 번호)","ACKD_SEQ + 1","NEXT_RCV_SEQ - 1 (마지막으로 성공적으로 받은 TLP의 sequence number)","항상 000h"],["NEXT_TRANSMIT_SEQ (the next TLP to be transmitted)","ACKD_SEQ + 1","NEXT_RCV_SEQ − 1 (the sequence number of the last successfully received TLP)","Always 000h"],2,"정답 요지: NEXT_RCV_SEQ - 1 (마지막으로 성공적으로 받은 TLP의 sequence number)","Key point: NEXT_RCV_SEQ − 1 (the sequence number of the last successfully received TLP)","§3.6.3.1"],["p3q13","p3_3",2,"C","outstanding unacknowledged TLP이 없는 상태에서 Ack DLLP를 받은 경우, 에러인가?","Is it an error to receive an Ack DLLP when there are no outstanding unacknowledged TLPs?",["항상 Data Link Protocol Error이다.","항상 그 Ack를 버리고 Recovery로 들어간다.","REPLAY_NUM을 1 증가시키지만 에러는 보고하지 않는다.","지정된 sequence number가 ACKD_SEQ와 같으면 에러가 아니다 (리셋 후 첫 TLP 전 포함)."],["Yes, it is always a Data Link Protocol Error.","Yes; the Ack is discarded and the Port enters Recovery.","REPLAY_NUM is incremented by 1, but no error is reported.","No, it is not an error if the specified sequence number matches ACKD_SEQ, including the time between reset and the first TLP transmission."],3,"정답 요지: 지정된 sequence number가 ACKD_SEQ와 같으면 에러가 아니다 (리셋 후 첫 TLP 전 포함).","Key point: No, it is not an error if the specified sequence number matches ACKD_SEQ, including the time between reset and the first TLP transmission.","§3.6.2.2"],["p3q14","p3_3",3,"C","Replay 중에 Nak을 받은 뒤, 더 나중 sequence number를 지정하는 Ack가 도착하면?","During a replay, if a Nak is received and then an Ack specifying a later Sequence Number arrives, what happens?",["Nak이 항상 우선하므로 이미 시작한 replay를 처음부터 다시 시작한다.","그 Ack가 Nak을 대체(supersede)하므로 Nak은 무시된다. 여러 Ack는 가장 나중 번호만 유효하다(collapse).","둘 다 무시하고 REPLAY_TIMER만 리셋한다.","구현 정의이며, 표준은 순서를 규정하지 않는다."],["The Nak always takes priority, so the replay already in progress is restarted from the beginning.","The Ack supersedes the Nak, and the Nak is ignored. Multiple Acks are collapsed so that only the one with the latest sequence number is considered.","Both are ignored and only the REPLAY_TIMER is reset.","It is implementation-defined; the specification does not constrain the order."],1,"정답 요지: 그 Ack가 Nak을 대체(supersede)하므로 Nak은 무시된다. 여러 Ack는 가장 나중 번호만 유효하다(collapse).","Key point: The Ack supersedes the Nak, and the Nak is ignored. Multiple Acks are collapsed so that only the one with the latest sequence number is considered.","§3.6.2.1"],["p3q15","p3_4",1,"C","Non-Flit Mode에서 Retry Buffer에 저장되는 것과 저장되지 않는 것은?","In Non-Flit Mode, what is stored in the Retry Buffer and what is not?",["모든 TLP와 모든 DLLP를 저장한다.","Ack/Nak DLLP만 저장하고 TLP는 Transaction Layer 버퍼에 남긴다.","전송된 TLP의 복사본은 저장하지만, nullified TLP는 저장하지 않는다.","nullified TLP만 저장해 나중에 재전송한다."],["Every TLP and every DLLP is stored.","Only Ack/Nak DLLPs are stored; TLPs remain in a Transaction Layer buffer.","Copies of transmitted TLPs are stored, except for nullified TLPs.","Only nullified TLPs are stored, so they can be retransmitted later."],2,"정답 요지: 전송된 TLP의 복사본은 저장하지만, nullified TLP는 저장하지 않는다.","Key point: Copies of transmitted TLPs are stored, except for nullified TLPs.","§3.6.2.1"],["p3q16","p3_4",2,"C","16.0 GT/s 이상을 지원하는 구현이 Non-Flit Mode에서 써야 하는 Simplified REPLAY_TIMER Limit은? (Extended Synch가 Clear일 때)","For implementations that support 16.0 GT/s or higher, what Simplified REPLAY_TIMER Limit must be used in Non-Flit Mode when the Extended Synch bit is Clear?",["24,000 ~ 31,000 Symbol Times (inclusive, −0%/+0%)","4,096 ~ 8,192 Symbol Times","80,000 ~ 100,000 Symbol Times","Link width와 MPS에 따라 Table 3-10/11/12에서 고른다"],["24,000 to 31,000 Symbol Times inclusive (−0%/+0%)","4,096 to 8,192 Symbol Times","80,000 to 100,000 Symbol Times","A value taken from Tables 3-10/11/12, depending on Link width and MPS"],0,"Simplified limits: Extended Synch Clear이면 24,000–31,000 ST, Set이면 80,000–100,000 ST. 16.0 GT/s 이상 지원 구현은 Non-Flit의 모든 속도에서 Simplified limits를 써야 한다. Flit Mode는 §4.2.3.4.2.1.6 Replay Schedule Rule 0을 따른다.","The Simplified limits are 24,000–31,000 ST when Extended Synch is Clear and 80,000–100,000 ST when it is Set. Implementations that support 16.0 GT/s or higher must use these limits at all rates in Non-Flit Mode. Flit Mode uses Replay Schedule Rule 0 in §4.2.3.4.2.1.6.","§3.6.2.1"],["p3q17","p3_4",2,"C","Non-Flit Mode에서 replay가 시작될 때 REPLAY_NUM과 Link retraining 조건은?","In Non-Flit Mode, how is REPLAY_NUM updated when a replay starts, and when is Link retraining signaled?",["REPLAY_NUM(3-bit)을 2만큼 증가시킨다. 110b 또는 111b에서 000b 또는 001b로 롤오버하면 Physical Layer에 Link retraining을 요청한다. Retry Buffer는 LinkUp=0b가 아니면 리셋되지 않는다.","REPLAY_NUM을 1만큼 증가시키고, 111b가 되면 즉시 DL_Inactive로 간다.","Nak을 받을 때마다 REPLAY_NUM을 0으로만 만들고 retraining은 하지 않는다.","REPLAY_NUM은 소프트웨어가 읽고 쓰며, 하드웨어는 4회 timeout 후만 Recovery로 간다."],["REPLAY_NUM (3 bits) is incremented by 2. If it rolls over from 110b or 111b to 000b or 001b, the Transmitter signals the Physical Layer to retrain the Link. The Retry Buffer is not reset unless Physical LinkUp becomes 0b.","REPLAY_NUM is incremented by 1, and the DLCMSM goes to DL_Inactive when it reaches 111b.","REPLAY_NUM is only cleared to 0 on every Nak, and retraining never occurs.","Software reads and writes REPLAY_NUM; hardware enters Recovery only after four timeouts."],0,"정답 요지: REPLAY_NUM(3-bit)을 2만큼 증가시킨다. 110b 또는 111b에서 000b 또는 001b로 롤오버하면 Physical Layer에 Link retraining을 요청한다. Retry Buffer는 LinkUp=0b가 아니면 리셋되지 않는다.","Key point: REPLAY_NUM (3 bits) is incremented by 2. If it rolls over from 110b or 111b to 000b or 001b, the Transmitter signals the Physical Layer to retrain the Link. The Retry Buffer is not reset unless Physical LinkUp becomes 0b.","§3.6.2.1"],["p3q18","p3_4",2,"P","Flit Mode replay에서 재전송되는 것과 Retry Buffer에 들어가는 것은?","In Flit Mode replay, what is retransmitted, and what is stored in the Retry Buffer?",["Flit 256 Byte 전체가 원본 그대로 재전송된다.","DLP만 재전송되고 TLP는 새 Sequence Number로 다시 만들어진다.","TLP Bytes만 재전송(replay)되고, DLP는 최신 Data Link payload로 바뀐다. DLLP와 Optimized_Update_FC는 Retry Buffer에 넣지 않지만, Flit_Marker는 TLP payload와 함께 저장된다.","IDLE Flit만 저장·재전송되며 Payload Flit은 FEC가 담당한다."],["The entire original 256-byte Flit is retransmitted unchanged.","Only the DLP is replayed; TLPs are rebuilt with a new Sequence Number.","Only TLP bytes are replayed; the DLP is replaced with the latest Data Link payload. DLLPs and Optimized_Update_FCs are not stored in the Retry Buffer, but Flit_Markers are stored with the TLP payload.","Only IDLE Flits are stored and replayed; Payload Flits are left to FEC."],2,"정답 요지: TLP Bytes만 재전송(replay)되고, DLP는 최신 Data Link payload로 바뀐다. DLLP와 Optimized_Update_FC는 Retry Buffer에 넣지 않지만, Flit_Marker는 TLP payload와 함께 저장된다.","Key point: Only TLP bytes are replayed; the DLP is replaced with the latest Data Link payload. DLLPs and Optimized_Update_FCs are not stored in the Retry Buffer, but Flit_Markers are stored with the TLP payload.","§4.2.3.3, §3.6.2.3, §4.2.3.4.2, Table 4-16 note 67"],["p3q19","p3_5",1,"C","Non-Flit Mode TLP Sequence Number의 폭과, DL_Inactive에서의 NEXT_TRANSMIT_SEQ / ACKD_SEQ 초기값은?","In Non-Flit Mode, what is the width of the TLP Sequence Number, and what are the DL_Inactive values of NEXT_TRANSMIT_SEQ and ACKD_SEQ?",["8-bit. 둘 다 00h","12-bit. NEXT_TRANSMIT_SEQ=000h, ACKD_SEQ=FFFh","12-bit. 둘 다 000h","16-bit. NEXT_TRANSMIT_SEQ=0001h, ACKD_SEQ=0000h"],["8 bits. Both are 00h","12 bits. NEXT_TRANSMIT_SEQ=000h, ACKD_SEQ=FFFh","12 bits. Both are 000h","16 bits. NEXT_TRANSMIT_SEQ=0001h, ACKD_SEQ=0000h"],1,"정답 요지: 12-bit. NEXT_TRANSMIT_SEQ=000h, ACKD_SEQ=FFFh","Key point: 12 bits. NEXT_TRANSMIT_SEQ=000h, ACKD_SEQ=FFFh","§3.6.2.1"],["p3q20","p3_5",2,"C","Transmitter가 Transaction Layer로부터 새 TLP 수락을 멈춰야 하는 조건은?","When must a Transmitter stop accepting new TLPs from the Transaction Layer?",["Retry Buffer에 TLP가 하나라도 있으면 수락을 중단한다.","REPLAY_TIMER가 동작 중이면 수락을 중단한다.","(NEXT_TRANSMIT_SEQ − ACKD_SEQ) mod 4096 == 0 이면 수락을 중단한다.","(NEXT_TRANSMIT_SEQ − ACKD_SEQ) mod 4096 >= 2048 이면 이 식이 거짓이 될 때까지 수락을 중단한다."],["It must cease accepting TLPs whenever the Retry Buffer contains any TLP.","It must cease accepting TLPs whenever REPLAY_TIMER is running.","It must cease accepting TLPs if (NEXT_TRANSMIT_SEQ − ACKD_SEQ) mod 4096 == 0.","If (NEXT_TRANSMIT_SEQ − ACKD_SEQ) mod 4096 >= 2048, it must cease accepting TLPs until that equation is no longer true."],3,"Equation 3-1 Tx SEQ Stall이 바로 그 조건이다. 12-bit 공간에서 최대 2048개 미만의 unacked TLP만 허용한다. nullified TLP는 NEXT_TRANSMIT_SEQ를 증가시키지 않는다.","That condition is Equation 3-1 (Tx SEQ Stall). At most fewer than 2048 unacknowledged TLPs are allowed in the 12-bit sequence space. A nullified TLP does not increment NEXT_TRANSMIT_SEQ.","§3.6.2.1"],["p3q21","p3_5",2,"C","Flit Sequence Number의 폭과, DL_Inactive에서 NEXT_TX_FLIT_SEQ_NUM의 값은?","What is the width of the Flit Sequence Number, and what is NEXT_TX_FLIT_SEQ_NUM in DL_Inactive?",["12-bit이며, 000h로 설정된다.","10-bit이며, 000h로 설정된다.","10-bit이며, DL_Inactive에서 001h로 설정된다.","8-bit이며, FFh로 설정된다."],["12 bits, and it is set to 000h.","10 bits, and it is set to 000h.","10 bits, and it is set to 001h in the DL_Inactive state.","8 bits, and it is set to FFh."],2,"정답 요지: 10-bit이며, DL_Inactive에서 001h로 설정된다.","Key point: 10 bits, and it is set to 001h in the DL_Inactive state.","§4.2.3.4.2.1, Table 4-16"],["p3q22","p3_6",2,"C","Non-Flit Mode TLP LCRC의 다항식 계수와 seed는?","What are the Non-Flit Mode TLP LCRC polynomial coefficients and seed?",["계수는 04C1 1DB7h, seed는 FFFF FFFFh이며, 계산 remainder를 complement하여 32-bit LCRC 필드에 넣는다.","계수는 04C1 1DB7h, seed는 0000 0000h이며 complement하지 않는다.","DLLP와 같은 16-bit CRC, seed FFFFh를 쓴다.","계수는 1EDC 6F41h, seed는 FFFF FFFFh이다."],["The coefficients are 04C1 1DB7h and the seed is FFFF FFFFh. The remainder is complemented and mapped into the 32-bit LCRC field.","The coefficients are 04C1 1DB7h and the seed is 0000 0000h, with no complement.","It uses the same 16-bit CRC as a DLLP, with seed FFFFh.","The coefficients are 1EDC 6F41h and the seed is FFFF FFFFh."],0,"정답 요지: 계수는 04C1 1DB7h, seed는 FFFF FFFFh이며, 계산 remainder를 complement하여 32-bit LCRC 필드에 넣는다.","Key point: The coefficients are 04C1 1DB7h and the seed is FFFF FFFFh. The remainder is complemented and mapped into the 32-bit LCRC field.","§3.6.2.1"],["p3q23","p3_6",2,"C","Transmitter가 TLP를 nullify할 때 LCRC와 Sequence Number는 어떻게 다루나?","When a Transmitter nullifies a TLP, how are the LCRC and Sequence Number handled?",["LCRC를 0으로 채우고 Sequence Number만 증가시킨다.","정상적인 complement LCRC를 쓰되 EDB Token만 붙인다.","LCRC를 생략하고 Sequence Number를 FFFh로 넣는다.","보통과 달리 LCRC remainder를 inversion(complement)하지 않은 채 사용하고, NEXT_TRANSMIT_SEQ는 증가시키지 않는다."],["It fills the LCRC with zeros and still increments the Sequence Number.","It uses the normal complemented LCRC and only appends an EDB Token.","It omits the LCRC and places FFFh in the Sequence Number.","It uses the calculated LCRC remainder without inversion (the logical inverse of the normal value) and does not increment NEXT_TRANSMIT_SEQ."],3,"정답 요지: 보통과 달리 LCRC remainder를 inversion(complement)하지 않은 채 사용하고, NEXT_TRANSMIT_SEQ는 증가시키지 않는다.","Key point: It uses the calculated LCRC remainder without inversion (the logical inverse of the normal value) and does not increment NEXT_TRANSMIT_SEQ.","§3.6.2.1"],["p3q24","p3_6",1,"C","Non-Flit Mode에서 수신 DLLP의 CRC가 계산값과 다르면?","In Non-Flit Mode, what happens if a received DLLP’s CRC does not match the calculated value?",["Nak을 보내 TLP와 함께 재전송을 요청한다.","그 DLLP는 discard되고, Bad DLLP error로 해당 Port에 보고된다.","조용히 무시하며 에러로 보고하지 않는다 (unsupported Type과 같다).","LCRC를 재계산해 맞으면 그대로 사용한다."],["A Nak is sent to request retransmission together with TLPs.","The DLLP is discarded, and a Bad DLLP error is reported associated with the Port.","It is silently ignored and is not reported as an error (the same as an unsupported Type).","The LCRC is recomputed and the DLLP is used if that check passes."],1,"정답 요지: 그 DLLP는 discard되고, Bad DLLP error로 해당 Port에 보고된다.","Key point: The DLLP is discarded, and a Bad DLLP error is reported associated with the Port.","§3.6.2.2, §3.6.2.3"],["p3q25","p3_7",1,"C","Shared Flow Control은 어느 모드에서 enable되는가?","In which mode is Shared Flow Control enabled?",["두 모드 모두 enable이 필수이다.","Flit Mode에서 enable되고, Non-Flit Mode에서는 disable된다.","Non-Flit Mode에서만 enable되고, Flit Mode는 Dedicated만 쓴다.","16.0 GT/s 이상 Non-Flit에서만 enable된다."],["It is required to be enabled in both modes.","It is enabled in Flit Mode and disabled in Non-Flit Mode.","It is enabled only in Non-Flit Mode; Flit Mode uses only dedicated credits.","It is enabled only in Non-Flit Mode at 16.0 GT/s and above."],1,"정답 요지: Flit Mode에서 enable되고, Non-Flit Mode에서는 disable된다.","Key point: It is enabled in Flit Mode and disabled in Non-Flit Mode.","§3.4"],["p3q26","p3_7",2,"C","FC_INIT1에서 보내야 하는 InitFC1 DLLP 집합은 Non-Flit와 Flit에서 어떻게 다른가?","How does the set of InitFC1 DLLPs that must be sent in FC_INIT1 differ between Non-Flit Mode and Flit Mode?",["두 모드 모두 Dedicated P/NP/Cpl 세 개만 보낸다.","Flit Mode는 Shared 세 개만 보내고 Dedicated는 UpdateFC로 알린다.","둘 다 VC마다 InitFC1 하나를 보내며, P/NP/Cpl은 payload 필드로 구분한다.","Non-Flit는 Dedicated P, NP, Cpl 세 개. Flit Mode는 그 다음 Shared P, NP, Cpl을 더해 여섯 개. 상대 순서도 이 순서를 따른다. 적어도 34 μs마다 한 번씩 전송해야 한다."],["Both modes send only the three Dedicated P/NP/Cpl InitFC1 DLLPs.","Flit Mode sends only the three Shared DLLPs; Dedicated credits are advertised with UpdateFC.","Both modes send one InitFC1 per VC, distinguishing P/NP/Cpl in a payload field.","Non-Flit Mode sends three Dedicated InitFC1 DLLPs (P, NP, Cpl). Flit Mode then adds Shared P, NP, and Cpl, for six in all, in that relative order. They must be transmitted at least once every 34 μs."],3,"정답 요지: Non-Flit는 Dedicated P, NP, Cpl 세 개. Flit Mode는 그 다음 Shared P, NP, Cpl을 더해 여섯 개. 상대 순서도 이 순서를 따른다. 적어도 34 μs마다 한 번씩 전송해야 한다.","Key point: Non-Flit Mode sends three Dedicated InitFC1 DLLPs (P, NP, Cpl). Flit Mode then adds Shared P, NP, and Cpl, for six in all, in that relative order. They must be transmitted at least once every 34 μs.","§3.4.1"],["p3q27","p3_7",2,"C","FC_INIT2에서 수신한 InitFC1/InitFC2의 HdrFC·DataFC 값은 어떻게 다루며, FI2는 언제 Set되나?","In FC_INIT2, how are HdrFC and DataFC in received InitFC1/InitFC2 handled, and when is FI2 Set?",["수신한 HdrFC/DataFC(및 Scale) 값은 ignore한다. FI2는 해당 VC의 InitFC2를 받거나, 그 VC의 TLP 또는 UpdateFC(Flit에서는 Optimized_Update_FC 포함)를 받으면 Set된다.","수신값을 다시 기록해 광고를 갱신하고, FI2는 6개 InitFC2를 모두 받아야만 Set된다.","FC_INIT2에서는 DLLP를 처리하지 않고, FI2는 34 μs timer만으로 Set된다.","InitFC2의 값이 InitFC1과 다르면 Malformed로 처리하고 FI2를 Set하지 않는다."],["Received HdrFC/DataFC (and Scale) values are ignored. FI2 is Set on receipt of any InitFC2 for that VC, or of any TLP or UpdateFC for that VC (in Flit Mode, also any Optimized_Update_FC).","The received values are recorded again to refresh the advertisement, and FI2 is Set only after all six InitFC2 DLLPs have been received.","DLLPs are not processed in FC_INIT2, and FI2 is Set only by a 34 μs timer.","If an InitFC2 value differs from InitFC1, it is treated as Malformed and FI2 is not Set."],0,"정답 요지: 수신한 HdrFC/DataFC(및 Scale) 값은 ignore한다. FI2는 해당 VC의 InitFC2를 받거나, 그 VC의 TLP 또는 UpdateFC(Flit에서는 Optimized_Update_FC 포함)를 받으면 Set된다.","Key point: Received HdrFC/DataFC (and Scale) values are ignored. FI2 is Set on receipt of any InitFC2 for that VC, or of any TLP or UpdateFC for that VC (in Flit Mode, also any Optimized_Update_FC).","§3.4.1"],["p3q28","p3_7",3,"C","Flit Mode Shared credits의 [Merged]에 대한 설명으로 옳은 것은?","Which statement about [Merged] shared credits in Flit Mode is correct?",["[Merged]는 Dedicated P/NP/Cpl을 하나의 pool로 합친다.","[Merged]는 Shared Non-Posted와 Shared Posted만 합칠 수 있다.","[Merged]는 Shared Completion이 Shared Posted와 같은 credit pool을 쓰겠다는 뜻이다. Shared Posted나 Shared Non-Posted에는 허용되지 않고, Dedicated credits는 절대 merge되지 않는다.","[Merged]는 VC마다 서로 다르게 켜고 끌 수 있으며 CplH만 merge하고 CplD는 별개여도 된다."],["[Merged] combines Dedicated P/NP/Cpl into one pool.","[Merged] may combine only Shared Non-Posted and Shared Posted credits.","[Merged] means Shared Completions share a common pool with Shared Posted credits. It is not permitted on Shared Posted or Shared Non-Posted credits, and dedicated credits are never merged.","[Merged] may be enabled independently per VC, and CplH may be merged while CplD remains separate."],2,"정답 요지: [Merged]는 Shared Completion이 Shared Posted와 같은 credit pool을 쓰겠다는 뜻이다. Shared Posted나 Shared Non-Posted에는 허용되지 않고, Dedicated credits는 절대 merge되지 않는다.","Key point: [Merged] means Shared Completions share a common pool with Shared Posted credits. It is not permitted on Shared Posted or Shared Non-Posted credits, and dedicated credits are never merged.","§3.4.1, Table 3-3"],["p3q29","p3_8",1,"C","Data payload에 대한 Flow Control unit size는?","What is the Flow Control unit size for data payload?",["1 DW (4 bytes).","1 Header당 무한대이며 payload는 credit을 쓰지 않는다.","Max_Payload_Size와 같은 값 (예: 128 또는 256 bytes).","4 DW (16 bytes). n = Roundup(Length / FC unit size) (Length는 payload 크기, DW 단위)."],["1 DW (4 bytes).","Infinite per header; payload does not consume credits.","The same value as Max_Payload_Size (for example 128 or 256 bytes).","4 DW (16 bytes). n = Roundup(Length / FC unit size), where Length is the payload size in DW."],3,"정답 요지: 4 DW (16 bytes). n = Roundup(Length / FC unit size) (Length는 payload 크기, DW 단위).","Key point: 4 DW (16 bytes). n = Roundup(Length / FC unit size), where Length is the payload size in DW.","§2.6.1, Table 2-49"],["p3q30","p3_8",2,"C","HdrScale/DataScale 값 00b, 01b, 10b, 11b의 scaling factor는? (Scaled Flow Control 지원 시)","When Scaled Flow Control is supported, what scaling factors do HdrScale/DataScale values 00b, 01b, 10b, and 11b represent?",["네 값 모두 factor 1이다.","00b는 Scaled FC를 지원하지 않음(factor 1). 01b=1, 10b=4, 11b=16.","00b=1, 01b=2, 10b=4, 11b=8.","00b=infinite, 01b=1, 10b=4, 11b=16."],["All four values are factor 1.","00b means Scaled FC is not supported (factor 1). 01b=1, 10b=4, 11b=16.","00b=1, 01b=2, 10b=4, 11b=8.","00b=infinite, 01b=1, 10b=4, 11b=16."],1,"Table 3-6: 00b — Scaled FC Supported=No, factor 1, HdrFC[7:0]/DataFC[11:0]. 01b Yes factor 1 (같은 필드). 10b factor 4 (HdrFC[9:2], DataFC[13:2]). 11b factor 16 (HdrFC[11:4], DataFC[15:4]). 16.0 GT/s 이상 또는 Flit Mode enabled이면 Scaled FC 비트를 Set해야 한다.","Table 3-6: 00b means Scaled FC is not supported, factor 1 (HdrFC[7:0]/DataFC[11:0]). 01b is supported, factor 1 (same fields). 10b is factor 4 (HdrFC[9:2], DataFC[13:2]). 11b is factor 16 (HdrFC[11:4], DataFC[15:4]). The Scaled Flow Control feature bit must be Set in Ports that support 16.0 GT/s or higher and if Flit Mode is enabled.","§3.5.1, Table 3-6, §3.3, Table 3-1"],["p3q31","p3_8",2,"C","Flit Mode Optimized_Update_FC가 한 32-bit payload에 실을 수 있는 credit과, 추가로 요구되는 UpdateFC는?","Which credits can an Optimized_Update_FC carry in one 32-bit payload, and what additional UpdateFC is still required?",["Dedicated와 Shared의 모든 P/NP/Cpl Hdr·Data를 한 번에 보낸다.","Ack Sequence Number만 실으며 credit은 보내지 않는다.","Shared NPRH, PRH, PRD를 4 Byte에 담는다 (scale 필드 없음, 초기화 때 광고한 scale을 사용). 디버그/분석기를 위해 VC마다 스케일된 UpdateFC DLLP를 적어도 10 μs에 한 번 보내야 한다.","CplH/CplD만 보내고, UpdateFC DLLP는 더 이상 보내지 않아도 된다."],["It sends all Dedicated and Shared P/NP/Cpl header and data credits at once.","It carries only an Ack Sequence Number and no credits.","It carries Shared NPRH, PRH, and PRD in 4 bytes (no scale fields; the scales advertised at initialization are used). For debug and analyzers, a scaled UpdateFC DLLP must still be sent at least once every 10 μs per VC.","It sends only CplH/CplD, and UpdateFC DLLPs are no longer required."],2,"정답 요지: Shared NPRH, PRH, PRD를 4 Byte에 담는다 (scale 필드 없음, 초기화 때 광고한 scale을 사용). 디버그/분석기를 위해 VC마다 스케일된 UpdateFC DLLP를 적어도 10 μs에 한 번 보내야 한다.","Key point: It carries Shared NPRH, PRH, and PRD in 4 bytes (no scale fields; the scales advertised at initialization are used). For debug and analyzers, a scaled UpdateFC DLLP must still be sent at least once every 10 μs per VC.","§3.5.1, §4.2.3.4.2, Table 4-18"],["p3q32","p3_8",2,"C","I/O 또는 Configuration Write Request와 그 Completion이 소비하는 credit은?","What Flow Control credits do an I/O or Configuration Write Request and its Completion consume?",["Request는 1 NPH + 1 NPD. Completion은 1 CplH만 (CplD 없음).","Request는 1 NPH만. Completion은 1 CplH + 1 CplD.","Request는 1 PH + 1 PD (Posted로 취급). Completion은 credit을 쓰지 않는다.","Request는 1 NPH + n NPD (n=Length). Completion은 1 CplH + n CplD."],["The Request consumes 1 NPH + 1 NPD. The Completion consumes 1 CplH only (no CplD).","The Request consumes 1 NPH only. The Completion consumes 1 CplH + 1 CplD.","The Request consumes 1 PH + 1 PD (it is treated as Posted). The Completion consumes no credits.","The Request consumes 1 NPH + n NPD (n=Length). The Completion consumes 1 CplH + n CplD."],0,"정답 요지: Request는 1 NPH + 1 NPD. Completion은 1 CplH만 (CplD 없음).","Key point: The Request consumes 1 NPH + 1 NPD. The Completion consumes 1 CplH only (no CplD).","§2.6.1, Table 2-49"],["p3q33","p3_8",3,"C","Root Complex(모든 Root Port 사이 peer-to-peer를 지원하지 않는 경우)와 Endpoint의 Completion header credit 초기 광고는?","What is the minimum initial Completion header (CplH) credit advertisement for a Root Complex that does not support peer-to-peer traffic between all Root Ports, and for an Endpoint?",["infinite FC units","항상 1 header credit","Max_Payload_Size에 비례한 유한 값 (최소 8)","Flit Mode에서만 infinite이고, Non-Flit에서는 0이다."],["Infinite FC units","Always 1 header credit","A finite value proportional to Max_Payload_Size (minimum 8)","Infinite only in Flit Mode; 0 in Non-Flit Mode"],0,"Table 2-50는 해당 RC와 Endpoint에 대해 CplH(및 같은 취지의 Cpl 광고)를 “infinite FC units”로 규정한다. Switch나 P2P를 지원하는 RC는 유한 광고가 필요할 수 있다. Flit에서 [Merged]이면 shared pool에서 PH credits가 Completion에도 쓰인다.","Table 2-50 specifies infinite FC units for CplH for a Root Complex that does not support peer-to-peer traffic between all Root Ports, and for an Endpoint. A Switch, or an RC that supports P2P, may need a finite advertisement. In Flit Mode, if [Merged] is enabled, PH credits in the shared pool are used for Completions.","§2.6.1, Table 2-50"],["c3q01","c3_1",1,"X","CXL.io link layer로 쓰이는 것은?","What is used as the CXL.io link layer?",["PCIe Data Link Layer","CXL.cachemem Link Layer Retry(LLR)","ARB/MUX","Flex Bus electrical sub-block"],["The PCIe Data Link Layer","CXL.cachemem Link Layer Retry (LLR)","The ARB/MUX","The Flex Bus electrical sub-block"],0,"CXL.io는 TLP를 안정적으로 주고받기 위해 PCIe DLL을 그대로 씁니다.","CXL.io reuses the PCIe DLL to exchange TLPs reliably.","§4.1"],["c3q02","c3_1",1,"X","256B Flit mode에서 PCIe가 정의한 PM DLLP와 Link Management DLLP를 CXL.io에 쓸 수 있나요?","In 256B Flit mode, may CXL.io use the PCIe-defined PM and Link Management DLLPs?",["PM DLLP만 쓸 수 있다","Link Management DLLP만 쓸 수 있다","쓰면 안 된다","PCIe와 똑같이 모두 쓴다"],["Only PM DLLPs may be used","Only Link Management DLLPs may be used","No, they must not be used","Yes, all of them, exactly as in PCIe"],2,"256B Flit mode에서는 이 DLLP들이 CXL.io에 해당하지 않습니다. CXL의 링크 PM은 ALMP 등 CXL 메커니즘으로 처리됩니다.","In 256B Flit mode these DLLPs do not apply to CXL.io; link PM is handled by CXL mechanisms such as ALMPs.","§4.1"],["c3q03","c3_1",2,"X","68B Flit mode에서 CXL.io framing은 협상된 link width가 x4일 때 어떤 규칙을 따르나요?","In 68B Flit mode, which framing rules does CXL.io follow when the negotiated width is x4?",["PCIe의 x4 framing 규칙을 적용한다","폭과 관계없이 PCIe의 x16 framing 규칙만 적용한다","PCIe의 x1 framing 규칙을 적용한다","256B flit framing으로 바꾼다"],["The PCIe x4 framing rules","Only the PCIe x16 framing rules, regardless of width","The PCIe x1 framing rules","It switches to 256B flit framing"],1,"CXL.io는 항상 x16 기준으로 한 줄의 data stream을 만들고, 좁은 링크에서는 그 stream을 나눠 보냅니다. N=1/2/4/8 규칙은 쓰지 않습니다.","CXL.io always forms one x16-style stream and spreads it over narrower links; the N=1/2/4/8 rules do not apply.","§4.1"],["c3q04","c3_1",1,"C","PCIe non-Flit mode와, 그 DLL을 그대로 쓰는 68B Flit mode의 CXL.io에서 수신기가 TLP 재전송을 요청할 때 보내는 것은?","In PCIe non-Flit mode, and in 68B Flit mode CXL.io that reuses that DLL, what does a receiver send to request TLP retransmission?",["RETRY.Req flit","ALMP","Error VDM","NAK DLLP"],["A RETRY.Req flit","An ALMP","An Error VDM","A NAK DLLP"],3,"CXL.io는 PCIe DLL의 ACK/NAK 재전송을 그대로 씁니다. RETRY.Req는 68B CXL.cachemem LLR 전용입니다.","CXL.io reuses the PCIe DLL ACK/NAK replay. RETRY.Req belongs only to 68B CXL.cachemem LLR.","§4.1"],["c3q05","c3_2",1,"X","68B Flit mode에서 CXL.cache/CXL.mem 오류 flit은 어떻게 복구되나요?","In 68B Flit mode, how are errored CXL.cache/CXL.mem flits recovered?",["PCIe DLL의 ACK/NAK","Physical Layer의 FEC만으로","cachemem link layer의 Link Layer Retry(LLR)","소프트웨어 재시도"],["By PCIe DLL ACK/NAK","By Physical Layer FEC alone","By Link Layer Retry (LLR) in the cachemem link layer","By software retry"],2,"68B 모드에서 cachemem 쪽 재전송은 자체 link layer의 LLR이 맡습니다.","In 68B mode, cachemem retransmission is done by its own link layer LLR.","§4.2.8"],["c3q06","c3_2",1,"X","256B Flit mode에서 재전송(replay)을 맡는 계층은?","In 256B Flit mode, which layer handles retransmission (replay)?",["Physical Layer","CXL.cachemem Link Layer","CXL.io Transaction Layer","ARB/MUX"],["The Physical Layer","The CXL.cachemem Link Layer","The CXL.io Transaction Layer","The ARB/MUX"],0,"256B 모드는 PCIe Flit mode를 기반으로 하며, 신뢰성 흐름이 PHY에 있으므로 68B의 LLR 흐름은 쓰지 않습니다.","256B mode builds on PCIe Flit mode with reliability in the PHY, so the 68B LLR flows do not apply.","§4.3.1"],["c3q07","c3_2",2,"X","68B와 256B Flit mode의 retry buffer 구조 차이는?","How do retry buffers differ between 68B and 256B Flit modes?",["둘 다 ARB/MUX의 공유 buffer 하나를 쓴다","68B는 PHY에 있고 256B는 link layer마다 따로 있다","256B에는 retry buffer가 없다","68B는 CXL.io와 cachemem link layer가 각자 관리하고, 256B는 PHY의 통합 Tx retry buffer 하나가 모두 처리한다"],["Both use one shared buffer in the ARB/MUX","68B keeps it in the PHY; 256B has one per link layer","256B mode has no retry buffer","In 68B, the CXL.io and cachemem link layers each manage their own; in 256B, one unified PHY Tx retry buffer handles all"],3,"256B 모드에서는 PCIe처럼 PHY가 Tx retry buffer와 선택적 Rx retry buffer를 두며, 둘 다 모든 retry 대상 CXL 트래픽을 통합해 처리합니다.","In 256B mode the PHY holds a Tx retry buffer and an optional Rx retry buffer, each unified for all retryable CXL traffic.","§6.3"],["c3q08","c3_2",2,"C","256B flit header의 Flit Sequence Number 폭은? (PCIe Flit mode와 같음)","How wide is the Flit Sequence Number in the 256B flit header? (same as PCIe Flit mode)",["12 bit","10 bit","8 bit","16 bit"],["12 bits","10 bits","8 bits","16 bits"],1,"Replay Command와 10-bit Flit Sequence Number는 PCIe 정의를 그대로 따릅니다. 12 bit는 PCIe non-Flit DLL의 TLP sequence number 폭입니다.","Replay Command and the 10-bit Flit Sequence Number follow PCIe. 12 bits is the TLP sequence number width of the non-Flit PCIe DLL.","§6.2.3.1.1"],["c3q09","c3_3",1,"X","LLRB(Link Layer Retry Buffer)는 어디에 있고 무엇을 담나요?","Where is the LLRB (Link Layer Retry Buffer) and what does it hold?",["수신 측에 있고, 오류 flit을 보관한다","송신 측에 있고, 보낸 retry 대상 flit을 보관한다","ARB/MUX에 있고, ALMP만 보관한다","Host 메모리에 있고, TLP를 보관한다"],["At the receiver; it keeps errored flits","At the sender; it keeps retryable flits already sent","In the ARB/MUX; it keeps only ALMPs","In host memory; it keeps TLPs"],1,"송신기는 retry 대상 flit을 보낼 때마다 LLRB에 복사해 두고, ACK를 받으면 비웁니다.","The sender copies every retryable flit into its LLRB and frees entries when ACKs arrive.","§4.2.8"],["c3q10","c3_3",2,"X","PCIe DLL과 달리 CXL.cachemem LLR의 sequence number는 어떻게 다뤄지나요?","Unlike the PCIe DLL, how are CXL.cachemem LLR sequence numbers handled?",["flit마다 12-bit로 실어 보낸다","flit마다 10-bit로 실어 보낸다","sequence number를 전혀 쓰지 않는다","flit마다 보내지 않고, LLR 과정의 control flit에서만 교환한다"],["A 12-bit number rides in every flit","A 10-bit number rides in every flit","No sequence numbers are used at all","They are not sent with each flit; they are exchanged only in control flits during LLR"],3,"링크 효율을 위해 각 장치가 sequence number를 내부에서만 세고, 재전송이 일어날 때 RETRY control flit으로 맞춥니다. 초기값은 0입니다.","For efficiency each side tracks numbers internally and syncs them via RETRY control flits during a retry; they start at 0.","§4.2.8"],["c3q11","c3_3",1,"X","CXL.cachemem에서 flit header의 ACK bit 하나는 몇 개의 acknowledgment를 뜻하나요?","In CXL.cachemem, how many acknowledgments does one ACK bit in a flit header represent?",["8개","1개","4개","16개"],["8","1","4","16"],0,"ACK bit 하나가 8개의 acknowledgment를 나타내며, 수신 측 NumAck는 ACK를 실어 보낼 때 8씩 줄어듭니다.","One ACK bit stands for eight acknowledgments; the receiver's NumAck drops by 8 when it sends one.","§4.2.8.1"],["c3q12","c3_3",3,"X","LLR deadlock을 막기 위해 각 장치의 retry queue가 가져야 할 최소 entry 수는?","What is the minimum number of retry queue entries per device required to avoid LLR deadlock?",["16","8","22","255"],["16","8","22","255"],2,"Forced Ack 크기 16 + 최대 All-Data Flit 4 + 2 = 22입니다. 상한은 8-bit counter 때문에 255입니다.","Forced Ack size 16 + max All-Data Flit 4 + 2 = 22. The upper limit is 255 because of the 8-bit counter.","§4.2.8.1"],["c3q13","c3_3",3,"X","LLRB에 빈 entry가 1개만 남았을 때 송신기가 retry 대상 flit을 보낼 수 없는 이유는?","Why can't the sender send a retryable flit when only one LLRB entry is free?",["전력을 아끼기 위해","CRC 계산 시간을 확보하기 위해","ALMP 자리를 예약하기 위해","retry 중에 buffer가 가득 찬 것인지 빈 것인지 구분이 모호해지는 것을 막기 위해"],["To save power","To leave time for CRC calculation","To reserve room for ALMPs","To avoid ambiguity between a full and an empty buffer during a retry"],3,"그래서 NumFreeBuf는 0이 되지 않습니다. 2개 남았을 때는 ACK를 실은 flit만 보낼 수 있어 양쪽 buffer가 동시에 차는 deadlock도 막습니다.","So NumFreeBuf never reaches 0; with two left, only an ACK-bearing flit may go, which also prevents both sides filling up and deadlocking.","§4.2.8.1"],["c3q14","c3_4",1,"X","CXL.cachemem LLCTRL 종류 중 LLRB에 들어가지 않는(retry 대상이 아닌) 것은?","Which CXL.cachemem LLCTRL type is not retryable (does not enter the LLRB)?",["LLCRD","RETRY","INIT","IDE"],["LLCRD","RETRY","INIT","IDE"],1,"RETRY flit은 retry 대상이 아니고, LLCRD·IDE·INIT는 retry 대상입니다. Control flit은 credit 없이 보낼 수 있습니다.","RETRY flits are not retryable, while LLCRD, IDE and INIT are. Control flits need no credits.","§4.2.6"],["c3q15","c3_4",2,"X","RETRY.Req flit에 담기는 정보는?","What does a RETRY.Req flit carry?",["송신 측의 WrPtr만","CRC-16 다항식","수신 측의 기대 sequence number(ESeq)와 NUM_RETRY","Viral LD-ID Vector"],["Only the sender's WrPtr","The CRC-16 polynomial","The receiver's expected sequence number (ESeq) and NUM_RETRY","The Viral LD-ID Vector"],2,"ESeq는 상대가 다시 보낼 첫 flit 위치를 알려 줍니다. WrPtr는 RETRY.Ack에 디버그 용도로만 실리고, Viral 정보도 RETRY.Ack에 실립니다.","ESeq points to the first flit to resend. WrPtr rides in RETRY.Ack for debug only, and viral info also rides in RETRY.Ack.","§4.2.8.3"],["c3q16","c3_4",1,"X","RETRY.Ack에 실린 WrPtr 값은 retry state machine에서 어떻게 쓰이나요?","How is the WrPtr value in RETRY.Ack used by the retry state machines?",["쓰지 않는다. 디버그용일 뿐이다","재전송 시작 위치로 쓴다","NUM_RETRY를 초기화하는 데 쓴다","TIMEOUT 값을 정하는 데 쓴다"],["It is not used; it is for debug only","As the start point for resending","To reset NUM_RETRY","To set the TIMEOUT value"],0,"재전송 위치는 RETRY.Req의 ESeq로 정해지고, RETRY.Ack의 WrPtr는 디버그 정보입니다.","The resend point comes from ESeq in RETRY.Req; WrPtr in RETRY.Ack is debug information only.","§4.2.8.3"],["c3q17","c3_4",3,"X","RETRY.Req 앞에 RETRY.Frame flit을 몇 개 보내며, 그 이유는?","How many RETRY.Frame flits precede a RETRY.Req, and why?",["5개. All-Data Flit이 최대 4개 연달아 올 수 있어 RETRY flit으로 잘못 해석되는 것을 막는다","1개. CRC를 다시 맞추기 위해","2개. 양방향 각각 하나씩","8개. ACK 8개를 대신하기 위해"],["Five, because up to four All-Data Flits can come back to back and could be mistaken for a RETRY flit","One, to realign CRC","Two, one per direction","Eight, standing in for eight ACKs"],0,"All-Data Flit은 header가 없어 데이터가 우연히 RETRY 인코딩과 같을 수 있습니다. 5개의 RETRY.Frame으로 진짜 control sequence를 구분합니다.","All-Data Flits have no header, so data could alias a RETRY encoding; five RETRY.Frame flits mark a real control sequence.","§4.2.8.4"],["c3q18","c3_5",2,"X","LRSM(Local Retry State Machine)과 RRSM(Remote Retry State Machine)은 각각 어디서 동작하나요?","Where do the LRSM (Local Retry State Machine) and RRSM (Remote Retry State Machine) act?",["LRSM은 Host만, RRSM은 Device만","둘 다 ARB/MUX 안에만 있다","LRSM은 오류 flit을 받은 쪽, RRSM은 그 flit을 보낸 쪽","LRSM은 CXL.io, RRSM은 CXL.cachemem"],["LRSM only in the host, RRSM only in the device","Both live only in the ARB/MUX","LRSM at the side that received the bad flit; RRSM at the side that sent it","LRSM for CXL.io, RRSM for CXL.cachemem"],2,"양방향 링크라 모든 장치가 두 상태 머신을 다 가집니다. 오류를 감지한 쪽은 LRSM으로 RETRY.Req를 보내고, 상대는 RRSM으로 RETRY.Ack와 재전송을 합니다.","Every device has both. The detecting side uses LRSM to send RETRY.Req; the partner uses RRSM to send RETRY.Ack and resend.","§4.2.8.5"],["c3q19","c3_5",3,"X","NUM_RETRY가 MAX_NUM_RETRY에 도달했고 NUM_PHY_REINIT는 아직 한계 미만이면 LRSM은?","When NUM_RETRY reaches MAX_NUM_RETRY and NUM_PHY_REINIT is still below its limit, what does the LRSM do?",["곧바로 RETRY_ABORT로 가서 링크 실패를 알린다","RETRY_PHY_REINIT로 가서 Physical Layer에 retrain을 요청한다","NUM_RETRY를 0으로 돌리고 조용히 계속한다","LLRB를 비우고 재전송을 포기한다"],["It goes straight to RETRY_ABORT and reports link failure","It goes to RETRY_PHY_REINIT and asks the Physical Layer to retrain","It silently resets NUM_RETRY and carries on","It empties the LLRB and gives up resending"],1,"LLR 재시도가 반복 실패하면 PHY 재초기화를 시도하고, 그 횟수(NUM_PHY_REINIT)도 한계에 닿으면 RETRY_ABORT로 갑니다.","Repeated LLR failures trigger a PHY reinit; when NUM_PHY_REINIT also hits its limit, the LRSM goes to RETRY_ABORT.","§4.2.8.5.1"],["c3q20","c3_5",2,"X","LLR의 TIMEOUT counter는 무엇을 기준으로 증가하나요?","What makes the LLR TIMEOUT counter increment?",["link layer clock마다","수신 flit마다","1 µs마다","local Tx가 flit(protocol 또는 control)을 보낼 때마다"],["Every link layer clock","Every received flit","Every 1 µs","Each flit (protocol or control) the local Tx sends"],3,"저전력 전환처럼 링크가 멈추는 구간에 잘못 만료되지 않도록 송신 flit 수로 셉니다. 보낼 것이 없으면 RETRY.Idle을 넣어 계속 세게 합니다.","Counting sent flits avoids false expiry while the link is paused (e.g., power transitions); with nothing to send, RETRY.Idle flits keep it counting.","§4.2.8.5.2"],["c3q21","c3_5",2,"X","Link Layer가 vLSM의 Active→Retrain 전환을 감지하면 수신 측은?","When the link layer sees the vLSM go from Active to Retrain, what does the receiver side do?",["LLRB를 지우고 sequence number를 0으로 돌린다","ALMP로 PM 진입을 요청한다","다음 flit에 link layer retry를 강제로 건다","아무것도 하지 않는다"],["Clears the LLRB and resets sequence numbers to 0","Requests PM entry with an ALMP","Forces a link layer retry on the next flit","Does nothing"],2,"PHY 재초기화 중 선로 위의 flit이 사라지거나 sequence number가 어긋나지 않도록 LLR을 강제합니다.","Forcing LLR keeps in-flight flits from being lost or sequence numbers from slipping during the PHY reinit.","§4.2.8.6"],["c3q22","c3_6",1,"X","68B Flit mode의 CXL.cachemem flit 오류 검출에 쓰는 CRC는?","Which CRC detects errors in 68B Flit mode CXL.cachemem flits?",["528-bit flit 전체에 대한 16-bit CRC","TLP마다 붙는 32-bit LCRC","8B CRC와 6B FEC","CRC 없이 parity만 쓴다"],["A 16-bit CRC over the whole 528-bit flit","A 32-bit LCRC per TLP","An 8B CRC with a 6B FEC","Parity only, no CRC"],0,"CRC는 flit의 data 512 bit에 대해 계산되어 bit [527:512]에 실립니다. 32-bit LCRC는 PCIe non-Flit DLL 방식입니다.","The CRC is computed over data bits [511:0] and carried in bits [527:512]. A 32-bit LCRC is the non-Flit PCIe DLL scheme.","§4.2.8.7"],["c3q23","c3_6",1,"X","CXL.cachemem CRC-16 다항식이 보장하는 검출 성능은?","What detection does the CXL.cachemem CRC-16 polynomial guarantee?",["모든 오류를 정정한다","1-bit 오류만 검출한다","burst 오류만 검출하고 random 오류는 못 잡는다","1·2·3-bit 오류는 모두 검출한다"],["It corrects every error","It detects only 1-bit errors","It catches only burst errors, not random ones","It detects all 1-, 2- and 3-bit errors"],3,"다항식은 1F053h이고, 1·2·3-bit 완전 검출과 좋은 4-bit 검출 특성을 기준으로 골랐습니다. CRC는 검출만 하고 정정은 하지 않습니다.","The polynomial is 1F053h, chosen for perfect 1-, 2- and 3-bit detection and strong 4-bit detection. A CRC detects; it does not correct.","§4.2.8.7.1"],["c3q24","c3_7",2,"X","256B flit header의 Prior Flit Type bit는 무엇을 알려 주나요?","What does the Prior Flit Type bit in the 256B flit header tell the receiver?",["직전 flit의 Protocol ID","직전 flit이 NOP/IDLE이었는지. 그렇다면 CRC 오류가 나도 replay가 필요 없다","직전 flit의 FEC 결과","직전 flit이 68B였는지"],["The previous flit's Protocol ID","Whether the previous flit was a NOP/IDLE, which needs no replay even if it had a CRC error","The previous flit's FEC result","Whether the previous flit was 68B"],1,"0이면 직전 flit이 NOP 또는 IDLE(retry buffer에 넣지 않음), 1이면 Payload 또는 Empty flit(넣음)입니다.","0 means the prior flit was a NOP or IDLE (not in the retry buffer); 1 means Payload or Empty (in the buffer).","§6.2.3.1.1"],["c3q25","c3_7",1,"X","256B Flit mode에서 retry buffer에 넣지 않는 flit은?","In 256B Flit mode, which flit is not placed in the retry buffer?",["ALMP flit","CXL.io NOP flit","CXL.io Payload flit","CXL.cachemem Payload flit"],["An ALMP flit","A CXL.io NOP flit","A CXL.io Payload flit","A CXL.cachemem Payload flit"],1,"Physical Layer NOP, IDLE, CXL.io NOP은 retry buffer에 넣지 않습니다. ALMP와 payload flit은 넣으므로 ALMP도 replay로 보호됩니다.","Physical Layer NOP, IDLE and CXL.io NOP flits stay out of the retry buffer; ALMPs and payload flits go in, so ALMPs are replay-protected.","§6.2.3.1.1"],["c3q26","c3_7",2,"X","Latency-optimized 256B flit에서 한 half만 CRC 실패하면 retry 단위는?","With a latency-optimized 256B flit, if only one half fails CRC, what is the retry unit?",["실패한 128B half만","64B 조각","해당 TLP 하나","256B flit 전체"],["Only the failed 128B half","A 64B chunk","Just that TLP","The whole 256B flit"],3,"재전송은 항상 256B 단위입니다. 수신기는 이미 소비한 half를 기억했다가 재전송된 flit에서 그 half를 버려야 합니다.","Retries are always 256B. The receiver tracks which half it already consumed and drops that half from the resent flit.","§6.3"],["c3q27","c3_7",3,"X","256B Flit mode의 NOP Insertion Hint는 어떻게 표현되나요?","How is the NOP Insertion Hint expressed in 256B Flit mode?",["sequence number 0인 NAK","Prior Flit Type=1인 NOP","전용 ALMP","Flit Type 00b인 IDLE flit"],["A NAK with sequence number 0","A NOP with Prior Flit Type = 1","A dedicated ALMP","An IDLE flit with Flit Type 00b"],0,"CRC 오류 뒤 FEC 경로에 들어간 수신기가 빠른 경로로 돌아갈 틈을 얻으려고 상대에게 NOP 1~2개를 요청하는 힌트입니다.","After a CRC error forces the slow FEC path, the receiver asks the partner for one or two NOPs to get back to the fast path.","§6.4.1.3.3"],["c3q28","c3_8",2,"X","68B Flit mode에서 Viral 상태를 상대에게 알리는 방법은?","In 68B Flit mode, how is a viral condition conveyed to the link partner?",["protocol flit마다 viral bit를 둔다","PCIe ERR_FATAL 메시지를 보낸다","다음 flit에 일부러 CRC 오류를 내고, 이어지는 RETRY.Ack에 viral 정보를 싣는다","ALMP로 LinkError를 요청한다"],["A viral bit in every protocol flit","A PCIe ERR_FATAL message","It forces a CRC error on the next flit and carries viral status in the resulting RETRY.Ack","An ALMP requesting LinkError"],2,"protocol flit에 bit를 따로 쓰지 않고 즉시 알릴 수 있습니다. MLD를 위해 RETRY.Ack에 Viral LD-ID Vector도 있습니다.","This avoids spending a protocol-flit bit and signals at once; for MLDs, RETRY.Ack also has a Viral LD-ID Vector.","§4.2.9"],["c3q29","c3_8",3,"X","256B flit에서 viral이나 late poison 때문에 CRC를 일부러 오염시킬 때의 규칙은?","In 256B flits, what is the rule for deliberately corrupting CRC for viral or late poison?",["CRC를 0으로 채우고 FEC는 원래 CRC로 계산한다","FEC만 반전하고 CRC는 그대로 둔다","Flit Header의 Flit Type을 11b로 바꾼다","CRC field의 모든 bit를 반전하고, FEC는 반전된 CRC로 계산한다"],["Zero the CRC and compute FEC over the original CRC","Invert only FEC and leave CRC alone","Change the Flit Type to 11b","Invert every CRC bit and compute FEC over the inverted CRC"],3,"수신기가 flit을 거부해 replay가 일어나게 하고, replay 때 추가 정보를 넣습니다. Latency-optimized flit은 해당 half의 CRC만 반전합니다.","This makes the receiver reject the flit and trigger a replay that carries extra info; latency-optimized flits invert only the affected half's CRC.","§6.2.3.2"],["c3q30","c3_9",2,"X","LLCRD forcing이 필요한 이유는?","Why is LLCRD forcing needed?",["링크 속도를 올리려고","반대 방향 트래픽이 없어도 ACK와 credit을 돌려줘 송신 측 LLRB가 막히지 않게 하려고","CRC 오류를 숨기려고","ALMP를 대신하려고"],["To raise the link speed","To return ACKs and credits even with no reverse traffic, so the sender's LLRB does not stall","To hide CRC errors","To replace ALMPs"],1,"ACK가 일정 수(Ack Force Threshold) 쌓이거나 timer가 차면 LLCRD flit을 넣어 ACK/credit을 돌려줍니다. 대역폭 낭비를 막기 위해 조건을 둡니다.","An LLCRD flit is injected when pending ACKs reach the Ack Force Threshold or a timer fires; the limits keep bandwidth waste low.","§4.2.8.2"],["c3q31","c3_9",1,"X","CXL.cachemem LLR의 sequence number는 Link Layer 초기화 때 어떤 값으로 시작하나요?","What value do CXL.cachemem LLR sequence numbers start from at link layer initialization?",["1","255","0","무작위 값"],["1","255","0","A random value"],2,"sequence number는 초기화 때 0으로 정해지고, retry buffer 깊이에 닿으면 0으로 돌아가는 wraparound counter로 동작합니다.","They start at 0 at initialization and wrap back to 0 when they reach the retry buffer depth.","§4.2.8"]],"4":[["p4q01","p4_1",1,"C","PCI Express가 정의하는 네 가지 address space와 기본 용도는?","What four address spaces does PCI Express define, and what is each used for?",["Memory (메모리 맵 위치 접근), I/O (I/O 맵 위치), Configuration (Function 설정), Message (이벤트 시그널링·범용 메시지).","Memory, I/O, Interrupt, DMA.","Posted, Non-Posted, Completion, Prefix.","Physical, Data Link, Transaction, Software."],["Memory (access to a memory-mapped location), I/O (I/O-mapped location), Configuration (Function configuration/setup), and Message (event signaling and general-purpose messaging).","Memory, I/O, Interrupt, and DMA.","Posted, Non-Posted, Completion, and Prefix.","Physical, Data Link, Transaction, and Software."],0,"Table 2-1: Memory / I/O / Configuration / Message. Transaction은 Request와 (필요한 경우) Completion으로 전달된다. Split-Transaction 프로토콜이다.","Table 2-1 lists Memory, I/O, Configuration, and Message. Transactions are carried using Requests and, where required, Completions. The protocol is a pipelined full Split-Transaction protocol.","§2.1.1, Table 2-1"],["p4q02","p4_1",1,"C","다음 중 Posted Request로 분류되는 것은?","Which of the following are classified as Posted Requests?",["Memory Read, I/O Write, Configuration Write","모든 Write Request (Memory/I/O/Configuration)","Memory Write Request와 Message Request","Completion과 Message만"],["Memory Reads, I/O Writes, and Configuration Writes","All Write Requests (Memory, I/O, and Configuration)","Memory Write Requests and Message Requests","Only Completions and Messages"],2,"정답 요지: Memory Write Request와 Message Request","Key point: Memory Write Requests and Message Requests","§2.4.1, Table 2-42, §2.2, §2.6.1"],["p4q03","p4_1",2,"C","I/O Transactions가 사용하는 주소 형식은?","What address format do I/O Transactions use?",["32-bit와 64-bit를 Memory와 같이 모두 사용할 수 있다.","Short Address Format 32-bit address만 사용한다.","ID routing만 사용하므로 주소 필드가 없다.","항상 64-bit Long Address Format만 사용한다."],["Either 32-bit or 64-bit, as with Memory Transactions.","Only the Short Address Format 32-bit address.","Only ID routing, so there is no address field.","Always only the 64-bit Long Address Format."],1,"정답 요지: Short Address Format 32-bit address만 사용한다.","Key point: Only the Short Address Format 32-bit address.","§2.1.1.2, §2.1.1.1"],["p4q04","p4_1",2,"C","일반적인 (Non-UIO) Memory Write Request는 Completion을 요구하는가?","Does an ordinary (non-UIO) Memory Write Request require a Completion?",["항상 Cpl(데이터 없음) Completion이 필요하다.","Length가 1 DW를 넘으면 Completion이 필요하다.","Relaxed Ordering이 Set된 경우에만 Completion이 필요하다.","요구하지 않는다 (Posted). Completions are used only where required — 예: read data 반환, I/O·Configuration Write 완료 확인. 모든 UIO Request는 Completion이 필요하다."],["Yes, it always requires a Cpl (no-data) Completion.","Yes, if Length is greater than 1 DW.","Yes, but only when Relaxed Ordering is Set.","No (it is Posted). Completions are used only where required, for example to return read data or to acknowledge I/O and Configuration Writes. All UIO Requests require Completions."],3,"정답 요지: 요구하지 않는다 (Posted). Completions are used only where required — 예: read data 반환, I/O·Configuration Write 완료 확인. 모든 UIO Request는 Completion이 필요하다.","Key point: No (it is Posted). Completions are used only where required, for example to return read data or to acknowledge I/O and Configuration Writes. All UIO Requests require Completions.","§2.2, §2.1.1.1"],["p4q05","p4_2",1,"C","Non-Flit Mode Fmt[2:0] 값 000b, 001b, 010b, 011b, 100b의 의미는?","In Non-Flit Mode, what do Fmt[2:0] values 000b, 001b, 010b, 011b, and 100b mean?",["000b: Memory / 001b: I/O / 010b: Cfg / 011b: Message / 100b: Completion","000b: Posted / 001b: Non-Posted / 010b: Completion / 011b: Prefix / 100b: Reserved","000b: 3 DW header, no data / 001b: 4 DW, no data / 010b: 3 DW, with data / 011b: 4 DW, with data / 100b: TLP Prefix","상위 비트가 data 유무, 하위 두 비트가 TC이다. 100b는 ECRC 존재를 뜻한다."],["000b: Memory; 001b: I/O; 010b: Cfg; 011b: Message; 100b: Completion","000b: Posted; 001b: Non-Posted; 010b: Completion; 011b: Prefix; 100b: Reserved","000b: 3 DW header, no data; 001b: 4 DW, no data; 010b: 3 DW, with data; 011b: 4 DW, with data; 100b: TLP Prefix","The top bit indicates data, and the lower two bits are TC. 100b means an ECRC is present."],2,"Table 2-2가 이 다섯 encoding을 정의하고, 그 외는 Reserved이다. TLP 종류는 Fmt와 Type[4:0]의 조합(Table 2-3)으로 결정된다.","Table 2-2 defines those five encodings; all others are Reserved. The TLP type is determined by the combination of Fmt and Type[4:0] in Table 2-3.","§2.2.1.1, Table 2-2"],["p4q06","p4_2",2,"C","Non-Flit Mode에서 MRd와 MWr의 Type[4:0]은 어떻게 구분되는가?","In Non-Flit Mode, how are MRd and MWr distinguished in Type[4:0]?",["둘 다 Type[4:0]=0 0000b이고, Fmt가 no-data(000/001b)이면 MRd, with-data(010/011b)이면 MWr이다. 32-bit는 3 DW Fmt, 64-bit는 4 DW Fmt를 쓴다.","MRd는 Type 0 0001b, MWr는 0 0000b로 Type이 다르다.","MRd는 Fmt=100b Prefix를 먼저 붙인다.","Type 필드만 보고 구분하며, Fmt는 항상 001b이다."],["Both use Type[4:0]=0 0000b. Fmt no-data (000b/001b) means MRd and Fmt with-data (010b/011b) means MWr. 32-bit addressing uses a 3 DW Fmt; 64-bit uses a 4 DW Fmt.","They use different Type values: MRd is 0 0001b and MWr is 0 0000b.","MRd is always preceded by a Fmt=100b Prefix.","They are distinguished by Type alone; Fmt is always 001b."],0,"Table 2-3: MRd는 Fmt 000/001 + Type 0 0000, MWr는 Fmt 010/011 + Type 0 0000. Type 0 0001은 MRdLk이다. 혼동하기 쉬운 포인트이다.","Table 2-3: MRd is Fmt 000b/001b + Type 0 0000b; MWr is Fmt 010b/011b + Type 0 0000b. Type 0 0001b is MRdLk. This is a common source of confusion.","§2.2.1.1, Table 2-3"],["p4q07","p4_2",2,"C","Length[9:0] 필드에서 1 DW, 1023 DW, 1024 DW를 나타내는 값은?","In the Length[9:0] field, which encodings represent 1 DW, 1023 DW, and 1024 DW?",["00 0000 0000b = 0 DW (payload 없음), 00 0000 0001b = 1 DW, 11 1111 1111b = 1024 DW","Length는 byte 단위이므로 0001h=1 byte, 0000h=1024 bytes이다.","00 0000 0000b는 Reserved이고, 최대는 11 1111 1111b=1024 DW이다.","00 0000 0001b = 1 DW, 11 1111 1111b = 1023 DW, 00 0000 0000b = 1024 DW"],["00 0000 0000b = 0 DW (no payload), 00 0000 0001b = 1 DW, and 11 1111 1111b = 1024 DW","Length is in bytes, so 0001h = 1 byte and 0000h = 1024 bytes.","00 0000 0000b is Reserved, and the maximum is 11 1111 1111b = 1024 DW.","00 0000 0001b = 1 DW, 11 1111 1111b = 1023 DW, and 00 0000 0000b = 1024 DW"],3,"Table 2-4: 00 0000 0001b→1 DW, …, 11 1111 1111b→1023 DW, 00 0000 0000b→1024 DW. Length는 integral number of DW이며 4-byte naturally aligned이다. payload가 없거나 참조하지 않는 TLP(Cpl, CplLk, 대부분의 Message)에서 Length는 Reserved이다.","Table 2-4: 00 0000 0001b = 1 DW, 11 1111 1111b = 1023 DW, and 00 0000 0000b = 1024 DW. Length is an integral number of naturally 4-byte-aligned DW. Length is Reserved for TLPs that do not contain or refer to a data payload, including Cpl, CplLk, and most Messages.","§2.2.1.1, Table 2-4"],["p4q08","p4_2",2,"C","Non-Flit Mode TLP 헤더에서 TD 비트와 EP 비트의 의미는?","In a Non-Flit Mode TLP header, what do the TD and EP bits mean?",["TD는 Traffic Class의 MSB이고, EP는 End-End Prefix 존재이다.","TD=1b는 TLP 끝에 1 DW TLP Digest(ECRC)가 있음을 나타낸다. EP=1b는 TLP가 poisoned임을 나타낸다.","TD=1b는 TPH가 있음을, EP=1b는 ECRC가 있음을 나타낸다.","둘 다 Reserved이며, Flit Mode의 TS 필드와 같다."],["TD is the MSB of Traffic Class, and EP indicates an End-End Prefix is present.","TD=1b indicates a 1 DW TLP Digest (ECRC) at the end of the TLP. EP=1b indicates the TLP is poisoned.","TD=1b indicates TPH is present, and EP=1b indicates an ECRC is present.","Both are Reserved, and they are equivalent to the Flit Mode TS field."],1,"정답 요지: TD=1b는 TLP 끝에 1 DW TLP Digest(ECRC)가 있음을 나타낸다. EP=1b는 TLP가 poisoned임을 나타낸다.","Key point: TD=1b indicates a 1 DW TLP Digest (ECRC) at the end of the TLP. EP=1b indicates the TLP is poisoned.","§2.2.1.1, §2.2.3"],["p4q09","p4_2",1,"C","Non-Flit Mode Completion(Cpl/CplD)의 헤더 크기와 라우팅은?","What is the header size and routing of a Non-Flit Mode Completion (Cpl/CplD)?",["4 DW header이며 address routing을 사용한다.","3 DW header이며 ID routing을 사용한다.","3 DW이며 implicit routing만 사용한다.","Cpl은 3 DW, CplD는 payload 때문에 4 DW header이다."],["A 4 DW header, using address routing.","A 3 DW header, using ID routing.","A 3 DW header, using only implicit routing.","Cpl uses a 3 DW header; CplD uses a 4 DW header because of the payload."],1,"정답 요지: 3 DW header이며 ID routing을 사용한다.","Key point: A 3 DW header, using ID routing.","§2.2.9.1, Table 2-3"],["p4q10","p4_3",1,"C","Flit Mode TLP의 첫 Header Base DW에 공통으로 들어가는 필드 구성은? (Non-Flit의 Fmt 자리와 비교)","Which fields occupy the first DW of a Flit Mode TLP Header Base, compared with the Non-Flit Fmt field?",["Fmt[2:0], Type[4:0], TC, TD, EP, Length — Non-Flit와 동일하다.","Type[4:0]과 12-bit Sequence Number만 있다.","OHC만 있고 Type은 Local Prefix에 있다.","Type[7:0], TC, OHC, TS, Attr, Length. 별도의 Fmt 필드는 없다."],["Fmt[2:0], Type[4:0], TC, TD, EP, and Length — the same as Non-Flit Mode.","Only Type[4:0] and a 12-bit Sequence Number.","Only OHC; the Type is in a Local Prefix.","Type[7:0], TC, OHC, TS, Attr, and Length. There is no separate Fmt field."],3,"Figure 2-6: 첫 DW는 Type, TC, OHC, TS, Attr, Length. TLP grammar는 Local Prefix(0개 이상, 각 1 DW) + Header Base(Type이 크기 결정) + OHC 0–7 DW + payload 0–1024 DW + (TS가 지시하면) Trailer이다.","Figure 2-6 places Type, TC, OHC, TS, Attr, and Length in the first DW. The TLP grammar is zero or more 1 DW Local Prefixes, a Header Base whose size is indicated by Type, 0–7 DW of OHC, a 0–1024 DW payload, and a Trailer if TS indicates one.","§2.2.1.2, Figure 2-6"],["p4q11","p4_3",2,"C","Flit Mode Type[7:0]=0000 0000b의 의미와, Non-Flit에서의 같은 코드 사용은?","What does Flit Mode Type[7:0]=0000 0000b mean, and how is that code used in Non-Flit Mode?",["Flit Mode에서는 NOP TLP (FC Type none, Receiver에서 버려짐)이다. Non-Flit에서는 이 Type 코드를 MRd에 사용한다.","두 모드 모두 Memory Read이다.","Flit Mode에서는 MRd 32-bit이고, Non-Flit에서는 NOP이다.","두 모드 모두 Reserved이며 사용하면 Malformed TLP이다."],["In Flit Mode it is a NOP TLP (FC Type none, discarded at the Receiver). Non-Flit Mode uses this Type code for MRd.","It is a Memory Read in both modes.","In Flit Mode it is a 32-bit MRd; in Non-Flit Mode it is a NOP.","It is Reserved in both modes, and using it is a Malformed TLP."],0,"정답 요지: Flit Mode에서는 NOP TLP (FC Type none, Receiver에서 버려짐)이다. Non-Flit에서는 이 Type 코드를 MRd에 사용한다.","Key point: In Flit Mode it is a NOP TLP (FC Type none, discarded at the Receiver). Non-Flit Mode uses this Type code for MRd.","§2.2.1.2, Table 2-5"],["p4q12","p4_3",2,"C","Non-Flit의 End-to-End TLP Prefix와 Steering Tag 처리가 Flit Mode에서 바뀌는 점은?","How do Non-Flit End-to-End TLP Prefixes and Steering Tags change in Flit Mode?",["E-E Prefix와 ST 규칙은 Non-Flit와 완전히 동일하다.","Flit Mode는 E-E Prefix를 금지하고 ST만 Byte Enables에 overlay한다.","End-to-End Prefix 내용은 헤더 안의 OHC로 들어간다. Steering Tag는 Byte Enables 위에 overlay되지 않고, PH·ST·AMA/AV가 OHC에 모인다.","ST는 여전히 BE와 overlay되고, OHC는 Local Prefix 전용이다."],["End-to-End Prefix and Steering Tag rules are identical to Non-Flit Mode.","Flit Mode prohibits End-to-End Prefixes and overlays only ST on the Byte Enables.","End-to-End Prefix content is incorporated in the header as OHC. Steering Tags are not overlaid on the Byte Enables; PH, Steering Tags, and AMA/AV are consolidated in OHC.","ST is still overlaid on the Byte Enables, and OHC is only for Local Prefixes."],2,"정답 요지: End-to-End Prefix 내용은 헤더 안의 OHC로 들어간다. Steering Tag는 Byte Enables 위에 overlay되지 않고, PH·ST·AMA/AV가 OHC에 모인다.","Key point: End-to-End Prefix content is incorporated in the header as OHC. Steering Tags are not overlaid on the Byte Enables; PH, Steering Tags, and AMA/AV are consolidated in OHC.","§2.2.1.2"],["p4q13","p4_3",2,"C","Flit Mode에서 Tag 필드 폭과, Flit Mode를 지원하는 Function의 Completer 능력은?","In Flit Mode, what is the Tag field width, and what Completer capability must a Function that supports Flit Mode implement?",["Tag는 Non-Flit와 같은 10 bits이고, 14-bit는 UIO에서만 허용된다.","Tag는 8 bits로 고정이다.","Tag는 16 bits이며, Completer capability 요구는 없다.","Tag는 14 bits이다. Flit Mode를 지원하는 Function은 14-Bit Tag Completer capability를 지원해야 하며, 이에 따라 10-Bit Completer도 자동으로 지원한다. 모든 Function은 8-Bit Tag Completer를 지원해야 한다."],["The Tag is 10 bits, as in Non-Flit Mode; 14-bit Tags are allowed only for UIO.","The Tag is fixed at 8 bits.","The Tag is 16 bits, and no Completer capability is required.","The Tag is 14 bits. A Function that supports Flit Mode must support 14-Bit Tag Completer capability, and thus automatically supports 10-Bit Tag Completer capability. All Functions must support 8-Bit Tag Completer capability."],3,"정답 요지: Tag는 14 bits이다. Flit Mode를 지원하는 Function은 14-Bit Tag Completer capability를 지원해야 하며, 이에 따라 10-Bit Completer도 자동으로 지원한다. 모든 Function은 8-Bit Tag Completer를 지원해야 한다.","Key point: The Tag is 14 bits. A Function that supports Flit Mode must support 14-Bit Tag Completer capability, and thus automatically supports 10-Bit Tag Completer capability. All Functions must support 8-Bit Tag Completer capability.","§2.2.9.2, §2.2.6.2.1, §2.2.6.2.2"],["p4q14","p4_3",3,"P","UIO TLP을 Non-Flit Mode Egress Port로 번역할 수 있는가?","May a UIO TLP be translated for an Egress Port that is in Non-Flit Mode?",["가능하며 Translation Rule은 항상 1:1이다.","할 수 없다. UIO는 Flit Mode에서만 정의되며, NFM으로의 번역은 허용되지 않는다. 그런 TLP은 Egress에서 block된다.","가능하지만 Tag를 10 bit로 잘라야 한다.","Switch만 번역을 허용하고 Endpoint는 허용하지 않는다."],["Yes, and the Translation Rule is always 1:1.","No. UIO is defined only for Flit Mode, and translation of UIO TLPs to NFM is not permitted. Such a TLP is blocked at the Egress Port.","Yes, but the Tag must be truncated to 10 bits.","Only a Switch may translate them; an Endpoint may not."],1,"정답 요지: 할 수 없다. UIO는 Flit Mode에서만 정의되며, NFM으로의 번역은 허용되지 않는다. 그런 TLP은 Egress에서 block된다.","Key point: No. UIO is defined only for Flit Mode, and translation of UIO TLPs to NFM is not permitted. Such a TLP is blocked at the Egress Port.","§2.2.1.2"],["p4q15","p4_4",1,"C","TLP 라우팅의 세 가지 주요 메커니즘은?","What are the three principal TLP routing mechanisms?",["Posted routing, Non-Posted routing, Completion routing","Broadcast, multicast, unicast","Address routing, ID routing, implicit routing","TC routing, VC routing, port routing"],["Posted routing, Non-Posted routing, and Completion routing","Broadcast, multicast, and unicast","Address routing, ID routing, and implicit routing","TC routing, VC routing, and port routing"],2,"정답 요지: Address routing, ID routing, implicit routing","Key point: Address routing, ID routing, and implicit routing","§2.2.4"],["p4q16","p4_4",2,"C","Address routing과 ID routing이 각각 쓰이는 TLP은?","Which TLPs use address routing, and which use ID routing?",["Address routing: Memory, I/O Request, Address Routed Message. ID routing: Configuration Request, ID Routed Message, Completion.","Address routing: Memory와 Completion. ID routing: 모든 Message와 Configuration.","모든 Request는 address routing, 모든 Completion은 implicit routing이다.","I/O는 ID routing, Configuration은 address routing이다."],["Address routing is used with Memory and I/O Requests and Address Routed Messages. ID routing is used with Configuration Requests, ID Routed Messages, and Completions.","Address routing is used with Memory and Completions. ID routing is used with all Messages and Configuration.","All Requests use address routing; all Completions use implicit routing.","I/O uses ID routing; Configuration uses address routing."],0,"정답 요지: Address routing: Memory, I/O Request, Address Routed Message. ID routing: Configuration Request, ID Routed Message, Completion.","Key point: Address routing is used with Memory and I/O Requests and Address Routed Messages. ID routing is used with Configuration Requests, ID Routed Messages, and Completions.","§2.2.4.1, §2.2.4.2"],["p4q17","p4_4",2,"C","Configuration Request의 라우팅과 헤더 크기는?","What is the routing and header size of a Configuration Request?",["ID routing을 사용하고 3 DW header이다. Type 0과 Type 1이 있다.","Address routing, 4 DW header이다.","Implicit routing, 3 DW header이다.","ID routing, 4 DW header에 64-bit 주소를 포함한다."],["It uses ID routing and a 3 DW header. There are Type 0 and Type 1 Configuration Requests.","It uses address routing and a 4 DW header.","It uses implicit routing and a 3 DW header.","It uses ID routing and a 4 DW header that includes a 64-bit address."],0,"정답 요지: ID routing을 사용하고 3 DW header이다. Type 0과 Type 1이 있다.","Key point: It uses ID routing and a 3 DW header. There are Type 0 and Type 1 Configuration Requests.","§2.2.7.1, Table 2-3"],["p4q18","p4_4",1,"C","Ingress Port와 Egress Port의 Data Stream mode가 다를 때 Routing Element의 의무는?","If a Routing Element’s Ingress and Egress Ports are in different Data Stream modes, what must it do?",["그런 구성은 금지되므로 Link를 Disable해야 한다.","번역하지 않고 원본 TLP를 그대로 전달한다.","FM과 NFM TLP 형식 사이를 번역해야 한다. 번역이 불가능한 경우는 이 장에서 정의한 대로 처리한다 (예: UIO → NFM은 불가).","항상 Non-Flit 형식으로만 전달한다."],["That configuration is illegal, so the Link must be Disabled.","It forwards the original TLP unchanged, with no translation.","It must translate between FM and NFM TLP formats. Cases where translation is not possible are handled as defined in this chapter (for example, UIO cannot be translated to NFM).","It always forwards only in Non-Flit format."],2,"정답 요지: FM과 NFM TLP 형식 사이를 번역해야 한다. 번역이 불가능한 경우는 이 장에서 정의한 대로 처리한다 (예: UIO → NFM은 불가).","Key point: It must translate between FM and NFM TLP formats. Cases where translation is not possible are handled as defined in this chapter (for example, UIO cannot be translated to NFM).","§2.2"],["p4q19","p4_5",1,"C","Non-Flit Mode에서 Length=1 DW인 Request의 Last DW BE는?","In Non-Flit Mode, what must Last DW BE be for a Request whose Length is 1 DW?",["1111b이어야 한다.","0000b이어야 한다. Length가 1 DW보다 크면 First/Last DW BE 모두 0000b이면 안 된다.","First DW BE와 같은 값이어야 한다.","Reserved이므로 송수신 모두 무시한다."],["It must be 1111b.","It must be 0000b. If Length is greater than 1 DW, neither First DW BE nor Last DW BE may be 0000b.","It must equal First DW BE.","It is Reserved, so both Transmitter and Receiver ignore it."],1,"정답 요지: 0000b이어야 한다. Length가 1 DW보다 크면 First/Last DW BE 모두 0000b이면 안 된다.","Key point: It must be 0000b. If Length is greater than 1 DW, neither First DW BE nor Last DW BE may be 0000b.","§2.2.5.1"],["p4q20","p4_5",2,"C","Non-contiguous Byte Enables가 허용되는 경우는?","When are non-contiguous Byte Enables permitted?",["어떤 Length에서도 자유롭게 허용된다.","Completer가 No Snoop을 Set한 경우에만 허용된다.","Configuration Request에서만 허용되고, Memory에서는 금지된다.","Length=1 DW인 모든 Request의 First DW BE에서 허용된다. 또한 QW-aligned이고 Length=2 DW(1 QW)인 Memory Request에서는 양쪽 BE 필드에서 허용된다."],["They are freely permitted at any Length.","They are permitted only when the Completer has No Snoop Set.","They are permitted only on Configuration Requests and are prohibited on Memory Requests.","They are permitted in First DW BE for every Request with Length=1 DW. They are also permitted in both BE fields for QW-aligned Memory Requests with Length=2 DW (1 QW)."],3,"정답 요지: Length=1 DW인 모든 Request의 First DW BE에서 허용된다. 또한 QW-aligned이고 Length=2 DW(1 QW)인 Memory Request에서는 양쪽 BE 필드에서 허용된다.","Key point: They are permitted in First DW BE for every Request with Length=1 DW. They are also permitted in both BE fields for QW-aligned Memory Requests with Length=2 DW (1 QW).","§2.2.5.1"],["p4q21","p4_5",2,"C","Flit Mode Memory Request에서 OHC-A1이 없고 BE 필드가 Reserved가 아닐 때, 암시되는 Byte Enable 값은?","In Flit Mode, if a Memory Request has no OHC-A1 and its BE fields are not Reserved, what Byte Enable values are implied?",["항상 둘 다 0000b로 암시된다.","암시값이 없으므로 OHC-A1이 필수이다.","1 DW Request는 First DW BE=1111b, Last DW BE=0000b. 1 DW보다 긴 Request는 양쪽 모두 1111b. 다른 값이 필요하면 OHC-A1이 있어야 한다.","TH=1b인 경우에만 1111b/0000b가 암시된다."],["Both are always implied to be 0000b.","There are no implied values, so OHC-A1 is required.","For a 1 DW Request, First DW BE=1111b and Last DW BE=0000b. For a longer Request both are 1111b. OHC-A1 must be present if any other non-Reserved BE values are required.","1111b/0000b are implied only when TH=1b."],2,"정답 요지: 1 DW Request는 First DW BE=1111b, Last DW BE=0000b. 1 DW보다 긴 Request는 양쪽 모두 1111b. 다른 값이 필요하면 OHC-A1이 있어야 한다.","Key point: For a 1 DW Request, First DW BE=1111b and Last DW BE=0000b. For a longer Request both are 1111b. OHC-A1 must be present if any other non-Reserved BE values are required.","§2.2.5.2"],["p4q22","p4_5",2,"C","Flit Mode에서 I/O Request와 Configuration Request에 반드시 포함되어야 하는 OHC는?","In Flit Mode, which OHC must be included for I/O Requests and for Configuration Requests?",["I/O Request는 OHC-A2, Configuration Request는 OHC-A3가 필수이다.","둘 다 OHC-A1이 필수이다.","둘 다 OHC가 금지된다 (암시 BE만 사용).","I/O는 OHC-A5, Configuration은 OHC-C가 필수이다."],["OHC-A2 is required for every I/O Request, and OHC-A3 is required for every Configuration Request.","OHC-A1 is required for both.","OHC is prohibited for both; only implied BEs are used.","I/O requires OHC-A5, and Configuration requires OHC-C."],0,"정답 요지: I/O Request는 OHC-A2, Configuration Request는 OHC-A3가 필수이다.","Key point: OHC-A2 is required for every I/O Request, and OHC-A3 is required for every Configuration Request.","§2.2.5.2"],["p4q23","p4_5",3,"C","I/O Request가 지켜야 하는 헤더 제약으로 옳은 것은?","Which set of header constraints must an I/O Request satisfy?",["64-bit address를 쓸 수 있고, TC는 임의의 값, Length는 최대 1024 DW이다.","ID routing, Length=0, Last DW BE=1111b가 필수이다.","Memory Write와 동일한 제약이 없으며 Length와 BE는 자유이다.","32-bit address routing, TC[2:0]=000b, Attr[1:0]=00b, AT[1:0]=00b, Length=00 0000 0001b, Last DW BE=0000b. TH와 Attr[2]는 Reserved. Receiver는 (Reserved bit 제외) 이 규칙을 선택적으로 검사해 위반 시 Malformed TLP로 처리할 수 있다."],["A 64-bit address may be used, TC may be any value, and Length may be up to 1024 DW.","ID routing is required, Length must be 0, and Last DW BE must be 1111b.","There are no extra constraints beyond a Memory Write; Length and BE are unrestricted.","32-bit address routing, TC[2:0]=000b, Attr[1:0]=00b, AT[1:0]=00b, Length=00 0000 0001b, and Last DW BE=0000b. TH and Attr[2] are Reserved. A Receiver may optionally check these rules (but must not check Reserved bits) and handle a violation as a Malformed TLP."],3,"정답 요지: 32-bit address routing, TC[2:0]=000b, Attr[1:0]=00b, AT[1:0]=00b, Length=00 0000 0001b, Last DW BE=0000b. TH와 Attr[2]는 Reserved. Receiver는 (Reserved bit 제외) 이 규칙을 선택적으로 검사해 위반 시 Malformed TLP로 처리할 수 있다.","Key point: 32-bit address routing, TC[2:0]=000b, Attr[1:0]=00b, AT[1:0]=00b, Length=00 0000 0001b, and Last DW BE=0000b. TH and Attr[2] are Reserved. A Receiver may optionally check these rules (but must not check Reserved bits) and handle a violation as a Malformed TLP.","§2.2.7.1"],["p4q24","p4_6",1,"C","기본(Strong) ordering에서 Posted Request가 다른 Posted Request를 앞지를 수 있는가?","Under default (strong) ordering, may a Posted Request pass another Posted Request?",["항상 허용된다. Posted는 어떤 트래픽이든 앞지를 수 있다.","원칙적으로 안 된다 (A2a). Relaxed Ordering이 Set되었거나, IDO가 Set되고 Requester ID(FM에서는 Segment 포함)가 다르면 (또는 둘 다 PASID가 있고 PASID가 다르면) 허용될 수 있다 (A2b).","Completer ID가 같을 때만 허용된다.","금지되며, RO/IDO가 Set되어도 예외가 없다."],["Yes, always. A Posted Request may pass any traffic.","Generally no (A2a). It may be permitted if Relaxed Ordering is Set, or if IDO is Set and the Requester IDs (including Requester Segment in FM) differ, or if both Requests contain PASIDs and the PASID values differ (A2b).","Only if the Completer IDs are the same.","No, and there is no exception even if RO or IDO is Set."],1,"정답 요지: 원칙적으로 안 된다 (A2a). Relaxed Ordering이 Set되었거나, IDO가 Set되고 Requester ID(FM에서는 Segment 포함)가 다르면 (또는 둘 다 PASID가 있고 PASID가 다르면) 허용될 수 있다 (A2b).","Key point: Generally no (A2a). It may be permitted if Relaxed Ordering is Set, or if IDO is Set and the Requester IDs (including Requester Segment in FM) differ, or if both Requests contain PASIDs and the PASID values differ (A2b).","§2.4.1, Table 2-42"],["p4q25","p4_6",2,"C","producer/consumer 모델을 깨지 않기 위해, Relaxed Ordering이 없는 Completions는 Posted Request를 앞지를 수 있는가?","To preserve the producer/consumer model, may Completions without Relaxed Ordering pass a Posted Request?",["항상 앞질러야 한다. 그렇지 않으면 deadlock이 난다.","기본적으로 안 된다 (D2a). I/O 또는 Configuration Write Completion, RO가 Set된 Completion, 또는 IDO가 Set되고 Completer ID가 그 Posted의 Requester ID와 다른 Completion은 허용될 수 있다 (D2b).","Posted를 앞지르는 것은 어떤 Completion에도 금지되고 예외가 없다.","Tag가 같으면 허용되고, 다르면 금지된다."],["Yes, they must always pass; otherwise a deadlock occurs.","Generally no (D2a). An I/O or Configuration Write Completion, a Completion with RO Set, or a Completion with IDO Set whose Completer ID differs from the Posted Request’s Requester ID may be permitted (D2b).","No Completion may pass a Posted Request, and there is no exception.","It is permitted when the Tags match and prohibited when they differ."],1,"정답 요지: 기본적으로 안 된다 (D2a). I/O 또는 Configuration Write Completion, RO가 Set된 Completion, 또는 IDO가 Set되고 Completer ID가 그 Posted의 Requester ID와 다른 Completion은 허용될 수 있다 (D2b).","Key point: Generally no (D2a). An I/O or Configuration Write Completion, a Completion with RO Set, or a Completion with IDO Set whose Completer ID differs from the Posted Request’s Requester ID may be permitted (D2b).","§2.4.1, Table 2-42"],["p4q26","p4_6",2,"C","같은 Memory Read Request에서 나온 여러 Completion의 통과(passing) 규칙은?","What is the passing rule for multiple Completions that belong to the same Memory Read Request?",["어떤 Completion이든 자유롭게 재정렬된다.","같은 Tag여도 TC가 다르면 반드시 앞질러야 한다.","Byte Count가 남은 Completion만 앞지를 수 있다.","같은 Transaction ID를 가진 Completions는 서로를 앞지르면 안 된다 (오름차순 주소 순서 유지). 서로 다른 Transaction ID의 Completions는 앞지를 수 있다."],["Any Completions may be freely reordered.","Even with the same Tag, they must pass if the TC differs.","Only a Completion with a remaining Byte Count may pass.","Completions with the same Transaction ID must not pass each other, so they remain in ascending address order. Completions with different Transaction IDs are permitted to pass each other."],3,"정답 요지: 같은 Transaction ID를 가진 Completions는 서로를 앞지르면 안 된다 (오름차순 주소 순서 유지). 서로 다른 Transaction ID의 Completions는 앞지를 수 있다.","Key point: Completions with the same Transaction ID must not pass each other, so they remain in ascending address order. Completions with different Transaction IDs are permitted to pass each other.","§2.4.1, Table 2-42"],["p4q27","p4_6",2,"C","Posted Request는 Non-Posted Request를 앞지를 수 있어야 하는가?","Must a Posted Request be able to pass a Non-Posted Request?",["그렇다. Table 2-42에서 Posted(Row A) vs Read/NPR with Data 항목은 Yes이다. 막히면 두 번째 트랜잭션이 첫 번째를 통과해야 하며, starvation을 막기 위한 fairness가 필요하다.","아니다. Posted는 Non-Posted 뒤에 고정되어야 한다.","Read에 대해서만 Yes이고, NPR with Data에 대해서는 No이다.","Endpoint에서만 Yes이고 Switch에서는 No이다."],["Yes. In Table 2-42 the Posted (Row A) versus Read / NPR-with-Data entries are Yes. When blocking occurs the second transaction must be allowed to pass the first, and fairness is required to prevent starvation.","No. A Posted Request must remain behind Non-Posted Requests.","Yes only versus Reads; the entry versus NPR with Data is No.","Yes only at an Endpoint; at a Switch the entry is No."],0,"정답 요지: 그렇다. Table 2-42에서 Posted(Row A) vs Read/NPR with Data 항목은 Yes이다. 막히면 두 번째 트랜잭션이 첫 번째를 통과해야 하며, starvation을 막기 위한 fairness가 필요하다.","Key point: Yes. In Table 2-42 the Posted (Row A) versus Read / NPR-with-Data entries are Yes. When blocking occurs the second transaction must be allowed to pass the first, and fairness is required to prevent starvation.","§2.4.1, Table 2-42"],["p4q28","p4_6",1,"C","Attributes 필드 Attr[2], Attr[1], Attr[0]이 각각 나타내는 것은?","What do Attribute bits Attr[2], Attr[1], and Attr[0] each indicate?",["Attr[2]=Relaxed Ordering, Attr[1]=No Snoop, Attr[0]=IDO","Attr[2]=No Snoop, Attr[1]=IDO, Attr[0]=Poisoned","Attr[2]=ID-Based Ordering (IDO), Attr[1]=Relaxed Ordering (RO), Attr[0]=No Snoop (NS)","세 비트 모두 Traffic Class의 확장이다."],["Attr[2]=Relaxed Ordering, Attr[1]=No Snoop, Attr[0]=IDO","Attr[2]=No Snoop, Attr[1]=IDO, Attr[0]=Poisoned","Attr[2]=ID-Based Ordering (IDO), Attr[1]=Relaxed Ordering (RO), Attr[0]=No Snoop (NS)","All three bits are an extension of Traffic Class."],2,"Figure 2-35: Attr[2] ID-Based Ordering, Attr[1] Relaxed Ordering, Attr[0] No Snoop. Table 2-12에서 [2:1]=00 default (PCI strongly ordered), 01 RO, 10 IDO, 11 RO plus IDO. No Snoop은 ordering을 바꾸지 않는다. I/O·Configuration에서 Attr[1]은 0이어야 하고 Attr[2](IDO)는 Reserved이다.","Figure 2-35: Attr[2] is IDO, Attr[1] is Relaxed Ordering, and Attr[0] is No Snoop. Table 2-12: [2:1]=00 is default PCI strongly ordered, 01 is RO, 10 is IDO, and 11 is RO plus IDO. No Snoop does not alter ordering. For I/O and Configuration Requests Attr[1] must be Clear and Attr[2] (IDO) is Reserved.","§2.2.6.3, §2.2.6.4, §2.2.6.5, Table 2-12"],["p4q29","p4_7",1,"C","Completion Status[2:0]의 정의된 encoding은?","What are the defined encodings of Completion Status[2:0]?",["000b UR, 001b SC, 010b CA, 011b RRS.","000b SC, 001b CA, 010b UR, 111b RRS.","000b SC, 111b UR뿐이며 나머지는 구현 정의이다.","000b Successful Completion (SC), 001b Unsupported Request (UR), 010b Request Retry Status (RRS), 100b Completer Abort (CA). 그 외는 Reserved."],["000b UR, 001b SC, 010b CA, and 011b RRS.","000b SC, 001b CA, 010b UR, and 111b RRS.","Only 000b SC and 111b UR are defined; the rest are implementation-defined.","000b Successful Completion (SC), 001b Unsupported Request (UR), 010b Request Retry Status (RRS), and 100b Completer Abort (CA). All others are Reserved."],3,"정답 요지: 000b Successful Completion (SC), 001b Unsupported Request (UR), 010b Request Retry Status (RRS), 100b Completer Abort (CA). 그 외는 Reserved.","Key point: 000b Successful Completion (SC), 001b Unsupported Request (UR), 010b Request Retry Status (RRS), and 100b Completer Abort (CA). All others are Reserved.","§2.2.9.1, Table 2-37, §2.2.9.2"],["p4q30","p4_7",2,"C","Cpl과 CplD는 각각 어떤 경우에 사용되나?","When are Cpl and CplD used?",["모든 성공 Completion은 CplD, 모든 실패는 Cpl이다. Memory Write도 성공 시 CplD를 보낸다.","Cpl(데이터 없음): I/O·Configuration Write·DMWr의 모든 Status, 그리고 Successful이 아닌 Read/AtomicOp Completion. CplD(데이터 있음): Memory/I/O/Configuration Read Completion과 AtomicOp Completion(성공 시).","CplD는 Memory Read 전용이고, I/O Read는 항상 Cpl만 쓴다.","Cpl과 CplD는 같은 의미이며 Fmt만 구현 선택이다."],["Every successful Completion is a CplD and every unsuccessful one is a Cpl. A Memory Write also returns CplD on success.","Cpl (no data) is used for I/O, Configuration Write, and DMWr Completions of any Status, and for Read or AtomicOp Completions whose Status is not Successful. CplD (with data) is used for Memory, I/O, and Configuration Read Completions and for AtomicOp Completions (when Successful).","CplD is only for Memory Reads; I/O Reads always use Cpl.","Cpl and CplD mean the same thing; Fmt is an implementation choice."],1,"정답 요지: Cpl(데이터 없음): I/O·Configuration Write·DMWr의 모든 Status, 그리고 Successful이 아닌 Read/AtomicOp Completion. CplD(데이터 있음): Memory/I/O/Configuration Read Completion과 AtomicOp Completion(성공 시).","Key point: Cpl (no data) is used for I/O, Configuration Write, and DMWr Completions of any Status, and for Read or AtomicOp Completions whose Status is not Successful. CplD (with data) is used for Memory, I/O, and Configuration Read Completions and for AtomicOp Completions (when Successful).","§2.2.1.1, Table 2-3"],["p4q31","p4_7",2,"C","Non-Flit Mode Completion의 Byte Count 필드에서 1 byte, 4095 bytes, 4096 bytes를 나타내는 값과, I/O·Configuration Completion에서의 값은?","In the Non-Flit Mode Completion Byte Count field, which encodings mean 1, 4095, and 4096 bytes, and what value is used for I/O and Configuration Completions?",["0000 0000 0000b=0 byte, 1111 1111 1111b=4096 bytes. I/O Completion은 항상 0이다.","Byte Count는 DW 단위이며 0001b=1 DW, 0000b=1024 DW이다.","0000 0000 0001b=1 byte, 1111 1111 1111b=4095 bytes, 0000 0000 0000b=4096 bytes. I/O·Configuration 등 (Memory Read/AtomicOp가 아닌) Completion의 Byte Count는 4여야 한다.","Byte Count는 Length 필드와 항상 같고, I/O에서는 1 DW를 byte로 환산한 1이다."],["0000 0000 0000b=0 bytes and 1111 1111 1111b=4096 bytes. An I/O Completion is always 0.","Byte Count is in DW: 0001b=1 DW and 0000b=1024 DW.","0000 0000 0001b=1 byte, 1111 1111 1111b=4095 bytes, and 0000 0000 0000b=4096 bytes. For Completions other than Memory Read and AtomicOp (including I/O and Configuration), Byte Count must be 4.","Byte Count always equals Length, and for I/O it is 1 (one DW expressed in bytes)."],2,"정답 요지: 0000 0000 0001b=1 byte, 1111 1111 1111b=4095 bytes, 0000 0000 0000b=4096 bytes. I/O·Configuration 등 (Memory Read/AtomicOp가 아닌) Completion의 Byte Count는 4여야 한다.","Key point: 0000 0000 0001b=1 byte, 1111 1111 1111b=4095 bytes, and 0000 0000 0000b=4096 bytes. For Completions other than Memory Read and AtomicOp (including I/O and Configuration), Byte Count must be 4.","§2.2.9.1"],["p4q32","p4_7",2,"C","BCM(Byte Count Modified) 비트를 PCI Express Completer가 Set할 수 있는가?","May a PCI Express Completer Set the BCM (Byte Count Modified) bit?",["없다. 이 비트는 PCI Express Completer가 Set해서는 안 되며, PCI-X completer만 Set할 수 있다.","있다. Memory Read를 split할 때마다 Set해야 한다.","Flit Mode에서만 Set한다.","Byte Count가 4096일 때만 Set한다."],["No. PCI Express Completers must not Set this bit; only PCI-X completers may Set it.","Yes. It must be Set whenever a Memory Read is split.","It is Set only in Flit Mode.","It is Set only when Byte Count is 4096."],0,"정답 요지: 없다. 이 비트는 PCI Express Completer가 Set해서는 안 되며, PCI-X completer만 Set할 수 있다.","Key point: No. PCI Express Completers must not Set this bit; only PCI-X completers may Set it.","§2.2.9.1"],["p4q33","p4_7",3,"C","Flit Mode에서 OHC-A5가 필수인 경우는?","In Flit Mode, when is OHC-A5 required?",["Unsuccessful Completions, Lower Address[1:0]이 00b가 아닌 Non-UIO Completions, 그리고 Destination Segment를 명시해야 하는 Completions. OHC-A5가 없으면 Status는 Successful, (Non-UIO는) Lower Address[1:0]=00b 등으로 암시된다.","모든 Completion에 필수이다.","Successful Completion에만 필수이다.","UIO Completion에만 필수이고 Non-UIO에서는 금지된다."],["For unsuccessful Completions, for non-UIO Completions whose Lower Address[1:0] is not 00b, and for Completions that must explicitly indicate Destination Segment. If OHC-A5 is absent, Successful Completion (and, for non-UIO, Lower Address[1:0]=00b) is implied.","It is required on every Completion.","It is required only on Successful Completions.","It is required only on UIO Completions and is prohibited on non-UIO Completions."],0,"정답 요지: Unsuccessful Completions, Lower Address[1:0]이 00b가 아닌 Non-UIO Completions, 그리고 Destination Segment를 명시해야 하는 Completions. OHC-A5가 없으면 Status는 Successful, (Non-UIO는) Lower Address[1:0]=00b 등으로 암시된다.","Key point: For unsuccessful Completions, for non-UIO Completions whose Lower Address[1:0] is not 00b, and for Completions that must explicitly indicate Destination Segment. If OHC-A5 is absent, Successful Completion (and, for non-UIO, Lower Address[1:0]=00b) is implied.","§2.2.9.2"],["p4q34","p4_8",1,"C","Flow Control이 구분하는 세 가지 TLP 유형은?","What three TLP types does Flow Control distinguish?",["Header, Data, Digest.","Memory, I/O, Configuration (Message는 credit을 쓰지 않음).","Posted Requests (P): Messages와 Memory Writes. Non-Posted Requests (NP): 모든 Reads, I/O Writes, Configuration Writes, AtomicOps, DMWrs. Completions (Cpl): 대응하는 NP Request와 연관.","Request, Response, Ack."],["Header, Data, and Digest.","Memory, I/O, and Configuration (Messages consume no credits).","Posted Requests (P): Messages and Memory Writes. Non-Posted Requests (NP): all Reads, I/O Writes, Configuration Writes, AtomicOps, and DMWrs. Completions (Cpl): associated with the corresponding NP Requests.","Request, Response, and Ack."],2,"§2.6.1이 이 세 유형을 정의하고, 각각 header/data credit (PH/PD, NPH/NPD, CplH/CplD)을 둔다. ordering 규칙(§2.4)과의 관계를 명시한다. Message with data는 1 PH + n PD이다.","Section 2.6.1 defines these three types, each with header and data credits (PH/PD, NPH/NPD, CplH/CplD), and notes the relationship to the ordering rules in §2.4. A Message with data consumes 1 PH + n PD.","§2.6.1, Table 2-49"],["p4q35","p4_8",2,"C","Memory Write Request와 Memory Read Completion의 credit 소비는?","What Flow Control credits do a Memory Write Request and a Memory Read Completion consume?",["둘 다 1 header credit만 소비하고 payload는 무료이다.","Memory Write: 1 PH + n PD. Memory Read Completion: 1 CplH + n CplD. 여기서 n = Roundup(Length/4 DW).","Memory Write는 1 NPH + n NPD, Completion은 1 PH이다.","Memory Write는 n PH (DW마다 header), Completion은 CplD만 소비한다."],["Both consume only 1 header credit; payload is free.","A Memory Write consumes 1 PH + n PD. A Memory Read Completion consumes 1 CplH + n CplD. Here n = Roundup(Length / 4 DW).","A Memory Write consumes 1 NPH + n NPD, and the Completion consumes 1 PH.","A Memory Write consumes n PH (one header per DW), and the Completion consumes only CplD."],1,"Table 2-49 그대로이다. Memory Read Request 자체는 1 NPH이다. header credit은 TLP Digest를 받을 능력을 포함한다.","This is exactly Table 2-49. The Memory Read Request itself consumes 1 NPH. Each header credit implies the ability to accept a TLP Digest with the corresponding TLP.","§2.6.1, Table 2-49"],["p4q36","p4_8",2,"C","Traffic Class(TC) 필드의 폭과, 모든 PCI Express device가 반드시 지원해야 하는 TC는?","What is the width of the Traffic Class (TC) field, and which TC must every PCI Express device support?",["4-bit로 16개의 TC. TC15가 default이다.","3-bit이지만 TC0는 optional이고 TC7만 필수이다.","VC ID와 동일한 3-bit이며, 하드웨어가 TC를 바꾸어 VC에 맞춘다.","3-bit로 8개의 TC(TC0–TC7). TC0(000b)는 Best Effort/default이며 모든 device가 지원해야 한다."],["It is 4 bits, giving 16 TCs, and TC15 is the default.","It is 3 bits, but TC0 is optional and only TC7 is required.","It is the same 3-bit field as VC ID, and hardware may change TC to match a VC.","It is 3 bits, giving eight TCs (TC0–TC7). TC0 (000b) is Best Effort/default and must be supported by every PCI Express device."],3,"정답 요지: 3-bit로 8개의 TC(TC0–TC7). TC0(000b)는 Best Effort/default이며 모든 device가 지원해야 한다.","Key point: It is 3 bits, giving eight TCs (TC0–TC7). TC0 (000b) is Best Effort/default and must be supported by every PCI Express device.","§2.2.6.6, Table 2-14"],["p4q37","p4_8",1,"C","TLP의 Reserved 필드를 만들 때와, Receiver·Switch가 그 값을 다루는 규칙은?","What are the rules for Reserved TLP fields when a TLP is formed, and how must Receivers and Switches handle them?",["형성 시 1로 채워 호환성을 시험해야 한다. Receiver는 Malformed로 처리해야 한다.","Receiver는 Reserved 비트를 반드시 검사해 1이면 UR을 반환해야 한다.","형성 시 모두 0으로 채워야 한다. Receiver는 값을 무시하고, Switch는 수정하지 않고 전달해야 한다.","Switch는 Reserved 필드를 0으로 클리어한 뒤 전달해야 한다."],["They must be filled with 1’s to test interoperability, and a Receiver must treat that as Malformed.","A Receiver must check Reserved bits and return UR if any is 1.","They must be filled with all 0’s when a TLP is formed. Receivers must ignore the values, and Switches must forward them unmodified.","A Switch must clear Reserved fields to 0 before forwarding."],2,"정답 요지: 형성 시 모두 0으로 채워야 한다. Receiver는 값을 무시하고, Switch는 수정하지 않고 전달해야 한다.","Key point: They must be filled with all 0’s when a TLP is formed. Receivers must ignore the values, and Switches must forward them unmodified.","§2.2, §2.2.7.1"],["p4q38","p4_8",2,"C","Non-Flit Mode에서 TD=1b인데 실제 TLP 크기(페이로드 포함)가 Digest 1 DW를 반영하지 않으면?","In Non-Flit Mode, if TD=1b but the observed TLP size (including any payload) does not account for a 1 DW Digest, what is the TLP?",["Malformed TLP이며, Receiving Port에 연관된 reported error이다.","Unsupported Request로 Completer가 Cpl을 돌려준다.","Digest를 무시하고 정상 처리한다 (ECRC 미지원 Receiver와 같다).","Poisoned TLP로 처리하고 EP 비트를 Set한다."],["It is a Malformed TLP, a reported error associated with the Receiving Port.","The Completer returns a Cpl with Unsupported Request.","The Digest is ignored and the TLP is processed normally (as at a Receiver that does not support ECRC).","It is handled as a Poisoned TLP and the EP bit is Set."],0,"정답 요지: Malformed TLP이며, Receiving Port에 연관된 reported error이다.","Key point: It is a Malformed TLP, a reported error associated with the Receiving Port.","§2.2.3, §2.2.1.2"],["c4q01","c4_1",1,"X","CXL.io는 어떤 성격의 인터페이스인가요?","What kind of interface is CXL.io?",["non-coherent load/store I/O 인터페이스","Host 메모리를 캐시하는 coherent 프로토콜","장치 메모리 전용 Master/Subordinate 프로토콜","PHY 관리 전용 sideband"],["A non-coherent load/store I/O interface","A coherent protocol for caching host memory","A Master/Subordinate protocol for device memory only","A sideband for PHY management only"],0,"CXL.io는 PCIe와 같은 I/O 의미를 갖습니다. Coherent caching은 CXL.cache, 장치 메모리 접근은 CXL.mem의 몫입니다.","CXL.io carries PCIe-like I/O semantics; coherent caching is CXL.cache and device-memory access is CXL.mem.","§3.1"],["c4q02","c4_1",1,"C","CXL.io와 PCIe에서 공통으로 TLP 전송을 조절하는 흐름 제어 방식은?","Which flow control governs TLP transmission in both CXL.io and PCIe?",["XON/XOFF 기반 흐름 제어","sliding window TCP 방식","credit 기반 흐름 제어","흐름 제어 없음"],["XON/XOFF flow control","TCP-style sliding window","Credit-based flow control","No flow control"],2,"CXL.io의 트랜잭션 유형, 패킷 형식, credit 기반 흐름 제어, VC, ordering은 PCIe 정의를 따릅니다.","CXL.io transaction types, packet format, credit-based flow control, VCs and ordering all follow PCIe.","§3.1"],["c4q03","c4_1",1,"X","CXL에서 discovery, enumeration, error reporting에 반드시 필요한 프로토콜은?","Which CXL protocol is required for discovery, enumeration and error reporting?",["CXL.cache","CXL.io","CXL.mem","어느 것도 필요 없다"],["CXL.cache","CXL.io","CXL.mem","None of them"],1,"CXL.io는 필수이고, CXL.cache와 CXL.mem은 장치 용도에 따라 선택적으로 구현합니다.","CXL.io is required; CXL.cache and CXL.mem are optional depending on the device's use.","§1.4"],["c4q04","c4_1",1,"X","다음 중 CXL.io가 PCIe Transaction Layer에서 그대로 가져오는 것이 아닌 것은?","Which of these does CXL.io NOT take over from the PCIe Transaction Layer?",["TLP 패킷 형식","Virtual Channel 관리","트랜잭션 ordering 규칙","CXL.cache의 D2H/H2D 채널 구조"],["The TLP packet format","Virtual Channel management","Transaction ordering rules","The CXL.cache D2H/H2D channel structure"],3,"D2H/H2D 채널은 CXL.cache 고유 구조로, PCIe TL에는 대응하는 것이 없습니다.","D2H/H2D channels are specific to CXL.cache and have no PCIe TL counterpart.","§3.1"],["c4q05","c4_1",2,"X","Flex Bus 계층에서 PCIe Transaction/Data Link Layer와 CXL.io 계층의 관계로 맞는 것은?","In Flex Bus layering, what is the relationship between the PCIe Transaction/Data Link Layers and the CXL.io layers?",["PCIe 계층은 항상 CXL.io와 별도로 있어야 한다","PCIe 계층이 CXL.cache까지 처리한다","PCIe 계층은 선택 구현이며, 구현하면 CXL.io 계층과 합쳐도 된다","CXL 장치는 PCIe 계층을 반드시 구현해야 한다"],["The PCIe layers must always be separate from CXL.io","The PCIe layers also handle CXL.cache","The PCIe layers are optional and, if present, may be merged with the CXL.io layers","Every CXL device must implement the PCIe layers"],2,"Host CPU는 보통 두 모드를 다 갖지만, accelerator AIC는 CXL mode만 구현해도 됩니다.","A host CPU usually has both modes, but an accelerator AIC may implement CXL mode only.","§1.6"],["c4q06","c4_2",1,"X","CXL.cache나 CXL.mem에 참여하는 Function이 INTx 메시지를 보낼 수 있나요?","May a Function that takes part in CXL.cache or CXL.mem generate INTx messages?",["보내면 안 된다","권장되지만 선택이다","CXL.mem에 참여할 때만 보낼 수 있다","PCIe와 똑같이 자유롭다"],["No, it must not","Yes, it is recommended but optional","Only when it takes part in CXL.mem","Yes, freely, as in PCIe"],0,"PCIe에서는 INTx emulation이 허용되지만, CXL.cache/CXL.mem에 참여하는 Function은 INTx를 쓰면 안 됩니다.","PCIe allows INTx emulation, but a Function that participates in CXL.cache/CXL.mem must not use INTx.","§3.1.1"],["c4q07","c4_2",3,"X","다음 중 INTx 메시지를 보내는 것이 (권장되진 않지만) 허용되는 Function은?","Which Function is permitted (though not recommended) to generate INTx messages?",["MLD의 LD에 속한 non-CXL Function","CXL.mem에 참여하는 Type 3 Function","CXL.cache에 참여하는 Type 1 Function","MLD가 아닌 장치에서 Non-CXL Function Map DVSEC에 열거된 non-CXL Function"],["A non-CXL Function belonging to an LD of an MLD","A Type 3 Function that takes part in CXL.mem","A Type 1 Function that takes part in CXL.cache","A non-CXL Function listed in the Non-CXL Function Map DVSEC on a non-MLD device"],3,"non-CXL Function은 INTx가 허용되지만, MLD의 LD에 속한 Function은 non-CXL이라도 INTx를 쓸 수 없습니다.","Non-CXL Functions may use INTx, but Functions in an MLD's LD may not, even if they are non-CXL.","§3.1.1"],["c4q08","c4_3",1,"X","CXL Power Management 메시지(PMREQ, PMRSP, PMGO 등)는 어떤 TLP로 보내나요?","Which TLP carries CXL power management messages (PMREQ, PMRSP, PMGO, etc.)?",["PCIe PM_PME message","4-DWORD payload가 있는 PCIe Vendor Defined Type 0 message","CXL.cachemem control flit","Configuration Write"],["A PCIe PM_PME message","A PCIe Vendor Defined Type 0 message with a 4-DWORD payload","A CXL.cachemem control flit","A Configuration Write"],1,"CXL은 새 TLP 유형을 만들지 않고 PCIe의 VDM 틀에 PM 정보를 담습니다.","CXL creates no new TLP type; it puts PM content inside the PCIe VDM format.","§3.1.2"],["c4q09","c4_3",1,"X","CXL VDM의 Vendor ID 값은?","What Vendor ID value do CXL VDMs use?",["8086h","1E98h","1AF4h","FFFFh"],["8086h","1E98h","1AF4h","FFFFh"],1,"PM VDM과 Error VDM 모두 Vendor ID 1E98h를 쓰고, Byte 15의 VDM Code로 종류를 나눕니다(PM=68h, Error=00h).","Both PM and Error VDMs use Vendor ID 1E98h; the VDM Code in Byte 15 tells them apart (PM=68h, Error=00h).","§3.1.2"],["c4q10","c4_3",2,"X","CXL PM VDM의 routing 방식은?","Which routing do CXL PM VDMs use?",["Routed to Root Complex","Broadcast from Root Complex","Route by ID","Local - Terminate at Receiver"],["Routed to Root Complex","Broadcast from Root Complex","Route by ID","Local - Terminate at Receiver"],3,"PM credit과 초기화는 링크 단위(link local)라서 PM VDM은 링크 상대에서 끝납니다.","PM credits and initialization are link-local, so PM VDMs terminate at the link partner.","§3.1.2"],["c4q11","c4_3",3,"X","CXL 장치가 poison(EP=1)된 PM VDM을 받으면?","What does a CXL component do when it receives a poisoned (EP=1) PM VDM?",["메시지를 버리고 advisory non-fatal error로 처리한다","Fatal error로 링크를 내린다","그대로 처리하고 오류를 기록하지 않는다","재전송을 요청한다"],["Drops it and treats it as an advisory non-fatal error","Takes the link down as a fatal error","Processes it and logs nothing","Requests a retransmission"],0,"정상 동작을 계속할 수 있으므로 advisory non-fatal로 다룹니다. 내용을 이해하지 못한 PM VDM은 오류 없이 조용히 버립니다.","Operation can continue, so it is advisory non-fatal. A PM VDM whose payload is not understood is silently dropped with no error.","§3.1.2"],["c4q12","c4_3",2,"X","GPF(Global Persistent Flush) PM 메시지와 credit의 관계는?","How do GPF (Global Persistent Flush) PM messages relate to PM credits?",["GPF 하나에 credit 2개가 필요하다","GPF는 CREDIT_RTN을 받은 뒤에만 보낼 수 있다","credit이 필요 없고, 수신 측은 GPF에 대해 CREDIT_RTN을 보내면 안 된다","GPF는 credit 대신 ALMP를 쓴다"],["Each GPF needs two credits","GPF may be sent only after a CREDIT_RTN","They need no credits, and the receiver must not send CREDIT_RTN for them","GPF uses ALMPs instead of credits"],2,"CREDIT_RTN 자체도 credit을 쓰지 않습니다. 다른 PM 메시지는 CREDIT_RTN으로 교환한 credit에 따라 보냅니다.","CREDIT_RTN itself uses no credit either; other PM messages follow the credits exchanged via CREDIT_RTN.","§3.1.2.1"],["c4q13","c4_4",2,"X","CXL Error VDM인 EFN(Event Firmware Notification)의 특징은?","What characterizes the CXL Error VDM called EFN (Event Firmware Notification)?",["4-DWORD payload와 Local routing을 쓴다","Host가 장치로 broadcast한다","CXL.cachemem link layer로 전달된다","data payload 없이 Root Complex로 routing되며 항상 장치가 시작한다"],["A 4-DWORD payload with local routing","Broadcast from the host to devices","Carried by the CXL.cachemem link layer","No data payload, routed to the Root Complex, always started by a device"],3,"EFN은 Vendor Defined Type 0, Vendor ID 1E98h, VDM Code 00h이고, 메모리 오류 보고에 쓰면 MEFN이라 부릅니다.","EFN is a Vendor Defined Type 0 message with Vendor ID 1E98h and VDM Code 00h; used for memory errors it is called MEFN.","§3.1.3"],["c4q14","c4_4",1,"X","장치가 검출한 CXL.cache/CXL.mem 오류는 어떻게 보고되나요?","How are CXL.cache/CXL.mem errors detected by a device reported?",["CXL.cachemem flit의 전용 error slot으로만 보낸다","CXL.io로 Upstream에 전파되고, PCIe AER에 internal error로 기록된다","ARB/MUX가 ALMP로 보고한다","보고하지 않고 장치 안에서만 처리한다"],["Sent only in a dedicated error slot of CXL.cachemem flits","Propagated upstream over CXL.io and logged as internal errors in PCIe AER","Reported by the ARB/MUX through ALMPs","Handled inside the device and never reported"],1,"cachemem 오류도 CXL.io 경로와 PCIe AER의 correctable/uncorrectable internal error로 드러납니다.","Cachemem errors surface through CXL.io as correctable/uncorrectable internal errors in PCIe AER.","§3.1.5"],["c4q15","c4_4",2,"X","PCIe에서는 optional이지만 CXL에서는 CXL.cache가 있을 때만 필수인 기능은?","Which PCIe-optional feature is required in CXL only when CXL.cache is present?",["AER","Data Poisoning by transmitter","ATS","SR-IOV"],["AER","Data Poisoning by transmitter","ATS","SR-IOV"],2,"Table 3-3의 ATS 요구는 CXL.cache가 있는 Type 1/Type 2에만 해당하고 Type 3에는 해당하지 않습니다. AER와 송신 측 Data Poisoning은 조건 없이 필요합니다. SR-IOV는 이 표에 없습니다.","Table 3-3's ATS requirement applies only with CXL.cache (Type 1/2, not Type 3); AER and transmitter Data Poisoning are needed unconditionally. SR-IOV is not in the table.","§3.1.4"],["c4q16","c4_4",1,"X","PCIe에서는 optional이지만 CXL에서는 필수로 나열된 기능은?","Which feature, optional in PCIe, is listed as required for CXL?",["Advanced Error Reporting(AER)","Resizable BAR","Hot-Plug Surprise","Access Control Services(ACS)"],["Advanced Error Reporting (AER)","Resizable BAR","Hot-Plug Surprise","Access Control Services (ACS)"],0,"Table 3-3에는 송신 측 Data Poisoning, ATS(CXL.cache가 있을 때), AER가 나열됩니다.","Table 3-3 lists transmitter Data Poisoning, ATS (when CXL.cache is present), and AER.","§3.1.4"],["c4q17","c4_5",2,"X","ATS Translation Completion의 CXL.io bit가 1이면?","What does CXL.io bit = 1 in an ATS Translation Completion mean?",["그 page에는 CXL.io로만 요청해야 하고 CXL.cache로 요청하면 위반이다","그 page는 CXL.cache로만 접근해야 한다","그 page는 HDM이다","변환이 실패했다"],["Requests to that page must use CXL.io only; using CXL.cache is a violation","The page must be accessed via CXL.cache only","The page is HDM","The translation failed"],0,"Host는 예를 들어 Uncacheable 메모리처럼 CXL.io로만 접근해야 하는 영역을 이 bit로 알려 줍니다.","The host uses this bit to mark regions, such as uncacheable memory, that must be reached via CXL.io only.","§3.1.6"],["c4q18","c4_5",2,"X","ATS 요청을 보내는 모든 CXL Function이 지켜야 할 것은?","What must every CXL Function that issues ATS requests do?",["ATS 요청에 PTH를 붙인다","ATS 요청을 CXL.cache 채널로 보낸다","ATS Capability의 Page Aligned Request bit를 1로 두고, 요청에 CXL Src bit를 1로 설정한다","CXL Src bit를 0으로 둔다"],["Prepend a PTH to ATS requests","Send ATS requests on the CXL.cache channel","Set Page Aligned Request to 1 in the ATS Capability and set the CXL Src bit to 1 in requests","Keep the CXL Src bit at 0"],2,"CXL Src bit는 PCIe ATS 요청에서는 Reserved인 자리를 씁니다. 이 bit가 1일 때만 completion의 CXL.io bit가 유효합니다.","The CXL Src bit uses a position that is Reserved in PCIe ATS requests; the completion's CXL.io bit is valid only when it is set.","§3.1.6"],["c4q19","c4_6",1,"X","PBR link에서 NOP이 아닌 CXL.io TLP에 붙는 PTH(PBR TLP Header)의 크기는?","On a PBR link, how large is the PTH (PBR TLP Header) added to non-NOP CXL.io TLPs?",["4 DWORD","1 DWORD","2 byte","16 byte"],["4 DWORDs","1 DWORD","2 bytes","16 bytes"],1,"PTH는 고정 1-DWORD이고 TLP Header base 바로 앞에 옵니다. NOP TLP에는 붙지 않고, Local Prefix가 있으면 PTH보다 먼저 보냅니다.","PTH is a fixed 1 DWORD placed right before the TLP header base; NOP TLPs never get one, and Local Prefixes go before it.","§3.1.8"],["c4q20","c4_6",3,"X","PBR link에서 PTH가 검출되기 전 DWORD 첫 byte의 bit[7:6]이 11b이면?","On a PBR link, before a PTH is found, what does bits[7:6] = 11b in a DWORD's first byte mean?",["NOP TLP","Local Prefix","Reserved (조용히 버림)","PTH"],["NOP TLP","Local Prefix","Reserved (silently dropped)","PTH"],3,"00b=NOP TLP, 01b=Reserved(그 DWORD를 조용히 버림), 10b=Local Prefix, 11b=PTH입니다.","00b = NOP TLP, 01b = Reserved (that DWORD is silently dropped), 10b = Local Prefix, 11b = PTH.","§3.1.8"],["c4q21","c4_6",2,"X","PTH가 붙는 PBR link는 어떤 링크인가요?","Which links count as PBR links that carry the PTH?",["모든 Host-장치 직결 링크","68B Flit mode 링크","Inter-Switch Link(ISL)와 PBR switch에서 G-FAM으로 가는 edge link","PCIe mode로 학습한 링크"],["Every direct host-to-device link","Links in 68B Flit mode","Inter-Switch Links (ISLs) and edge links from a PBR switch to G-FAM","Links trained in PCIe mode"],2,"PBR fabric 안의 ISL과 G-FAM edge link에서만 PTH를 쓰며, PTH를 넣고 빼는 위치는 fabric 경로에서 정해집니다.","Only ISLs and G-FAM edge links inside the PBR fabric carry PTH; where it is inserted and removed is set along the fabric path.","§3.1.8"],["c4q22","c4_7",1,"X","MLD Port에서 CXL.io가 LD-ID를 나르는 방법은?","How does CXL.io carry the LD-ID over an MLD Port?",["VendPrefixL0 Local TLP Prefix에 16-bit LD-ID를 싣는다","TLP header의 Tag field에 4-bit로 싣는다","PTH에 싣는다","별도 ALMP로 보낸다"],["A 16-bit LD-ID in the VendPrefixL0 Local TLP Prefix","4 bits in the TLP header Tag field","Inside the PTH","In a separate ALMP"],0,"CXL.io는 16-bit LD-ID를 쓰고 FFFFh는 FM 전용으로 예약됩니다. CXL.mem은 하위 4 bit만 씁니다.","CXL.io uses a 16-bit LD-ID with FFFFh reserved for the FM; CXL.mem uses only the low 4 bits.","§2.4.1.2"],["c4q23","c4_7",3,"X","PBR switch에 직결된 non-MLD HBR edge link에서 VendPrefixL0가 담는 것은?","On a non-MLD HBR edge link attached to a PBR switch, what does VendPrefixL0 carry?",["16-bit LD-ID","HDM decoder 번호","CXL DevLoad 값","PBR-ID[11:0]. switch 입구에서는 대상 DPID, 출구에서는 출발 SPID"],["A 16-bit LD-ID","An HDM decoder number","A CXL DevLoad value","PBR-ID[11:0]: the target DPID at switch ingress, the source SPID at egress"],3,"Host와 장치 사이의 inter-domain 통신 등에 씁니다. switch 쪽 처리는 기본으로 꺼져 있고 FM이 포트별로 켭니다.","It supports inter-domain host-device traffic, among other uses; switch handling is off by default and the FM enables it per port.","§3.1.9"],["c4q24","c4_8",2,"X","Latency-optimized 256B flit에서 CXL.io NOP TLP alignment 계산의 기준이 되는 TLP 영역 크기는?","In a latency-optimized 256B flit, what TLP area size is CXL.io NOP TLP alignment computed against?",["236 byte","232 byte","240 byte","256 byte"],["236 bytes","232 bytes","240 bytes","256 bytes"],1,"Standard 256B flit은 236 byte, latency-optimized flit은 첫 half 끝의 6B CRC 때문에 232 byte가 기준입니다.","It is 236 bytes for standard 256B flits and 232 bytes for latency-optimized flits because of the 6B CRC after the first half.","§4.1"],["c4q25","c4_8",3,"X","Standard 256B flit에서 PCIe의 '최대 non-NOP TLP 수' 규칙은 어떻게 적용되나요?","In a standard 256B flit, how is the PCIe maximum non-NOP TLP count rule applied?",["flit 전체 256 byte에 한 번 적용한다","앞 128 TLP byte와 나머지 108 TLP byte 두 묶음에 따로 적용한다","64 byte 묶음 4개에 따로 적용한다","CXL에서는 적용하지 않는다"],["Once over the whole 256-byte flit","Separately to two groups: the first 128 TLP bytes and the remaining 108","Separately to four 64-byte groups","It does not apply in CXL"],1,"64 GT/s 이하에서는 각 묶음에 PCIe의 8개 제한이 적용됩니다. Latency-optimized flit은 128 + 104 byte로 나눕니다.","At 64 GT/s and below, PCIe's limit of 8 applies per group; latency-optimized flits split into 128 + 104 bytes.","§4.1"],["c4q26","c4_8",2,"X","68B Flit mode에서 CXL.io TLP가 flit 경계에서 정확히 끝났고 더 보낼 CXL.io 트래픽이 없으면?","In 68B Flit mode, if a CXL.io TLP ends exactly on a flit boundary and no more CXL.io traffic is pending, what happens?",["아무것도 보내지 않는다","TLP를 다음 flit에서 다시 보낸다","CXL.cachemem flit으로 마무리한다","Link Layer가 IDLE token을 담은 CXL.io flit을 하나 더 보내 수신기가 TLP를 처리하게 한다"],["Nothing is sent","The TLP is resent in the next flit","A CXL.cachemem flit closes it","The link layer sends one more CXL.io flit with IDLE tokens so the receiver can process the TLP"],3,"수신기는 TLP가 nullified가 아닌 정상 TLP임을 확인할 후속 표시가 필요하므로, 다음 CXL.io flit이 반드시 있어야 합니다.","The receiver needs a following indication to confirm the TLP is good rather than nullified, so a following CXL.io flit is required.","§6.2.2.7"],["c4q27","c4_9",1,"C","예전 CXL 스펙에 있던 'Deferrable Writes' 확장은 지금 어디에 정의되어 있나요?","Where is the 'Deferrable Writes' extension from earlier CXL specs defined now?",["PCIe Base Specification","CXL.cache 프로토콜","CXL Fabric Manager API","ARB/MUX 장"],["The PCIe Base Specification","The CXL.cache protocol","The CXL Fabric Manager API","The ARB/MUX chapter"],0,"이 프로토콜은 PCIe Base Specification에 채택되어 이제 PCIe와 CXL.io가 같은 정의를 씁니다.","It was adopted into the PCIe Base Specification, so PCIe and CXL.io now share the definition.","§3.1.7"],["c4q28","c4_9",2,"X","Bundled Port의 Streamlined Port는 CXL.io 관점에서 어떻게 동작하나요?","From the CXL.io point of view, how does a Streamlined Port in a Bundled Port behave?",["68B Flit mode로만 동작한다","CXL.io를 전혀 지원하지 않는다","독립된 PCIe port처럼 PCIe 규칙을 따르고, 256B Flit mode로만 동작한다","여러 port가 하나의 TLP 흐름으로 자동 합쳐진다"],["Only in 68B Flit mode","It has no CXL.io support","Like an independent PCIe port following PCIe rules, in 256B Flit mode only","Several ports merge automatically into one TLP stream"],2,"링크 집계는 아직 PCIe에 정의가 없어 각 port가 독립적으로 동작합니다. 대역폭이 큰 VC0 트래픽은 standard full-capability port를 쓰도록 권장합니다.","There is no PCIe link aggregation yet, so each port acts on its own; heavy VC0 traffic is recommended on a standard full-capability port.","§3.1.12"],["c4q29","c4_9",3,"X","UIO Completion에 들어가는 CDL(CXL DevLoad) field는?","What is the CDL (CXL DevLoad) field in UIO Completions?",["모든 PCIe Completion에 있는 8-bit field","PTH 안의 4-bit field","ALMP의 Byte 2","UIOWrCpl, UIORdCpl, UIORdCplD에 있는 2-bit field로 HDM 장치의 부하를 알린다"],["An 8-bit field in every PCIe Completion","A 4-bit field inside the PTH","Byte 2 of an ALMP","A 2-bit field in UIOWrCpl, UIORdCpl and UIORdCplD that reports the HDM device's load"],3,"UIO Direct P2P to HDM에서 QoS Telemetry를 지원하기 위한 field입니다.","It supports QoS Telemetry for UIO Direct P2P to HDM.","§3.1.10"]],"5":[["p5q01","p5_1",1,"C","PCI Express Transaction Layer가 지원하는 네 가지 address space는 무엇인가?","Which four address spaces does the PCI Express Transaction Layer support?",["Memory, I/O, Configuration, Message","Memory, I/O, Configuration, Cache-Coherent","Memory, I/O, Configuration, DMA","Memory, Configuration, Interrupt, Flit"],["Memory, I/O, Configuration, and Message","Memory, I/O, Configuration, and Cache-Coherent","Memory, I/O, Configuration, and DMA","Memory, Configuration, Interrupt, and Flit"],0,"표준은 PCI의 Memory·I/O·Configuration 세 address space에 Message Space를 더해 네 가지를 지원한다고 한다. Cache-coherent address space는 PCIe Transaction Layer에 정의되어 있지 않다.","The Transaction Layer includes the three PCI address spaces (Memory, I/O, and Configuration) and adds Message Space. A cache-coherent address space is not defined for the PCIe Transaction Layer.","§1.5.1"],["p5q02","p5_1",1,"C","Transaction Descriptor의 No Snoop attribute가 1b이면 Cache Coherency Management는 무엇을 의미하는가?","If the No Snoop attribute in the Transaction Descriptor is 1b, what does that Cache Coherency Management encoding mean?",["The Completer must snoop all CPU caches before completing the Request","The Request uses a directory-based coherency protocol defined in this specification","Hardware enforced cache coherency is not expected","Transaction ordering rules are relaxed in the same way as the Relaxed Ordering attribute"],["The Completer must snoop all CPU caches before completing the Request","The Request uses a directory-based coherency protocol defined in this specification","Hardware enforced cache coherency is not expected","Transaction ordering rules are relaxed in the same way as the Relaxed Ordering attribute"],2,"정답 요지: Hardware enforced cache coherency is not expected","Key point: Hardware enforced cache coherency is not expected","§2.2.6.5"],["p5q03","p5_1",2,"C","No Snoop attribute에 대한 다음 설명 중 PCIe Base 7.0과 일치하는 것은?","Which statement about the No Snoop attribute matches PCI Express Base 7.0?",["No Snoop must be Set on every Memory Write so that the Root Complex can skip cache lookup.","This attribute is not applicable and must be Clear for Configuration Requests, I/O Requests, Memory Requests that are Message Signaled Interrupts, and Message Requests (except where specifically permitted).","Setting No Snoop automatically enables Relaxed Ordering for that TLP.","The Base specification defines a cache-line state machine (e.g., M/E/S/I) that Endpoints must implement when No Snoop is Clear."],["No Snoop must be Set on every Memory Write so that the Root Complex can skip cache lookup.","This attribute is not applicable and must be Clear for Configuration Requests, I/O Requests, Memory Requests that are Message Signaled Interrupts, and Message Requests (except where specifically permitted).","Setting No Snoop automatically enables Relaxed Ordering for that TLP.","The Base specification defines a cache-line state machine (e.g., M/E/S/I) that Endpoints must implement when No Snoop is Clear."],1,"No Snoop은 Config·I/O·MSI Memory·Message Request에는 적용되지 않으며 (특별히 허용된 경우를 제외하고) Clear여야 한다. Base spec은 Endpoint용 cache-line state machine을 정의하지 않는다.","The attribute is not applicable and must be Clear for Configuration, I/O, MSI Memory, and Message Requests (except where specifically permitted). The Base spec does not define a cache-line state machine for Endpoints.","§2.2.6.5"],["p5q04","p5_1",2,"C","PCIe Base 7.0 원문에서 cache coherency와 관련하여 실제로 정의된 내용은 무엇인가?","What does PCI Express Base 7.0 actually define regarding cache coherency?",["A normative definition that CXL.io is identical to the PCIe Transaction Layer","A mandatory cache-coherent agent protocol that every Endpoint must implement","A requirement that all Memory Requests snoop host caches","A No Snoop attribute that indicates whether hardware-enforced cache coherency is expected"],["A normative definition that CXL.io is identical to the PCIe Transaction Layer","A mandatory cache-coherent agent protocol that every Endpoint must implement","A requirement that all Memory Requests snoop host caches","A No Snoop attribute that indicates whether hardware-enforced cache coherency is expected"],3,"Base spec이 규범적으로 정의하는 것은 Transaction Descriptor의 No Snoop(Cache Coherency Management Attribute)이다. CXL.io가 PCIe TL과 동일하다는 정의나 Endpoint 필수 coherency protocol은 이 표준에 없다.","What the Base spec normatively defines is the No Snoop (Cache Coherency Management) attribute. It does not define CXL.io as identical to the PCIe Transaction Layer, nor a mandatory Endpoint coherency protocol.","§2.2.6.5"],["p5q05","p5_2",2,"C","Alternate Protocol Negotiation은 어느 LTSSM 조건에서, 어떤 Ordered Set으로 수행되는가?","Under which LTSSM conditions, and with which Ordered Sets, is Alternate Protocol Negotiation performed?",["During Recovery.RcvrLock after reaching L0, by exchanging SDS Ordered Sets in 128b/130b encoding","During Detect.Quiet, by exchanging TS1 Ordered Sets in 1b/1b encoding","During Configuration.Lanenum.Wait, Configuration.Lanenum.Accept, and Configuration.Complete, while LinkUp=0b, by exchanging Modified TS1/TS2 Ordered Sets in 8b/10b encoding","During L0, by exchanging PM_Enter_L23 DLLPs"],["During Recovery.RcvrLock after reaching L0, by exchanging SDS Ordered Sets in 128b/130b encoding","During Detect.Quiet, by exchanging TS1 Ordered Sets in 1b/1b encoding","During Configuration.Lanenum.Wait, Configuration.Lanenum.Accept, and Configuration.Complete, while LinkUp=0b, by exchanging Modified TS1/TS2 Ordered Sets in 8b/10b encoding","During L0, by exchanging PM_Enter_L23 DLLPs"],2,"§4.2.5.2는 APN이 LinkUp=0b인 Configuration.Lanenum.Wait/Accept 및 Configuration.Complete에서 8b/10b Modified TS1/TS2 교환으로 이뤄진다고 규정한다.","§4.2.5.2 states that alternate protocols may be negotiated during Configuration.Lanenum.Wait, Configuration.Lanenum.Accept, and Configuration.Complete while LinkUp=0b, through Modified TS1/TS2 Ordered Sets in 8b/10b encoding.","§4.2.5.2"],["p5q06","p5_2",1,"C","PCIe Base 7.0에서 alternate protocol의 정의는 무엇인가?","How does PCI Express Base 7.0 define an alternate protocol?",["A non-PCIe protocol using the PCIe PHY layer","Any protocol that replaces the PCIe Physical Layer with a different PHY","A software-only protocol negotiated after enumeration in Configuration Space","A cache-coherency protocol that is mandatory when Flit Mode is enabled"],["A non-PCIe protocol using the PCIe PHY layer","Any protocol that replaces the PCIe Physical Layer with a different PHY","A software-only protocol negotiated after enumeration in Configuration Space","A cache-coherency protocol that is mandatory when Flit Mode is enabled"],0,"표준 문장: 'An alternate protocol is defined to be a non-PCIe protocol using the PCIe PHY layer.' Ordered Set block 규칙은 그대로 쓰고 Data Block 내용만 alternate protocol 규칙에 따라 바뀔 수 있다.","The spec defines an alternate protocol as a non-PCIe protocol using the PCIe PHY layer. Ordered Set blocks are used as-is; Data Block contents may be modified according to the alternate protocol.","§4.2.5.2"],["p5q07","p5_2",2,"C","Alternate protocol mode에서 PCIe protocol과 alternate protocol의 공존에 대해 표준이 허용하는 것은?","What does the specification permit regarding coexistence of the PCIe protocol and alternate protocols?",["Exactly one protocol, either PCIe or a single alternate protocol, may be active; mixing is forbidden","PCIe protocol must be disabled completely once any alternate protocol is advertised in Modified TS1","Alternate protocols are permitted only in Non-Flit Mode and never together with PCIe","One may choose to run the PCIe protocol in addition to one or multiple alternate protocols in the alternate protocol mode"],["Exactly one protocol, either PCIe or a single alternate protocol, may be active; mixing is forbidden","PCIe protocol must be disabled completely once any alternate protocol is advertised in Modified TS1","Alternate protocols are permitted only in Non-Flit Mode and never together with PCIe","One may choose to run the PCIe protocol in addition to one or multiple alternate protocols in the alternate protocol mode"],3,"표준은 alternate protocol mode에서 PCIe protocol을 하나 또는 여러 alternate protocol과 함께 운용하는 것을 허용한다. Alternate protocol은 128b/130b 또는 1b/1b encoding의 PCIe PHY와 함께 지원될 수 있다.","The spec permits running the PCIe protocol in addition to one or multiple alternate protocols in alternate protocol mode. Alternate protocols may be supported with the PCIe PHY in 128b/130b or 1b/1b encodings.","§4.2.5.2"],["p5q08","p5_2",3,"C","Alternate Protocol Negotiation이 성공한 뒤 Data Block이 alternate protocol을 나르기 시작하는 시점은?","After a successful Alternate Protocol Negotiation, when do Data Blocks start carrying the alternate protocol?",["Immediately when the first Modified TS1 with Usage=010b is transmitted in Configuration.Lanenum.Wait","After transmitting the SDS Ordered Set at the highest data rate after equalization has been performed","As soon as the Upstream Port returns Negotiation Status 10b in a Modified TS1","Only after software sets a DVSEC enable bit following enumeration in L0"],["Immediately when the first Modified TS1 with Usage=010b is transmitted in Configuration.Lanenum.Wait","After transmitting the SDS Ordered Set at the highest data rate after equalization has been performed","As soon as the Upstream Port returns Negotiation Status 10b in a Modified TS1","Only after software sets a DVSEC enable bit following enumeration in L0"],1,"성공 시 Link는 2.5 GT/s L0으로 들어간 뒤 더 높은 속도로 올리고 필요하면 equalization을 수행한다. 최고 속도에서 equalization 후 SDS Ordered Set을 보낸 뒤에야 Data Block이 alternate protocol을 나르고 Link는 그 protocol 제어 아래로 들어간다.","On success the Link goes to L0 at 2.5 GT/s, then changes to higher rates and performs equalization if needed. After transmitting the SDS Ordered Set at the highest data rate after equalization, Data Blocks carry the alternate protocol and the Link is under that protocol’s control.","§4.2.5.2"],["p5q09","p5_2",2,"C","Downstream Port가 Alternate Protocol Negotiation을 시작하는 조건은?","When does a Downstream Port that supports Alternate Protocol Negotiation start the negotiation process?",["When it first enters Recovery.Idle with LinkUp=1 and Usage Mode Selected is 000b","When it first enters Configuration.Lanenum.Wait, LinkUp=0, and the Modified TS Usage Mode Selected field is 010b","When software writes the DVSEC Vendor ID after reaching L0 at 64.0 GT/s","When it first enters Detect.Active and receives two consecutive TS2 Ordered Sets"],["When it first enters Recovery.Idle with LinkUp=1 and Usage Mode Selected is 000b","When it first enters Configuration.Lanenum.Wait, LinkUp=0, and the Modified TS Usage Mode Selected field is 010b","When software writes the DVSEC Vendor ID after reaching L0 at 64.0 GT/s","When it first enters Detect.Active and receives two consecutive TS2 Ordered Sets"],1,"협상 시작은 Configuration.Lanenum.Wait 최초 진입, LinkUp=0, Modified TS Usage Mode Selected=010b일 때이며, Modified TS Usage=010b인 Modified TS1/TS2를 보내는 것으로 이루어진다.","A supporting Downstream Port starts negotiation when it first enters Configuration.Lanenum.Wait, LinkUp=0, and Modified TS Usage Mode Selected is 010b, by sending Modified TS1/TS2 with Modified TS Usage=010b.","§4.2.5.2"],["p5q10","p5_2",2,"C","Alternate Protocol Negotiation 절차 전 구간에 대해 표준이 strongly recommend하는 data rate 안내는?","What data-rate guidance does the specification strongly recommend throughout the Alternate Protocol Negotiation procedure?",["Only 2.5 GT/s may be advertised until after SDS at the final rate","128.0 GT/s must already be the operational data rate before Modified TS1 is sent","The advertised data rate must be exactly 8.0 GT/s in Configuration.Complete","A data rate of 32.0 GT/s or higher is advertised in all three Configuration substates throughout the procedure"],["Only 2.5 GT/s may be advertised until after SDS at the final rate","128.0 GT/s must already be the operational data rate before Modified TS1 is sent","The advertised data rate must be exactly 8.0 GT/s in Configuration.Complete","A data rate of 32.0 GT/s or higher is advertised in all three Configuration substates throughout the procedure"],3,"표준은 세 Configuration substate 전체에서 32.0 GT/s 이상을 advertise할 것을 strongly recommend한다. 이는 must가 아니라 권고이므로 퀴즈에서도 권고로 묻는다.","The spec strongly recommends that a data rate of 32.0 GT/s or higher is advertised in all three substates throughout the entire alternate protocol negotiation procedure. This is a recommendation, not a must.","§4.2.5.2"],["p5q11","p5_3",1,"C","Modified TS1/TS2의 Modified TS Usage 필드 010b는 무엇을 나타내는가?","What does the Modified TS Usage field encoding 010b indicate in Modified TS1/TS2 Ordered Sets?",["Alternate Protocol Negotiation","PCIe protocol only","PCIe protocol only with vendor-defined Training Set Messages","Equalization bypass to the highest PAM4 rate"],["Alternate Protocol Negotiation","PCIe protocol only","PCIe protocol only with vendor-defined Training Set Messages","Equalization bypass to the highest PAM4 rate"],0,"Modified TS Usage는 000b=PCIe protocol only, 001b=PCIe protocol only with vendor defined Training Set Messages, 010b=Alternate Protocol Negotiation, 나머지는 Reserved이다.","Modified TS Usage encodings are 000b=PCIe protocol only, 001b=PCIe protocol only with vendor-defined Training Set Messages, 010b=Alternate Protocol Negotiation, and others Reserved.","§4.2.5.1"],["p5q12","p5_3",2,"C","Upstream Port가 지원하지 않는 Modified TS Usage 값을 받았을 때 어떻게 응답해야 하는가?","How must an Upstream Port respond to unsupported Modified TS Usage values?",["By transmitting Modified TS Usage 010b with Negotiation Status 11b","By immediately entering Detect.Quiet","By transmitting Modified TS Usage 000b","By ignoring the Modified TS and continuing to send ordinary TS1 with the same Usage field"],["By transmitting Modified TS Usage 010b with Negotiation Status 11b","By immediately entering Detect.Quiet","By transmitting Modified TS Usage 000b","By ignoring the Modified TS and continuing to send ordinary TS1 with the same Usage field"],2,"표준: 'Upstream Ports must respond to unsupported Modified TS Usage values by transmitting Modified TS Usage 000b.' 000b이면 Link는 PCI Express Link로 동작한다.","Upstream Ports must respond to unsupported Modified TS Usage values by transmitting Modified TS Usage 000b. With Usage 000b, the Link operates as a PCI Express Link.","§4.2.5.2"],["p5q13","p5_3",3,"C","Modified TS Usage=010b인 Modified TS1에서, Upstream Port의 Alternate Protocol Negotiation Status 10b는 무엇을 뜻하는가?","In a Modified TS1 with Modified TS Usage=010b, what does Alternate Protocol Negotiation Status 10b mean when sent by an Upstream Port?",["The Upstream Port does not yet have an answer for the protocol request","The Upstream Port does not support the requested protocol","The Downstream Port is confirming the selected protocol","The Upstream Port supports the requested protocol"],["The Upstream Port does not yet have an answer for the protocol request","The Upstream Port does not support the requested protocol","The Downstream Port is confirming the selected protocol","The Upstream Port supports the requested protocol"],3,"Table 4-41: TS1에서 USP 00b=아직 답이 없음, 01b=요청 protocol 미지원, 10b=요청 protocol 지원. 11b와 DSP의 01b/10b는 Reserved. 확인(confirmation)은 Modified TS2의 00b이다.","In Table 4-41, for Modified TS1 the USP encodings are 00b=no answer yet, 01b=does not support the requested protocol, and 10b=supports the requested protocol. Confirmation is status 00b in Modified TS2.","§4.2.5.2"],["p5q14","p5_3",3,"C","Alternate Protocol이 선택되지 않는 경우와, Downstream Port가 어떤 Alternate Protocol도 쓰지 않기로 할 때의 동작은?","When is no Alternate Protocol selected, and how must a Downstream Port indicate that it will not use any Alternate Protocol?",["Any single Modified TS1 with Status 10b automatically selects that protocol, and the Downstream Port then sends ordinary TS2","No protocol is selected unless the Downstream Port sends and receives a protocol confirmation in Modified TS2; if it decides not to use any Alternate Protocol, it must transmit Modified TS2 with Modified TS Usage 000b or 001b","The Upstream Port selects the protocol by sending Modified TS2 with Usage 010b and Status 11b","Software must write the Alternate Protocol Control register before any protocol can be declined"],["Any single Modified TS1 with Status 10b automatically selects that protocol, and the Downstream Port then sends ordinary TS2","No protocol is selected unless the Downstream Port sends and receives a protocol confirmation in Modified TS2; if it decides not to use any Alternate Protocol, it must transmit Modified TS2 with Modified TS Usage 000b or 001b","The Upstream Port selects the protocol by sending Modified TS2 with Usage 010b and Status 11b","Software must write the Alternate Protocol Control register before any protocol can be declined"],1,"표준은 TS2에서 DSP가 보내고 받는 protocol confirmation이 있어야 선택된다고 한다. Alternate Protocol을 쓰지 않으려면 Modified TS2를 Usage 000b 또는 001b로 보낸다.","No protocol is selected unless the Downstream Port sends and receives a protocol confirmation in Modified TS2. If it decides not to use any Alternate Protocol, it must transmit Modified TS2 with Usage 000b or 001b.","§4.2.5.2"],["p5q15","p5_3",2,"C","Alternate Protocol Negotiation과 Lane number negotiation의 관계로 옳은 것은?","What is the required relationship between Alternate Protocol Negotiation and Lane number negotiation?",["Lane number negotiation must fully complete, including Configuration.Idle, before any Modified TS Usage=010b is sent","Alternate Protocol Negotiation is allowed only after the Link has reached L0 and Lane numbers are already frozen","Alternate Protocol Negotiation must be concurrent with the Lane number negotiation","The two negotiations are mutually exclusive; the Downstream Port must choose one or the other"],["Lane number negotiation must fully complete, including Configuration.Idle, before any Modified TS Usage=010b is sent","Alternate Protocol Negotiation is allowed only after the Link has reached L0 and Lane numbers are already frozen","Alternate Protocol Negotiation must be concurrent with the Lane number negotiation","The two negotiations are mutually exclusive; the Downstream Port must choose one or the other"],2,"표준: 'Alternate Protocol Negotiation must be concurrent with the Lane number negotiation.' DSP는 Configuration.Complete로 넘어가기 전에 일련의 Modified TS1으로 protocol을 요청·평가한다.","Alternate Protocol Negotiation must be concurrent with Lane number negotiation. The Downstream Port requests one or more Alternate Protocols with a series of Modified TS1 Ordered Sets and determines the resulting protocol before transitioning to Configuration.Complete.","§4.2.5.2"],["p5q16","p5_4",1,"C","Designated Vendor-Specific Extended Capability(DVSEC)의 PCI Express Extended Capability ID는?","What is the PCI Express Extended Capability ID for the Designated Vendor-Specific Extended Capability (DVSEC)?",["0023h","000Bh","002Bh","0010h"],["0023h","000Bh","002Bh","0010h"],0,"DVSEC Extended Capability ID는 0023h이다. 002Bh는 Alternate Protocol Extended Capability, 10h는 PCI-compatible PCI Express Capability ID이다.","The Extended Capability ID for DVSEC is 0023h. 002Bh is the Alternate Protocol Extended Capability, and 10h is the PCI-compatible PCI Express Capability ID.","§7.9.6.1"],["p5q17","p5_4",2,"C","DVSEC가 일반 Vendor-Specific Extended Capability(VSEC)와 구별되는 핵심 목적은 무엇인가?","What is the key purpose that distinguishes DVSEC from a general Vendor-Specific Extended Capability (VSEC)?",["It allows component vendors to expose vendor-specific registers that can be present in components by a variety of vendors, identified by a DVSEC Vendor ID that names the vendor who defined the contents","It replaces the Function’s PCI Vendor ID in the Type 0/1 header so that a single Vendor ID is shared by all vendors","It is mandatory in every Function and must be the first Extended Capability at offset 100h","It may only be implemented in RCRBs and is forbidden in Function Configuration Space"],["It allows component vendors to expose vendor-specific registers that can be present in components by a variety of vendors, identified by a DVSEC Vendor ID that names the vendor who defined the contents","It replaces the Function’s PCI Vendor ID in the Type 0/1 header so that a single Vendor ID is shared by all vendors","It is mandatory in every Function and must be the first Extended Capability at offset 100h","It may only be implemented in RCRBs and is forbidden in Function Configuration Space"],0,"DVSEC는 여러 vendor의 component에 같은 vendor-specific register 집합을 올릴 수 있게 하는 optional Extended Capability이다. DVSEC Vendor ID는 그 내용을 정의한 vendor를 가리키며, software는 DVSEC ID를 해석하기 전에 이 값을 qualify해야 한다.","DVSEC is an optional Extended Capability that lets vendors expose vendor-specific registers that can appear in components from a variety of vendors. The DVSEC Vendor ID identifies the vendor that defined the contents; software must qualify it before interpreting the DVSEC ID.","§7.9.6"],["p5q18","p5_4",1,"C","하나의 PCI Express Function 또는 RCRB에 DVSEC Capability structure를 몇 개까지 둘 수 있는가?","How many DVSEC Capability structures is a single PCI Express Function or RCRB permitted to contain?",["At most one DVSEC structure per Function or RCRB","Exactly two: one in the PCI-compatible region and one in Extended Configuration Space","Multiple DVSEC Capability structures are permitted","None in Functions; DVSEC is defined only for Switches"],["At most one DVSEC structure per Function or RCRB","Exactly two: one in the PCI-compatible region and one in Extended Configuration Space","Multiple DVSEC Capability structures are permitted","None in Functions; DVSEC is defined only for Switches"],2,"표준: 'A single PCI Express Function or RCRB is permitted to contain multiple DVSEC Capability structures.' DVSEC는 Function 또는 RCRB에 구현할 수 있는 optional Extended Capability이다.","A single PCI Express Function or RCRB is permitted to contain multiple DVSEC Capability structures. DVSEC is optional and may be implemented by any Function or RCRB.","§7.9.6"],["p5q19","p5_4",2,"C","Software가 DVSEC ID 필드를 해석하기 전에 반드시 qualify해야 하는 값은?","Which field must software qualify before interpreting the DVSEC ID field?",["The Function’s Device ID in the Type 0/1 header only","The DVSEC Vendor ID","The Alternate Protocol Vendor ID in Modified TS1","The VSEC Rev field of a different VSEC structure"],["The Function’s Device ID in the Type 0/1 header only","The DVSEC Vendor ID","The Alternate Protocol Vendor ID in Modified TS1","The VSEC Rev field of a different VSEC structure"],1,"Header 2 규칙: software는 DVSEC ID를 해석하기 전에 DVSEC Vendor ID를 qualify해야 한다. DVSEC Revision도 DVSEC Vendor ID와 DVSEC ID를 qualify한 뒤에 해석한다.","Software must qualify the DVSEC Vendor ID before interpreting the DVSEC ID. The DVSEC Revision likewise requires qualifying the DVSEC Vendor ID and DVSEC ID first.","§7.9.6.3"],["p5q20","p5_5",1,"C","Alternate Protocol Extended Capability의 Extended Capability ID는?","What is the Extended Capability ID for the Alternate Protocol Extended Capability?",["0023h","0001h","0019h","002Bh"],["0023h","0001h","0019h","002Bh"],3,"Alternate Protocol Capability의 Extended Capability ID는 002Bh이고 Capability Version은 이 버전에서 1h여야 한다.","The Extended Capability ID for the Alternate Protocol Capability is 002Bh. The Capability Version must be 1h for this version of the specification.","§7.9.20.1"],["p5q21","p5_5",2,"C","Alternate Protocol Extended Capability를 둘 수 있는 위치 제한으로 옳은 것은?","Where is the Alternate Protocol Extended Capability permitted to be implemented?",["In every Function of a Multi-Function Upstream Port Device, including Function 1 and above","Only in Root Complex Integrated Endpoints","Only in a Function associated with a Downstream Port, or in Function 0 (and only Function 0) of a Device associated with an Upstream Port","Only in the Root Complex Register Block, never in Function Configuration Space"],["In every Function of a Multi-Function Upstream Port Device, including Function 1 and above","Only in Root Complex Integrated Endpoints","Only in a Function associated with a Downstream Port, or in Function 0 (and only Function 0) of a Device associated with an Upstream Port","Only in the Root Complex Register Block, never in Function Configuration Space"],2,"이 structure는 Alternate Protocol Negotiation을 구현하는 component에서 optional이며, DSP의 Function, 또는 USP Device의 Function 0에만 허용된다.","The structure is optional in components that implement Alternate Protocol Negotiation. It is only permitted in a Function associated with a Downstream Port, or in Function 0 of a Device associated with an Upstream Port.","§7.9.20"],["p5q22","p5_5",2,"C","Alternate Protocol Control Register의 Alternate Protocol Negotiation Global Enable bit가 Clear이면 어떻게 되는가?","What happens when the Alternate Protocol Negotiation Global Enable bit in the Alternate Protocol Control Register is Clear?",["Alternate Protocol Negotiation is disabled for this Link","Alternate Protocol Negotiation is forced on for all Lanes regardless of Modified TS Usage","The bit is ignored; negotiation is controlled only by LTSSM timers","The Port must immediately retrain into Loopback"],["Alternate Protocol Negotiation is disabled for this Link","Alternate Protocol Negotiation is forced on for all Lanes regardless of Modified TS Usage","The bit is ignored; negotiation is controlled only by LTSSM timers","The Port must immediately retrain into Loopback"],0,"이 bit가 Set이면 해당 Link에서 APN이 enable되고, Clear이면 disable된다. Selective Enable Mask가 없으면 이 Global Enable만으로 제어된다.","When this bit is Set, Alternate Protocol Negotiation is enabled for this Link; when Clear, it is disabled. If the Selective Enable Mask Register is not present, negotiation is controlled solely by this Global Enable bit.","§7.9.20.3"],["p5q23","p5_6",1,"P","Data Stream in Flit Mode 지원이 필수가 되는 조건은?","When is support for Data Stream in Flit Mode mandatory?",["For every PCI Express component, including 2.5 GT/s-only implementations","Only if the component also implements an alternate protocol","Only in Non-Flit Mode Root Ports","Only if a data rate that exceeds 32.0 GT/s is supported"],["For every PCI Express component, including 2.5 GT/s-only implementations","Only if the component also implements an alternate protocol","Only in Non-Flit Mode Root Ports","Only if a data rate that exceeds 32.0 GT/s is supported"],3,"Non-Flit Mode Data Stream 지원은 필수이다. Flit Mode Data Stream 지원은 32.0 GT/s를 초과하는 data rate를 지원할 때에만 필수이다(32.0 GT/s 자체만 지원하면 Flit이 필수는 아니다).","Support of Data Stream in Non-Flit Mode is mandatory. Support of Data Stream in Flit Mode is mandatory only if a data rate that exceeds 32.0 GT/s is supported.","§1.2"],["p5q24","p5_6",1,"C","PCI Express Capabilities Register에서 Flit Mode Supported bit의 위치와 의미는?","Where is the Flit Mode Supported bit, and what does it mean?",["Bit 0 of the Command Register, RW; software Sets it to force Flit Mode","Bit 15, HwInit; when Set it indicates support for Flit Mode","Bit 3 of the Header Type Register, RO; when Set the Function is a Flit-only Endpoint","Bit 8 of the Link Control Register, RW; it enables Clock Power Management in Flit Mode"],["Bit 0 of the Command Register, RW; software Sets it to force Flit Mode","Bit 15, HwInit; when Set it indicates support for Flit Mode","Bit 3 of the Header Type Register, RO; when Set the Function is a Flit-only Endpoint","Bit 8 of the Link Control Register, RW; it enables Clock Power Management in Flit Mode"],1,"PCI Express Capabilities Register bit 15 Flit Mode Supported는 HwInit이다. Flit Mode를 지원하면 Set, 지원하지 않으면 Clear여야 한다.","Bit 15 of the PCI Express Capabilities Register is Flit Mode Supported (HwInit). It must be Set by implementations that support Flit Mode and Clear by those that do not.","§7.5.3.2"],["p5q25","p5_6",2,"C","하드웨어 initialization 동안 PCI Express Link는 무엇을 negotiation하는가?","During hardware initialization, what do the two agents at each end of a PCI Express Link negotiate?",["BAR sizes, Capability lists, and D-states, which must be completed by system firmware first","Link width, data rate, and Flit mode, with no firmware or operating system software involved","Only Lane reversal; width and rate are fixed in straps and never negotiated","The CXL.io Transaction Layer version, which is defined in this Base specification"],["BAR sizes, Capability lists, and D-states, which must be completed by system firmware first","Link width, data rate, and Flit mode, with no firmware or operating system software involved","Only Lane reversal; width and rate are fixed in straps and never negotiated","The CXL.io Transaction Layer version, which is defined in this Base specification"],1,"표준: 각 Link는 양단 agent가 Link width, data rate, Flit mode를 negotiation하여 설정되며 firmware나 OS는 관여하지 않는다. CXL.io 버전을 이 Base spec이 정의한다는 주장은 원문에 없다.","Each Link is set up following a negotiation of Link width, data rate, and Flit mode by the two agents at each end. No firmware or OS software is involved. The Base spec does not define a CXL.io Transaction Layer version.","§1.2"],["p5q26","p5_6",2,"C","MUST@FLIT로 표시된 feature는 언제 필수인가?","When are features marked MUST@FLIT mandatory?",["They are mandatory only in Non-Flit Mode and reserved when Flit Mode Supported is Set","They apply only after software Sets the Flit Mode Disable bit in the Link Control Register","They are mandatory solely for Root Complex Integrated Endpoints","They are mandatory for components that support Flit Mode (the Flit Mode Supported bit is Set), and strongly recommended for all other components"],["They are mandatory only in Non-Flit Mode and reserved when Flit Mode Supported is Set","They apply only after software Sets the Flit Mode Disable bit in the Link Control Register","They are mandatory solely for Root Complex Integrated Endpoints","They are mandatory for components that support Flit Mode (the Flit Mode Supported bit is Set), and strongly recommended for all other components"],3,"용어 정의: MUST@FLIT feature는 Flit Mode Supported bit가 Set인 component에 필수이고, 그 외 component에는 strongly recommended이다.","MUST@FLIT features are mandatory for components that support Flit Mode (Flit Mode Supported is Set) and are strongly recommended for all other components.","§Terms and Acronyms (MUST@FLIT)"],["p5q27","p5_7",1,"C","PCIe Base 7.0 Reference Documents에서 [CXL]로 가리키는 문서는?","In the PCI Express Base 7.0 reference documents, what does the tag [CXL] refer to?",["The Compute Express Link Specification (listed as CXL-3.2 in this revision’s reference list)","A normative CXL.io chapter that is part of this Base specification itself","The PCI Firmware Specification only","The OpenCAPI cache-coherence specification"],["The Compute Express Link Specification (listed as CXL-3.2 in this revision’s reference list)","A normative CXL.io chapter that is part of this Base specification itself","The PCI Firmware Specification only","The OpenCAPI cache-coherence specification"],0,"Reference Documents는 CXL / CXL-3.2를 Compute Express Link Specification으로 나열한다. CXL.io 전체를 이 Base spec 안의 normative chapter로 정의하지는 않는다.","The reference list includes CXL / CXL-3.2 as the Compute Express Link Specification. The Base spec does not itself contain a normative CXL.io chapter.","§Reference Documents"],["p5q28","p5_7",2,"C","Completion header의 CDL[1:0] 필드에 대해 PCIe Base 7.0이 규정하는 바는?","What does PCI Express Base 7.0 specify about the CDL[1:0] field in the Completion header?",["The field is a mandatory PCIe traffic-class override that every Completer must implement","The field replaces the Completion Status field when Flit Mode is enabled","The field is assigned for use by [CXL] and must be treated as Reserved for use cases not covered by [CXL]","The field must be 11b on all Completions in Non-Flit Mode"],["The field is a mandatory PCIe traffic-class override that every Completer must implement","The field replaces the Completion Status field when Flit Mode is enabled","The field is assigned for use by [CXL] and must be treated as Reserved for use cases not covered by [CXL]","The field must be 11b on all Completions in Non-Flit Mode"],2,"표준: 'The CDL[1:0] field is assigned for use by [CXL]; this field must be treated as Reserved for use cases not covered by [CXL].' CXL 전용 인코딩을 Base spec 정답으로 단정하지 않는다.","The CDL[1:0] field is assigned for use by [CXL] and must be treated as Reserved for use cases not covered by [CXL]. This question does not treat CXL-only encodings as Base-spec answers.","§2.2"],["p5q29","p5_7",2,"C","ATS Translation Request header의 CXL Src bit에 대해 Base spec이 말하는 것은?","What does the Base specification say about the CXL Src bit in an ATS Translation Request header?",["This bit must be Set on every ATS Translation Request, including in non-CXL systems.","This bit enables a PCIe-defined cache-coherency protocol in the Completer.","This bit is the same as the No Snoop attribute and must be copied from it.","This bit is assigned for use by [CXL]. In non-CXL systems, this bit is Reserved."],["This bit must be Set on every ATS Translation Request, including in non-CXL systems.","This bit enables a PCIe-defined cache-coherency protocol in the Completer.","This bit is the same as the No Snoop attribute and must be copied from it.","This bit is assigned for use by [CXL]. In non-CXL systems, this bit is Reserved."],3,"정답 요지: This bit is assigned for use by [CXL]. In non-CXL systems, this bit is Reserved.","Key point: This bit is assigned for use by [CXL]. In non-CXL systems, this bit is Reserved.","§10.2.2.7"],["p5q30","p5_7",3,"C","다음 중 PCIe Base 7.0이 실제로 규범적으로 적고 있는 서술은?","Which of the following is actually stated normatively in PCI Express Base 7.0?",["CXL.io is defined in this specification as being identical to the PCIe Transaction Layer, and every PCIe Device must implement CXL.cache","An alternate protocol is a non-PCIe protocol using the PCIe PHY layer, negotiated with Modified TS1/TS2, and DVSEC is an optional Extended Capability for vendor-defined registers that can appear across vendors","Type 1, Type 2, and Type 3 CXL Devices are classified in Chapter 7 of this Base specification","Flit Mode exists only for CXL and is optional at 128.0 GT/s for PCIe"],["CXL.io is defined in this specification as being identical to the PCIe Transaction Layer, and every PCIe Device must implement CXL.cache","An alternate protocol is a non-PCIe protocol using the PCIe PHY layer, negotiated with Modified TS1/TS2, and DVSEC is an optional Extended Capability for vendor-defined registers that can appear across vendors","Type 1, Type 2, and Type 3 CXL Devices are classified in Chapter 7 of this Base specification","Flit Mode exists only for CXL and is optional at 128.0 GT/s for PCIe"],1,"APN·PHY 재사용·DVSEC는 Base spec에 정의되어 있다. CXL.io≡PCIe TL, CXL Type 1/2/3 분류, CXL.cache 의무는 이 표준의 규범 문장이 아니다. Flit Mode는 32.0 GT/s 초과 data rate에서 PCIe에도 필수이다.","APN, PHY reuse, and DVSEC are defined in the Base spec. The Base spec does not define CXL.io as identical to the PCIe TL, classify CXL Type 1/2/3 Devices, or require CXL.cache. Flit Mode is mandatory for PCIe when a rate exceeding 32.0 GT/s is supported.","§4.2.5.2"],["p5q31","p5_6",3,"P","32.0 GT/s까지만 지원하고 그 초과 data rate는 지원하지 않는 component에 대해 Flit Mode Data Stream 지원은?","For a component whose highest supported data rate is 32.0 GT/s (and which does not support a rate that exceeds 32.0 GT/s), is Flit Mode Data Stream support mandatory?",["Yes. Every component that supports 32.0 GT/s must implement Flit Mode","Flit Mode is forbidden at 32.0 GT/s and allowed only at 2.5 GT/s","No. Flit Mode Data Stream support is mandatory only if a data rate that exceeds 32.0 GT/s is supported. Non-Flit Mode Data Stream support remains mandatory.","The component must implement Flit Mode but must clear the Flit Mode Supported bit"],["Yes. Every component that supports 32.0 GT/s must implement Flit Mode","Flit Mode is forbidden at 32.0 GT/s and allowed only at 2.5 GT/s","No. Flit Mode Data Stream support is mandatory only if a data rate that exceeds 32.0 GT/s is supported. Non-Flit Mode Data Stream support remains mandatory.","The component must implement Flit Mode but must clear the Flit Mode Supported bit"],2,"정답 요지: No. Flit Mode Data Stream support is mandatory only if a data rate that exceeds 32.0 GT/s is supported. Non-Flit Mode Data Stream support remains mandatory.","Key point: No. Flit Mode Data Stream support is mandatory only if a data rate that exceeds 32.0 GT/s is supported. Non-Flit Mode Data Stream support remains mandatory.","§1.2"],["p5q32","p5_3",2,"C","Modified TS Usage=010b일 때 Symbols 10–11에 실리는 필드는?","When Modified TS Usage=010b, what field is carried in Symbols 10–11 of the Modified TS1/TS2 Ordered Set?",["Alternate Protocol Vendor ID","Training Set Message Vendor ID","The DVSEC Vendor ID from Configuration Space","The Function’s Type 0 Vendor ID, which must match or the Ordered Set is ignored"],["Alternate Protocol Vendor ID","Training Set Message Vendor ID","The DVSEC Vendor ID from Configuration Space","The Function’s Type 0 Vendor ID, which must match or the Ordered Set is ignored"],0,"Modified TS Usage=001b이면 Training Set Message Vendor ID, 010b이면 Alternate Protocol Vendor ID이다. 그 밖의 Usage에서는 Reserved이다. 이 Vendor ID가 해당 protocol request/response를 정의한다.","Symbols 10–11 carry the Training Set Message Vendor ID if Usage=001b and the Alternate Protocol Vendor ID if Usage=010b; otherwise they are Reserved. A protocol request or response is associated with the protocol defined by that Alternate Protocol Vendor ID.","§4.2.5.1 / §4.2.5.2"],["c5q01","c5_1",1,"X","모든 CXL 구현에서 반드시 있어야 하는 프로토콜은?","Which protocol must every CXL implementation include?",["CXL.io","CXL.cache","CXL.mem","세 프로토콜 모두 선택 사항"],["CXL.io","CXL.cache","CXL.mem","All three are optional"],0,"CXL.io는 discovery, enumeration, error reporting 등에 쓰이므로 필수이고, CXL.cache와 CXL.mem은 장치 용도에 따라 고르는 선택 프로토콜이다.","CXL.io is needed for discovery, enumeration, and error reporting, so it is mandatory. CXL.cache and CXL.mem are optional, chosen by device usage.","§1.4.1"],["c5q02","c5_1",1,"X","Type 1 CXL 장치가 쓰는 프로토콜 조합은?","Which protocol set does a Type 1 CXL device use?",["CXL.io만","CXL.io + CXL.cache","CXL.io + CXL.mem","CXL.cache + CXL.mem만 (CXL.io 없음)"],["CXL.io only","CXL.io + CXL.cache","CXL.io + CXL.mem","CXL.cache + CXL.mem only (no CXL.io)"],1,"Type 1은 coherent cache는 있지만 Host에 노출하는 메모리(HDM)는 없는 장치라 CXL.io와 CXL.cache를 쓴다.","Type 1 has a coherent cache but no host-visible memory (HDM), so it uses CXL.io and CXL.cache.","§2.1"],["c5q03","c5_1",1,"X","CXL.cache, CXL.mem, CXL.io 세 프로토콜을 모두 협상하는 장치 Type은?","Which device type negotiates all three protocols (CXL.cache, CXL.mem, CXL.io)?",["Type 3","MLD의 FM-owned LD","Type 2","Type 1"],["Type 3","The FM-owned LD of an MLD","Type 2","Type 1"],2,"Type 2는 coherent cache와 장치 부착 메모리를 함께 가진 accelerator라 세 프로토콜을 모두 쓴다.","Type 2 is an accelerator with both a coherent cache and device-attached memory, so it uses all three protocols.","§2.2"],["c5q04","c5_1",1,"X","Type 3 메모리 확장 장치(memory expander)에 대한 설명으로 옳은 것은?","Which statement about a Type 3 memory expander is correct?",["Host 메모리를 캐시하려고 CXL.cache를 쓴다","CXL.io 없이 CXL.mem만으로 열거된다","Host Bias/Device Bias 전환을 반드시 구현한다","CXL.io와 CXL.mem을 쓰며 CXL.cache 요청은 보내지 않는다"],["It uses CXL.cache to cache host memory","It is enumerated with CXL.mem alone, without CXL.io","It must implement Host/Device Bias flipping","It uses CXL.io and CXL.mem and sends no CXL.cache requests"],3,"Type 3는 Host 요청을 CXL.mem으로 처리하는 장치다. Host 메모리 위에서 일하는 accelerator가 아니므로 CXL.cache 요청을 하지 않고, 열거와 관리는 CXL.io로 한다.","Type 3 serves host requests over CXL.mem. It is not an accelerator working on host memory, so it issues no CXL.cache requests; CXL.io handles enumeration and management.","§2.3"],["c5q05","c5_1",2,"X","스펙이 '전통적인 PCIe로 충분하다'고 보는 장치는?","Which kind of device does the spec say is well served by traditional PCIe?",["Producer-Consumer ordering으로 Host 메모리에 작업하고, 작업 제출·완료 때만 Host와 상호작용하는 non-coherent I/O 장치","표준에 없는 복잡한 atomic 연산이 필요한 accelerator","대용량 메모리를 Host에 coherent하게 노출하려는 장치","Host와 연산을 나누며 포인터 기반 데이터를 다루는 GPU"],["A non-coherent I/O device using Producer-Consumer ordering on host memory, talking to the host only at work submission and completion","An accelerator needing complex atomics beyond the standard set","A device that wants to expose large memory coherently to the host","A GPU splitting work with the host over pointer-based data"],0,"Producer-Consumer 모델로 큰 데이터 스트림을 처리하는 전통적인 장치는 CXL의 고급 기능이 거의 필요 없다고 스펙이 먼저 짚는다.","The spec notes up front that classic Producer-Consumer devices streaming large data rarely need CXL's advanced features.","§2.0"],["c5q06","c5_1",2,"X","Type 1 장치가 coherent cache를 원하는 대표 이유로 스펙이 드는 예는?","What example does the spec give for why a Type 1 device wants a coherent cache?",["MSI-X 인터럽트 수를 늘리려고","PCIe 표준 atomic 연산 세트에 없는 복잡한 atomic을 수행하려고","Host에 대용량 메모리를 노출하려고","Link 속도를 128 GT/s로 올리려고"],["To increase the number of MSI-X vectors","To perform complex atomics not in the PCIe standard atomic set","To expose large memory capacity to the host","To raise the link speed to 128 GT/s"],1,"캐시 coherence가 있으면 장치가 원하는 ordering 모델과 atomic 연산을 자유롭게 구현할 수 있다. Producer-Consumer 모델이 잘 맞지 않는 장치가 대상이다.","With cache coherence, the device can implement any ordering model and any atomics it needs. It targets devices where Producer-Consumer ordering fits poorly.","§2.1"],["c5q07","c5_1",2,"X","Type 1 장치가 지원할 수 있는 캐시 크기를 제한하는 요소로 스펙이 지목하는 것은?","What does the spec say limits the cache size a Type 1 device can have?",["Link 폭(lane 수)","CXL.io credit 수","Host의 snoop filter 용량","장치의 BAR 크기"],["The link width (lane count)","The number of CXL.io credits","The host's snoop-filtering capacity","The device's BAR size"],2,"Type 1 캐시는 보통 작고, Host 프로세서의 snoop filter가 이를 추적한다. 그래서 지원 가능한 크기는 Host snoop filter 용량에 달려 있다.","A Type 1 cache is usually small and is tracked by the host's snoop filter, so its supported size depends on that capacity.","§2.1"],["c5q08","c5_1",1,"C","CXL 장치를 발견하고 열거할 때 소프트웨어가 쓰는 기본 틀은?","What basic framework does software use to discover and enumerate a CXL device?",["CXL.mem MemRd로 장치 ID를 읽는다","ALMP로 장치 Type을 교환한다","CXL.cache snoop 응답으로 판단한다","PCIe와 같은 Configuration Space 기반 열거 (CXL.io 경로)"],["Reading a device ID with CXL.mem MemRd","Exchanging the device type with ALMPs","Inferring it from CXL.cache snoop responses","PCIe-style Configuration Space enumeration over the CXL.io path"],3,"CXL.io가 discovery와 enumeration을 맡고, CXL 장치 발견은 PCIe 모델을 따른다(세부 차이는 있음). PCIe 장치와 공통인 출발점이다.","CXL.io handles discovery and enumeration, and CXL device discovery follows the PCIe model (with some differences). This starting point is shared with PCIe.","§9.10"],["c5q09","c5_2",1,"X","HDM은 무엇의 약자인가?","What does HDM stand for?",["Host-managed Device Memory","Hardware Device Mapping","Host Direct Memory","Hybrid DRAM Module"],["Host-managed Device Memory","Hardware Device Mapping","Host Direct Memory","Hybrid DRAM Module"],0,"Type 2·Type 3 장치 메모리가 Host 주소 공간에 노출되면 HDM(Host-managed Device Memory)이라고 부른다.","When Type 2 or Type 3 device memory is exposed to the host, it is called HDM (Host-managed Device Memory).","§2.0"],["c5q10","c5_2",1,"X","HDM의 세 가지 coherence 모델이 아닌 것은?","Which is NOT one of the three HDM coherence models?",["HDM-DB (Device Coherent using Back-Invalidate)","HDM-P (Peer Coherent)","HDM-H (Host-only Coherent)","HDM-D (Device Coherent)"],["HDM-DB (Device Coherent using Back-Invalidate)","HDM-P (Peer Coherent)","HDM-H (Host-only Coherent)","HDM-D (Device Coherent)"],1,"스펙의 세 모델은 HDM-H, HDM-D, HDM-DB이다. HDM-P라는 모델은 없다.","The spec's three models are HDM-H, HDM-D, and HDM-DB. There is no HDM-P model.","§3.3.1"],["c5q11","c5_2",2,"X","CXL.mem의 세 HDM 모델과 사용 장치를 바르게 짝지은 것은?","Which pairing of HDM model and device type is correct?",["세 모델 모두 Type 1에서만 쓴다","HDM-DB는 Type 3에서 쓸 수 없다","HDM-H는 Type 3 전용, HDM-D는 legacy Type 2 전용, HDM-DB는 Type 2나 Type 3","HDM-H는 Type 2 전용, HDM-D는 Type 3 전용, HDM-DB는 Type 1 전용"],["All three are used only by Type 1","HDM-DB cannot be used by Type 3","HDM-H: Type 3 only; HDM-D: legacy Type 2 only; HDM-DB: Type 2 or Type 3","HDM-H: Type 2 only; HDM-D: Type 3 only; HDM-DB: Type 1 only"],2,"HDM-H는 Type 3용, HDM-D는 CXL.cache로 coherence를 맞추는 legacy Type 2용, HDM-DB는 Type 2와 Type 3 모두 쓸 수 있다.","HDM-H is for Type 3, HDM-D is for legacy Type 2 that uses CXL.cache for coherence, and HDM-DB can be used by Type 2 or Type 3.","§3.3.1"],["c5q12","c5_2",2,"X","HDM-D와 HDM-DB의 핵심 차이는?","What is the key difference between HDM-D and HDM-DB?",["HDM-D는 Host만 coherence를 관리하고, HDM-DB는 coherence가 없다","HDM-D는 256B Flit 전용이고 HDM-DB는 68B Flit 전용이다","HDM-DB는 CXL.io로 snoop을 보낸다","HDM-D는 CXL.cache로, HDM-DB는 CXL.mem의 Back-Invalidate Snoop 채널로 device coherence를 푼다"],["HDM-D is host-only coherent; HDM-DB has no coherence","HDM-D is 256B-Flit-only; HDM-DB is 68B-Flit-only","HDM-DB sends snoops over CXL.io","HDM-D resolves device coherence via CXL.cache; HDM-DB uses the CXL.mem Back-Invalidate Snoop channel"],3,"'D'는 CXL.cache 경로로, 'DB'는 CXL.mem의 전용 BISnp/BIRsp 채널로 장치가 Host 캐시 상태를 정리한다.","'D' uses the CXL.cache path; 'DB' uses CXL.mem's dedicated BISnp/BIRsp channels for the device to manage host cache state.","§2.2"],["c5q13","c5_2",2,"X","256B Flit mode를 구현하는 장치에 대한 규칙으로 옳은 것은?","Which rule applies to devices that implement 256B Flit mode?",["HDM-DB를 지원해야 하며, HDM-D 흐름은 68B Flit 호환을 위해 남는다","HDM-D만 지원해야 한다","HDM 모델을 하나도 지원하면 안 된다","CXL.mem 대신 CXL.io로 메모리를 노출해야 한다"],["They must support HDM-DB; HDM-D flows remain for 68B Flit compatibility","They must support HDM-D only","They must not support any HDM model","They must expose memory over CXL.io instead of CXL.mem"],0,"256B Flit mode 장치는 HDM-DB가 필수다. HDM-D 흐름은 68B Flit mode와의 호환을 위해 지원된다.","HDM-DB is required for 256B Flit mode devices. HDM-D flows stay supported for 68B Flit compatibility.","§2.2.1"],["c5q14","c5_2",2,"X","GPGPU의 GDDR처럼 장치 전용으로 쓰이는 PDM(Private Device Memory)과 HDM의 차이로 옳은 것은?","How does PDM (Private Device Memory, e.g., a GPGPU's GDDR) differ from HDM?",["HDM은 장치 드라이버만 접근할 수 있다","PDM은 Host가 접근할 수 없고 시스템과 coherent하지 않지만, HDM은 coherent한 시스템 주소에 매핑된다","PDM은 CXL에서 금지된다","PDM은 Host 캐시가 자동으로 추적한다"],["Only the device driver can access HDM","PDM is not host-accessible or coherent with the system; HDM is mapped into coherent system address space","CXL forbids PDM","Host caches track PDM automatically"],1,"PDM은 장치와 드라이버만 관리하므로 Host 메모리와 큰 복사가 오가야 한다. CXL은 PDM을 금지하지 않는다.","PDM is managed only by the device and its driver, which forces big copies to and from host memory. CXL does not forbid PDM.","§2.2"],["c5q15","c5_2",3,"X","HDM-DB로 노출된 메모리를 가진 Type 3 장치에 추가로 필요한 것은?","What extra block does a Type 3 device need when its memory is exposed as HDM-DB?",["CXL.cache D2H Request 채널","별도의 PCIe Root Port","장치 내부의 Device Coherence engine(DCOH)","Bias Table과 Transition Agent"],["A CXL.cache D2H Request channel","A separate PCIe Root Port","An internal Device Coherence engine (DCOH)","A Bias Table and Transition Agent"],2,"HDM-H 기본 구조에 더해, HDM-DB를 쓰는 Type 3는 coherence를 추적할 DCOH가 필요하다. 이로써 accelerator처럼 동작하거나 peer 직접 접근을 받을 수 있다.","On top of the basic HDM-H design, an HDM-DB Type 3 needs a DCOH to track coherence. This lets it act like an accelerator or accept direct peer access.","§2.3"],["c5q16","c5_3",1,"X","HDM-D의 Bias-based coherency 모델이 정의하는 두 bias 상태는?","Which two bias states does the HDM-D Bias-based coherency model define?",["Read Bias와 Write Bias","Shared Bias와 Exclusive Bias","Local Bias와 Remote Bias","Host Bias와 Device Bias"],["Read Bias and Write Bias","Shared Bias and Exclusive Bias","Local Bias and Remote Bias","Host Bias and Device Bias"],3,"장치 부착 메모리는 Host Bias 또는 Device Bias 상태에 있다. 어느 상태든 Host는 같은 메모리 뷰를 본다.","Device-attached memory is in Host Bias or Device Bias. Either way, the host sees the same uniform view.","§2.2.2"],["c5q17","c5_3",1,"X","Device Bias 상태에서 장치가 자기 메모리에 접근할 때 맞는 설명은?","In Device Bias, how does the device access its own memory?",["Host에 아무 트랜잭션도 보내지 않고 바로 접근한다","매번 Host에 요청을 보내 coherence를 확인한다","CXL.io Memory Read로만 접근한다","접근할 수 없다"],["Directly, without sending any transaction to the host","It sends a request to the host every time to resolve coherence","Only through CXL.io Memory Reads","It cannot access it"],0,"Device Bias에서는 Host 캐시에 그 line이 없다는 것이 보장되므로 장치가 Host를 거치지 않고 고대역·저지연으로 접근한다.","In Device Bias the host is guaranteed not to cache the line, so the device accesses it directly at high bandwidth and low latency.","§2.2.2.2"],["c5q18","c5_3",1,"X","Host Bias가 주로 쓰이는 작업 구간은?","During which part of the work cycle is Host Bias typically used?",["장치 리셋 중","Host가 작업 제출 때 operand를 쓰거나 완료 후 결과를 읽어 갈 때","장치가 연산을 실행하는 동안","Link가 L1 상태일 때"],["During device reset","When the host writes operands at submission or reads results after completion","While the device is executing the work","While the link is in L1"],1,"Host가 장치 메모리에 많이 접근하는 제출·완료 구간에는 Host Bias, 장치가 실행하는 구간에는 Device Bias가 유리하다.","Host Bias suits submission and completion, when the host touches device memory heavily. Device Bias suits the execution phase.","§2.2.2.1"],["c5q19","c5_3",2,"X","Bias 모드를 유지하려고 Type 2 장치가 구현하는 요소가 아닌 것은?","Which is NOT something a Type 2 device builds to maintain bias modes?",["bias 전환을 돕는 Transition Agent(TA)","Host를 위한 기본 load/store 접근 지원","Host CPU 안의 Home Agent","page 단위 bias를 추적하는 Bias Table"],["A Transition Agent (TA) for bias flips","Basic load/store access support for the host","The Home Agent inside the host CPU","A Bias Table tracking bias per page"],2,"Bias Table(page 단위, 예: 4KB), Transition Agent, Host의 load/store 지원은 장치 쪽 요소다. Home Agent는 Host 쪽 블록이다.","The Bias Table (per page, e.g., 4 KB), the Transition Agent, and host load/store support are device-side. The Home Agent is a host block.","§2.2.2"],["c5q20","c5_3",2,"X","장치가 bias를 전혀 구현하지 않으면 어떻게 되는가?","What happens if a device implements no bias at all?",["모든 메모리가 Device Bias로 고정된다","CXL.mem을 쓸 수 없다","Host가 자동으로 HDM-H로 바꾼다","모든 장치 부착 메모리가 Host Bias로 동작해 접근이 Host를 거친다"],["All memory is fixed in Device Bias","CXL.mem becomes unusable","The host automatically switches it to HDM-H","All device-attached memory degenerates to Host Bias, so accesses go through the host"],3,"bias 구현은 필수가 아니다. 구현하지 않으면 전부 Host Bias가 되어 장치 접근도 Host를 거쳐야 한다.","Bias is optional. Without it, everything is Host Bias and even device accesses must route through the host.","§2.2.2.3"],["c5q21","c5_3",3,"X","HDM-D 영역의 cacheline을 Host Bias에서 Device Bias로 바꾸기 전에 장치가 해야 하는 일은?","Before flipping an HDM-D cacheline from Host Bias to Device Bias, what must the device do?",["RdOwnNoData를 보내고 H2D Response로 GO-E를 받는다","CLFlush를 보내고 GO-I를 받는 것으로 충분하다","CXL.io로 MSI를 보낸다","아무것도 하지 않고 Bias Table만 바꾼다"],["Issue RdOwnNoData and receive GO-E on H2D Response","Issuing CLFlush and receiving GO-I is enough","Send an MSI over CXL.io","Nothing; just update the Bias Table"],0,"CLFlush/GO-I 뒤에도 Host가 Monitor 때문에 Shared로 계속 추적할 수 있어 충분 조건이 아니다. RdOwnNoData로 GO-E를 받은 뒤에 bias를 바꿔야 한다.","After CLFlush/GO-I the host may still track the line as Shared (e.g., for a Monitor), so it is not sufficient. The device must get GO-E via RdOwnNoData first.","§3.2.4.2.13"],["c5q22","c5_4",1,"X","CXL.cache는 방향마다 몇 개의 채널을 가지는가?","How many channels does CXL.cache have in each direction?",["6개","3개 (Request, Response, Data)","1개","2개 (Request, Data)"],["Six","Three (Request, Response, Data)","One","Two (Request, Data)"],1,"D2H와 H2D 각각 Request, Response, Data 세 채널이 있다. 채널을 나눠 서로 다른 메시지가 전용 wire를 쓴다.","Each of D2H and H2D has Request, Response, and Data channels, so different messages use dedicated wires.","§3.2.1"],["c5q23","c5_4",1,"X","CXL.cache Data 채널이 한 번에 옮기는 데이터 단위는?","What data unit do CXL.cache Data channels transfer?",["4KB page","가변 길이 TLP payload","항상 64-byte cacheline 전체","4-byte DWORD"],["A 4 KB page","A variable-length TLP payload","Always a full 64-byte cacheline","A 4-byte DWORD"],2,"D2H Data와 H2D Data 모두 항상 64-byte cacheline 전체를 옮긴다. 이는 TLP 길이가 가변인 PCIe와 다른 점이다.","Both D2H Data and H2D Data always move a full 64-byte cacheline, unlike variable-length PCIe TLPs.","§3.2.1"],["c5q24","c5_4",1,"X","H2D Request 채널이 주로 나르는 메시지는?","What does the H2D Request channel mainly carry?",["장치의 메모리 읽기 요청","Host 쓰기 데이터","인터럽트 메시지","coherence 유지를 위한 Host의 snoop"],["Memory read requests from the device","Host write data","Interrupt messages","Snoops from the host to keep coherence"],3,"H2D Request는 Host가 장치 캐시에 보내는 snoop이다. 반환할 데이터를 쓸 버퍼 위치도 함께 담는다.","H2D Request carries host snoops to device caches, plus the buffer location for any returned data.","§3.2.1"],["c5q25","c5_4",2,"X","CXL.cache 채널을 서로 독립적으로 동작시키는 이유는?","Why must CXL.cache channels work independently of each other?",["채널을 엮으면 같은 주소의 요청이 snoop 응답을 기다리며 deadlock이 날 수 있어서","전력 소모를 줄이려고","PCIe ordering 규칙을 그대로 따르려고","Data 채널을 없애려고"],["Linking them could deadlock, since a request to an address waits for that address's snoop responses","To cut power","To reuse PCIe ordering rules unchanged","To eliminate the Data channel"],0,"Host는 주소 X의 snoop 응답을 모두 모을 때까지 같은 주소의 D2H 요청을 막을 수 있다. 채널이 엮이면 forward progress가 깨진다.","The host may hold a D2H request to address X until all snoop responses for X arrive; tying channels together would break forward progress.","§3.2.2.1"],["c5q26","c5_4",3,"X","CXL.cache 채널 사이에서 예외적으로 유지해야 하는 ordering은?","Which cross-channel ordering must CXL.cache still preserve?",["D2H Response는 D2H Request를 앞지를 수 없다","앞서 보낸 GO(H2D Response)를 나중 cycle의 같은 주소 snoop이 앞지르지 않아야 한다","D2H Data는 항상 D2H Request보다 먼저 가야 한다","모든 H2D 메시지는 송신 순서대로 도착해야 한다"],["D2H Response cannot pass D2H Request","A GO (on H2D Response) must not be passed by a later-cycle snoop to the same address","D2H Data must always precede D2H Request","All H2D messages must arrive in send order"],1,"Host는 같은 주소에 새 snoop을 보내기 전에 장치가 GO를 관찰해야 한다. 그래서 먼저 보낸 GO는 나중 snoop에 추월당하지 않는다고 가정한다.","The host needs the device to observe a GO before newer snoops to that address, so earlier GOs are assumed not to be passed by later snoops.","§3.2.2.1"],["c5q27","c5_4",2,"X","CXL.cache crediting 요약에서 다른 메시지 클래스에 의해 막힐 수 있는 채널은?","In the CXL.cache crediting summary, which channel may be blocked by all other message classes?",["H2D Data","D2H Data","D2H Request","H2D Response"],["H2D Data","D2H Data","D2H Request","H2D Response"],2,"D2H Request는 Host 버퍼가 필요해 앞선 요청 때문에 막힐 수 있다. Response와 Data 채널은 미리 할당된 버퍼로 가며 반드시 진행해야 한다.","D2H Request needs a host buffer and can be held by earlier requests. Response and Data channels go to pre-allocated buffers and must make progress.","§3.2.2.2"],["c5q28","c5_4",3,"X","장치가 CXL.cache 요청을 보내기 위한 Host Physical Address(HPA)를 얻는 기본 방법은?","How does a device normally obtain the Host Physical Address (HPA) for CXL.cache requests?",["CXL.mem MemRd 응답","ALMP 교환","Configuration Read","CXL.io의 ATS 요청"],["A CXL.mem MemRd response","An ALMP exchange","A Configuration Read","An ATS request on CXL.io"],3,"장치는 CXL.io ATS로 HPA를 받는다. ATS 완료가 CXL.io 전용으로 표시한 HPA에는 CXL.cache 요청을 보내면 안 된다.","The device gets HPAs via ATS on CXL.io. It must not use CXL.cache for HPAs that the ATS completion marks as CXL.io-only.","§3.2.5.13"],["c5q29","c5_5",1,"X","line을 Shared 상태로 캐시하려는 장치 읽기 요청은?","Which device read request asks to cache a line in Shared state?",["RdShared","RdOwn","ItoMWr","CleanEvict"],["RdShared","RdOwn","ItoMWr","CleanEvict"],0,"RdShared는 보통 GO-S를 받는다. RdOwn은 쓰기 가능한 상태(E/M)를 원한다.","RdShared typically receives GO-S. RdOwn asks for a writeable state (E/M).","§3.2.4.2.8"],["c5q30","c5_5",1,"X","RdCurr 요청에 대한 설명으로 옳은 것은?","Which statement about RdCurr is correct?",["장치 캐시의 line을 Host로 내보낸다","최신 데이터를 받지만 GO가 없고, line을 캐시하지 않고 한 번만 쓴다","line을 Exclusive로 캐시한다","데이터 없이 소유권만 얻는다"],["It evicts a device cache line to the host","It gets current data with no GO; the device uses it once and does not cache it","It caches the line in Exclusive","It gains ownership without data"],1,"RdCurr는 어떤 캐시 상태도 바꾸지 않고 현재 값을 읽는다. Host는 이 line을 추적할 필요가 없다.","RdCurr reads the current value without changing any cache state, so the host need not track the line.","§3.2.4.2.6"],["c5q31","c5_5",1,"X","장치가 Modified line을 Host로 내보낼 때 쓰는 요청은?","Which request does a device use to evict a Modified line to the host?",["CleanEvictNoData","RdAny","DirtyEvict","CleanEvict"],["CleanEvictNoData","RdAny","DirtyEvict","CleanEvict"],2,"DirtyEvict는 Modified 64-byte line을 내보내고 보통 GO-WritePull을 받아 데이터를 보낸다. CleanEvict는 Exclusive(clean) line용이다.","DirtyEvict evicts a Modified 64-byte line and usually receives GO-WritePull before sending data. CleanEvict is for Exclusive (clean) lines.","§3.2.4.2.15"],["c5q32","c5_5",2,"X","CleanEvict/DirtyEvict를 장치 부착 메모리(device-attached memory) 주소에 대해 CXL.cache로 보내지 않는 이유는?","Why are CleanEvict/DirtyEvict not sent on CXL.cache for device-attached memory addresses?",["Host가 그 주소를 모르기 때문에","CXL.io로만 보낼 수 있기 때문에","256B Flit에서만 허용되기 때문에","그 주소의 evict는 장치 내부에서 자기 메모리로 처리하기 때문에"],["The host does not know those addresses","They can only go over CXL.io","They are allowed only in 256B Flit mode","Evictions for those addresses are handled inside the device to its own memory"],3,"장치 부착 메모리로의 evict는 CXL.cache에서 허용되지 않고 장치 내부에서 끝낸다. 대신 ItoMWr, WrCur 같은 non-Evict 쓰기는 쓸 수 있다.","Evicts to device-attached memory are not allowed on CXL.cache; the device completes them internally. Non-Evict writes such as ItoMWr or WrCur may still be used.","§3.2.5.12"],["c5q33","c5_5",2,"X","GO(Global Observation) 메시지가 전달하는 정보는?","What does a GO (Global Observation) message convey?",["요청이 다음 소유권을 갖게 됐다는 것과 허용된 MESI 캐시 상태(또는 오류)","링크 폭 변경 결과","메모리 데이터 64 bytes","전원 상태 전환 요청"],["That the request has next ownership, plus the permitted MESI state (or an error)","The result of a link width change","64 bytes of memory data","A power state transition request"],0,"GO는 H2D Response로 오며, 요청이 다음 소유권을 갖는다는 보장과 함께 캐시 상태(MESI), 1회 사용, 오류 여부를 알린다.","GO arrives on H2D Response. It guarantees next ownership and tells the cache state (MESI), single-use, or error.","§3.2.5.10"],["c5q34","c5_5",3,"X","FastGO를 받은 요청이 시스템 전체에 관찰됐음을 알리는 최종 메시지는?","After a FastGO, which final message says the request is observed system-wide?",["Cmp-E","ExtCmp","GO_WritePull_Drop","RspIHitI"],["Cmp-E","ExtCmp","GO_WritePull_Drop","RspIHitI"],1,"FastGO는 CPU socket 같은 하위 영역 안에서만 소유권을 보장한다. 시스템 전체 관찰은 ExtCmp로 확인한다.","FastGO only guarantees ownership within a sub-domain such as a CPU socket. ExtCmp confirms system-wide observation.","§3.2.5.11"],["c5q35","c5_5",3,"X","D2H 메모리 쓰기와 CXL.io MSI 사이의 순서가 중요할 때 순서를 지키는 책임은 누구에게 있는가?","When D2H memory writes must be ordered against an MSI on CXL.io, who must enforce the order?",["ARB/MUX가 보장한다","Switch가 보장한다","장치 (Host는 CXL.cache 요청 순서를 보존하지 않음)","Host가 자동으로 보존한다"],["The ARB/MUX guarantees it","The switch guarantees it","The device (the host does not preserve CXL.cache request order)","The host preserves it automatically"],2,"PCIe에서는 MSI도 posted write라서 앞선 posted write를 앞지르지 않는 ordering 규칙이 순서를 지켜 준다. 반면 Host는 CXL.cache 요청 순서를 보존하지 않으므로, CXL.cache 쓰기와 MSI의 순서는 장치가 직접 맞춰야 한다.","In PCIe, an MSI is a posted write and ordering rules keep it behind earlier posted writes. The host does not preserve CXL.cache request order, so the device itself must order CXL.cache writes before the MSI.","§3.2.5.14"],["c5q36","c5_6",1,"X","Host가 요청자에게 line 소유권(Exclusive)을 주려고 보내는 snoop은?","Which host snoop is sent so the requester can get ownership (Exclusive)?",["SnpData","SnpCur","GO-S","SnpInv"],["SnpData","SnpCur","GO-S","SnpInv"],3,"SnpInv는 주로 쓰기 요청이 계기가 되며, 받은 장치는 모든 사본을 invalidate하고 dirty 데이터는 돌려줘야 한다.","SnpInv is usually triggered by writes. The device must invalidate all copies and return any dirty data.","§3.2.4.4.2"],["c5q37","c5_6",2,"X","SnpData를 받은 장치가 해야 하는 일은?","What must a device do when it receives SnpData?",["line을 invalidate하거나 Shared로 낮추고, dirty면 데이터를 Host에 돌려준다","항상 line을 Modified로 올린다","응답하지 않아도 된다","CXL.io로 데이터를 보낸다"],["Invalidate or downgrade the line to Shared, returning dirty data to the host","Always upgrade the line to Modified","No response is needed","Send data over CXL.io"],0,"SnpData는 보통 읽기 요청이 계기다. 장치는 S로 낮추거나 무효화하고, dirty 데이터가 있으면 돌려준다.","SnpData is usually triggered by reads. The device downgrades to S or invalidates and returns dirty data if held.","§3.2.4.4.1"],["c5q38","c5_6",2,"X","장치가 RspIFwdM으로 snoop에 응답했다. 다음으로 일어나는 일은?","A device answers a snoop with RspIFwdM. What follows?",["H2D Data로 데이터를 받는다","D2H Data 채널로 64 bytes 데이터를 snoop이 지정한 Host 버퍼(UQID)로 보낸다","Host는 응답만 받고 바로 완료한다","장치가 line을 Modified로 유지한다"],["It receives data on H2D Data","It sends 64 bytes on D2H Data to the host buffer (UQID) named by the snoop","The host completes on the response alone","The device keeps the line Modified"],1,"Rsp*Fwd* 응답이면 장치는 64 bytes를 D2H Data로 보내야 한다. RspIFwdM은 Modified였던 line이 이제 I 상태라는 뜻이다.","With any Rsp*Fwd* response the device must send 64 bytes on D2H Data. RspIFwdM means a Modified line is now Invalid.","§3.2.4.4"],["c5q39","c5_6",1,"X","snoop한 line이 장치의 어떤 캐시에도 없을 때 일반적인 응답은?","What is the usual response when a snooped line is in none of the device caches?",["RspVFwdV","RspSHitSE","RspIHitI","RspSFwdM"],["RspVFwdV","RspSHitSE","RspIHitI","RspSFwdM"],2,"RspIHitI는 line을 찾지 못했다는 뜻이고, Host는 그 장치에서 line이 지워졌다고 볼 수 있다.","RspIHitI means the line was not found, so the host may assume the device no longer holds it.","§3.2.4.3.1"],["c5q40","c5_6",3,"X","Direct P2P CXL.mem을 쓰는 장치가, 다른 인터페이스로 요청했던 line에 대한 snoop을 받으면?","A device using Direct P2P CXL.mem gets a snoop on a different interface than the one used to request the line. What does it do?",["line을 즉시 invalidate하고 데이터를 보낸다","오류로 보고 Link를 retrain한다","snoop을 무시하고 응답하지 않는다","그 주소를 캐시하지 않은 것처럼 RspIHitI 또는 BIRspI로 응답하고 상태를 바꾸지 않는다"],["Invalidate the line immediately and send data","Treat it as an error and retrain the link","Ignore the snoop without responding","Respond as if not cached (RspIHitI or BIRspI) and leave the line state unchanged"],3,"장치는 각 line을 어느 인터페이스로 요청했는지 추적해야 한다. 다른 인터페이스로 온 snoop에는 '없음'으로 답하고 상태를 유지한다.","The device must track which interface requested each line. A snoop on the other interface gets a 'not cached' reply with no state change.","§3.3.2.2"],["c5q41","c5_7",1,"X","CXL.mem에서 요청을 내보내는 Master와 응답하는 Subordinate의 일반적인 배치는?","In CXL.mem, which side is usually the Master (requester) and which the Subordinate (responder)?",["Host CPU coherency engine이 Master, 메모리 장치가 Subordinate","메모리 장치가 Master, Host가 Subordinate","Switch가 항상 Master","Master와 Subordinate 구분이 없다"],["The host CPU coherency engine is Master; the memory device is Subordinate","The memory device is Master; the host is Subordinate","The switch is always Master","There is no Master/Subordinate split"],0,"CPU 쪽 coherency engine이 읽기·쓰기를 내보내는 Master이고, 메모리 장치가 데이터·완료로 답하는 Subordinate다.","The CPU coherency engine sources reads and writes as Master; the memory device answers with data and completions as Subordinate.","§3.3.1"],["c5q42","c5_7",1,"X","S2M(Subordinate→Master) 메시지 클래스가 아닌 것은?","Which is NOT an S2M (Subordinate-to-Master) message class?",["BISnp (Back-Invalidate Snoop)","RwD (Request with Data)","NDR (No Data Response)","DRS (Data Response)"],["BISnp (Back-Invalidate Snoop)","RwD (Request with Data)","NDR (No Data Response)","DRS (Data Response)"],1,"M2S는 Req, RwD, BIRsp이고 S2M은 NDR, DRS, BISnp이다.","M2S classes are Req, RwD, and BIRsp; S2M classes are NDR, DRS, and BISnp.","§3.3.1"],["c5q43","c5_7",2,"X","BI* 채널(S2M BISnp, M2S BIRsp)을 반드시 지원해야 하는 장치는?","Which devices must support the BI* channels (S2M BISnp, M2S BIRsp)?",["모든 Type 1 장치","CXL.io만 쓰는 장치","HDM-DB를 지원하는 장치","HDM-D만 쓰는 Type 2 장치"],["All Type 1 devices","CXL.io-only devices","Devices that support HDM-DB","Type 2 devices using only HDM-D"],2,"HDM-DB 장치는 BI* 채널이 필수다. HDM-D 영역만 쓰는 Type 2는 BI* 채널이 없을 수 있다.","HDM-DB devices must have the BI* channels. A Type 2 using only HDM-D regions may lack them.","§3.3.2"],["c5q44","c5_7",2,"X","Back-Invalidate Snoop(BISnp)을 도입한 주된 목적은?","What is the main purpose of Back-Invalidate Snoop (BISnp)?",["Host가 장치 캐시를 snoop하려고","링크 오류를 재전송하려고","전원 상태를 바꾸려고","장치가 Host의 장치 메모리 캐시를 추적하는 inclusive Snoop Filter를 구현할 수 있게 하려고"],["To let the host snoop device caches","To retransmit link errors","To change power states","To let the device implement an inclusive Snoop Filter tracking host caching of device memory"],3,"BISnp는 장치가 Host 캐시 상태를 바꾸도록 시작하는 snoop이다. 68B의 D2H Req 경로는 M2S Req 진행을 기다리며 막힐 수 있어 inclusive Snoop Filter에 맞지 않는다.","BISnp is a device-initiated snoop that changes host cache state. The 68B D2H Req path can block on M2S Req progress, so it cannot support an inclusive Snoop Filter.","§3.3.3"],["c5q45","c5_7",3,"X","어떤 주소에 대해 S2M BISnp가 진행 중일 때 장치의 규칙은?","While an S2M BISnp to an address is outstanding, what rule applies to the device?",["대응하는 M2S BIRsp로 끝날 때까지 같은 주소의 M2S Req를 막는다","같은 주소의 M2S RwD를 막는다","모든 주소의 M2S Req를 막는다","BISnp를 취소하고 다시 보낸다"],["Block M2S Req to that address until the matching M2S BIRsp completes it","Block M2S RwD to that address","Block M2S Req to all addresses","Cancel and resend the BISnp"],0,"같은 주소의 M2S Req만 BIRsp가 올 때까지 막는다. M2S RwD는 M2S Req나 BISnp에 의존하지 않고 끝까지 진행해야 한다.","Only M2S Req to the same address is held until BIRsp arrives. M2S RwD must drain without depending on M2S Req or BISnp.","§3.3.3"],["c5q46","c5_7",3,"X","Accelerator가 peer Type 3 메모리에 Direct P2P CXL.mem으로 접근하려면 필요한 토폴로지 조건은?","What topology condition is required for an accelerator to reach a peer Type 3 memory with Direct P2P CXL.mem?",["두 장치가 같은 MLD 안의 LD","두 장치 모두 PBR Edge DSP에 직접 연결","두 장치가 같은 Root Port에 직접 연결(Switch 없음)","HBR Switch만 있으면 됨"],["Both are LDs inside the same MLD","Both devices directly attached to PBR Edge DSPs","Both on the same Root Port with no switch","Any HBR switch is enough"],1,"모든 CXL.mem 메시지가 HBR switch가 목적지를 판단할 정보를 담지는 않으므로 PBR 라우팅이 필요하다. Edge DSP의 FAST/LDST 테이블이 경로를 정한다.","Not every CXL.mem message has enough information for an HBR switch to route it, so PBR is required. Edge DSP tables (FAST, LDST) pick the destination.","§3.3.2.1"],["c5q47","c5_8",1,"X","CXL.mem에서 장치가 보내는 일반 메모리 읽기 데이터 응답 opcode는?","Which S2M DRS opcode carries normal memory read data?",["Cmp","BISnp","MemData","MemRd"],["Cmp","BISnp","MemData","MemRd"],2,"MemRd는 M2S 요청이고, 데이터는 S2M DRS의 MemData로 돌아온다. Cmp는 데이터 없는 NDR 완료다.","MemRd is the M2S request; data returns as S2M DRS MemData. Cmp is a data-less NDR completion.","§3.3.10"],["c5q48","c5_8",2,"X","완료 메시지를 받지 않는 M2S Req opcode는?","Which M2S Req opcode receives no completion message?",["MemRd","MemInv","MemClnEvct","MemSpecRd"],["MemRd","MemInv","MemClnEvct","MemSpecRd"],3,"MemSpecRd는 home agent가 coherence를 풀기 전에 메모리 접근을 미리 시작해 지연을 줄이는 speculative read로, 완료를 받지 않는다.","MemSpecRd is a speculative read that starts the memory access before coherence is resolved, to cut latency. It gets no completion.","§3.3.5"],["c5q49","c5_8",2,"X","CXL.mem 프로토콜이 저장·반환할 수 있게 한 기본 Metadata 크기는?","How many bits of Metadata does the CXL.mem protocol allow to be stored and returned (basic Meta0)?",["2 bits","8 bits","64 bits","Metadata는 정의되지 않는다"],["2 bits","8 bits","64 bits","Metadata is not defined"],0,"프로토콜은 2 bits Metadata를 허용한다. Metadata 지원은 선택이며 Host와 미리 협상해야 한다.","The protocol allows 2 bits of Metadata. Support is optional and must be negotiated with the host in advance.","§3.3.1"],["c5q50","c5_8",3,"X","MemRdFwd/MemWrFwd를 받을 수 있는 장치 메모리 영역은?","Which device memory regions can receive MemRdFwd/MemWrFwd?",["모든 HDM 영역","HDM-D로 매핑된 영역 (HDM-H나 HDM-DB만 있으면 받지 않음)","HDM-H 영역만","HDM-DB 영역만"],["All HDM regions","Regions mapped as HDM-D (not sent if only HDM-H or HDM-DB)","HDM-H regions only","HDM-DB regions only"],1,"두 opcode는 HDM-D 장치 메모리에 대한 CXL.cache D2H 요청의 결과로만 Host가 보낸다.","The host sends these only as a result of CXL.cache D2H requests to HDM-D device memory.","§3.3.5"],["c5q51","c5_8",2,"X","NDR/DRS의 DevLoad 필드 값 00b가 뜻하는 장치 부하 상태는?","What load level does DevLoad 00b in NDR/DRS indicate?",["Moderate Overload","Optimal Load","Light Load (요청을 더 받을 여유 있음)","Severe Overload"],["Moderate Overload","Optimal Load","Light Load (readily handles more requests)","Severe Overload"],2,"DevLoad는 Light(00b), Optimal(01b), Moderate Overload(10b), Severe Overload(11b) 네 단계다. 00b는 CXL 1.1 호환을 위해 Host 영향이 가장 적은 값으로 정했다.","DevLoad has four levels: Light (00b), Optimal (01b), Moderate Overload (10b), Severe Overload (11b). 00b was chosen to have the least host impact for CXL 1.1 compatibility.","§3.3.9"],["c5q52","c5_8",3,"X","장치나 switch가 MemRd 주소를 HDM으로 디코드하지 못했을 때 쓰는 DRS opcode의 동작은?","When a device or switch cannot decode a MemRd address as HDM, what does the special DRS opcode do?",["응답하지 않는다","Cmp-E로 응답한다","Link Down을 일으킨다","MemData-NXM으로 payload를 모두 1로 채우고, poison이 켜져 있으면 poison을 설정한다"],["Send no response","Answer with Cmp-E","Force Link Down","Send MemData-NXM with an all-1s payload, setting poison if poison is enabled"],3,"MemData-NXM은 응답 하나로 Host의 추적 구조를 해제하게 해 준다. Host는 HDM-H면 DRS, HDM-D*면 DRS+NDR을 기대하므로 애매한 경우를 피하려고 만든 opcode다.","MemData-NXM lets one response free host tracking. The host expects DRS for HDM-H and DRS+NDR for HDM-D*, so this opcode avoids the ambiguity.","§3.3.10"],["c5q53","c5_8",2,"X","S2M NDR의 Cmp-M에 대한 규칙으로 옳은 것은?","Which rule about S2M NDR Cmp-M is correct?",["Host 지원은 선택이고, 장치는 이 응답을 끌 수 있어야 한다","모든 Host와 장치가 반드시 지원한다","256B Flit에서는 금지된다","BI conflict 핸드셰이크 완료를 뜻한다"],["Host support is optional, and devices must support disabling it","All hosts and devices must support it","It is forbidden in 256B Flit mode","It signals completion of the BI conflict handshake"],0,"Cmp-M은 DCOH가 Modified 상태를 알리는 응답이다. Host 구현에 따라 선택이며 장치는 비활성화를 지원해야 한다. BI conflict 완료는 BI-ConflictAck다.","Cmp-M tells the host Modified state. It is optional for hosts, and devices must allow disabling it. BI conflict completion is BI-ConflictAck.","§3.3.9"]],"6":[["p6q01","p6_1",1,"P","PCI Express Configuration model이 지원하는 두 가지 Configuration Space access mechanism은?","Which two Configuration Space access mechanisms does the PCI Express Configuration model support?",["The PCI-compatible Configuration Access Mechanism (CAM) and the PCI Express Enhanced Configuration Access Mechanism (ECAM)","Only I/O-mapped CF8h/CFCh; memory-mapped access is not architected","Only ECAM; the PCI-compatible mechanism is removed in 7.0","SMBus and MCTP only, with no in-band Configuration Requests"],["The PCI-compatible Configuration Access Mechanism (CAM) and the PCI Express Enhanced Configuration Access Mechanism (ECAM)","Only I/O-mapped CF8h/CFCh; memory-mapped access is not architected","Only ECAM; the PCI-compatible mechanism is removed in 7.0","SMBus and MCTP only, with no in-band Configuration Requests"],0,"§7장 서두는 CAM(§7.2.1)과 ECAM(§7.2.2) 두 mechanism을 지원한다고 명시한다. CAM은 Conventional PCI enumeration software와의 binary compatibility를 위한 것이다.","Chapter 7 states that the model supports the PCI-compatible CAM (§7.2.1) and ECAM (§7.2.2). CAM provides binary compatibility with Conventional PCI enumeration software.","§7.2"],["p6q02","p6_1",1,"P","PCI Express Extended Configuration Space에 접근할 수 있는 mechanism은?","Which mechanism can access PCI Express Extended Configuration Space?",["Either CAM or ECAM, interchangeably, including I/O CF8h/CFCh","Only Type 0 Configuration Requests that use the Register Number field alone","Only the ECAM mechanism defined in §7.2.2","Only RCRB accesses at offset 000h"],["Either CAM or ECAM, interchangeably, including I/O CF8h/CFCh","Only Type 0 Configuration Requests that use the Register Number field alone","Only the ECAM mechanism defined in §7.2.2","Only RCRB accesses at offset 000h"],2,"표준: Extended Configuration Space는 §7.2.2의 ECAM으로만 접근할 수 있다. PCI-compatible Configuration Request의 Extended Register Address는 모두 0이어야 한다.","Extended Configuration Space can only be accessed using the ECAM mechanism in §7.2.2. For PCI-compatible Configuration Requests, the Extended Register Address field must be all zeros.","§7.2 / §7.2.1"],["p6q03","p6_1",1,"P","Function Configuration Space에서 PCI-compatible region의 크기와 Extended Capabilities가 시작되는 offset은?","In a Function’s Configuration Space, what is the size of the PCI-compatible region and at what offset do Extended Capabilities always begin?",["The first 64 bytes are the PCI-compatible region; Extended Capabilities begin at offset 40h","The first 256 bytes are the PCI-compatible region; Extended Capabilities always begin at offset 100h","The entire 4 KB space is PCI-compatible; Extended Capabilities begin at offset 000h","The first 512 bytes are PCI-compatible; Extended Capabilities begin at offset 200h"],["The first 64 bytes are the PCI-compatible region; Extended Capabilities begin at offset 40h","The first 256 bytes are the PCI-compatible region; Extended Capabilities always begin at offset 100h","The entire 4 KB space is PCI-compatible; Extended Capabilities begin at offset 000h","The first 512 bytes are PCI-compatible; Extended Capabilities begin at offset 200h"],1,"처음 256바이트가 PCI-compatible region이며 conventional PCI Configuration Space를 completely alias한다. Config Space의 Extended Capabilities는 항상 offset 100h에서 시작한다(RCRB는 000h).","The first 256 bytes form the PCI-compatible region and completely alias conventional PCI Configuration Space. Extended Capabilities in Configuration Space always begin at offset 100h (in an RCRB they begin at 000h).","§7.5.1 / §7.6.1"],["p6q04","p6_2",2,"P","ECAM memory address mapping(Table 7-1)에서 Device Number와 Function Number에 해당하는 비트는? (non-ARI)","In the ECAM memory address mapping (Table 7-1), which bits carry the Device Number and Function Number for a non-ARI Request?",["A[15:8] = Device Number, A[7:2] = Function Number","A[27:20] = Device Number, A[19:12] = Function Number","A[11:8] = Device Number, A[7:2] = Function Number","A[19:15] = Device Number, A[14:12] = Function Number"],["A[15:8] = Device Number, A[7:2] = Function Number","A[27:20] = Device Number, A[19:12] = Function Number","A[11:8] = Device Number, A[7:2] = Function Number","A[19:15] = Device Number, A[14:12] = Function Number"],3,"Table 7-1: A[(20+n-1):20] Bus Number(1≤n≤8), A[19:15] Device Number, A[14:12] Function Number, A[11:8] Extended Register Number, A[7:2] Register Number, A[1:0]는 access size와 함께 Byte Enable을 생성한다.","Table 7-1 maps A[(20+n-1):20] to Bus Number (1≤n≤8), A[19:15] Device Number, A[14:12] Function Number, A[11:8] Extended Register Number, A[7:2] Register Number, and A[1:0] (with access size) to Byte Enables.","§7.2.2"],["p6q05","p6_2",2,"P","Host bridge가 Bus Number에 n=3개의 memory address bit를 map하면, ECAM window 정렬과 접근 가능한 Bus Number 범위는?","If a host bridge maps n=3 memory address bits to the Bus Number field, how is the ECAM window aligned and which Bus Numbers can be addressed?",["The base is aligned to a 4 KB boundary and the system can address Bus Numbers 0 through 255","The base is aligned to a 1 MB boundary and the system can address only Bus Number 0","The base is aligned to an 8 MB (2^23-byte) boundary and the system can address Bus Numbers 0 through 7","The base is aligned to a 256 MB boundary and the system can address Bus Numbers 0 through 15"],["The base is aligned to a 4 KB boundary and the system can address Bus Numbers 0 through 255","The base is aligned to a 1 MB boundary and the system can address only Bus Number 0","The base is aligned to an 8 MB (2^23-byte) boundary and the system can address Bus Numbers 0 through 7","The base is aligned to a 256 MB boundary and the system can address Bus Numbers 0 through 15"],2,"범위는 2^(n+20) 바이트 경계에 정렬되고 Bus 0부터 2^n−1까지 지원한다. n=3이면 8 MB 정렬, A[22:20]가 Bus[2:0], 접근 가능한 Bus는 0–7이다. n은 1부터 8까지이다.","The window is aligned to a 2^(n+20)-byte boundary and supports Bus Numbers 0 through 2^n−1. For n=3 the base is 8 MB-aligned, A[22:20] map to Bus[2:0], and Buses 0–7 are addressable. n satisfies 1≤n≤8.","§7.2.2"],["p6q06","p6_2",2,"P","ARI Device의 Extended Function을 대상으로 하는 ECAM Request에서 A[19:12]는 무엇을 나타내는가?","For ECAM Requests targeting Extended Functions in an ARI Device, what do address bits A[19:12] represent?",["The 8-bit Function Number, replacing the 5-bit Device Number and 3-bit Function Number fields","The Bus Number, because ARI Devices do not decode Function Number","The Extended Register Number only","A reserved field that must be zero"],["The 8-bit Function Number, replacing the 5-bit Device Number and 3-bit Function Number fields","The Bus Number, because ARI Devices do not decode Function Number","The Extended Register Number only","A reserved field that must be zero"],0,"Table 7-1 주석: ARI Device의 Extended Function을 대상으로 하면 A[19:12]가 8-bit Function Number이며, 위의 5-bit Device Number와 3-bit Function Number를 대체한다.","The Table 7-1 note states that for Requests targeting Extended Functions in an ARI Device, A[19:12] represents the 8-bit Function Number, which replaces the 5-bit Device Number and 3-bit Function Number fields.","§7.2.2"],["p6q07","p6_3",1,"C","Base Address Register bit 0이 Memory Space Indicator / I/O Space Indicator로서 의미하는 바는?","What does bit 0 of a Base Address Register indicate as the Memory / I/O Space Indicator?",["0b maps the BAR into I/O Space; 1b maps the BAR into Memory Space","Bit 0 is writable and selects 32-bit versus 64-bit decoding","Bit 0 is the Prefetchable bit and must be Set for all Memory BARs","0b maps the BAR into Memory Space; 1b maps the BAR into I/O Space"],["0b maps the BAR into I/O Space; 1b maps the BAR into Memory Space","Bit 0 is writable and selects 32-bit versus 64-bit decoding","Bit 0 is the Prefetchable bit and must be Set for all Memory BARs","0b maps the BAR into Memory Space; 1b maps the BAR into I/O Space"],3,"모든 BAR의 bit 0은 RO이며 Memory면 0b, I/O면 1b를 반환한다. Memory Type은 bits 2:1이고, bit 3의 역사적 Prefetchable 정의는 7.0에서 deprecated/undefined이다.","Bit 0 in all BARs is read-only: Memory Space BARs return 0b and I/O Space BARs return 1b. Memory type is encoded in bits 2:1. The historical bit-3 Prefetchable definition is deprecated and undefined in 7.0.","§7.5.1.2.1"],["p6q08","p6_3",1,"C","Memory Base Address Register bits 2:1의 정의된 encoding은?","What are the defined encodings of bits 2:1 in a Memory Base Address Register?",["00b = 64-bit; 10b = 32-bit; 01b = below 1 MB; 11b = prefetchable","00b = 32-bit Memory Space; 10b = 64-bit Memory Space; 01b and 11b are Reserved","01b = 32-bit; 11b = 64-bit; 00b and 10b are Reserved","Bits 2:1 are writable base-address bits and have no type encoding"],["00b = 64-bit; 10b = 32-bit; 01b = below 1 MB; 11b = prefetchable","00b = 32-bit Memory Space; 10b = 64-bit Memory Space; 01b and 11b are Reserved","01b = 32-bit; 11b = 64-bit; 00b and 10b are Reserved","Bits 2:1 are writable base-address bits and have no type encoding"],1,"Table 7-9: 00b는 32-bit Memory Space, 10b는 64-bit Memory Space, 01b와 11b는 Reserved이다. (01b는 과거 1 MB 미만 mapping용으로 쓰였을 수 있어 software는 인식해야 한다는 각주가 있다.)","Table 7-9: 00b means a 32-bit Memory BAR, 10b means a 64-bit Memory BAR, and 01b and 11b are Reserved. A footnote notes that the below-1 MB encoding existed in an earlier PCI Local Bus Specification.","§7.5.1.2.1"],["p6q09","p6_3",3,"P","PCI Express Base 7.0에서 Memory BAR bit 3에 대한 규정으로 옳은 것은?","What does PCI Express Base 7.0 specify about bit 3 of a Memory BAR?",["Bit 3 is the architected Prefetchable bit and must be Set if and only if the range is prefetchable","The historical definition of bit 3 is now deprecated and bit 3 is undefined; for backward compatibility it is strongly recommended that bit 3 be Set for 64-bit Memory BARs and Clear for 32-bit Memory BARs","Bit 3 must be hardwired to 0b on all Memory BARs in 7.0","Bit 3 is RW and software uses it to enable relaxed-ordering for MMIO"],["Bit 3 is the architected Prefetchable bit and must be Set if and only if the range is prefetchable","The historical definition of bit 3 is now deprecated and bit 3 is undefined; for backward compatibility it is strongly recommended that bit 3 be Set for 64-bit Memory BARs and Clear for 32-bit Memory BARs","Bit 3 must be hardwired to 0b on all Memory BARs in 7.0","Bit 3 is RW and software uses it to enable relaxed-ordering for MMIO"],1,"7.0은 bit 3의 역사적(Prefetchable) 정의를 deprecated하고 undefined로 둔다. 다만 legacy software 호환을 위해 64-bit Memory BAR에서는 Set, 32-bit에서는 Clear를 strongly recommend한다. Bits 3–0은 RO이다.","In 7.0 the historical definition of bit 3 is deprecated and bit 3 is undefined. For backward compatibility it is strongly recommended that bit 3 be Set for 64-bit Memory BARs and Clear for 32-bit Memory BARs. Bits 3–0 are read-only.","§7.5.1.2.1"],["p6q10","p6_3",2,"C","System software가 각 BAR이 요구하는 address space 크기를 알아내는 권장 방법은?","How should system software determine how much address space a Function’s BAR requires?",["Read the Class Code; the size is implied by the programming interface byte","Write 0’s to the BAR and measure how many bits stay 1","Issue an I/O Read to port CF8h for every possible size from 16 bytes to 2 GB","Write a value of all 1’s to each BAR and then read it back; low-order bits of the Base Address field return 0’s to indicate the required size"],["Read the Class Code; the size is implied by the programming interface byte","Write 0’s to the BAR and measure how many bits stay 1","Issue an I/O Read to port CF8h for every possible size from 16 bytes to 2 GB","Write a value of all 1’s to each BAR and then read it back; low-order bits of the Base Address field return 0’s to indicate the required size"],3,"표준: all 1’s를 쓴 뒤 다시 읽는다. Base Address field의 하위 비트 0이 필요한 크기를 나타낸다. 미구현 BAR은 0으로 hardwired여야 한다. 공간 크기는 2의 거듭제곱이며 naturally aligned이다.","Software should write all 1’s to each BAR and read it back. Low-order zeros in the Base Address field indicate the required size. Unimplemented BARs must be hardwired to zero. Address spaces are a power of two and naturally aligned.","§7.5.1.2.1"],["p6q11","p6_3",2,"P","32-bit BAR이 지원하는 크기 범위와, Function이 I/O BAR당 소비하면 안 되는 상한은?","What size range does a 32-bit BAR support, and what is the maximum a Function may consume per I/O BAR?",["I/O Space from 16 bytes to 256 bytes, or Memory Space from 128 bytes to 2 GB; a Function must not consume more than 256 bytes per I/O BAR","I/O and Memory both from 4 KB to 4 GB, with no I/O-size cap","Memory from 16 bytes to 256 bytes, I/O from 128 bytes to 2 GB","Only 1 MB or 4 KB sizes are permitted for either Space"],["I/O Space from 16 bytes to 256 bytes, or Memory Space from 128 bytes to 2 GB; a Function must not consume more than 256 bytes per I/O BAR","I/O and Memory both from 4 KB to 4 GB, with no I/O-size cap","Memory from 16 bytes to 256 bytes, I/O from 128 bytes to 2 GB","Only 1 MB or 4 KB sizes are permitted for either Space"],0,"32-bit BAR은 I/O 16 B–256 B 또는 Memory 128 B–2 GB의 power-of-two 크기 하나를 지원한다. I/O로 control function을 map하는 Function은 I/O BAR(또는 Enhanced Allocation entry)당 256바이트를 초과해 소비하면 안 된다. Memory BAR 최소는 128바이트이다.","A 32-bit BAR supports a single power-of-two size from 16 bytes to 256 bytes (I/O) or 128 bytes to 2 GB (Memory). Functions that map control functions into I/O Space must not consume more than 256 bytes per I/O BAR or Enhanced Allocation entry. The minimum Memory Space requested by a BAR is 128 bytes.","§7.5.1.2.1"],["p6q12","p6_3",2,"C","Type 0와 Type 1 Configuration Space Header에 할당된 BAR DWORD 위치 수는? 64-bit BAR은 어떻게 공간을 쓰는가?","How many DWORD locations are allocated for BARs in Type 0 versus Type 1 headers, and how does a 64-bit BAR consume those locations?",["Both headers have six DWORD locations, and a 64-bit BAR uses only one DWORD plus a hidden extension","Type 0 has two DWORD locations and Type 1 has six; a 64-bit BAR uses a single DWORD","Type 0 has six DWORD locations (offsets 10h–24h) and Type 1 has two; an implemented 64-bit BAR consumes two consecutive DWORD locations","Type 0 has four QWORD locations starting at 40h, and Type 1 has none"],["Both headers have six DWORD locations, and a 64-bit BAR uses only one DWORD plus a hidden extension","Type 0 has two DWORD locations and Type 1 has six; a 64-bit BAR uses a single DWORD","Type 0 has six DWORD locations (offsets 10h–24h) and Type 1 has two; an implemented 64-bit BAR consumes two consecutive DWORD locations","Type 0 has four QWORD locations starting at 40h, and Type 1 has none"],2,"Type 0는 offset 10h부터 여섯 DWORD, Type 1는 두 DWORD만 할당한다. 64-bit BAR은 연속된 두 DWORD를 사용한다. Software는 10h부터 24h까지 위로 가며 구현된 BAR을 찾는다. Memory BAR을 64-bit로 만드는 것이 strongly recommended이다.","A Type 0 header has six DWORD BAR locations starting at 10h; a Type 1 header has only two. An implemented 64-bit BAR consumes two consecutive DWORD locations. Software must start at 10h and continue through 24h. It is strongly recommended that each Memory BAR be 64 bits wide.","§7.5.1.2.1"],["p6q13","p6_4",1,"P","Header Type Register(offset 0Eh)에서 bit 7과 bits 6:0이 나타내는 것은?","In the Header Type Register (offset 0Eh), what do bit 7 and bits 6:0 indicate?",["Bit 7 is the Capabilities List present bit; bits 6:0 are the Revision ID","Bit 7 enables ARI Forwarding; bits 6:0 must be 0000010b for all PCIe Functions","The entire register is RW and software programs the header format at boot","Bit 7 is Multi-Function Device; bits 6:0 are Header Layout, with 0000000b for Type 0 and 0000001b for Type 1"],["Bit 7 is the Capabilities List present bit; bits 6:0 are the Revision ID","Bit 7 enables ARI Forwarding; bits 6:0 must be 0000010b for all PCIe Functions","The entire register is RW and software programs the header format at boot","Bit 7 is Multi-Function Device; bits 6:0 are Header Layout, with 0000000b for Type 0 and 0000001b for Type 1"],3,"Bits 6:0 Header Layout은 Type 0이면 0000000b, Type 1이면 0000001b여야 한다. 0000010b는 Reserved(과거 CardBus). Bit 7이 Set이면 Device가 multiple Functions를 포함할 수 있다. 이 register는 VF에 적용되지 않고 0으로 hardwired여야 한다.","Bits 6:0 (Header Layout) must be 0000000b for Type 0 and 0000001b for Type 1; 0000010b is Reserved. When bit 7 is Set, the Device may contain multiple Functions. The register does not apply to VFs and must be hardwired to zero for them.","§7.5.1.1.9"],["p6q14","p6_4",2,"P","Type 1 header의 Secondary Bus Number와 Subordinate Bus Number는 각각 무엇을 기록하는가?","What do the Secondary Bus Number and Subordinate Bus Number registers in a Type 1 header record?",["Secondary is the bus of the primary interface; Subordinate is always equal to the Primary Bus Number","Secondary is the bus number of the PCI bus segment to which the bridge’s secondary interface is connected; Subordinate is the highest-numbered PCI bus segment behind (subordinate to) the bridge","Both registers are hardwired to 00h and are not used by PCI Express Functions","Secondary is the Device Number of the Downstream Port; Subordinate is the Function Number"],["Secondary is the bus of the primary interface; Subordinate is always equal to the Primary Bus Number","Secondary is the bus number of the PCI bus segment to which the bridge’s secondary interface is connected; Subordinate is the highest-numbered PCI bus segment behind (subordinate to) the bridge","Both registers are hardwired to 00h and are not used by PCI Express Functions","Secondary is the Device Number of the Downstream Port; Subordinate is the Function Number"],1,"두 register 모두 configuration software가 program하는 RW이며 default는 00h이다. Bridge는 이 값으로 primary interface에서 본 ID-routed TLP를 secondary로 전달할지 결정한다. Primary Bus Number도 legacy 호환을 위해 RW, default 00h로 구현해야 한다.","Both are read/write, programmed by configuration software, and default to 00h. The bridge uses them to decide when and how to respond to an ID-routed TLP on its primary interface. The Primary Bus Number must also be implemented as RW with default 00h for legacy compatibility.","§7.5.1.3.3 / §7.5.1.3.4"],["p6q15","p6_4",2,"P","Type 1 Memory Base / Memory Limit register가 정의하는 memory window의 granularity는?","What address granularity do the Type 1 Memory Base and Memory Limit registers use for the memory window?",["4 KB; the registers supply Address[31:12]","64 KB; the registers supply Address[31:16]","1 MB; the registers supply Address[31:20], and the lower 20 bits are assumed 0 for the base and FFFFFh for the limit","256 bytes; the registers supply the entire 32-bit address"],["4 KB; the registers supply Address[31:12]","64 KB; the registers supply Address[31:16]","1 MB; the registers supply Address[31:20], and the lower 20 bits are assumed 0 for the base and FFFFFh for the limit","256 bytes; the registers supply the entire 32-bit address"],2,"상위 12비트가 RW로 Address[31:20]에 대응한다. Base의 [19:0]은 0, Limit의 [19:0]은 FFFFFh로 가정하므로 window 바닥은 1 MB 정렬, 꼭대기는 1 MB 경계보다 하나 작다. Secondary에 window가 없으면 Limit를 Base보다 작게 program해야 한다.","The upper 12 bits are RW and correspond to Address[31:20]. The lower 20 bits are assumed 0 for the base and FFFFFh for the limit, so the window is 1 MB-aligned at the bottom and ends one byte below a 1 MB boundary. If there is no memory-mapped space on the secondary side, Limit must be programmed smaller than Base.","§7.5.1.3.8"],["p6q16","p6_4",2,"P","PCI Express Function에서 Type 1 Secondary Latency Timer(offset 1Bh)는 어떻게 구현되어야 하는가?","How must the Type 1 Secondary Latency Timer (offset 1Bh) be implemented for a PCI Express Function?",["It does not apply to PCI Express and must be read-only and hardwired to 00h","It is RW and must be programmed to at least 16 clocks","It is sticky and preserves the last Conventional PCI latency value across hot reset","It is required to report the L1 exit latency in microseconds"],["It does not apply to PCI Express and must be read-only and hardwired to 00h","It is RW and must be programmed to at least 16 clocks","It is sticky and preserves the last Conventional PCI latency value across hot reset","It is required to report the L1 exit latency in microseconds"],0,"표준: 이 register는 PCI Express에 적용되지 않으며 read-only이고 00h로 hardwired되어야 한다. PCIe-to-PCI/PCI-X Bridge는 해당 Bridge 규격을 따른다.","This register does not apply to PCI Express and must be read-only and hardwired to 00h. For PCI Express to PCI/PCI-X Bridges, refer to that bridge specification.","§7.5.1.3.5"],["p6q17","p6_4",3,"P","FPB Routing ID를 쓰지 않는 PCI Express Switch의 Configuration Space 표현에서, Switch 내부 bus에 무엇이 나타나고 무엇이 금지되는가?","In the Configuration Space representation of a PCI Express Switch that is not using FPB Routing ID mechanisms, what may appear on the Switch’s internal bus, and what is not permitted?",["Only the PCI-PCI Bridges representing the Switch Downstream Ports may appear on the internal bus; Endpoints, represented by Type 0 headers, are not permitted to appear on the internal bus","Type 0 Endpoints must be placed on the internal bus as peers of the Upstream Port","The Upstream Port is a Type 0 Endpoint, and Downstream Ports are hidden from Configuration Space","RCiEPs are required to appear on the Switch internal bus as Device 0 Function 0"],["Only the PCI-PCI Bridges representing the Switch Downstream Ports may appear on the internal bus; Endpoints, represented by Type 0 headers, are not permitted to appear on the internal bus","Type 0 Endpoints must be placed on the internal bus as peers of the Upstream Port","The Upstream Port is a Type 0 Endpoint, and Downstream Ports are hidden from Configuration Space","RCiEPs are required to appear on the Switch internal bus as Device 0 Function 0"],0,"Switch USP는 PCI-PCI Bridge이고 그 secondary bus가 내부 routing logic이다. DSP들도 그 내부 bus에서 나가는 PCI-PCI Bridge이다. 내부 bus에는 DSP를 나타내는 Bridge만 나타날 수 있고 Type 0 Endpoint는 금지된다.","The Switch Upstream Port is a PCI-PCI Bridge whose secondary bus represents the Switch’s internal routing logic. Downstream Ports are PCI-PCI Bridges from that internal bus. Only those Downstream Port Bridges may appear on the internal bus; Type 0 Endpoints are not permitted there.","§7.1"],["p6q18","p6_5",1,"P","Capabilities Pointer(offset 34h)에 대한 요구로 옳은 것은?","Which requirement applies to the Capabilities Pointer register (offset 34h)?",["It may be zero if the Function implements no PCI-compatible Capabilities","It is RW and software must write 40h before enumerating Capabilities","It must be non-zero, because every PCI Express Function must implement the PCI Express Capability structure somewhere in this list; the bottom two bits are Reserved and must be 00b, and the register is HwInit","It points into Extended Configuration Space and must be greater than FFh"],["It may be zero if the Function implements no PCI-compatible Capabilities","It is RW and software must write 40h before enumerating Capabilities","It must be non-zero, because every PCI Express Function must implement the PCI Express Capability structure somewhere in this list; the bottom two bits are Reserved and must be 00b, and the register is HwInit","It points into Extended Configuration Space and must be greater than FFh"],2,"모든 PCIe Function은 PCI Express Capability structure를 이 linked list 어딘가에 넣어야 하므로 pointer는 non-zero여야 한다. Software는 하위 2비트를 mask한 뒤 첫 capability를 가리키는 pointer로 사용한다.","Every PCI Express Function must implement the PCI Express Capability structure in this linked list, so the pointer must be non-zero. Software must mask the reserved bottom two bits before using it as a pointer to the first capability.","§7.5.1.1.11"],["p6q19","p6_5",1,"P","PCI Power Management Capability의 Capability_ID 값과, PCI Express Capability structure의 Capability ID 값은?","What Capability_ID value identifies the PCI Power Management Capability, and what Capability ID identifies the PCI Express Capability structure?",["10h for Power Management and 01h for the PCI Express Capability","01h for Power Management and 10h for the PCI Express Capability","05h for Power Management and 11h for the PCI Express Capability","00h for both; they are distinguished only by Version fields"],["10h for Power Management and 01h for the PCI Express Capability","01h for Power Management and 10h for the PCI Express Capability","05h for Power Management and 11h for the PCI Express Capability","00h for both; they are distinguished only by Version fields"],1,"PM Capability_ID는 01h를 반환하며, 한 Function의 capability list에 01h item은 하나만 둘 수 있다. PCI Express Capability ID는 10h이다. 각 item의 Next Capability Pointer가 00h이면 list의 끝이다.","The PM Capability_ID returns 01h, and a Function may have only one list item with Capability_ID 01h. The PCI Express Capability ID is 10h. A Next Capability Pointer of 00h terminates the list.","§7.5.2.1 / §7.5.3.1"],["p6q20","p6_5",2,"P","이 규격에 적합한 Function의 PCI Express Capabilities Register Capability Version 필드는 무엇으로 hardwired되어야 하는가?","To what value must the Capability Version field in the PCI Express Capabilities Register be hardwired for Functions compliant to this specification?",["1h","0h","7h","2h"],["1h","0h","7h","2h"],3,"PCI Express Capabilities Register bits 3:0 Capability Version은 이 규격에 적합한 Function에서 2h로 hardwired되어야 한다. Software는 작성 시점의 최고 버전 이상도 호환 구조로 보고 검사해야 한다.","The Capability Version field (bits 3:0) must be hardwired to 2h for Functions compliant to this specification. Software must also accept version numbers greater than or equal to the highest number defined when the software was written.","§7.5.3.2"],["p6q21","p6_5",2,"C","PCI Express Capabilities Register의 Device/Port Type 인코딩 중 Type 00h header Function에 정의된 값은?","Which Device/Port Type encodings are defined for Functions that implement a Type 00h Configuration Space header?",["0100b Root Port, 0101b Switch Upstream Port, 0110b Switch Downstream Port, 0111b PCIe-to-PCI/PCI-X Bridge","0000b Root Port and 0001b Switch Downstream Port only","0000b PCI Express Endpoint, 0001b Legacy PCI Express Endpoint, 1001b RCiEP, 1010b Root Complex Event Collector","1111b for all Endpoints; the header type already distinguishes the rest"],["0100b Root Port, 0101b Switch Upstream Port, 0110b Switch Downstream Port, 0111b PCIe-to-PCI/PCI-X Bridge","0000b Root Port and 0001b Switch Downstream Port only","0000b PCI Express Endpoint, 0001b Legacy PCI Express Endpoint, 1001b RCiEP, 1010b Root Complex Event Collector","1111b for all Endpoints; the header type already distinguishes the rest"],2,"Type 00h header: 0000b Endpoint, 0001b Legacy Endpoint, 1001b RCiEP, 1010b RCEC. Type 01h header: 0100b Root Port, 0101b Switch USP, 0110b Switch DSP, 0111b PCIe-to-PCI/PCI-X Bridge, 1000b PCI/PCI-X-to-PCIe Bridge. 나머지 인코딩은 Reserved이다.","For Type 00h headers: 0000b Endpoint, 0001b Legacy Endpoint, 1001b RCiEP, 1010b RCEC. For Type 01h headers: 0100b Root Port, 0101b Switch USP, 0110b Switch DSP, 0111b PCIe-to-PCI/PCI-X Bridge, and 1000b PCI/PCI-X-to-PCIe Bridge. All other encodings are Reserved.","§7.5.3.2"],["p6q22","p6_6",1,"C","PCI Express Extended Capability Header의 비트 배치는?","How are the fields of a PCI Express Extended Capability Header laid out?",["Bits 15:0 Capability ID, bits 19:16 Capability Version, bits 31:20 Next Capability Offset","Bits 7:0 Capability ID, bits 15:8 Next Capability Pointer, bits 31:16 Version","Bits 31:16 Capability ID, bits 15:0 Next Capability Offset","Bits 15:0 Next Capability Offset, bits 31:16 Capability ID; there is no Version field"],["Bits 15:0 Capability ID, bits 19:16 Capability Version, bits 31:20 Next Capability Offset","Bits 7:0 Capability ID, bits 15:8 Next Capability Pointer, bits 31:16 Version","Bits 31:16 Capability ID, bits 15:0 Next Capability Offset","Bits 15:0 Next Capability Offset, bits 31:16 Capability ID; there is no Version field"],0,"모든 Extended Capability는 이 header로 시작하며 DWORD aligned여야 한다. Config Space에서 Next Capability Offset은 list 끝이면 000h, 그렇지 않으면 0FFh보다 커야 한다(PCI-compatible Space 시작점 기준).","Every Extended Capability must begin with this header and must be DWORD aligned. In Configuration Space the Next Capability Offset must be 000h (end of list) or greater than 0FFh, relative to the beginning of PCI-compatible Configuration Space.","§7.6 / §7.6.3"],["p6q23","p6_6",2,"P","Configuration Space에 Extended Capability가 하나도 없을 때, offset 100h의 header는 어떻게 표시해야 하는가? RCRB에서 없을 때는?","If there are no Extended Capabilities in Configuration Space, what must the header at offset 100h contain? What about absence in an RCRB?",["In both cases the first DWORD must be all 1’s","In Configuration Space: ID FFFFh; in an RCRB: ID 0000h","Absence is indicated by a Capabilities Pointer of 00h only; offset 100h is undefined","In Configuration Space: Capability ID 0000h, Capability Version 0h, Next Capability Offset 000h. In an RCRB: Capability ID FFFFh and Next Capability Offset 000h"],["In both cases the first DWORD must be all 1’s","In Configuration Space: ID FFFFh; in an RCRB: ID 0000h","Absence is indicated by a Capabilities Pointer of 00h only; offset 100h is undefined","In Configuration Space: Capability ID 0000h, Capability Version 0h, Next Capability Offset 000h. In an RCRB: Capability ID FFFFh and Next Capability Offset 000h"],3,"Config Space Extended Capabilities는 항상 100h에서 시작하고, 없으면 ID=0000h, Version=0h, Next=000h이다. RCRB Extended Capabilities는 000h에서 시작하고, 없으면 ID=FFFFh, Next=000h이다. Config Space의 Extended Capabilities는 ECAM으로만 접근한다.","Extended Capabilities in Configuration Space always begin at 100h; absence is ID 0000h, Version 0h, Next 000h. In an RCRB they begin at 000h, and absence is ID FFFFh with Next 000h. Configuration Space Extended Capabilities are accessible only via ECAM.","§7.6.1 / §7.6.2"],["p6q24","p6_7",1,"C","DVSEC Designated Vendor-Specific Header 1에서 DVSEC Vendor ID, DVSEC Revision, DVSEC Length의 비트 위치는?","In DVSEC Designated Vendor-Specific Header 1, where are the DVSEC Vendor ID, DVSEC Revision, and DVSEC Length fields?",["Bits 15:0 DVSEC Length, bits 31:16 DVSEC Vendor ID; there is no Revision field","Bits 15:0 DVSEC Vendor ID, bits 19:16 DVSEC Revision, bits 31:20 DVSEC Length (bytes in the entire DVSEC structure, including headers)","Bits 7:0 DVSEC Vendor ID and bits 15:8 DVSEC ID only","The Function’s Type 0 Vendor ID is reused; Header 1 is Reserved"],["Bits 15:0 DVSEC Length, bits 31:16 DVSEC Vendor ID; there is no Revision field","Bits 15:0 DVSEC Vendor ID, bits 19:16 DVSEC Revision, bits 31:20 DVSEC Length (bytes in the entire DVSEC structure, including headers)","Bits 7:0 DVSEC Vendor ID and bits 15:8 DVSEC ID only","The Function’s Type 0 Vendor ID is reused; Header 1 is Reserved"],1,"Length는 PCI Express Extended Capability Header, DVSEC Header 1, DVSEC Header 2, vendor-specific register를 포함한 전체 바이트 수이다. DVSEC ID는 Header 2(offset 08h) bits 15:0에 있다. Extended Capability ID는 0023h이다.","Length is the number of bytes in the entire DVSEC structure, including the Extended Capability Header, DVSEC Header 1, DVSEC Header 2, and vendor-specific registers. The DVSEC ID is bits 15:0 of Header 2 (offset 08h). The Extended Capability ID is 0023h.","§7.9.6.2 / §7.9.6.3"],["p6q25","p6_7",2,"C","다음 중 DVSEC에 대한 서술로 옳은 것은?","Which statement about DVSEC is correct?",["DVSEC is mandatory in every Function and must be located at offset 40h in the PCI-compatible region","DVSEC is an optional Extended Capability; a Function or RCRB may contain multiple DVSEC structures, and software must qualify the DVSEC Vendor ID before interpreting the DVSEC ID","The DVSEC Vendor ID must equal the Function’s Vendor ID in the Type 0/1 header, or the capability is invalid","DVSEC ID 0023h is stored in the Type 0 Capabilities Pointer"],["DVSEC is mandatory in every Function and must be located at offset 40h in the PCI-compatible region","DVSEC is an optional Extended Capability; a Function or RCRB may contain multiple DVSEC structures, and software must qualify the DVSEC Vendor ID before interpreting the DVSEC ID","The DVSEC Vendor ID must equal the Function’s Vendor ID in the Type 0/1 header, or the capability is invalid","DVSEC ID 0023h is stored in the Type 0 Capabilities Pointer"],1,"DVSEC Vendor ID는 내용을 정의한 vendor의 Vendor ID이며 Function header Vendor ID와 같아야 한다는 요구는 없다. 여러 vendor의 component가 같은 DVSEC 정의를 구현할 수 있게 하려는 것이 목적이다.","The DVSEC Vendor ID is the Vendor ID of the vendor that defined the contents; it is not required to match the Function header Vendor ID. The point of DVSEC is that the same defined structure can appear in components from a variety of vendors.","§7.9.6"],["p6q26","p6_8",2,"P","ARI Forwarding이 enable되어 있지 않고 FPB Routing ID를 쓰지 않는 Downstream Port는, 해당 Link의 Logical Bus에서 어떤 Device Number만 연관시켜야 하는가? 다른 Device Number를 겨냥한 Configuration Request는?","If ARI Forwarding is not enabled and FPB Routing ID mechanisms are not used, which Device Number must a Downstream Port associate with the device on the Link’s Logical Bus? What happens to Configuration Requests specifying other Device Numbers?",["Devices 0–31 are all valid; unimplemented Devices return Configuration Request Retry Status forever","Only Device 31; Device 0 is reserved for the Downstream Port itself","Device Numbers are ignored; every Type 1 Request is forwarded unchanged","Only Device 0; Requests specifying Device Numbers 1–31 must be terminated by the Switch Downstream Port or Root Port with Unsupported Request Completion Status"],["Devices 0–31 are all valid; unimplemented Devices return Configuration Request Retry Status forever","Only Device 31; Device 0 is reserved for the Downstream Port itself","Device Numbers are ignored; every Type 1 Request is forwarded unchanged","Only Device 0; Requests specifying Device Numbers 1–31 must be terminated by the Switch Downstream Port or Root Port with Unsupported Request Completion Status"],3,"해당 Link의 Bus Number와 Device 0을 겨냥한 Request는 device로 전달된다. Device 1–31은 Switch DSP 또는 Root Port가 UR로 종료한다(PCI의 Master Abort에 해당).","Configuration Requests targeting the Bus Number associated with the Link and specifying Device Number 0 are delivered to the device. Requests specifying Device Numbers 1–31 must be terminated with Unsupported Request Completion Status (equivalent to Master Abort in PCI).","§7.3.1"],["p6q27","p6_8",2,"P","Non-ARI Device는 Type 0 Configuration Read Request의 Device Number가 0이 아니어도 응답해야 하는가?","Must a non-ARI Device respond to a Type 0 Configuration Read Request even if the Device Number specified in the Request is not 0?",["Yes. Non-ARI Devices must respond to all Type 0 Configuration Read Requests, regardless of the Device Number specified in the Request","No. They must silently drop any Type 0 Request whose Device Number is not 0","They may respond only if the Device Number matches a value strapped at reset","They must complete such Requests as Completer Abort"],["Yes. Non-ARI Devices must respond to all Type 0 Configuration Read Requests, regardless of the Device Number specified in the Request","No. They must silently drop any Type 0 Request whose Device Number is not 0","They may respond only if the Device Number matches a value strapped at reset","They must complete such Requests as Completer Abort"],0,"Non-ARI Device는 assigned Device Number를 capture해야 하고(§2.2.6.2), Type 0 Configuration Read에는 Request에 적힌 Device Number와 관계없이 모두 응답해야 한다. 다만 DSP는 Device 1–31 Type 1을 UR로 종료하므로 정상 enumeration 경로에서는 Device 0만 전달된다.","Non-ARI Devices must capture their assigned Device Number (§2.2.6.2) and must respond to all Type 0 Configuration Read Requests regardless of the Device Number in the Request. A Downstream Port still terminates Type 1 Requests for Devices 1–31 with UR, so only Device 0 is delivered in normal enumeration.","§7.3.1"],["p6q28","p6_8",2,"P","Sticky 속성(ROS, RWS, RW1CS) 비트는 hot reset 또는 FLR에서 어떻게 다루어지는가?","How are bits with the Sticky attributes ROS, RWS, and RW1CS affected by hot reset or FLR?",["They are always cleared to 0 by both hot reset and FLR","They are cleared by FLR but preserved across hot reset only","They are neither initialized nor modified by hot reset or FLR","They are reloaded from EEPROM on every FLR but not on hot reset"],["They are always cleared to 0 by both hot reset and FLR","They are cleared by FLR but preserved across hot reset only","They are neither initialized nor modified by hot reset or FLR","They are reloaded from EEPROM on every FLR but not on hot reset"],2,"ROS/RWS/RW1CS 정의는 공통으로 비트가 hot reset이나 FLR로 초기화되거나 수정되지 않는다는 것이다. HwInit 비트도 FLR로 바뀌지 않으며, Conventional Reset과 이후 re-initialization 후에만 값이 바뀔 수 있다.","For ROS, RWS, and RW1CS the definition is that bits are neither initialized nor modified by hot reset or FLR. HwInit bits are also not modified by an FLR; after initialization they may change only following Conventional Reset and subsequent re-initialization.","§7.4"],["p6q29","p6_8",1,"P","Software가 Vendor ID register를 읽어 Function이 존재하는지 판단할 때, 어떤 값이 'Function이 없다'는 뜻인가? (non-VF)","When software reads the Vendor ID register to determine whether a Function is present, which value indicates that no Function is present (for non-VFs)?",["0000h","FFFEh","0010h","FFFFh"],["0000h","FFFEh","0010h","FFFFh"],3,"표준은 Vendor ID가 FFFFh이면 Function이 없음을 나타낸다고 한다. VF의 Vendor ID/Device ID도 읽으면 FFFFh를 반환해야 하며, VI software가 연관 PF 값을 대신 돌려주는 것이 권장된다.","A Vendor ID value of FFFFh indicates that no Function is present. For VFs this field must return FFFFh when read; VI software should return the associated PF’s Vendor ID as the VF’s Vendor ID.","§7.5.1.1.1"],["p6q30","p6_8",3,"P","Root Control Register의 Configuration RRS Software Visibility Enable bit가 Set되면 Root Port는 무엇을 할 수 있는가?","When the Configuration RRS Software Visibility Enable bit in the Root Control Register is Set, what does the Root Port do?",["It converts all RRS Completions into Successful Completions with Vendor ID FFFFh and never reports them to software","It is enabled to indicate to software when Request Retry Status (RRS) Completion Status is received in response to a Configuration Request","It disables all Configuration Requests until the Endpoint leaves Detect","It automatically issues FLR to any Function that returns RRS"],["It converts all RRS Completions into Successful Completions with Vendor ID FFFFh and never reports them to software","It is enabled to indicate to software when Request Retry Status (RRS) Completion Status is received in response to a Configuration Request","It disables all Configuration Requests until the Endpoint leaves Detect","It automatically issues FLR to any Function that returns RRS"],1,"이 bit는 Root Port가 Configuration Request에 대한 RRS Completion Status를 software에 알리도록 enable한다(§2.3.1). Capability가 없으면 0b로 hardwired. 대응 Capability bit는 Root Capabilities Register의 Configuration RRS Software Visibility이다. Enable되지 않으면 RC는 일반적으로 RRS가 아닌 status가 올 때까지 Configuration Request를 재발행한다.","When Set, this bit enables the Root Port to indicate to software when RRS Completion Status is received for a Configuration Request (see §2.3.1). Ports that do not implement the capability must hardwire the bit to 0b. The companion capability bit is in the Root Capabilities Register. If the feature is not enabled, the Root Complex generally re-issues the Configuration Request until it completes with a status other than RRS.","§7.5.3.12 / §2.3.2"],["p6q31","p6_8",3,"P","이 규격에 적합한 Function의 Power Management Capabilities Register Version 필드(bits 18:16)는 무엇으로 hardwired되어야 하는가?","To what value must the Version field (bits 18:16) in the Power Management Capabilities Register be hardwired for Functions compliant to this specification?",["001b","010b","011b","111b"],["001b","010b","011b","111b"],2,"Version은 이 규격에 적합한 Function에서 011b로 hardwired되어야 한다. PME Clock(bit 19)은 PCIe에 적용되지 않으며 0b로 hardwired되어야 한다.","Version must be hardwired to 011b for Functions compliant to this specification. The PME Clock bit does not apply to PCI Express and must be hardwired to 0b.","§7.5.2.1"],["p6q32","p6_5",2,"P","PCI Express Capability의 Device Capabilities, Device Control, Device Status register는 누구에게 필수인가? Link Capabilities/Control/Status는?","For whom are the PCI Express Capability Device Capabilities, Device Control, and Device Status registers required? What about the Link Capabilities, Link Control, and Link Status registers?",["The Device registers are required for all PCI Express device Functions. The Link registers are required for all Root Ports, Switch Ports, Bridges, and Endpoints that are not RCiEPs.","Both sets are required only in Root Ports, and Endpoints must hardwire all of them to 1","The Link registers are required in RCiEPs, and the Device registers are optional everywhere","Neither set is required if MSI-X is implemented"],["The Device registers are required for all PCI Express device Functions. The Link registers are required for all Root Ports, Switch Ports, Bridges, and Endpoints that are not RCiEPs.","Both sets are required only in Root Ports, and Endpoints must hardwire all of them to 1","The Link registers are required in RCiEPs, and the Device registers are optional everywhere","Neither set is required if MSI-X is implemented"],0,"구현하지 않는 Device/Link Capabilities 2 등 대응 공간은 0으로 hardwired해야 한다. Slot register는 특정 Switch Downstream/Root Port에서 요구된다. PCI Express Capability structure 자체는 모든 PCI Express device Function에 필수이다.","Functions that do not implement the Device or Link Capabilities/Status/Control 2 registers must hardwire those spaces to 0. Slot registers are required in certain Switch Downstream and Root Ports. The PCI Express Capability structure itself is required for PCI Express device Functions.","§7.5.3"],["p6q33","p6_8",2,"P","RsvdP와 RsvdZ reserved bit에 대해 software가 지켜야 할 write 규칙은?","What write rules must software follow for RsvdP and RsvdZ reserved bits?",["RsvdP bits must return zero when read, and software must preserve the value read for writes. RsvdZ bits must return zero when read, and software must use 0b for writes.","Both types may be written with any value; hardware will ignore them","RsvdZ bits must be written with the value previously read; RsvdP bits must be written as 1b","Software must Set every reserved bit to 1b to enable future features"],["RsvdP bits must return zero when read, and software must preserve the value read for writes. RsvdZ bits must return zero when read, and software must use 0b for writes.","Both types may be written with any value; hardware will ignore them","RsvdZ bits must be written with the value previously read; RsvdP bits must be written as 1b","Software must Set every reserved bit to 1b to enable future features"],0,"RsvdP는 미래 RW 구현을 위해 Reserved and Preserved이고, RsvdZ는 미래 RW1C 구현을 위해 Reserved and Zero이다. 둘 다 읽으면 0을 반환해야 한다.","RsvdP is Reserved and Preserved (for future RW implementations). RsvdZ is Reserved and Zero (for future RW1C implementations). Both are read-only and must return zero when read.","§7.4"],["p6q34","p6_4",1,"P","PCI Express Endpoint와 Legacy Endpoint는 Configuration Space에서 어디에 나타나야 하는가? RCiEP와 Root Complex Event Collector는?","Where must PCI Express Endpoints and Legacy Endpoints appear in Configuration Space, and where do RCiEPs and Root Complex Event Collectors appear?",["All of them must appear on a Switch’s internal bus as Type 0 Functions","RCiEPs must appear below a Root Port, and ordinary Endpoints appear as peers of Root Ports","Endpoints and Legacy Endpoints must appear within a Hierarchy Domain originated by the Root Complex (a tree headed by a Root Port). RCiEPs and Root Complex Event Collectors do not appear in those domains; they appear as peers of the Root Ports.","Legacy Endpoints are hidden from Configuration Space and are discovered only via ACPI"],["All of them must appear on a Switch’s internal bus as Type 0 Functions","RCiEPs must appear below a Root Port, and ordinary Endpoints appear as peers of Root Ports","Endpoints and Legacy Endpoints must appear within a Hierarchy Domain originated by the Root Complex (a tree headed by a Root Port). RCiEPs and Root Complex Event Collectors do not appear in those domains; they appear as peers of the Root Ports.","Legacy Endpoints are hidden from Configuration Space and are discovered only via ACPI"],2,"Root Port 자체가 PCI Express Link를 시작하는 PCI-PCI Bridge이다. 별도로 명시되지 않는 한 Configuration Space 요구는 Single-Function Device와 Multi-Function Device의 각 Function에 개별적으로 적용된다.","A Root Port is a PCI-PCI Bridge structure that originates a PCI Express Link from a Root Complex. Unless otherwise specified, Configuration Space requirements for a device apply to a Single-Function Device and to each Function of a Multi-Function Device individually.","§7.1"],["p6q35","p6_3",3,"P","32-bit Memory BAR으로 1 MB address space를 요구하는 Function은 address bit를 어떻게 구현해야 하는가?","How must a Function that wants a 1 MB memory address space in a single 32-bit Base Address Register implement the address bits?",["It must implement only bit 0 as RW and hardwire bits 31:1 to 1","It must implement the top 12 bits of the Address register as Read-Write and hardwire the other address bits to 0","It must implement all 32 bits as RW so software can place the window on any byte boundary","It must use two 32-bit BARs even for a 1 MB 32-bit window"],["It must implement only bit 0 as RW and hardwire bits 31:1 to 1","It must implement the top 12 bits of the Address register as Read-Write and hardwire the other address bits to 0","It must implement all 32 bits as RW so software can place the window on any byte boundary","It must use two 32-bit BARs even for a 1 MB 32-bit window"],1,"표준의 예: 1 MB를 쓰는 32-bit BAR은 상위 12 address bit를 RW로 구현하고 나머지 address bit는 0으로 hardwire한다. 각 BAR은 연관된 address space의 적절히 정렬된 임의의 주소로 구성될 수 있어야 한다. RW bit의 default 값은 implementation specific이다.","The spec’s example is that a Function wanting 1 MB in a single 32-bit BAR must implement the top 12 bits of the Address register as RW and hardwire the other address bits to 0. Each BAR must be configurable to any appropriately aligned address in the associated space. The default of the RW bits is implementation specific.","§7.5.1.2.1"],["p6q36","p6_6",2,"P","PCI Express Extended Capability structure는 어떤 정렬을 지켜야 하며, Config Space에서 Next Capability Offset의 허용 값은?","What alignment is required for each PCI Express Extended Capability structure, and what Next Capability Offset values are legal in Configuration Space?",["Each structure may start on any byte offset, including 40h in the PCI-compatible region","Structures must be 4 KB aligned, and Next must be a 16-bit Capability ID","Next may point to 34h, the Capabilities Pointer, to wrap the list","Each Capability structure must be DWORD aligned. In Configuration Space the Next Capability Offset must be 000h (end of list) or greater than 0FFh."],["Each structure may start on any byte offset, including 40h in the PCI-compatible region","Structures must be 4 KB aligned, and Next must be a 16-bit Capability ID","Next may point to 34h, the Capabilities Pointer, to wrap the list","Each Capability structure must be DWORD aligned. In Configuration Space the Next Capability Offset must be 000h (end of list) or greater than 0FFh."],3,"Next Capability Offset은 PCI-compatible Configuration Space의 시작점 기준이므로, list를 끝내지 않는 한 항상 0FFh보다 커야 한다. Extended Capabilities는 첫 256바이트 안이 아니라 100h 이상에 위치한다.","The Next Capability Offset is relative to the beginning of PCI-compatible Configuration Space, so except for the 000h terminator it must always be greater than 0FFh. Extended Capabilities live at 100h and above, not in the first 256 bytes.","§7.6 / §7.6.3"],["c6q01","c6_1",1,"X","CXL 스펙이 정의한 DVSEC 구조에서 DVSEC Vendor ID 필드 값은?","What is the DVSEC Vendor ID value in DVSEC structures defined by the CXL spec?",["1E98h","8086h","0000h","FFFFh"],["1E98h","8086h","0000h","FFFFh"],0,"CXL 정의 Configuration Space 블록은 DVSEC Vendor ID를 1E98h로 둬서 CXL 스펙이 정의한 구조임을 표시한다.","CXL-defined configuration blocks set DVSEC Vendor ID to 1E98h to mark them as CXL-spec structures.","§8.1.1"],["c6q02","c6_1",1,"C","DVSEC(Designated Vendor-Specific Extended Capability)는 어느 스펙이 정의한 capability 형식인가?","Which specification defines the DVSEC (Designated Vendor-Specific Extended Capability) format itself?",["UEFI 스펙","PCIe Base Specification","CXL 스펙만의 고유 형식","ACPI 스펙"],["The UEFI spec","The PCIe Base Specification","A format unique to the CXL spec","The ACPI spec"],1,"DVSEC는 PCIe가 정의한 Extended Capability 형식이다. CXL은 이 틀 안에 자기 Vendor ID와 DVSEC ID로 레지스터 블록을 넣는다. 표준 DVSEC 필드 설명은 PCIe Base Spec을 참조한다.","DVSEC is a PCIe-defined extended capability. CXL places its register blocks inside it using its own Vendor ID and DVSEC IDs, and refers to the PCIe Base Spec for the standard fields.","§8.1.3"],["c6q03","c6_1",1,"X","CXL DVSEC Revision을 n에서 n+1로 올릴 때 허용되지 않는 것은?","When a CXL DVSEC goes from Revision n to n+1, what is NOT allowed?",["끝에 새 레지스터를 붙이고 DVSEC Length 늘리기","낮은 Revision용 소프트웨어가 계속 동작하게 두기","기존 필드의 의미를 다시 정의하기","Revision n의 reserved 필드를 새 기능으로 채우기"],["Appending registers and increasing DVSEC Length","Letting software written for lower revisions keep working","Redefining the meaning of existing fields","Filling Revision n reserved fields with new features"],2,"Revision이 올라가도 하위 호환을 지켜야 한다. reserved 필드를 쓰거나 레지스터를 덧붙일 수는 있지만 기존 필드 의미는 바꿀 수 없다.","Backward compatibility must hold. New revisions may use reserved fields or append registers, but must not redefine existing fields.","§8.1.1"],["c6q04","c6_2",1,"C","소프트웨어가 어떤 Endpoint가 CXL 장치인지 일반 PCIe 장치인지 구분하는 방법은?","How can software tell a CXL device from an ordinary PCIe device?",["Class Code가 항상 다르다","Type 1 header를 쓰는지 본다","BAR 개수로 판단한다","Function 0에 PCIe DVSEC for CXL Devices(DVSEC ID 0000h)가 있는지 본다"],["The Class Code always differs","Check whether it uses a Type 1 header","Judge by the number of BARs","Check Function 0 for the PCIe DVSEC for CXL Devices (DVSEC ID 0000h)"],3,"두 장치 모두 표준 PCIe Endpoint처럼 Type 0 header로 보인다. 차이는 이 DVSEC의 유무이며, 표준 PCIe 장치는 이 DVSEC를 노출하면 안 된다.","Both look like standard PCIe Endpoints with a Type 0 header. The difference is this DVSEC, which a standard PCIe device must not expose.","§8.1.3"],["c6q05","c6_2",2,"X","CXL VH 아래의 CXL 장치(RCD 아님)가 Function 0에 두는 PCIe DVSEC for CXL Devices의 Revision 조건은?","For a non-RCD CXL device in a CXL VH, what revision must its Function 0 PCIe DVSEC for CXL Devices have?",["1 이상","0만 허용","정확히 3","제한 없음, 0도 허용"],["1 or higher","Only 0","Exactly 3","No limit; 0 is fine"],0,"RCD는 Revision 0 이상이면 되지만, RCD가 아닌 장치는 Revision 1 이상을 구현해야 한다.","An RCD may use Revision 0 or higher, but non-RCD devices must implement Revision 1 or higher.","§9.12.2"],["c6q06","c6_2",3,"X","RCD가 아닌 CXL 장치에서 PCIe DVSEC for CXL Devices가 장치 전체의 CXL 기능을 제어하는 위치는?","For a non-RCD CXL device, where does the PCIe DVSEC for CXL Devices control CXL functionality for the whole device?",["Root Port의 DVSEC","Function 0의 DVSEC","모든 Function의 DVSEC를 OR한 값","마지막 Function의 DVSEC"],["The Root Port's DVSEC","The DVSEC in Function 0","The OR of every Function's DVSEC","The DVSEC in the last Function"],1,"RCD든 아니든 Function 0 DVSEC의 capability·status·control 필드가 장치 전체의 CXL 기능을 제어한다.","In both cases, the capability, status, and control fields of the Function 0 DVSEC govern the whole device's CXL functionality.","§8.1.3"],["c6q07","c6_3",1,"X","DVSEC CXL Capability 레지스터의 IO_Capable 비트에 대한 규칙은?","What is the rule for the IO_Capable bit in the DVSEC CXL Capability register?",["소프트웨어가 설정한다","MLD에서는 0이다","항상 1이어야 한다","Type 3에서는 0이어야 한다"],["Software sets it","It is 0 for an MLD","It must be 1","It must be 0 for Type 3"],2,"CXL.io는 모든 CXL 장치의 필수 프로토콜이라 IO_Capable은 반드시 1이고, Control의 IO_Enable도 항상 1을 반환한다.","CXL.io is mandatory, so IO_Capable must be 1 and IO_Enable in Control always reads 1.","§8.1.3.1"],["c6q08","c6_3",2,"X","MLD의 모든 LD에서 DVSEC CXL Capability의 Cache_Capable과 Mem_Capable 값은?","For every LD of an MLD, what are Cache_Capable and Mem_Capable in DVSEC CXL Capability?",["Cache_Capable=1, Mem_Capable=0","둘 다 1","둘 다 0","Cache_Capable=0, Mem_Capable=1"],["Cache_Capable=1, Mem_Capable=0","Both 1","Both 0","Cache_Capable=0, Mem_Capable=1"],3,"MLD는 Type 3 전용이므로 LD는 CXL.cache를 지원하지 않고(0) CXL.mem은 지원해야 한다(1).","MLDs are Type 3 only, so each LD has no CXL.cache (0) and must support CXL.mem (1).","§8.1.3.1"],["c6q09","c6_3",2,"X","Mem_Capable=1인 장치에서 HDM_Count 필드가 가질 수 없는 값은?","For a device with Mem_Capable=1, which HDM_Count value is illegal?",["00b (범위 0개)","01b (범위 1개)","10b (범위 2개)","위 셋 모두 합법"],["00b (zero ranges)","01b (one range)","10b (two ranges)","All three are legal"],0,"HDM_Count는 DVSEC로 보고하는 HDM 범위 수다. Mem_Capable=1인데 00b(0개)를 보고하는 것은 금지되며, 11b는 reserved다.","HDM_Count reports the HDM ranges exposed via DVSEC. Reporting 00b (zero) with Mem_Capable=1 is illegal; 11b is reserved.","§8.1.3.1"],["c6q10","c6_3",1,"X","DVSEC CXL Control의 Mem_Enable이 0(기본값)일 때 장치가 할 수 있는 동작은?","When Mem_Enable in DVSEC CXL Control is 0 (default), what may the component do?",["CXL.io도 끈다","CXL.mem 트랜잭션을 조용히 버릴 수 있다","CXL.mem 트랜잭션을 정상 처리해야 한다","Link를 Down시킨다"],["Disable CXL.io too","Silently drop all CXL.mem transactions","It must process CXL.mem normally","Bring the link down"],1,"Mem_Enable과 Cache_Enable은 각 프로토콜을 켜는 비트다. 0이면 해당 프로토콜 트랜잭션을 조용히 버려도 된다.","Mem_Enable and Cache_Enable turn each protocol on. While 0, the component may silently drop that protocol's transactions.","§8.1.3.2"],["c6q11","c6_3",3,"X","DVSEC CXL Lock의 CONFIG_LOCK을 설정하면 일어나는 일과 해제 조건은?","What does setting CONFIG_LOCK in DVSEC CXL Lock do, and what clears it?",["CXL.io가 꺼지고 소프트웨어가 0을 쓰면 풀린다","HDM Decoder가 해제되고 CXL Reset으로 풀린다","DVSEC의 RWL 필드가 읽기 전용이 되고, Conventional Reset으로만 풀린다 (CXL Reset으로는 안 풀림)","모든 레지스터가 0으로 초기화되고 FLR로 풀린다"],["CXL.io turns off; writing 0 clears it","HDM decoders are released; CXL Reset clears it","RWL fields in the DVSEC become read-only; only a Conventional Reset clears it (CXL Reset does not)","All registers reset to 0; FLR clears it"],2,"CONFIG_LOCK은 RWO 비트로, 설정하면 Cache_Enable·Mem_Enable 같은 RWL 필드를 잠근다. 장치 Conventional Reset 때 풀리고 CXL Reset에는 영향받지 않는다.","CONFIG_LOCK is RWO and locks RWL fields such as Cache_Enable and Mem_Enable. A device Conventional Reset clears it; CXL Reset leaves it alone.","§8.1.3.6"],["c6q12","c6_4",2,"X","GPF DVSEC for CXL Ports(DVSEC ID 0004h)가 필수인 곳은?","Where is the GPF DVSEC for CXL Ports (DVSEC ID 0004h) mandatory?",["모든 CXL Endpoint","Upstream Switch Port만","FM-owned LD","CXL Root Port와 CXL Downstream Switch Port"],["Every CXL Endpoint","Upstream Switch Ports only","The FM-owned LD","CXL Root Ports and CXL Downstream Switch Ports"],3,"GPF timeout을 설정하는 이 DVSEC는 아래쪽 장치로 GPF를 보내는 Root Port와 DSP에 필수다.","This DVSEC, which configures GPF timeouts, is required on Root Ports and DSPs that send GPF downstream.","§8.1.6"],["c6q13","c6_4",1,"X","MLD DVSEC(DVSEC ID 0009h)가 필수인 대상은?","Which function must implement the MLD DVSEC (DVSEC ID 0009h)?",["FM-owned LD(FMLD)","모든 SLD","CXL Root Port","일반 PCIe 장치"],["The FM-owned LD (FMLD)","Every SLD","CXL Root Ports","Plain PCIe devices"],0,"MLD DVSEC은 지원 LD 수 등을 FM에 보고하며 FMLD에 필수다.","The MLD DVSEC reports items such as the number of supported LDs to the FM and is mandatory for the FMLD.","§8.1.10"],["c6q14","c6_4",2,"X","Register Locator DVSEC(0008h)이 '허용되지 않는(Not Permitted)' 대상은?","For which component is the Register Locator DVSEC (0008h) 'Not Permitted'?",["SLD","일반 PCIe 장치","CXL Root Port","CXL Upstream Switch Port"],["An SLD","A plain PCIe device","A CXL Root Port","A CXL Upstream Switch Port"],1,"Register Locator DVSEC은 RP, USP, DSP와 RCD가 아닌 장치에 필수이고, CXL이 아닌 PCIe 장치에는 허용되지 않는다.","The Register Locator DVSEC is mandatory for RPs, USPs, DSPs, and non-RCD devices, and is not permitted on a plain PCIe device.","§8.1.1"],["c6q15","c6_5",1,"X","CXL VH 안의 구성 요소에서 Component Register가 놓이는 곳을 알려 주는 구조는?","In a CXL VH, which structure tells software where the Component Registers are?",["ACPI DSDT","DVSEC CXL Range 레지스터","Register Locator DVSEC (BAR 번호와 오프셋)","PCIe Capability List의 MSI-X 테이블"],["The ACPI DSDT","The DVSEC CXL Range registers","The Register Locator DVSEC (BAR number and offset)","The MSI-X table in the PCIe capability list"],2,"VH 구성 요소의 Component Register는 표준 PCIe BAR 공간에 매핑되고, Register Locator DVSEC이 BAR와 오프셋을 알려 준다.","In a VH, Component Registers sit in standard PCIe BAR space, and the Register Locator DVSEC gives the BAR and offset.","§8.2.2"],["c6q16","c6_5",2,"X","Register Locator의 Register Block Identifier 01h가 가리키는 블록은?","Which block does Register Block Identifier 01h in the Register Locator point to?",["CXL Device Registers","CPMU Registers","BAR Virtualization ACL Registers","Component Registers"],["CXL Device Registers","CPMU Registers","BAR Virtualization ACL Registers","Component Registers"],3,"01h는 Component Registers, 02h는 BAR Virtualization ACL, 03h는 CXL Device Registers, 04h는 CPMU다.","01h is Component Registers, 02h BAR Virtualization ACL, 03h CXL Device Registers, and 04h CPMU.","§8.1.9.1"],["c6q17","c6_5",2,"C","Register Locator의 Register BIR 값 000b가 가리키는 BAR는?","Which BAR does Register BIR value 000b in the Register Locator point to?",["Configuration Space 오프셋 10h의 BAR (BAR0)","오프셋 24h의 BAR","Expansion ROM BAR","BIR 000b는 reserved"],["The BAR at configuration offset 10h (BAR0)","The BAR at offset 24h","The Expansion ROM BAR","BIR 000b is reserved"],0,"BIR 000b~101b는 오프셋 10h~24h의 BAR 여섯 개에 대응한다. Type 0 header의 BAR가 10h부터 시작한다는 점은 PCIe와 공통이다.","BIR 000b-101b map to the six BARs at offsets 10h-24h. BARs starting at offset 10h in a Type 0 header is common PCIe knowledge.","§8.1.9.1"],["c6q18","c6_5",3,"X","Component Register 블록 안에서 CXL.cachemem Primary Range의 위치는?","Where is the CXL.cachemem Primary Range within the Component Register block?",["오프셋 F000h~FFFFh 고정","오프셋 1000h~1FFFh (4KB)","오프셋 0000h~0FFFh","오프셋 E000h~E3FFh"],["Fixed at offset F000h-FFFFh","Offset 1000h-1FFFh (4 KB)","Offset 0000h-0FFFh","Offset E000h-E3FFh"],1,"0000h~0FFFh는 CXL.io용으로 reserved, 1000h~1FFFh가 CXL.cachemem Primary Range, E000h~E3FFh가 ARB/MUX 레지스터다.","0000h-0FFFh is reserved for CXL.io, 1000h-1FFFh is the CXL.cachemem Primary Range, and E000h-E3FFh holds ARB/MUX registers.","§8.2.3"],["c6q19","c6_5",2,"X","CXL Component Register의 64-bit 레지스터를 소프트웨어가 접근하는 규칙은?","How must software access a 64-bit CXL Component Register?",["Configuration Read로만 접근한다","4-byte 두 번으로 나눠 읽어야 한다","8-byte 한 번으로 접근하며 부분 읽기는 허용되지 않는다","1-byte씩 나눠 읽어야 한다"],["Only through Configuration Reads","As two 4-byte reads","As one 8-byte access; partial reads are not permitted","Byte by byte"],2,"Component Register는 CXL.io Memory Read/Write로 접근하며, 32-bit은 4-byte, 64-bit은 8-byte 단위로 접근해야 한다. 어기면 동작이 정의되지 않는다.","Component Registers use CXL.io memory reads and writes: 4-byte access for 32-bit and 8-byte for 64-bit registers, or behavior is undefined.","§8.2.3"],["c6q20","c6_6",1,"X","HDM Decoder가 CXL.mem 장치 안에서 하는 일은?","What does an HDM Decoder do inside a CXL.mem device?",["PCIe Bus Number를 배정한다","MSI 벡터를 매핑한다","Link 속도를 고른다","interleave를 고려해 HPA를 DPA(Device Physical Address)로 변환한다"],["Assign PCIe bus numbers","Map MSI vectors","Choose the link speed","Translate HPA to DPA (Device Physical Address), accounting for interleaving"],3,"장치의 HDM Decoder는 HPA를 DPA로 바꾼다. Host Bridge나 USP의 디코더는 대상 Root Port나 DSP를 고른다.","A device HDM Decoder converts HPA to DPA. Host Bridge and USP decoders pick the target Root Port or DSP.","§8.2.4.20"],["c6q21","c6_6",2,"X","CXL 장치(device)가 광고할 수 있는 HDM Decoder 수의 상한은?","What is the maximum number of HDM decoders a CXL device may advertise?",["10개 (switch와 Host Bridge는 32개까지)","4개","32개","16개"],["10 (switches and Host Bridges up to 32)","4","32","16"],0,"장치는 10개를 넘길 수 없고, CXL switch와 Host Bridge는 32개까지 광고할 수 있다.","The cap is 10 decoders for a device, while a switch or Host Bridge can report as many as 32.","§8.2.4.20.1"],["c6q22","c6_6",1,"X","HDM Decoder Control의 Interleave Granularity(IG) 기본값(0h)은?","What is the default Interleave Granularity (IG = 0h) in HDM Decoder Control?",["256 MB","256 Bytes","64 Bytes","4 KB"],["256 MB","256 bytes","64 bytes","4 KB"],1,"IG 0h는 256B이고, 6h(16KB)까지 정의된다. 256MB는 interleave set의 base·size 단위이지 IG가 아니다.","IG 0h is 256 B, with encodings up to 6h (16 KB). 256 MB is the base/size unit of an interleave set, not IG.","§8.2.4.20.7"],["c6q23","c6_6",3,"X","HDM Decoder의 3/6/12/16-way interleave(IW)에 대한 규칙으로 옳은 것은?","Which rule about 3-, 6-, 12-, and 16-way interleave (IW) in HDM decoders is correct?",["Switch USP 전용이다","모든 구성 요소가 반드시 지원한다","CXL.mem 장치에서만 유효하며, USP와 Host Bridge는 해당 capability 비트를 0으로 고정한다","Host Bridge 전용이다"],["Switch USPs only","Every component must support them","Valid only for CXL.mem devices; USPs and Host Bridges hardwire those capability bits to 0","Host Bridges only"],2,"1/2/4/8-way는 공통이지만 3·6·12·16-way는 장치에서만 유효하다. 3의 배수 way를 쓰면 decoder Size도 3의 배수여야 commit된다.","1/2/4/8-way are general, but 3/6/12/16-way are valid only on devices. With 3x ways, the decoder size must be a multiple of 3 to commit.","§8.2.4.20.1"],["c6q24","c6_7",1,"X","HDM Decoder를 활성화하려면 소프트웨어가 마지막에 하는 일은?","What does software do last to activate an HDM decoder?",["Error Not Committed 비트에 1을 쓴다","DVSEC CXL Control의 IO_Enable을 쓴다","Link를 retrain한다","레지스터를 모두 설정한 뒤 Commit 비트를 1로 쓰고 Committed를 확인한다"],["Write 1 to Error Not Committed","Write IO_Enable in DVSEC CXL Control","Retrain the link","After programming all registers, set Commit to 1 and check Committed"],3,"각 decoder는 commit돼야 CXL.mem을 디코드한다. 하드웨어는 10ms 안에 Committed나 Error Not Committed 중 하나를 설정해야 한다.","Each decoder must be committed before it decodes CXL.mem. Hardware sets Committed or Error Not Committed within 10 ms.","§8.2.4.20.12"],["c6q25","c6_7",2,"X","Lock On Commit=1로 decoder를 commit할 때 하드웨어가 검사하지 않는 것은?","When committing with Lock On Commit=1, which check does the hardware NOT perform?",["Decoder base가 4KB 정렬인지","다음 decoder의 base가 이전 decoder의 끝 이상인지","interleave way의 target이 서로 다른지","이전 decoder가 이미 Committed인지"],["Whether the base is 4 KB aligned","Whether the next base is at or above the previous decoder's end","Whether interleave targets are distinct","Whether the previous decoder is already Committed"],0,"검사 항목은 순서·비중첩, wraparound 없음, 3의 배수 way일 때 Size 조건, target 중복 없음, 이전 decoder Committed이다. base는 원래 bits[31:28] 단위로만 표현돼 256MB 정렬이 된다.","The checks cover order and no overlap, no wraparound, the size rule for 3x ways, distinct targets, and the prior decoder being Committed. Base is held in bits[31:28] and up, so it is 256 MB aligned by construction.","§8.2.4.20.12"],["c6q26","c6_7",2,"X","Lock On Commit=0인 decoder를 다시 프로그래밍하는 올바른 순서는?","What is the right way to reprogram a decoder with Lock On Commit=0?",["장치를 FLR한다","트래픽을 멈추고 Commit을 지운 뒤 필드를 바꾸고 다시 Commit을 설정한다","Commit=1 상태에서 바로 Base를 바꾼다","Error Not Committed를 지운다"],["FLR the device","Quiesce traffic, clear Commit, change fields, then set Commit again","Change Base while Commit=1","Clear Error Not Committed"],1,"Commit이 1인 상태에서 바꾸면 동작이 정의되지 않는다. Lock On Commit=0이면 alias 검사도 없어 소프트웨어가 책임진다.","Changing fields while Commit=1 is undefined. With Lock On Commit=0, there are no alias checks, so software owns correctness.","§8.2.4.20.13"],["c6q27","c6_7",3,"X","CXL.mem 장치에서 HDM Decoder Global Control의 HDM Decoder Enable을 1로 설정하면?","On a CXL.mem device, what happens when HDM Decoder Enable in HDM Decoder Global Control is set?",["Host Bridge의 decoder가 꺼진다","CXL.cache가 켜진다","장치가 DVSEC CXL Range Base 레지스터 대신 HDM Decoder로 CXL.mem을 디코드한다","DVSEC Range와 HDM Decoder를 동시에 쓴다"],["The Host Bridge decoders turn off","CXL.cache turns on","The device decodes CXL.mem with HDM decoders instead of the DVSEC CXL Range Base registers","It uses DVSEC Ranges and HDM decoders together"],2,"이 비트는 장치에만 적용된다. Host Bridge와 USP는 항상 HDM Decoder로 디코드하므로 이 비트가 0을 반환한다.","This bit applies only to devices. Host Bridges and USPs always decode with HDM decoders and return 0 here.","§8.2.4.20.2"],["c6q28","c6_8",1,"X","RCD(Restricted CXL Device) 모드의 제약이 아닌 것은?","Which is NOT a restriction of RCD (Restricted CXL Device) mode?",["Hot-Plug를 지원하지 않는다","Device/Port Type이 RCiEP다","HBR 외 라우팅은 지원하지 않는다","256B Flit mode만 지원한다"],["No Hot-Plug","Device/Port Type is RCiEP","No routing other than HBR","Only 256B Flit mode is supported"],3,"RCD는 68B Flit mode만 지원한다. Hot-Plug 미지원, RCiEP 타입, HBR 전용, non-CXL 소프트웨어에 link가 보이지 않음이 제약이다.","RCD supports only 68B Flit mode. Its restrictions are no Hot-Plug, RCiEP type, HBR only, and a link hidden from non-CXL-aware software.","§9.11.1"],["c6q29","c6_8",1,"C","CXL Root Port는 PCIe Configuration Space에서 어떻게 보이는가?","How does a CXL Root Port appear in PCIe configuration space?",["Type 1 header를 가진 표준 PCIe Root Port","Type 0 header를 가진 Endpoint","RCiEP","Configuration Space에 보이지 않는다"],["A standard PCIe Root Port with a Type 1 header","An Endpoint with a Type 0 header","An RCiEP","It is not visible in configuration space"],0,"CXL Root Port는 PCIe Root Port처럼 Type 1 header와 Root Port 타입으로 보인다. 그 아래 CXL 장치는 Type 0 header Endpoint로 보인다.","A CXL Root Port shows a Type 1 header and the Root Port type, just like PCIe. CXL devices below it appear as Type 0 header Endpoints.","§9.12.1"],["c6q30","c6_8",2,"X","ACPI 시스템에서 CXL Host Bridge를 식별하는 Hardware ID(HID)는?","In an ACPI system, which Hardware ID (HID) identifies a CXL Host Bridge?",["ACPI0007","ACPI0016","PNP0A08","PNP0A03"],["ACPI0007","ACPI0016","PNP0A08","PNP0A03"],1,"CXL Host Bridge는 HID ACPI0016으로 식별하고, CEDT로 세 종류의 Host Bridge 개념을 구분할 수 있다. PNP0A08은 PCIe Host Bridge다.","CXL Host Bridges use HID ACPI0016, and CEDT helps tell the three host-bridge concepts apart. PNP0A08 is the PCIe Host Bridge ID.","§9.12"],["c6q31","c6_8",2,"X","CXL 2.0 이후 규격을 따르는 CXL Memory Device의 Class Code(Base/Sub/PI)는?","What Class Code (Base/Sub/PI) does a CXL Memory Device following CXL 2.0 or later use?",["05h / 80h / 00h","FFh / FFh / FFh","05h / 02h / 10h","01h / 08h / 02h"],["05h / 80h / 00h","FFh / FFh / FFh","05h / 02h / 10h","01h / 08h / 02h"],2,"Base Class 05h(memory controller), Sub Class 02h(CXL memory device), Programming Interface 10h다. 이런 장치는 Register Block ID 03h도 광고해야 한다.","Base Class 05h (memory controller), Sub Class 02h (CXL memory device), PI 10h. Such a device must also advertise Register Block ID 03h.","§8.1.12.1"],["c6q32","c6_8",3,"X","System Firmware가 SRAT/HMAT를 만들 때 HDM의 지연·대역폭 정보를 장치에서 얻는 형식은?","When System Firmware builds SRAT/HMAT, in what form does it get HDM latency/bandwidth data from the device?",["MSI-X 테이블","Vital Product Data","ALMP","CDAT (Table Access DOE 또는 UEFI 드라이버로 제공)"],["The MSI-X table","Vital Product Data","ALMP","CDAT (via Table Access DOE or a UEFI driver)"],3,"System Firmware는 HDM 특성을 모르므로 장치가 CDAT로 알려 준다. 장치는 Table Access DOE나 UEFI 드라이버로 CDAT를 내보낸다.","System Firmware does not know HDM properties, so the device provides CDAT, exported via Table Access DOE or a UEFI driver.","§9.13"]],"7":[["p7q01","p7_1",1,"P","모든 Function이 지원해야 하는 D-state와, D0의 두 substate 진입 조건은?","Which D-states must every Function support, and when does a Function enter the two D0 substates?",["D0 is required and is split into D0uninitialized (after Conventional Reset or FLR) and D0active (when MSE, I/O Space Enable, or Bus Master Enable is Set). D3Hot and D3Cold are also required. D1 and D2 are optional.","Only D0active is required; D3 is optional and D0uninitialized does not exist","D1 and D2 are required; D3Cold is forbidden on PCI Express","A Function enters D0active automatically in Detect, before any Configuration Request"],["D0 is required and is split into D0uninitialized (after Conventional Reset or FLR) and D0active (when MSE, I/O Space Enable, or Bus Master Enable is Set). D3Hot and D3Cold are also required. D1 and D2 are optional.","Only D0active is required; D3 is optional and D0uninitialized does not exist","D1 and D2 are required; D3Cold is forbidden on PCI Express","A Function enters D0active automatically in Detect, before any Configuration Request"],0,"모든 Function은 D0를 지원해야 한다. Conventional Reset 직후와 FLR 완료 후는 D0uninitialized이다. Memory/I/O Space Enable 또는 Bus Master Enable 중 하나라도 Set되면 D0active로 들어간다. D3(Hot과 Cold 모두)는 필수, D1·D2는 optional이다.","All Functions must support D0. After Conventional Reset, and after FLR completes, the Function is in D0uninitialized. It enters D0active whenever Memory Space Enable, I/O Space Enable, or Bus Master Enable is Set. D3 support is required (both D3Hot and D3Cold). D1 and D2 support is optional.","§5.3.1.1 / §5.3.1.4"],["p7q02","p7_1",2,"P","D1 또는 D3Hot 상태의 Function이 받아들일 수 있는 Request TLP 종류는? 그 밖의 received Request는?","Which Request TLPs may a Function in D1 or D3Hot accept, and how must other received Requests be handled?",["All TLP types are accepted, but Completions are delayed until D0","Only Memory Writes are accepted; Configuration Requests must be retried with RRS","Only Configuration and Message Requests are accepted; all other received Requests must be handled as Unsupported Requests","No TLPs are accepted; the Link must be in Electrical Idle continuously"],["All TLP types are accepted, but Completions are delayed until D0","Only Memory Writes are accepted; Configuration Requests must be retried with RRS","Only Configuration and Message Requests are accepted; all other received Requests must be handled as Unsupported Requests","No TLPs are accepted; the Link must be in Electrical Idle continuously"],2,"D1과 D3Hot 모두 Configuration과 Message Request만 받아들인다. 다른 received Request는 UR로 처리하고, received Completion은 Unexpected Completion으로 처리하는 것이 optional이다.","In both D1 and D3Hot, Configuration and Message Requests are the only TLPs accepted. All other received Requests must be handled as Unsupported Requests; received Completions may optionally be handled as Unexpected Completions.","§5.3.1.2 / §5.3.1.4.1"],["p7q03","p7_1",2,"P","D3Hot → D0 전이 직후, Immediate_Readiness_on_Return_to_D0 bit가 Clear일 때 system software가 지켜야 할 최소 recovery time은?","After a D3Hot → D0 transition, what minimum recovery time must system software allow if Immediate_Readiness_on_Return_to_D0 is Clear?",["At least 100 ms, the same interval as the PME Service Timeout","At least 10 ms, before accessing the Function (including Configuration Requests); earlier access results in undefined behavior","At least 1.0 s, the Configuration-Ready polling limit","No wait is required; the Function must complete the first Configuration Request immediately in all cases"],["At least 100 ms, the same interval as the PME Service Timeout","At least 10 ms, before accessing the Function (including Configuration Requests); earlier access results in undefined behavior","At least 1.0 s, the Configuration-Ready polling limit","No wait is required; the Function must complete the first Configuration Request immediately in all cases"],1,"Immediate_Readiness_on_Return_to_D0가 Set이면 이 10 ms를 포함한 D0 복귀 후 delay 요구가 면제된다. 그 bit가 Clear이면 최소 10 ms를 기다리지 않고 접근하면 동작은 undefined이다.","Unless Immediate_Readiness_on_Return_to_D0 is Set, software must allow at least 10 ms after D3Hot → D0 before accessing the Function. Accesses during that recovery time, including Configuration Requests, result in undefined behavior.","§5.3.1.4 / §7.5.2.1"],["p7q04","p7_1",2,"P","PMCSR No_Soft_Reset bit가 Set인 경우와 Clear인 경우, software가 PowerState를 써 D3Hot에서 D0로 바꿨을 때 Function 상태는?","After software writes PowerState to move a Function from D3Hot to D0, what is the Function’s state if No_Soft_Reset is Set versus Clear?",["Set: the Function is held in D3Hot until a Cold Reset. Clear: the Function jumps directly to D3Cold","The bit only affects VFs and is ignored for PFs","Set and Clear both force a Fundamental Reset and a return to D0uninitialized","Set: internal state is preserved and the Function is in D0active with no additional software intervention required. Clear: internal Function state is undefined and software must fully re-initialize because the Function is in D0uninitialized. This bit MUST@FLIT be Set."],["Set: the Function is held in D3Hot until a Cold Reset. Clear: the Function jumps directly to D3Cold","The bit only affects VFs and is ignored for PFs","Set and Clear both force a Fundamental Reset and a return to D0uninitialized","Set: internal state is preserved and the Function is in D0active with no additional software intervention required. Clear: internal Function state is undefined and software must fully re-initialize because the Function is in D0uninitialized. This bit MUST@FLIT be Set."],3,"No_Soft_Reset과 무관하게, Fundamental Reset으로 D3Hot에서 D0가 되면 D0uninitialized로 돌아가며 PME가 지원·enable되어 있으면 PME context만 보존된다. Link가 L2/L3 Ready로 갔다면 이 bit와 관계없이 Function은 reset된다.","Regardless of this bit, a D3Hot → D0 transition by Fundamental Reset returns the Function to D0uninitialized with only PME context preserved if PME is supported and enabled. The Function is also reset if the Link has transitioned to L2/L3 Ready, regardless of No_Soft_Reset. The bit MUST@FLIT be Set.","§7.5.2.2 / §5.3.1.4"],["p7q05","p7_1",1,"P","Function이 D3Cold로 들어가는 시점과, 다시 D0로 나올 때 일어나는 일은?","When does a Function enter D3Cold, and what happens when it returns toward D0?",["It enters D3Cold by writing PowerState=11b, and context is always preserved without a reset","D3Cold is entered automatically after 10 ms in D3Hot even if main power remains","It enters D3Cold when its main power is removed. A power-on sequence with its associated Cold Reset transitions it to D0uninitialized with power-on defaults restored, and software must perform a full initialization to reach D0active","Leaving D3Cold requires only setting Bus Master Enable; Configuration Space is already valid"],["It enters D3Cold by writing PowerState=11b, and context is always preserved without a reset","D3Cold is entered automatically after 10 ms in D3Hot even if main power remains","It enters D3Cold when its main power is removed. A power-on sequence with its associated Cold Reset transitions it to D0uninitialized with power-on defaults restored, and software must perform a full initialization to reach D0active","Leaving D3Cold requires only setting Bus Master Enable; Configuration Space is already valid"],2,"PowerState 11b는 D3Hot이다. D3Cold는 main power 제거로 들어간다. PME_En이 Set이고 D3Cold wakeup을 지원하면 resume 동안 검사를 위해 PME context를 PMCSR에 유지해야 한다.","PowerState 11b is D3Hot. D3Cold is entered when main power is removed. If PME_En is Set, Functions that support wakeup from D3Cold must maintain PME context in the PMCSR for inspection during resume.","§5.3.1.4.2 / §7.5.2.2"],["p7q06","p7_1",2,"P","Software가 PMCSR PowerState 필드에 지원하지 않는 optional state를 write하면?","What happens if software writes an unsupported, optional state to the PMCSR PowerState field?",["The write operation must complete normally, but the data is discarded and no state change occurs","The Function must complete the write as Unsupported Request and hang the Link","The Function must enter D3Hot as a safe fallback","The write is reported as a Completer Abort and PowerState becomes undefined"],["The write operation must complete normally, but the data is discarded and no state change occurs","The Function must complete the write as Unsupported Request and hang the Link","The Function must enter D3Hot as a safe fallback","The write is reported as a Completer Abort and PowerState becomes undefined"],0,"PowerState 인코딩은 00b=D0, 01b=D1, 10b=D2, 11b=D3Hot이다. Default는 00b. 미지원 optional state write는 정상 완료되지만 데이터는 버리고 상태 변화는 없다.","PowerState encodings are 00b=D0, 01b=D1, 10b=D2, and 11b=D3Hot. The default is 00b. A write of an unsupported optional state must complete normally, but the data is discarded and no state change occurs.","§7.5.2.2"],["p7q07","p7_2",1,"P","D-state와 L-state의 대상, 그리고 L0p의 위치에 대한 설명으로 옳은 것은?","Which statement correctly describes what D-states and L-states apply to, and where L0p fits?",["D-states and L-states are identical names for the same Function power state","L0p is a top-level Link state between L0 and L0s, required in Non-Flit Mode","L-states are visible to legacy PCI-PM software as PCI bus power states D4–D7","D-states are associated with a particular Function; L-states are associated with a particular Link. L0p is a reduced-power sub-state of L0 (not a separate top-level Link state in this list)."],["D-states and L-states are identical names for the same Function power state","L0p is a top-level Link state between L0 and L0s, required in Non-Flit Mode","L-states are visible to legacy PCI-PM software as PCI bus power states D4–D7","D-states are associated with a particular Function; L-states are associated with a particular Link. L0p is a reduced-power sub-state of L0 (not a separate top-level Link state in this list)."],3,"개요는 D0/D1/D2/D3Hot/D3Cold와 L0, L0p(L0의 sub-state), L0s, L1, L1.0/L1.1/L1.2, L2를 구분한다. Link state는 PCI-PM legacy software에 직접 보이지 않는다.","The overview associates D-states with a Function and L-states with a Link. L0p is described as a reduced-power sub-state of L0. Link states are not visible to PCI-PM legacy-compatible software.","§5.1 / §5.2"],["p7q08","p7_2",2,"P","Table 5-2에 따르면, Downstream component의 D-state가 Link의 permissible interconnect state를 어떻게 결정하는가?","According to Table 5-2, how does the Downstream component’s D-state determine the permissible interconnect (Link) state?",["Every Downstream D-state allows only L0","D0: L0, L0s, L1, or L2/L3 Ready. D1/D2/D3Hot: L1 or L2/L3 Ready. D3Cold: L2 (if the platform provides Vaux) or L3","D3Hot forces L3 immediately, even while main power is still applied","D0 allows only L2, and D3Cold allows only L0"],["Every Downstream D-state allows only L0","D0: L0, L0s, L1, or L2/L3 Ready. D1/D2/D3Hot: L1 or L2/L3 Ready. D3Cold: L2 (if the platform provides Vaux) or L3","D3Hot forces L3 immediately, even while main power is still applied","D0 allows only L2, and D3Cold allows only L0"],1,"Link의 PM state는 Downstream component의 D-state가 결정한다. ASPM L0s/L1 지원 요구는 form factor에 따라 달라질 수 있다.","The Link’s power-management state is determined by the D-state of its Downstream component. ASPM L0s and L1 requirements are form-factor specific.","§5.3.2 / Table 5-2"],["p7q09","p7_2",2,"P","L0s에 대한 다음 설명 중 표준과 일치하는 것은?","Which statement about L0s matches the specification?",["Reference clocks and PLLs must be turned off in L0s, just as in L1.2","All main power supplies, component reference clocks, and internal PLLs must remain active during L0s; TLP and DLLP transmission is disabled for a Port whose Link is in Tx_L0s; one side of a Link may be in L0s while the other is in L0","Both directions of the Link must enter L0s together; asymmetric L0s is forbidden","L0s is required in Flit Mode and is the only ASPM state Retimers support"],["Reference clocks and PLLs must be turned off in L0s, just as in L1.2","All main power supplies, component reference clocks, and internal PLLs must remain active during L0s; TLP and DLLP transmission is disabled for a Port whose Link is in Tx_L0s; one side of a Link may be in L0s while the other is in L0","Both directions of the Link must enter L0s together; asymmetric L0s is forbidden","L0s is required in Flit Mode and is the only ASPM state Retimers support"],1,"L0s는 low resume latency standby이다. ASPM에서 지원은 form factor가 명시적으로 요구하지 않으면 optional이다. 공통 reference clock을 쓰면 L0s→L0 전이 시간이 100 Symbol Time 미만이기를 기대한다(desired). Flit Mode와 Retimer는 L0s를 지원하지 않는다.","L0s is a low-resume-latency standby state. Support is optional for ASPM unless the form-factor specification explicitly requires it. With a common reference clock, the L0s-to-L0 transition is desired to be less than 100 Symbol Times. Flit Mode and Retimers do not support L0s.","§5.2 / §5.4.1.1"],["p7q10","p7_2",2,"P","L2, L3, L2/L3 Ready의 구분으로 옳은 것은?","Which description correctly distinguishes L2, L3, and L2/L3 Ready?",["L2 and L3 are identical, and L2/L3 Ready is an optional ASPM substate of L0s","L3 keeps Vaux and Beacon logic active; L2 removes all power including auxiliary","Software writes PowerState to enter L3 directly while main power is still on","L2/L3 Ready is a required staging pseudo-state (LTSSM L2) used to prepare for power and clock removal. After main power is removed the Link goes to L2 if Vaux is provided and used, or to L3 if no Vaux is provided or used. L3 is the Link Off state when no power is present."],["L2 and L3 are identical, and L2/L3 Ready is an optional ASPM substate of L0s","L3 keeps Vaux and Beacon logic active; L2 removes all power including auxiliary","Software writes PowerState to enter L3 directly while main power is still on","L2/L3 Ready is a required staging pseudo-state (LTSSM L2) used to prepare for power and clock removal. After main power is removed the Link goes to L2 if Vaux is provided and used, or to L3 if no Vaux is provided or used. L3 is the Link Off state when no power is present."],3,"L2/L3 Ready 전이 protocol 지원은 필수이다. L2는 optional이며 Vaux에 의존한다. Downstream component는 PME_TO_Ack 뒤 PM_Enter_L23 DLLP로 L2/L3 Ready 진입을 시작한다.","L2/L3 Ready transition-protocol support is required. L2 support is optional and depends on auxiliary power. The Downstream component initiates L2/L3 Ready entry by sending a PM_Enter_L23 DLLP after the PME_Turn_Off / PME_TO_Ack handshake.","§5.2"],["p7q11","p7_3",1,"P","Active State Power Management(ASPM)의 기본 성격은?","What is the basic nature of Active State Power Management (ASPM)?",["It is an autonomous hardware-based mechanism that can place an idle Link into a lower-power state even when the connected components are in D0; software may disable it","It is only a software-driven protocol that can be used when the Function is in D3Hot","It replaces PCI-PM completely and forbids D-state transitions","It applies only to Root Complex internal Links and system Egress Ports"],["It is an autonomous hardware-based mechanism that can place an idle Link into a lower-power state even when the connected components are in D0; software may disable it","It is only a software-driven protocol that can be used when the Function is in D3Hot","It replaces PCI-PM completely and forbids D-state transitions","It applies only to Root Complex internal Links and system Egress Ports"],0,"ASPM은 PCI-PM software-compatible feature와 orthogonal한 최소 요구이다. Internal Root Complex Link나 system Egress Port와 연관되지 않은 모든 Port는 ASPM 최소 요구를 지원해야 한다. Root Complex는 PCI-PM 요구에서는 면제될 수 있지만 ASPM 최소 요구는 구현해야 한다.","ASPM must be treated as orthogonal to PCI-PM software-compatible features from a minimum-requirements perspective. All Ports not associated with an Internal Root Complex Link or system Egress Port must support the minimum ASPM requirements. The Root Complex is exempt from PCI-PM software-compatible requirements but must implement the minimum ASPM requirements.","§5.1 / §5.4.1"],["p7q12","p7_3",1,"P","Non-Flit Mode와 Flit Mode에서 ASPM의 low-power 'standby' Link state 구성은 어떻게 다른가?","How do the ASPM low-power “standby” Link states differ between Non-Flit Mode and Flit Mode?",["Both modes use only L0s; L1 is removed in Flit Mode","Flit Mode requires L0s and forbids L0p","In Non-Flit Mode the standby states are L0s and L1. In Flit Mode, L0p effectively replaces L0s, and L1 remains. Flit Mode does not support L0s, and Retimers do not support L0s.","Non-Flit Mode uses only L1.2, and Flit Mode uses only L3"],["Both modes use only L0s; L1 is removed in Flit Mode","Flit Mode requires L0s and forbids L0p","In Non-Flit Mode the standby states are L0s and L1. In Flit Mode, L0p effectively replaces L0s, and L1 remains. Flit Mode does not support L0s, and Retimers do not support L0s.","Non-Flit Mode uses only L1.2, and Flit Mode uses only L3"],2,"L0s 지원은 form factor가 명시적으로 요구하지 않으면 optional이다. ASPM L1도 form factor가 특별히 요구하지 않으면 optional이다. 반면 PCI-PM compatible power management에서 L1 지원은 필수이다.","L0s support is optional unless the form-factor specification explicitly requires it. ASPM support for L1 is optional unless a form factor specifically requires it. L1 support is required for PCI-PM compatible power management.","§5.4.1 / §5.4.1.1 / §5.2"],["p7q13","p7_3",2,"P","Software가 ASPM L1을 enable/disable할 때 지켜야 하는 순서와 조건은?","When software enables or disables ASPM L1, what sequencing and conditions are required?",["Software must enable the Downstream component first and disable the Upstream component first","Only the Downstream component has an ASPM Control field; the Upstream component is always enabled","ASPM L1 may be enabled on one component even if the other reports no L1 support","Software must enable ASPM L1 on the Downstream component only if both components on the Link support it, enabling the Upstream component before the Downstream component and disabling it after the Downstream component"],["Software must enable the Downstream component first and disable the Upstream component first","Only the Downstream component has an ASPM Control field; the Upstream component is always enabled","ASPM L1 may be enabled on one component even if the other reports no L1 support","Software must enable ASPM L1 on the Downstream component only if both components on the Link support it, enabling the Upstream component before the Downstream component and disabling it after the Downstream component"],3,"Upstream component(Root에 더 가까운 쪽)를 먼저 enable하고, disable할 때는 Downstream component를 먼저 disable한다. L1 entry는 ASPM Control field가 제어한다.","The Upstream component (closer to the Root) is enabled first; on disable, the Downstream component is disabled first. When supported, L1 entry is controlled by the ASPM Control field.","§5.4.1.3"],["p7q14","p7_3",2,"P","ASPM L1 진입을 위해 정의된 세 가지 power management Message/DLLP는 각각 어떤 종류인가?","Of the three power-management Messages that support ASPM L1 entry, which are DLLPs and which is a TLP?",["All three are DLLPs","PM_Active_State_Request_L1 is a DLLP, PM_Request_Ack is a DLLP, and PM_Active_State_Nak is a TLP","All three are TLPs in VC0","PM_Active_State_Request_L1 is a TLP, and both Ack and Nak are DLLPs"],["All three are DLLPs","PM_Active_State_Request_L1 is a DLLP, PM_Request_Ack is a DLLP, and PM_Active_State_Nak is a TLP","All three are TLPs in VC0","PM_Active_State_Request_L1 is a TLP, and both Ack and Nak are DLLPs"],1,"표준이 세 이름을 이렇게 분류한다. L1 ASPM entry가 enable된 component의 Upstream Port가 L1 진입을 시작할 수 있다. 언제 시작할지는 implementer policy이다.","The spec lists PM_Active_State_Request_L1 (DLLP), PM_Request_Ack (DLLP), and PM_Active_State_Nak (TLP). An Upstream Port on a component enabled for L1 ASPM entry may initiate entry into L1. When to initiate is left to the implementer.","§5.4.1.3.1"],["p7q15","p7_3",3,"P","Non-ARI Multi-Function Device에서 각 Function의 ASPM Control 값이 다를 때, 전체 component 정책은?","For a non-ARI Multi-Function Device whose Functions have different ASPM Control values, what policy applies to the component?",["The Function with the numerically largest Function Number alone determines ASPM","ASPM is enabled for both L0s and L1 as soon as any Function Sets 11b, ignoring the others","Functions in a non-D0 state are ignored. If any D0 Function has ASPM disabled (00b), or if one D0 Function is L0s-only (01b) and another is L1-only (10b), ASPM is disabled for the entire component. Otherwise the most active common denominator among D0 Functions is used.","Software is forbidden from programming different ASPM Control values; the hardware treats that as a Malformed TLP"],["The Function with the numerically largest Function Number alone determines ASPM","ASPM is enabled for both L0s and L1 as soon as any Function Sets 11b, ignoring the others","Functions in a non-D0 state are ignored. If any D0 Function has ASPM disabled (00b), or if one D0 Function is L0s-only (01b) and another is L1-only (10b), ASPM is disabled for the entire component. Otherwise the most active common denominator among D0 Functions is used.","Software is forbidden from programming different ASPM Control values; the hardware treats that as a Malformed TLP"],2,"나머지 규칙: D0 Function 중 하나라도 L0s-only(01b)이면 (위 충돌/disable 조건이 아닐 때) L0s only, 하나라도 L1-only(10b)이면 L1 only, 그렇지 않으면 L0s와 L1 모두 enable. ARI Device는 Function 0의 ASPM Control만 사용하며 Function 0의 D-state와 무관하다.","Otherwise: if at least one D0 Function is L0s-only, ASPM is enabled for L0s only; else if at least one D0 Function is L1-only, ASPM is enabled for L1 only; else ASPM is enabled for both. For ARI Devices, ASPM Control is determined solely by Function 0, regardless of Function 0’s D-state.","§5.4.1"],["p7q16","p7_4",1,"P","ASPM L0p를 사용할 수 있는 조건과, software-visible exit latency가 보고되는 위치는?","Under what conditions can ASPM L0p be used, and where are the software-visible L0p exit latencies reported?",["L0p is supported in Flit Mode only and can be used only when both Link partners support it. Local and Remote L0p Exit Latency are reported in the Data Link Feature Extended Capability.","L0p is required in Non-Flit Mode and is reported in the Slot Capabilities Register","L0p can be used in any Mode once a single Port Sets ASPM Control=01b","L0p exit latency is reported only in the L1 PM Substates Control 2 Register"],["L0p is supported in Flit Mode only and can be used only when both Link partners support it. Local and Remote L0p Exit Latency are reported in the Data Link Feature Extended Capability.","L0p is required in Non-Flit Mode and is reported in the Slot Capabilities Register","L0p can be used in any Mode once a single Port Sets ASPM Control=01b","L0p exit latency is reported only in the L1 PM Substates Control 2 Register"],0,"지원될 때 ASPM L0p는 Link Control의 Hardware Autonomous Width Disable bit와 Device Control 3 Register의 여러 field로 제어된다. L0p는 짧은 entry latency와 더 긴 exit latency를 제공하며, width 변경 중에도 Link 동작을 유지한다.","When supported, ASPM L0p is controlled by the Hardware Autonomous Width Disable bit in the Link Control Register and by several Device Control 3 Register fields. L0p provides short entry latency and a longer exit latency, and it supports Link operation while a Link width change is in progress.","§5.4.1.2"],["p7q17","p7_4",2,"P","L1 Exit Latency 필드를 L0p에 적용할 때 그 값이 의미하는 바는?","When the L1 Exit Latency field is used for L0p, what does that value indicate?",["The time required to widen the Link. The Link remains operational during this period, but at lower bandwidth.","The time the Link spends in Electrical Idle with all Lanes off, identical to L1.2.Idle","The time until CLKREQ# may be deasserted","A reserved encoding that software must ignore in Flit Mode"],["The time required to widen the Link. The Link remains operational during this period, but at lower bandwidth.","The time the Link spends in Electrical Idle with all Lanes off, identical to L1.2.Idle","The time until CLKREQ# may be deasserted","A reserved encoding that software must ignore in Flit Mode"],0,"표준은 L1 exit latency가 L0p에도 적용된다고 하면서, L0p에서는 Link를 넓히는 데 필요한 시간이라고 설명한다. 그 기간 동안 Link는 더 낮은 bandwidth로 계속 동작한다.","The spec says the L1 exit latency also applies to L0p, but for L0p it indicates the time required to widen the Link. The Link remains operational during that period, but at lower bandwidth.","§5.4.1"],["p7q18","p7_5",1,"P","L1.0, L1.1, L1.2 substate의 핵심 차이는?","What is the key difference among the L1.0, L1.1, and L1.2 substates?",["L1.1 removes common mode and main power; L1.2 is identical to L0s","L1.0 turns off Vaux; L1.1 and L1.2 are software-only D-states","L1.0 is conventional L1 (Electrical Idle exit detection required). L1.1 maintains Link common mode voltages and uses bidirectional open-drain CLKREQ#; EI exit detection is not required. L1.2 does not require common mode to be maintained and also uses CLKREQ# without required EI exit detection.","All three substates require Electrical Idle exit detection on every Lane and a free-running reference clock"],["L1.1 removes common mode and main power; L1.2 is identical to L0s","L1.0 turns off Vaux; L1.1 and L1.2 are software-only D-states","L1.0 is conventional L1 (Electrical Idle exit detection required). L1.1 maintains Link common mode voltages and uses bidirectional open-drain CLKREQ#; EI exit detection is not required. L1.2 does not require common mode to be maintained and also uses CLKREQ# without required EI exit detection.","All three substates require Electrical Idle exit detection on every Lane and a free-running reference clock"],2,"L1 PM Substates를 지원하는 Port는 L1.0가 아닌 substate에서 reference clock을 요구하면 안 된다. 모든 L1 PM Substate에서의 탈출은 CLKREQ# assertion으로 시작된다.","Ports that support L1 PM Substates must not require a reference clock in L1 PM Substates other than L1.0. Exit from all L1 PM Substates is initiated when CLKREQ# is asserted.","§5.5 / §5.2"],["p7q19","p7_5",2,"P","ASPM L1용 L1.2 substate를 지원하는 Port는 추가로 무엇을 지원해야 하는가?","What additional mechanism must Ports that support the L1.2 substate for ASPM L1 support?",["Beacon only, never WAKE#","Latency Tolerance Reporting (LTR)","L0s in Flit Mode","A mandatory retrimer on the Link"],["Beacon only, never WAKE#","Latency Tolerance Reporting (LTR)","L0s in Flit Mode","A mandatory retrimer on the Link"],1,"표준: ASPM L1용 L1.2를 지원하는 Port는 LTR을 지원해야 한다. ASPM L1.2 진입에는 CLKREQ# deassert와 함께 snooped/non-snooped LTR 값이 LTR_L1.2_THRESHOLD 이상(또는 requirement 없음)이어야 한다.","Ports that support the L1.2 substate for ASPM L1 must support LTR. Entry into ASPM L1.2 also requires that the last snooped and non-snooped LTR values be greater than or equal to LTR_L1.2_THRESHOLD, or that there be no corresponding service-latency requirement.","§5.5 / §5.5.1"],["p7q20","p7_5",2,"P","PCI-PM L1.0에서 PCI-PM L1.2 Enable이 Set된 경우, L1.2로 들어가는 조건은?","When in PCI-PM L1.0 with the PCI-PM L1.2 Enable bit Set, when must the L1.2 substate be entered?",["When CLKREQ# is asserted and LTR is disabled","Automatically 4 μs after entering L0, regardless of CLKREQ#","Only after software writes the Link Activation Control bit","When CLKREQ# is deasserted"],["When CLKREQ# is asserted and LTR is disabled","Automatically 4 μs after entering L0, regardless of CLKREQ#","Only after software writes the Link Activation Control bit","When CLKREQ# is deasserted"],3,"PCI-PM L1.1은 PCI-PM L1.1 Enable이 Set이고 PCI-PM L1.2 Enable이 Clear이며 CLKREQ#가 deassert될 때 들어간다. USP는 Link가 L1.0에 들어가기 전에는 CLKREQ#를 deassert하면 안 된다. 어느 Port든 CLKREQ#를 assert하여 L1.2 진입을 막을 수 있다.","PCI-PM L1.1 is entered when the PCI-PM L1.1 Enable bit is Set, the PCI-PM L1.2 Enable bit is Clear, and CLKREQ# is deasserted. An Upstream Port must not deassert CLKREQ# until the Link has entered L1.0. Either Port may assert CLKREQ# to prevent entry into L1.2.","§5.5.1"],["p7q21","p7_5",3,"P","L1.2의 세 substate 가운데 L1.2.Idle에서 허용되는 동작은?","Which behavior is permitted in L1.2.Idle, one of the three L1.2 substates?",["Both Ports must keep transmitters in L0 and continue sending SKP Ordered Sets","Common mode must be maintained, but CLKREQ# is ignored","Both Ports may power-down any active logic, including circuits required to maintain common mode, and the PHY of both Ports may have their power removed","The Downstream Port must remain in L1.2.Entry until main power is removed"],["Both Ports must keep transmitters in L0 and continue sending SKP Ordered Sets","Common mode must be maintained, but CLKREQ# is ignored","Both Ports may power-down any active logic, including circuits required to maintain common mode, and the PHY of both Ports may have their power removed","The Downstream Port must remain in L1.2.Entry until main power is removed"],2,"L1.2는 Entry·Idle·Exit 세 substate를 가진다. L1.2.Entry에서는 여전히 common mode를 유지하고, Port는 이 상태에서 CLKREQ#를 assert하면 안 되며, CLKREQ#가 assert되면 next state는 L1.0, 아니면 TPOWER_OFF를 기다린 뒤 L1.2.Idle이다.","L1.2 has Entry, Idle, and Exit substates. In L1.2.Entry both Ports continue to maintain common mode and must not assert CLKREQ#; the next state is L1.0 if CLKREQ# is asserted, else L1.2.Idle after TPOWER_OFF. On exit, Link and PHY state must be maintained or restored so the result is indistinguishable from L1.0.","§5.5.3"],["p7q22","p7_5",3,"P","Table 5-11에서 TL1.2와 TPOWER_OFF의 정의로 옳은 것은?","Which statement correctly quotes Table 5-11 parameters TL1.2 and TPOWER_OFF?",["TL1.2 is the time a Port must stay in L1.2 when CLKREQ# must remain inactive, with a minimum of 4 μs. TPOWER_OFF is CLKREQ# deassertion to entry into L1.2.Idle, with a maximum of 2 μs.","TL1.2 has a maximum of 2 ns, and TPOWER_OFF has a minimum of 100 ms","Both parameters are fixed at 10 ms and are not programmable","TL1.2 is programmable from 0 to 255 Symbol Times; TPOWER_OFF is reserved"],["TL1.2 is the time a Port must stay in L1.2 when CLKREQ# must remain inactive, with a minimum of 4 μs. TPOWER_OFF is CLKREQ# deassertion to entry into L1.2.Idle, with a maximum of 2 μs.","TL1.2 has a maximum of 2 ns, and TPOWER_OFF has a minimum of 100 ms","Both parameters are fixed at 10 ms and are not programmable","TL1.2 is programmable from 0 to 255 Symbol Times; TPOWER_OFF is reserved"],0,"같은 표에서 TCOMMONMODE는 0–255 μs로 programmable, TPOWER_ON은 L1 PM Substates Control 2에서 0–3100 μs, TL1O_REFCLK_OFF는 0–100 ns이다. 표에 min만 있거나 max만 있는 항목을 서로 바꿔 단정하지 않도록 주의한다.","In the same table, TCOMMONMODE is programmable from 0 to 255 μs, TPOWER_ON is set in L1 PM Substates Control 2 in the range 0 to 3100 μs, and TL1O_REFCLK_OFF is 0 to 100 ns. Do not treat a min-only or max-only parameter as if both bounds were specified.","§5.5.5 / Table 5-11"],["p7q23","p7_6",1,"P","PM_PME Message의 종류, Traffic Class, 라우팅 방향은?","What kind of TLP is a PM_PME Message, which Traffic Class must it use, and in which direction is it routed?",["It is a DLLP that uses any TC and is broadcast Downstream","It is a non-posted Request that must use TC7 and is routed to the Endpoint","It is a Message with data payload that must use VC1","It is a posted Transaction Layer Packet that must use TC0 and is always routed toward the Root Complex"],["It is a DLLP that uses any TC and is broadcast Downstream","It is a non-posted Request that must use TC7 and is routed to the Endpoint","It is a Message with data payload that must use VC1","It is a posted Transaction Layer Packet that must use TC0 and is always routed toward the Root Complex"],3,"다른 Power Management system Message와 마찬가지로 general purpose Traffic Class TC0를 써야 한다. Upstream Link로 PM_PME를 보내려면 device는 Link를 L0로 전이해야 하고, 달리 명시되지 않으면 전송 후에도 L0를 유지한다.","Like all other Power Management system Messages, PM_PME must use TC0. To send a PM_PME on its Upstream Link, a device must transition the Link to L0 if it was not already in L0, and unless otherwise noted it keeps the Link in L0 after transmission.","§5.3.3.3"],["p7q24","p7_6",2,"P","PME Service Timeout mechanism의 만료 시간과, 만료 시 PME를 요청한 agent의 동작은?","What is the PME Service Timeout interval, and what does a PME-requesting agent do when it expires?",["The timeout is a fixed 10 ms with no tolerance, after which PME_Status is cleared automatically","If after 100 ms (+50% / −5%) the agent’s PME_Status bit has not been cleared, the timeout expires and the agent re-sends the PM_PME Message (reactivating the Link first if it is in a non-communicating state)","The timeout is 1.0 s, after which the agent must enter D3Cold","There is no architected retry; a lost PM_PME is permanently discarded"],["The timeout is a fixed 10 ms with no tolerance, after which PME_Status is cleared automatically","If after 100 ms (+50% / −5%) the agent’s PME_Status bit has not been cleared, the timeout expires and the agent re-sends the PM_PME Message (reactivating the Link first if it is in a non-communicating state)","The timeout is 1.0 s, after which the agent must enter D3Cold","There is no architected retry; a lost PM_PME is permanently discarded"],1,"이 timeout은 Root Complex의 유한 PM_PME 버퍼로 인한 backpressure 상황에서도 PM_PME가 영구히 사라지지 않게 하려는 장치이다. 공차는 표준에 +50%/−5%로 명시되어 있으므로 ‘정확히 100.000 ms’로 단정하지 않는다.","The timeout exists so that PM_PME Messages are not lost permanently, including under Root Complex backpressure. The specification states the interval as 100 ms with a +50%/−5% tolerance, so the correct value is not a single exact instant.","§5.3.3.3.1"],["p7q25","p7_6",2,"P","PME_Turn_Off Message를 받은 device가 해야 할 일과, 그 다음 L2/L3 Ready 진입 방법은?","What must a device do when it receives a PME_Turn_Off Message, and how does it then enter L2/L3 Ready?",["It must silently drop PME_Turn_Off and stay in L0 indefinitely","It must block transmission of PM_PME Messages, transmit a PME_TO_Ack Message Upstream, and then (in any device D state after that handshake) request a Link transition to L2/L3 Ready using a PM_Enter_L23 DLLP. A PM_PME may be sent after the Link returns to L0 through LDn.","It must immediately remove main power without sending any Ack","It must convert PME_Turn_Off into a PM_PME and send it Downstream"],["It must silently drop PME_Turn_Off and stay in L0 indefinitely","It must block transmission of PM_PME Messages, transmit a PME_TO_Ack Message Upstream, and then (in any device D state after that handshake) request a Link transition to L2/L3 Ready using a PM_Enter_L23 DLLP. A PM_PME may be sent after the Link returns to L0 through LDn.","It must immediately remove main power without sending any Ack","It must convert PME_Turn_Off into a PM_PME and send it Downstream"],1,"D0, D1, D2, D3Hot의 device는 PME_Turn_Off를 받으면 PME_TO_Ack을 보내야 한다. 비통신 상태로 들어가기 전에는 PME_Turn_Off가 Downstream으로 broadcast되어야 한다. Switch는 모든 DSP에서 PME_TO_Ack을 받은 뒤에야 Upstream으로 PME_TO_Ack을 보낸다.","Devices in D0, D1, D2, and D3Hot must respond to PME_Turn_Off by transmitting PME_TO_Ack. A PME_Turn_Off must be broadcast Downstream before a Link or hierarchy portion is transferred into a non-communicating state. A Switch must wait to receive PME_TO_Ack on all of its Downstream Ports before sending PME_TO_Ack Upstream.","§5.3.3.4 / §5.3.2"],["p7q26","p7_6",2,"P","Switch가 Downstream Port에서 받은 PM_PME를 처리하는 방법과, Bridge Function의 PME_Status bit가 Set되는 경우는?","How must a Switch handle a PM_PME received on a Downstream Port, and when is a PCI-PCI Bridge Function’s PME_Status bit Set?",["The Switch must drop all PM_PME Messages at the Downstream Port and Set PME_Status on every Port they pass","The Switch converts PM_PME into a WAKE# signal and never forwards a TLP","PME_Status is Set on every Bridge that forwards a PM_PME, even if the Bridge itself is not the source","The Switch must route a PM_PME received on any Downstream Port to its Upstream Port. The Bridge Function’s PME_Status bit is Set only when the Bridge Function itself is generating a PME, not when it is merely propagating a PME Message."],["The Switch must drop all PM_PME Messages at the Downstream Port and Set PME_Status on every Port they pass","The Switch converts PM_PME into a WAKE# signal and never forwards a TLP","PME_Status is Set on every Bridge that forwards a PM_PME, even if the Bridge itself is not the source","The Switch must route a PM_PME received on any Downstream Port to its Upstream Port. The Bridge Function’s PME_Status bit is Set only when the Bridge Function itself is generating a PME, not when it is merely propagating a PME Message."],3,"PME capable Function은 PMCSR에 PME_Status와 그 동작을 구현해야 하고, Link wakeup을 시작하거나 PM_PME를 발행할 때 PME_Status를 Set해야 한다. Software가 해당 Function의 PME_Status에 write-1-to-clear를 하면 PME assertion이 인정된다.","PME-capable Functions must implement PME_Status and must Set it when they initiate Link wakeup or issue a PM_PME Message. A Function’s PME assertion is acknowledged when software writes 1 to clear that Function’s PME_Status bit.","§5.3.3.4 / §7.5.2"],["p7q27","p7_6",2,"P","PMC PME_Support 필드(bits 31:27)의 각 비트가 나타내는 PME 가능 D-state는?","Which D-state does each bit of the PMC PME_Support field (bits 31:27) indicate PME can be generated from?",["Bit 27 = D0, bit 28 = D1, bit 29 = D2, bit 30 = D3Hot, bit 31 = D3Cold","Bit 27 = D3Cold, bit 31 = D0, and bits 28–30 are Reserved","All five bits must be 0 on every PCI Express Function","Bit 31 = L2, bit 30 = L1, and the others map to ASPM states"],["Bit 27 = D0, bit 28 = D1, bit 29 = D2, bit 30 = D3Hot, bit 31 = D3Cold","Bit 27 = D3Cold, bit 31 = D0, and bits 28–30 are Reserved","All five bits must be 0 on every PCI Express Function","Bit 31 = L2, bit 30 = L1, and the others map to ASPM states"],0,"Bit 31(D3Cold에서 PME)은 특수한 경우로 auxiliary power가 필요하다. D3Cold PME를 지원하면 PME Context는 Reset의 영향을 받지 않고, 지원하지 않으면 Reset assertion 때 초기화된다. Root Complex/Switch Port Bridge는 지원하는 각 D-state 비트를 Set하여 PME Message를 forward할 수 있음을 표시해야 한다.","Bit 31 (PME from D3Cold) is a special case requiring some form of auxiliary power. If PME from D3Cold is supported, PME Context is not affected by Reset; otherwise it is initialized on Reset. Bridge structures representing Root Complex/Switch Ports must Set each bit for a supported D-state to indicate they will forward PME Messages.","§7.5.2.1 / §7.5.2.2"],["p7q28","p7_7",1,"P","Latency Tolerance Reporting(LTR) mechanism의 목적과, Link power management에 대한 직접 효과는?","What is the purpose of the Latency Tolerance Reporting (LTR) mechanism, and does it directly affect Link power management?",["It is a mandatory Link-PM protocol that forces the Link into L1.2 whenever LTR is enabled","It replaces ASPM Control and must be implemented by every Function","It lets Endpoints report service latency requirements for Memory Reads and Writes to the Root Complex so platform resource PM policy can consider those requirements. It does not directly affect Link power management or Switch internal power management, though indirect effects are possible.","It reports Configuration-Request latency only and has no relationship to Memory traffic"],["It is a mandatory Link-PM protocol that forces the Link into L1.2 whenever LTR is enabled","It replaces ASPM Control and must be implemented by every Function","It lets Endpoints report service latency requirements for Memory Reads and Writes to the Root Complex so platform resource PM policy can consider those requirements. It does not directly affect Link power management or Switch internal power management, though indirect effects are possible.","It reports Configuration-Request latency only and has no relationship to Memory traffic"],2,"Root Complex는 요청된 service latency를 반드시 지킬 필요는 없지만, LTR이 가리키는 latency를 넘지 않는 worst-case service latency를 제공할 것이 strongly encouraged이다. LTR 지원은 optional이다.","The Root Complex is not required to honor the requested service latencies, but is strongly encouraged to provide a worst-case service latency that does not exceed the latencies indicated by LTR. Support for LTR is optional.","§6.18"],["p7q29","p7_7",2,"P","LTR Message 형성 규칙 중 Traffic Class와 payload에 대한 요구는? 규칙을 어기면?","What are the Traffic Class and payload rules for forming an LTR Message, and what happens if the TC rule is violated?",["The LTR Message must include a 16-DWORD payload and may use any TC","The LTR Message must use TC7 and is a Completion rather than a Message","The Length field must be 1, and a TC other than TC0 is treated as an Advisory Non-Fatal error only","The LTR Message has no data payload (TLP Type is Msg), must use TC0, and a Receiver that implements LTR support must handle a violation as a Malformed TLP"],["The LTR Message must include a 16-DWORD payload and may use any TC","The LTR Message must use TC7 and is a Completion rather than a Message","The Length field must be 1, and a TC other than TC0 is treated as an Advisory Non-Fatal error only","The LTR Message has no data payload (TLP Type is Msg), must use TC0, and a Receiver that implements LTR support must handle a violation as a Malformed TLP"],3,"Message Code는 0001 0000b, Routing은 100b이다. Length field는 Reserved이다. 이 에러는 Receiving Port와 연관된 reported error이다.","The Message Code is 0001 0000b and the routing field is 100b. The Length field is Reserved. The Malformed TLP is a reported error associated with the Receiving Port.","§2.2.8.8"],["p7q30","p7_7",2,"P","hierarchy에서 LTR을 enable할 때 software가 지켜야 할 조건과 순서는?","When enabling LTR in a hierarchy, what conditions and sequencing must software follow?",["Software must enable the most Downstream Endpoint first, then Switches, then the Root Port","Software must not enable LTR in an Endpoint unless the Root Complex and all intermediate Switches indicate support for LTR. When enabling LTR in a hierarchy, devices closest to the Root Port must be enabled first. Not all Endpoints need to support LTR.","LTR may be enabled in an Endpoint even if an intermediate Switch does not support LTR; the Switch will silently drop the Messages","All Endpoints in the hierarchy must support LTR before any one Endpoint may be enabled"],["Software must enable the most Downstream Endpoint first, then Switches, then the Root Port","Software must not enable LTR in an Endpoint unless the Root Complex and all intermediate Switches indicate support for LTR. When enabling LTR in a hierarchy, devices closest to the Root Port must be enabled first. Not all Endpoints need to support LTR.","LTR may be enabled in an Endpoint even if an intermediate Switch does not support LTR; the Switch will silently drop the Messages","All Endpoints in the hierarchy must support LTR before any one Endpoint may be enabled"],1,"LTR을 지원하지 않거나 enable되지 않은 Downstream Port가 LTR Message를 받으면 그 Message는 Unsupported Request로 처리되어야 한다.","If an LTR Message is received at a Downstream Port that does not support LTR, or if LTR is not enabled, the Message must be treated as an Unsupported Request.","§6.18"],["p7q31","p7_7",2,"P","PMCSR write로 non-D0 state로 지시받을 때, 직전에 보낸 LTR Message에 Requirement bit가 Set되어 있었다면 device는 무엇을 해야 하는가?","If a device is directed to a non-D0 state by a PMCSR write, and its most recently transmitted LTR Message had a Requirement bit Set, what must it do?",["It must keep the previous LTR values unchanged so the platform continues to use them in D3","It must send an LTR Message with both Requirement bits Set and LatencyValue all 1’s","It must send a new LTR Message with both Requirement bits clear before transitioning to the non-D0 state","It must wait for the Root Complex to send a PME_Turn_Off before any LTR update"],["It must keep the previous LTR values unchanged so the platform continues to use them in D3","It must send an LTR Message with both Requirement bits Set and LatencyValue all 1’s","It must send a new LTR Message with both Requirement bits clear before transitioning to the non-D0 state","It must wait for the Root Complex to send a PME_Turn_Off before any LTR update"],2,"이후 다시 D0로 지시되면 새 LTR Message를 보내는 것이 recommended이다. LTR Mechanism Enable이 Configuration Write나 (MUST@FLIT) FLR로 Clear될 때도, 이전에 Requirement가 Set이었으면 Requirement를 clear한 LTR을 보내야 한다. Requirement bit가 Clear이면 LatencyValue/Scale은 무시된다. Scale 110b–111b는 Not Permitted이다.","If later directed back to D0, it is recommended that the device send a new LTR Message. If LTR Mechanism Enable is cleared by a Configuration Write, or MUST@FLIT by FLR, and a prior Message had any Requirement bit Set, the device must send a new LTR with Requirement bits clear. If a Requirement bit is Clear, LatencyValue and LatencyScale are ignored. Scale encodings 110b–111b are Not Permitted.","§6.18"],["p7q32","p7_8",1,"P","Link Capabilities Register의 Clock Power Management bit(bit 18)가 Upstream Port에서 1b이면 무엇을 나타내는가? Downstream Port에서는?","For an Upstream Port, what does a 1b in the Clock Power Management bit (bit 18) of the Link Capabilities Register indicate? What about a Downstream Port?",["The component tolerates removal of reference clock(s) via CLKREQ# when the Link is in L1 and L2/L3 Ready. For Downstream Ports this bit must be hardwired to 0b.","The Port requires the reference clock to remain running in L1 and L2/L3 Ready, and Downstream Ports must hardwire the bit to 1b","The bit enables L0s and must be Set on every Downstream Port","The bit is RW and software Sets it to force Beacon signaling"],["The component tolerates removal of reference clock(s) via CLKREQ# when the Link is in L1 and L2/L3 Ready. For Downstream Ports this bit must be hardwired to 0b.","The Port requires the reference clock to remain running in L1 and L2/L3 Ready, and Downstream Ports must hardwire the bit to 1b","The bit enables L0s and must be Set on every Downstream Port","The bit is RW and software Sets it to force Beacon signaling"],0,"이 Capability는 CLKREQ#를 지원하는 form factor에만 해당한다. Non-ARI MFD에서는 각 Function이 독립적으로 표시하며, 모든 Function이 1b일 때만 reference clock 제거가 허용된다. ARI Device는 모든 Function이 같은 값을 표시해야 한다. L1 PM Substates의 CLKREQ# semantics는 Clock Power Management과 독립적으로 관리된다.","This capability applies only in form factors that support CLKREQ#. For a non-ARI Multi-Function Device, software may permit reference-clock removal only if all Functions indicate 1b. For ARI Devices, all Functions must indicate the same value. L1 PM Substates define other CLKREQ# semantics, managed independently of Clock Power Management.","§7.5.3.6"],["p7q33","p7_8",2,"P","Link Control Register의 Enable Clock Power Management bit(bit 8)가 0b일 때와 1b일 때 Upstream Port의 CLKREQ# 동작은?","How does an Upstream Port operate the CLKREQ# signal when the Enable Clock Power Management bit (bit 8) in the Link Control Register is 0b versus 1b?",["0b: clock power management is disabled and the device must hold CLKREQ# low. 1b: the device is permitted to use CLKREQ# to power manage the Link clock according to the form-factor protocol. The default is 0b unless a form factor specifies otherwise.","0b: the device must deassert CLKREQ# at all times. 1b: CLKREQ# is hardwired high","The bit is ignored on Upstream Ports and used only on Downstream Ports","1b forbids CLKREQ# use; 0b requires the device to toggle CLKREQ# every 4 μs"],["0b: clock power management is disabled and the device must hold CLKREQ# low. 1b: the device is permitted to use CLKREQ# to power manage the Link clock according to the form-factor protocol. The default is 0b unless a form factor specifies otherwise.","0b: the device must deassert CLKREQ# at all times. 1b: CLKREQ# is hardwired high","The bit is ignored on Upstream Ports and used only on Downstream Ports","1b forbids CLKREQ# use; 0b requires the device to toggle CLKREQ# every 4 μs"],0,"이 bit는 Upstream Port와 CLKREQ# form factor에만 적용된다. Downstream Port와 Clock Power Management를 지원하지 않는 component는 0b로 hardwired해야 한다. ARI Device에서는 Function 0의 설정만 사용된다. L1 PM Substates를 통한 CLKREQ# 제어는 이 bit 값에 종속되지 않는다.","The bit applies only to Upstream Ports and form factors that support CLKREQ#. Downstream Ports and components that do not support Clock Power Management must hardwire it to 0b. For ARI Devices, enablement is solely by Function 0. CLKREQ# control via L1 PM Substates is not dependent on this bit.","§7.5.3.7"],["p7q34","p7_8",2,"P","L1 PM Substates가 enable되어 있을 때, Upstream Port가 CLKREQ#를 deassert하는 것이 허용되는 Link state는?","When the L1 PM Substates mechanism is enabled, in which Link states is an Upstream Port permitted to deassert CLKREQ#?",["L0 and Recovery only; CLKREQ# must stay deasserted in L1","Detect and Polling only","PCI-PM L1, ASPM L1, or the L2/L3 Ready pseudo-state; CLKREQ# must be asserted by the Upstream Port when the Link is in any other state","Any state including L0, as long as a TLP is in flight"],["L0 and Recovery only; CLKREQ# must stay deasserted in L1","Detect and Polling only","PCI-PM L1, ASPM L1, or the L2/L3 Ready pseudo-state; CLKREQ# must be asserted by the Upstream Port when the Link is in any other state","Any state including L0, as long as a TLP is in flight"],2,"이 요구를 만족할 수 없으면 L1 PM Substates를 enable하면 안 된다. CLKREQ#는 Upstream과 Downstream Port 모두 bidirectional open-drain로 지원되어야 하고, 각 Port의 신호가 서로 연결되어야 한다.","If these requirements cannot be satisfied, L1 PM Substates must not be enabled. CLKREQ# must be supported as a bidirectional open-drain signal by both Ports, each Port must have a unique instance, and the two CLKREQ# signals must be connected.","§5.5"],["p7q35","p7_2",3,"P","PCI-PM으로 L1에 들어가기 위해, Single-Function Device의 Upstream Port와 non-ARI Multi-Function Device의 Upstream Port는 각각 어떤 조건을 보는가?","For PCI-PM entry into L1, what condition does the Upstream Port of a Single-Function Device use, versus the Upstream Port of a non-ARI Multi-Function Device?",["Both types initiate L1 as soon as Function 0 leaves D0, ignoring other Functions","A Single-Function Device initiates L1 based solely on its Function being programmed to D1, D2, or D3Hot. A non-ARI Multi-Function Device must not initiate L1 until all of its Functions have been programmed to a non-D0 D-state.","A Multi-Function Device initiates L1 when any one Function enters D1, even if others remain in D0active","Only the Root Port may initiate PCI-PM L1; Upstream Ports of Endpoints never request L1"],["Both types initiate L1 as soon as Function 0 leaves D0, ignoring other Functions","A Single-Function Device initiates L1 based solely on its Function being programmed to D1, D2, or D3Hot. A non-ARI Multi-Function Device must not initiate L1 until all of its Functions have been programmed to a non-D0 D-state.","A Multi-Function Device initiates L1 when any one Function enters D1, even if others remain in D0active","Only the Root Port may initiate PCI-PM L1; Upstream Ports of Endpoints never request L1"],1,"ARI Device는 적어도 한 Function이 non-D0이고, 나머지 Function은 non-D0이거나 D0uninitialized일 때까지 PCI-PM L1을 시작하면 안 된다. SR-IOV에서는 Link Power State가 PF 설정만으로 제어되며 VF D-state는 영향을 주지 않는다.","An ARI Device must not initiate PCI-PM L1 until at least one Function is in a non-D0 state and all Functions are either in a non-D0 state or D0uninitialized. With SR-IOV, the Link Power State is controlled solely by the PFs; VF D-states do not affect it.","§5.3.2"],["p7q36","p7_5",2,"P","Link Activation mechanism의 목적과, Link Activation Control bit가 Set일 때 Port의 CLKREQ# 동작은?","What is Link Activation for, and what must a Port do with CLKREQ# when the Link Activation Control bit is Set?",["It permanently disables ASPM L0s and must be Set on every Upstream Port","It forces the Link into L1.2 even if CLKREQ# stays deasserted","It is mandatory in all Root Ports and replaces PME_Turn_Off","It is an optional mechanism to temporarily disable L1 Substates (for example to avoid stalls such as a D3Hot→D0 Configuration Write). When the Control bit is Set, a Port that is about to enter L1 must assert CLKREQ# and keep it asserted while in L1."],["It permanently disables ASPM L0s and must be Set on every Upstream Port","It forces the Link into L1.2 even if CLKREQ# stays deasserted","It is mandatory in all Root Ports and replaces PME_Turn_Off","It is an optional mechanism to temporarily disable L1 Substates (for example to avoid stalls such as a D3Hot→D0 Configuration Write). When the Control bit is Set, a Port that is about to enter L1 must assert CLKREQ# and keep it asserted while in L1."],3,"Link Activation은 Downstream Port가 지원할 수 있으며, L1 PM Substates Capabilities Register의 Link Activation Supported bit로 표시된다. Control bit는 PCI-PM 또는 ASPM의 L1.1/L1.2 Enable 중 하나가 Set된 경우에만 Port 동작에 영향을 준다.","A Downstream Port may support Link Activation, indicated by Link Activation Supported in the L1 PM Substates Capabilities Register. The Control bit must have no effect unless one or more of the PCI-PM/ASPM L1.1/L1.2 Enable bits are Set.","§5.5.6"],["c7q01","c7_1",1,"X","CXL에서 여러 프로토콜의 전원 상태를 모아 Physical Layer 전원 관리를 이끄는 블록은?","In CXL, which block consolidates the power states of the protocols and drives Physical Layer power management?",["ARB/MUX","CXL.mem Link Layer","Root Complex의 IOMMU","Retimer"],["The ARB/MUX","The CXL.mem Link Layer","The Root Complex IOMMU","A retimer"],0,"ARB/MUX가 양쪽 프로토콜의 PM 상태를 조율하고 하나로 합쳐 PHY 전원 상태를 결정한다.","The ARB/MUX coordinates PM states across protocols on both sides, merges them, and drives the PHY power state.","§10.1"],["c7q02","c7_1",1,"X","CXL Physical Layer가 지원하지 않는 링크 전원 상태는?","Which link power state does the CXL Physical Layer NOT support?",["L0 (정상 동작)","L0s","L1","L2"],["L0 (normal operation)","L0s","L1","L2"],1,"CXL PHY는 PCIe Base Spec의 L1과 L2를 지원하지만 L0s는 지원하지 않는다. CXL.io PM에서도 L0s는 지원되지 않는다.","The CXL PHY supports L1 and L2 as in the PCIe Base Spec, but not L0s. CXL.io PM does not support L0s either.","§10.2.5"],["c7q03","c7_1",2,"X","CXL Physical Layer의 L1/L2 진입·탈출 조건이 PCIe와 다른 핵심은?","What is the key difference from PCIe in how the CXL Physical Layer enters and exits L1/L2?",["CXL은 L2를 소프트웨어만 지시한다","CXL은 L1 탈출이 항상 Hot Reset을 거친다","진입·탈출 조건은 PCIe와 같지만, 진입·탈출을 CXL ARB/MUX가 지시한다","CXL은 L1 진입에 ACPI 명령이 필요하다"],["Only software can direct L2 in CXL","L1 exit in CXL always passes through Hot Reset","Conditions follow PCIe, but the CXL ARB/MUX directs entry and exit","CXL needs an ACPI command to enter L1"],2,"상태 정의와 조건은 PCIe Base Spec을 따른다. 다만 CXL에서는 여러 프로토콜 사정을 아는 ARB/MUX가 PHY의 진입과 탈출을 이끈다.","States and conditions follow PCIe, but in CXL the ARB/MUX, which sees all protocols, directs PHY entry and exit.","§10.2.5"],["c7q04","c7_2",1,"C","CXL 전원 관리 메시지(PMREQ 등)는 어떤 PCIe 메시지 형식으로 보내는가?","What PCIe message form carries CXL power management messages such as PMREQ?",["PCIe PM_PME 메시지","Configuration Write","DLLP","Vendor Defined Type 0 메시지 (4-DWORD data payload)"],["PCIe PM_PME messages","Configuration Writes","DLLPs","Vendor Defined Type 0 messages with a 4-DWORD data payload"],3,"CXL PM 메시지는 PCIe Vendor Defined Type 0 메시지(VDM)에 Vendor ID 1E98h를 넣어 보낸다. VDM 자체는 PCIe에 있는 공통 메커니즘이다.","CXL PM messages are PCIe Vendor Defined Type 0 messages (VDMs) with Vendor ID 1E98h. The VDM mechanism itself is shared with PCIe.","§3.1.2"],["c7q05","c7_2",2,"X","CXL PM VDM의 PM Logical Opcode 06h가 뜻하는 것은?","What does PM Logical Opcode 06h mean in a CXL PM VDM?",["Global Persistent Flush (GPF)","AGENT_INFO","RESETPREP","CREDIT_RTN"],["Global Persistent Flush (GPF)","AGENT_INFO","RESETPREP","CREDIT_RTN"],0,"00h AGENT_INFO, 02h RESETPREP, 04h PMREQ(PMRSP·PMGO 포함), 06h GPF, FEh CREDIT_RTN이다.","00h AGENT_INFO, 02h RESETPREP, 04h PMREQ (with PMRSP/PMGO), 06h GPF, FEh CREDIT_RTN.","§3.1.2"],["c7q06","c7_2",2,"C","CXL 장치가 PMREQ 메시지로 Host에 알리는 latency tolerance 값의 형식은?","In what format does a CXL device report latency tolerance in a PMREQ message?",["CXL 전용 8-bit 코드","PCIe LTR 형식 (Snoop / No-Snoop Latency)","ACPI _CST 형식","MSI 데이터 형식"],["A CXL-only 8-bit code","The PCIe LTR format (Snoop / No-Snoop Latency)","The ACPI _CST format","The MSI data format"],1,"PMREQ payload는 PCIe LTR 메시지의 Snoop·No-Snoop Latency 필드 형식을 그대로 쓴다. LTR 개념은 PCIe와 공통이다.","The PMREQ payload reuses the Snoop and No-Snoop Latency fields of the PCIe LTR message. LTR is shared with PCIe.","§3.1.2"],["c7q07","c7_2",2,"X","CXL 구성 요소가 poison(EP=1)이 설정된 PM VDM을 받으면?","What does a CXL component do when it receives a PM VDM with poison (EP=1)?",["fatal error를 보고하고 Link를 Down시킨다","송신자에게 재전송을 요청한다","메시지를 버리고 advisory non-fatal error로 처리한다","메시지를 그대로 처리한다"],["Report a fatal error and bring the link down","Ask the sender to retransmit","Drop it and treat the event as an advisory non-fatal error","Process it normally"],2,"수신자는 poison된 PM VDM을 버린다. 정상 동작을 계속할 수 있으므로 advisory non-fatal error로 다룬다. payload를 이해하지 못하면 조용히 버리고 uncorrectable error를 알리지 않는다.","The receiver drops a poisoned PM VDM and, since it can keep running, treats it as advisory non-fatal. An unknown payload is silently dropped with no uncorrectable error.","§3.1.2"],["c7q08","c7_2",2,"X","coherent cache나 coherent 메모리를 가진 CXL 장치가 package idle 상태 전환을 조율하는 방법은?","How must a CXL device with a coherent cache or coherent memory coordinate package-idle transitions?",["PCIe Allow-L1 신호만 쓴다","ALMP만 쓴다","조율 없이 각자 진입한다","ResetPrep, PMReq, PMRsp, PMGo를 쓰는 CXL 최적화 VDM 프로토콜"],["Only the PCIe Allow-L1 signal","Only ALMPs","Each side enters without coordination","The CXL-optimized VDM protocol with ResetPrep, PMReq, PMRsp, and PMGo"],3,"coherence를 공유하는 장치는 memory coherency 손실을 막기 위해 VDM 기반 프로토콜로 Host와 상태 전환을 맞춰야 한다.","Devices that share coherence must align transitions with the host through the VDM-based protocol to avoid losing memory coherency.","§10.2.2"],["c7q09","c7_3",1,"X","CXL PM 진입은 몇 단계(phase)로 나뉘는가?","Into how many phases is CXL PM entry divided?",["3단계","1단계","2단계","5단계"],["Three","One","Two","Five"],0,"Phase 1은 프로토콜별 협상, Phase 2는 ALMP로 ARB/MUX 인터페이스를 PM 상태로, Phase 3는 조건부로 Tx lane을 electrical idle로 보낸다.","Phase 1 is protocol negotiation, Phase 2 moves ARB/MUX interfaces to PM with ALMPs, and conditional Phase 3 puts Tx lanes in electrical idle.","§10.3"],["c7q10","c7_3",1,"X","PM 진입 Phase 2를 항상 시작하는 쪽은?","Which side always initiates PM entry Phase 2?",["Switch의 FM","Downstream Component의 ARB/MUX","Upstream Component의 ARB/MUX","Host 소프트웨어"],["The switch's FM","The ARB/MUX of the Downstream Component","The ARB/MUX of the Upstream Component","Host software"],1,"Downstream Component의 ARB/MUX가 ALMP request를 보내고, Upstream Component는 자기 상위 계층이 지시했을 때만 ALMP response로 수락한다.","The Downstream Component ARB/MUX sends the ALMP request; the Upstream Component accepts with an ALMP response only when its upper layers direct it.","§10.3.2"],["c7q11","c7_3",3,"X","Phase 2에서 Downstream Component가 응답을 못 받았을 때 PM 진입을 다시 시도하기 전 기다려야 하는 최소 시간은?","In Phase 2, how long must the Downstream Component wait for a response before retrying PM entry?",["최소 10 ms","기다릴 필요 없이 바로 재시도","최소 1 ms (recovery 시간 제외)","최소 1 us"],["At least 10 ms","No wait; retry at once","At least 1 ms (excluding time in recovery)","At least 1 us"],2,"Downstream 쪽은 최소 1ms 기다린 뒤 재시도한다. 그 전에 Active Request ALMP를 보내 진입을 취소할 수는 있다. L2 진입은 이 규칙의 예외다.","The downstream side waits at least 1 ms before retrying, and may abort earlier with an Active Request ALMP. L2 entry is the exception.","§10.3.2"],["c7q12","c7_3",1,"X","PM 진입 Phase 3(electrical idle)가 실행되는 조건은?","When is PM entry Phase 3 (electrical idle) executed?",["CXL.io 하나만 PM 상태에 들어가면","Host가 MSI를 보낼 때","항상 Phase 1 직후","ARB/MUX의 모든 프로토콜 인터페이스가 같은 가상 PM 상태에 들어갔을 때만"],["As soon as CXL.io alone enters PM","When the host sends an MSI","Always right after Phase 1","Only when all ARB/MUX protocol interfaces have entered the same virtual PM state"],3,"Phase 3는 조건부다. 모든 프로토콜이 같은 PM 상태여야 PHY가 Tx lane을 electrical idle로 보낸다. 시작은 항상 Downstream Component가 한다.","Phase 3 is conditional: all protocols must share the same PM state before the PHY sends Tx lanes to electrical idle. The Downstream Component always starts it.","§10.3.3"],["c7q13","c7_3",3,"X","ASPM L1에서 나올 때 Phase 2와 Phase 3의 탈출 순서는?","When exiting ASPM L1, in what order do Phase 3 and Phase 2 exit?",["Phase 3가 먼저 나오고(PCIe L1 탈출과 같음), 그 뒤 프로토콜별로 Phase 2를 ALMP로 나온다","Phase 2가 먼저 나오고 Phase 3가 나중이다","두 단계가 동시에 나온다","Phase 2 탈출은 없다"],["Phase 3 exits first (same as PCIe L1 exit), then each protocol exits Phase 2 using ALMPs","Phase 2 first, then Phase 3","Both exit at once","There is no Phase 2 exit"],0,"탈출은 계층적이다. PHY가 PCIe 방식으로 L0에 돌아온 뒤, 각 프로토콜이 Active 요청·상태 ALMP를 주고받아야 프로토콜 전송이 허용된다.","Exit is hierarchical: the PHY returns to L0 the PCIe way, then each protocol trades Active request/status ALMPs before traffic is allowed.","§10.3.4"],["c7q14","c7_4",1,"C","모든 CXL Function이 구현해야 하는 PCI Power Management 관련 요구는?","What PCI Power Management requirement applies to every CXL function?",["ACPI _PSx만 쓴다","PCI PM Capability를 구현하고 D0와 D3 device state를 지원한다","PCI PM Capability를 구현하면 안 된다","D1과 D2만 지원한다"],["Use only ACPI _PSx","Implement the PCI PM Capability and support D0 and D3","Must not implement the PCI PM Capability","Support only D1 and D2"],1,"CXL Function도 PCIe처럼 PCI Power Management Capability를 두고 D0·D3를 지원해야 한다.","Like PCIe functions, CXL functions must have the PCI Power Management Capability and support D0 and D3.","§10.4"],["c7q15","c7_4",2,"X","RCD가 아닌 구성 요소의 CXL.io L1 진입 규칙으로 옳은 것은?","Which CXL.io L1 entry rule applies to a component not in RCD mode?",["L1을 지원하지 않는다","L0s를 대신 쓴다","PCI-PM을 지원해야 하며, D3Hot이나 D1이 되면 CXL.io L1 진입을 시작해야 한다 (ASPM L1은 선택)","ASPM L1만 지원하고 PCI-PM은 지원하지 않는다"],["It does not support L1","It uses L0s instead","It must support PCI-PM and start CXL.io L1 entry when placed in D3Hot or D1 (ASPM L1 optional)","It supports ASPM L1 only, not PCI-PM"],2,"RCD 링크는 ASPM L1만 지원하지만, RCD가 아니면 PCI-PM이 필수이고 ASPM L1은 선택이다.","RCD links support only ASPM-directed L1, while non-RCD components must support PCI-PM, with ASPM L1 optional.","§10.4"],["c7q16","c7_4",2,"X","CXL.cache와 CXL.mem의 링크 전원 관리가 CXL.io와 다른 점은?","How does CXL.cache/CXL.mem link power management differ from CXL.io?",["PCI-PM D-state로만 동작한다","DLLP 핸드셰이크를 반드시 쓴다","전원 관리를 지원하지 않는다","ASPM만 지원하며 Link Layer 사이 PM 진입 핸드셰이크가 없고 ARB/MUX가 ALMP로 조율한다"],["Only via PCI-PM D-states","It must use a DLLP handshake","No power management at all","ASPM only, with no Link Layer PM handshake; the ARB/MUX coordinates via ALMPs"],3,"cachemem 쪽은 각자 ARB/MUX에 L1을 요청하고, 양쪽 ARB/MUX가 ALMP로 진입을 맞춘다.","Each cachemem side asks its ARB/MUX for L1 on its own, and the two ARB/MUXes coordinate entry with ALMPs.","§10.5"],["c7q17","c7_4",3,"X","256B Flit mode에서 CXL.io ASPM 진입 Phase 1이 PCIe ASPM L1과 다른 점은?","In 256B Flit mode, how does CXL.io ASPM entry Phase 1 differ from PCIe ASPM L1?",["PM 진입용 DLLP를 주고받지 않고, 각 Link Layer가 자기 ARB/MUX에 독립적으로 요청한다","PM_Request_Ack DLLP를 더 많이 보낸다","Phase 1이 생략되고 바로 L2로 간다","Host 소프트웨어가 DLLP를 대신 보낸다"],["No PM-entry DLLPs are exchanged; each Link Layer independently asks its ARB/MUX","More PM_Request_Ack DLLPs are sent","Phase 1 is skipped and the link goes straight to L2","Host software sends the DLLPs instead"],0,"PCIe ASPM L1은 DLLP 핸드셰이크를 쓰지만, CXL 256B Flit mode에서는 PM 진입 DLLP를 쓰지 않는다. 68B Flit mode에서는 PCIe ASPM L1 협상 규칙을 Phase 1로 따른다.","PCIe ASPM L1 uses a DLLP handshake, but CXL 256B Flit mode uses none for PM entry. In 68B Flit mode, Phase 1 follows the PCIe ASPM L1 negotiation rules.","§10.4.1"],["c7q18","c7_5",1,"X","ALMP는 무엇의 약자이며 누가 만드는가?","What does ALMP stand for, and who generates it?",["Auxiliary Low-power Message, 소프트웨어가 생성","ARB/MUX Link Management Packet, ARB/MUX가 생성","Active Link Memory Packet, Memory Controller가 생성","Alternate Link Mode Protocol, PHY가 생성"],["Auxiliary Low-power Message, generated by software","ARB/MUX Link Management Packet, generated by the ARB/MUX","Active Link Memory Packet, generated by the memory controller","Alternate Link Mode Protocol, generated by the PHY"],1,"ARB/MUX는 각 Link Layer를 대신해 전원 상태 전환 요청을 ALMP로 상대 ARB/MUX에 전달한다.","The ARB/MUX sends power-state transition requests to the remote ARB/MUX as ALMPs on behalf of each link layer.","§5.0"],["c7q19","c7_5",1,"X","Flex Bus 링크가 PCIe mode로 동작할 때 ALMP는?","What happens to ALMPs when the Flex Bus link runs in PCIe mode?",["ALMP 전송 빈도가 늘어난다","CXL.io만 ALMP를 쓴다","ARB/MUX가 우회되어 ALMP 생성이 꺼진다","ALMP가 DLLP로 바뀌어 전송된다"],["ALMPs are sent more often","Only CXL.io uses ALMPs","The ARB/MUX is bypassed and ALMP generation is disabled","ALMPs are sent as DLLPs"],2,"PCIe mode에서는 ARB/MUX bypass가 적용되어 ALMP를 만들지 않는다. bypass 여부는 HwInit이나 link training으로 정한다.","In PCIe mode the ARB/MUX is bypassed and no ALMPs are generated; bypass is set by HwInit or during link training.","§5.2.1"],["c7q20","c7_5",2,"X","68B Flit mode에서 1-DWORD ALMP를 보호하는 방법은?","How is the 1-DWORD ALMP protected in 68B Flit mode?",["FEC와 CRC로 보호한다","IDE로 암호화한다","보호하지 않는다","flit의 하위 16 bytes에 4번 복제한다 (오류 감지 시 retrain)"],["FEC and CRC protect it","IDE encrypts it","It has no protection","It is replicated four times in the flit's lower 16 bytes (an error triggers a retrain)"],3,"68B에서는 ALMP를 네 번 복제해 무결성을 확보하고, 오류를 감지하면 링크를 retrain한다. 256B에서는 복제 없이 CRC·FEC와 PHY replay buffer로 보호한다.","In 68B mode the ALMP is replicated four times, and a detected error causes a retrain. In 256B mode it is protected by CRC/FEC and the PHY replay buffer, without replication.","§5.2"],["c7q21","c7_5",2,"X","vLSM 상태 L1.0과 SLEEP_L2에 대한 설명으로 옳은 것은?","Which statement about vLSM states L1.0 and SLEEP_L2 is correct?",["L1.0은 PCIe L1에 대응하고 Retrain으로 Active에 돌아가며, SLEEP_L2는 Reset을 거쳐야 Active가 된다","둘 다 Retrain만으로 Active로 돌아간다","L1.0은 reserved이고 L1.1이 PCIe L1에 대응한다","SLEEP_L2는 Active의 하위 상태다"],["L1.0 maps to PCIe L1 and returns to Active via Retrain; SLEEP_L2 must go through Reset","Both return to Active by Retrain alone","L1.0 is reserved and L1.1 maps to PCIe L1","SLEEP_L2 is a substate of Active"],0,"L1.1~L1.3은 향후용 reserved이고 L1.0이 PCIe L1에 대응한다. SLEEP_L2에서는 Reset을 지나야 Active로 갈 수 있다.","L1.1-L1.3 are reserved for future use; L1.0 maps to PCIe L1. From SLEEP_L2, the link must pass through Reset to reach Active.","§5.1"],["c7q22","c7_5",3,"X","256B Flit mode에서 PM 전환 요청 ALMP를 받아들이지 않을 때 동작은?","In 256B Flit mode, what happens when a PM transition request ALMP is not accepted?",["L2로 강제 진입한다","Active.PMNAK 상태 ALMP를 보낸다 (68B에서는 상태 ALMP를 보내지 않음)","아무 ALMP도 보내지 않는다","LinkError로 전환한다"],["The link is forced into L2","An Active.PMNAK Status ALMP is sent (68B sends no status ALMP)","No ALMP is sent at all","The link moves to LinkError"],1,"68B에서는 거절 시 상태 ALMP 없이 양쪽 vLSM이 현재 상태를 유지한다. 256B에서는 Active.PMNAK 상태 ALMP로 거절을 알린다.","In 68B mode a rejection sends no status ALMP and both vLSMs stay put. In 256B mode, an Active.PMNAK Status ALMP signals the rejection.","§5.2"],["c7q23","c7_5",2,"X","vLSM ALMP의 Byte 3 Virtual LSM Instance Number 0010b가 가리키는 대상은?","In a vLSM ALMP, what does Virtual LSM Instance Number 0010b in Byte 3 target?",["L0p 협상","모든 vLSM 동시","CXL.cache와 CXL.mem","CXL.io"],["L0p negotiation","All vLSMs at once","CXL.cache and CXL.mem","CXL.io"],2,"0001b는 CXL.io, 0010b는 CXL.cache+CXL.mem 인터페이스다. L0p ALMP는 Byte 1 message code가 따로 있다.","0001b is CXL.io and 0010b is CXL.cache+CXL.mem. L0p ALMPs use a separate Byte 1 message code.","§5.2"],["c7q24","c7_6",1,"X","256B Flit mode에서 L0p 폭 협상에 쓰는 것은?","What is used to negotiate L0p width in 256B Flit mode?",["PCIe Link Management DLLP","Configuration Write","PM VDM","ARB/MUX의 L0p Negotiation ALMP"],["PCIe Link Management DLLPs","Configuration Writes","PM VDMs","L0p Negotiation ALMPs from the ARB/MUX"],3,"L0p 자체는 PCIe Base Spec 정의를 따르지만, CXL은 Link Management DLLP 대신 ALMP로 상대와 폭을 협상한다.","L0p follows the PCIe definition, but CXL negotiates width with ALMPs instead of Link Management DLLPs.","§5.1.2.5"],["c7q25","c7_6",2,"X","priority 요청이 없을 때 ARB/MUX가 정하는 L0p 폭(aggregated width)의 규칙은?","Without a priority request, what rule governs the L0p width the ARB/MUX aggregates?",["두 Link Layer가 요청한 폭 중 큰 값 이상이어야 한다","두 요청 중 작은 값이어야 한다","항상 x1이다","항상 x16이다"],["It must be at least the larger of the two Link Layers' requested widths","It must be the smaller request","Always x1","Always x16"],0,"일반 요청이면 큰 요청 폭 이상으로 정하고, 필요하면 더 넓게 잡을 수도 있다. 열 제한 같은 priority 요청이면 priority로 요청된 가장 낮은 폭을 쓴다.","For normal requests, the width is at least the larger request and may be wider. With a priority request (e.g., thermal), the lowest priority-requested width is used.","§5.1.2.5"],["c7q26","c7_6",3,"X","L0p request ALMP를 받은 ARB/MUX가 ACK 또는 NAK로 응답해야 하는 시한은?","Within what time must an ARB/MUX answer an L0p request ALMP with ACK or NAK?",["시한 없음","1 us 이내 (LTSSM L0 시간만 셈)","1 ms 이내","10 ms 이내"],["No limit","Within 1 us (counting only LTSSM L0 time)","Within 1 ms","Within 10 ms"],1,"응답 시한은 1us이며 retry buffer에 머문 시간은 빼고 L0 동안만 센다. 동시에 미해결 L0p 요청은 하나만 둘 수 있다.","The limit is 1 us, counted only in L0 and excluding retry buffer time. Only one L0p request may be outstanding.","§5.1.2.5"],["c7q27","c7_7",1,"X","Global Persistent Flush(GPF)의 목적은?","What is the purpose of Global Persistent Flush (GPF)?",["HDM Decoder를 초기화한다","CXL.io credit을 반환한다","캐시와 메모리 버퍼의 데이터를 persistence domain으로 flush해 전원 손실 등에 대비한다","링크 속도를 낮춰 전력을 줄인다"],["Reset HDM decoders","Return CXL.io credits","Flush cache and memory buffers to a persistence domain, e.g., before power loss","Lower link speed to save power"],2,"GPF는 persistent memory용 하드웨어 flush 메커니즘이다. 갑작스러운 전원 손실 같은 비정상 종료 직전에 in-flight 데이터를 persistent media에 써 둔다.","GPF is a hardware flush mechanism for persistent memory that writes in-flight data to persistent media before events such as sudden power loss.","§9.8"],["c7q28","c7_7",1,"X","GPF의 두 단계에서 각각 하는 일로 옳은 것은?","Which correctly describes the two GPF phases?",["Phase 1: 메모리 버퍼 flush / Phase 2: 캐시 write back","Phase 1: 링크 retrain / Phase 2: 장치 리셋","두 단계 모두 같은 일을 반복한다","Phase 1: 새 트래픽 중단과 캐시 write back / Phase 2: 장치 내부 쓰기 버퍼를 persistence domain으로 flush"],["Phase 1: flush memory buffers; Phase 2: write back caches","Phase 1: retrain; Phase 2: reset the device","Both phases repeat the same work","Phase 1: stop new traffic and write back caches; Phase 2: flush local write buffers to persistence"],3,"두 단계로 나누고 Host가 그 사이에 barrier를 두면, 장치가 버퍼를 flush하는 동안 새 트래픽을 받지 않는다.","Splitting into two phases with a host barrier between them ensures no new traffic arrives while devices flush their buffers.","§9.8.1"],["c7q29","c7_7",2,"X","GPF Phase 1 요청의 Payload[1] 비트가 1이면 장치(CXL.cache 지원)는?","If Payload[1] is set in a GPF Phase 1 request, what does a CXL.cache-capable device do?",["caching을 끄고 장치 캐시의 modified line을 write back한다","즉시 최저 전원 상태로 간다","Dirty Shutdown Count를 올린다","응답하지 않는다"],["Disable caching and write back modified lines in its cache","Go straight to the lowest power state","Increment the Dirty Shutdown Count","Send no response"],0,"Payload[1]은 Phase 1에서 캐시 flush를 요구하는 비트다. Payload[0]은 전원 손실이 임박했다는 표시다.","Payload[1] requests cache flushing in Phase 1. Payload[0] signals that power failure is imminent.","§9.8.2"],["c7q30","c7_7",3,"X","GPF Phase 1에서 장치가 자기 로컬 HDM이 아닌 곳에 매핑된(persistent일 수 있는) dirty line을 write back하는 순서는?","In GPF Phase 1, how does a device write back a dirty line that is not in its local HDM and may be persistent?",["CleanEvictNoData를 보낸다","DirtyEvict를 보낸 뒤 CLFlush를 보낸다","CLFlush 하나만 보낸다","MemWr를 CXL.mem으로 보낸다"],["Send CleanEvictNoData","Issue DirtyEvict, then CLFlush","Issue only CLFlush","Send MemWr on CXL.mem"],1,"로컬 persistent HDM의 dirty line은 장치 내부 방식으로 처리하고, 그 밖의 persistent일 수 있는 dirty line은 DirtyEvict와 CLFlush 두 단계로 Host에 보낸다.","Dirty lines in local persistent HDM use internal means; other possibly persistent dirty lines go to the host in two steps, DirtyEvict then CLFlush.","§9.8.2"],["c7q31","c7_7",2,"X","GPF에서 Payload[8] 비트의 역할은?","What is the role of the Payload[8] bit in GPF?",["전원 손실 임박 표시","캐시 flush 요구","Phase 1 캐시 flush 오류 표시 (Phase 1 응답과 Phase 2 요청에서 유효)","Phase 2 시작 표시"],["It signals imminent power loss","It requests a cache flush","It flags a Phase 1 cache-flush error (valid in Phase 1 responses and Phase 2 requests)","It marks the start of Phase 2"],2,"Switch가 timeout을 감지하거나 장치가 Phase 1에 실패하면 응답에 Payload[8]을 설정한다. Host는 Phase 2 요청에 이를 실어 모든 장치에 알리고, persistent 장치는 Dirty Shutdown Count를 올린다.","A switch timeout or device Phase 1 failure sets Payload[8] in the response. The host carries it in Phase 2 requests to every device, and persistent devices bump the Dirty Shutdown Count.","§9.8.1"],["c7q32","c7_7",2,"X","GPF 메시지의 credit 처리 규칙은?","How are credits handled for GPF messages?",["GPF마다 CREDIT_RTN이 필수다","PMREQ credit을 빌려 쓴다","CXL.mem credit을 쓴다","GPF 메시지는 credit을 쓰지 않으며, GPF 요청에 CREDIT_RTN을 기대하지 않는다"],["Each GPF needs a CREDIT_RTN","They borrow PMREQ credits","They use CXL.mem credits","GPF messages use no credit, and no CREDIT_RTN is expected in reply"],3,"장치와 switch는 다른 PM 메시지에 의존하지 않고 GPF를 받아 처리할 수 있어야 한다. 그래서 GPF는 credit 없이 동작한다.","Devices and switches must handle GPF without depending on other PM messages, so GPF runs without credits.","§9.8.1"],["c7q33","c7_8",1,"X","Root Port와 DSP의 GPF Phase 1·Phase 2 timeout을 설정하는 곳은?","Where are the GPF Phase 1 and Phase 2 timeouts of Root Ports and DSPs configured?",["GPF DVSEC for CXL Port (system software가 설정)","GPF DVSEC for CXL Device","HDM Decoder Control","ARB/MUX PM Timeout Control"],["The GPF DVSEC for CXL Port (set by system software)","The GPF DVSEC for CXL Device","HDM Decoder Control","ARB/MUX PM Timeout Control"],0,"Root Port와 DSP는 한 장치가 GPF를 막지 않도록 timeout을 둔다. 값은 Timeout Base × Timeout Scale로 정한다.","Root Ports and DSPs use timeouts so one device cannot stall GPF. The value is Timeout Base times Timeout Scale.","§8.1.6"],["c7q34","c7_8",1,"X","GPF DVSEC for CXL Device가 보고하는 정보는?","What does the GPF DVSEC for CXL Device report?",["HDM 범위 크기","Phase 2 완료 최대 시간과 Phase 2 중 active power (mW 단위)","Phase 1 timeout 설정값","링크 폭"],["The HDM range size","Maximum time to finish Phase 2 and active power during Phase 2 (in mW)","The Phase 1 timeout setting","The link width"],1,"이 DVSEC은 GPF를 지원하는 CXL.mem 장치의 Function 0에 있다. 시스템 소프트웨어는 이 값으로 에너지 예산과 timeout을 계산한다.","This DVSEC lives in Function 0 of GPF-capable CXL.mem devices. Software uses it for energy budgeting and timeout sizing.","§8.1.7"],["c7q35","c7_8",1,"X","시스템이 S0에서 Sx(S3 등)로 들어갈 때 Host가 CXL 장치에 보내는 PM VDM은?","When the system goes from S0 to an Sx state (e.g., S3), which PM VDM does the host send to CXL devices?",["PMREQ","AGENT_INFO","RESETPREP (ResetType=S0→Sx, PrepType=General Prep)","GPF Phase 1"],["PMREQ","AGENT_INFO","RESETPREP (ResetType = S0 to Sx, PrepType = General Prep)","GPF Phase 1"],2,"장치는 context를 flush하고 메모리를 self-refresh 같은 안전 상태로 둔 뒤 RESETPREP 응답을 보낸다. 그 뒤 PERST#가 언제든 assert될 수 있다.","The device flushes context, puts memory in a safe state such as self-refresh, then replies with RESETPREP. PERST# may be asserted any time after.","§9.4"],["c7q36","c7_8",3,"X","GPF를 지원하는 장치가 그 사실을 Host에 알리는 방법은?","How does a GPF-capable device advertise GPF support to the host?",["DVSEC CXL Capability의 Viral_Capable을 설정한다","GPF Phase 1 요청을 먼저 보낸다","Class Code를 바꾼다","AGENT_INFO 응답의 CAPABILITY_VECTOR bit[1]을 설정한다"],["Set Viral_Capable in DVSEC CXL Capability","Send a GPF Phase 1 request first","Change its Class Code","Set bit[1] of CAPABILITY_VECTOR in its AGENT_INFO response"],3,"CAPABILITY_VECTOR bit[0]은 CXL 1.1 PM 메시지 지원, bit[1]은 GPF 메시지 지원이다. eRCD를 뺀 모든 CXL 장치는 GPF를 지원해야 한다.","In CAPABILITY_VECTOR, bit[0] is CXL 1.1 PM message support and bit[1] is GPF support. All CXL devices except eRCDs must support GPF.","§9.8.2"]],"8":[["p8q01","p8_1",1,"C","PCI Express는 오류를 크게 어떻게 분류하나요?","How does PCI Express classify errors at the top level?",["Uncorrectable error와 Correctable error의 두 유형으로 분류하고, Uncorrectable은 다시 Fatal과 Non-Fatal로 나눈다.","Correctable, Recoverable, Unrecoverable의 세 유형으로만 분류한다.","Physical Layer, Data Link Layer, Transaction Layer의 세 유형으로만 분류한다.","Fatal과 Advisory의 두 유형으로만 분류한다."],["As two types, Uncorrectable and Correctable; Uncorrectable errors are further classified as Fatal or Non-Fatal.","Only as three types: Correctable, Recoverable, and Unrecoverable.","Only by layer: Physical, Data Link, and Transaction.","Only as two types: Fatal and Advisory."],0,"이 구분은 기능 장애를 초래하는 오류와 성능 저하를 초래하는 오류를 가르기 위한 것입니다. Uncorrectable은 Figure 6-1처럼 Fatal/Non-Fatal로 세분됩니다.","The split separates errors that cause functional failure from those that mainly degrade performance. Uncorrectable errors are further split into Fatal and Non-Fatal, as shown in Figure 6-1.","§6.2.2"],["p8q02","p8_1",1,"C","Correctable error의 정의에 가장 가까운 설명은?","Which description best matches a Correctable error?",["해당 Link와 관련 하드웨어를 신뢰할 수 없게 만들어 reset이 필요할 수 있는 오류이다.","특정 transaction만 신뢰할 수 없고 Link는 정상인 오류로, 항상 ERR_FATAL로 알린다.","하드웨어가 정보 손실 없이 복구할 수 있는 오류 조건이다. Data Link Level Retry로 고쳐지는 경우도 여기에 해당한다.","소프트웨어만 복구할 수 있고 하드웨어 retry는 금지된 오류이다."],["An error that makes the Link and related hardware unreliable and may require a reset.","An error that makes only one transaction unreliable, always signaled with ERR_FATAL.","An error condition where hardware can recover without any loss of information. A case corrected by Data Link Level Retry is one example.","An error that only software can recover from, with hardware retry forbidden."],2,"Link 수준 Correctable error의 빈도를 보면 Link 건전성을 가늠할 수 있습니다. Transaction 수준에서도, 한 agent가 탐지했더라도 다른 agent가 더 적절히 처리할 수 있는 경우가 포함됩니다.","The rate of Link-level correctable errors can be used as a Link-integrity signal. Transaction-level cases are also included when one agent detects a problem but another agent is in a better position to handle it.","§6.2.2.1"],["p8q03","p8_1",1,"C","Fatal error의 정의로 옳은 것은?","Which statement correctly defines a Fatal error?",["특정 transaction만 신뢰할 수 없고 Link 자체는 완전히 동작하는 uncorrectable error이다.","해당 Link와 관련 하드웨어를 신뢰할 수 없게 만드는 uncorrectable error이며, 신뢰성 있는 동작으로 돌아가려면 해당 Link 구성 요소의 reset이 필요할 수 있다.","하드웨어가 정보 손실 없이 복구하는 correctable error의 다른 이름이다.","항상 Advisory Non-Fatal로 처리되어 ERR_COR만 보내는 오류이다."],["An uncorrectable error that makes only a particular transaction unreliable, while the Link remains fully functional.","An uncorrectable error that makes that Link, and the hardware tied to it, untrustworthy. Getting back to trustworthy operation may require resetting those components.","Another name for a correctable error that hardware recovers from without loss of information.","An error that must always be handled as Advisory Non-Fatal and signaled only with ERR_COR."],1,"플랫폼이 Fatal error를 어떻게 다룰지, 영향을 어떻게 제한할지는 구현에 달려 있습니다. Non-Fatal과 구분하는 이유는 장치/시스템의 Requester·Receiver 로직이 다르게 대응할 수 있게 하기 위함입니다.","How a platform handles Fatal errors, and any attempt to limit their effects, is implementation-specific. Separating them from Non-Fatal errors lets requester/receiver logic respond differently.","§6.2.2.2.1"],["p8q04","p8_1",1,"C","Non-Fatal error의 정의로 옳은 것은?","Which statement correctly defines a Non-Fatal error?",["Link와 관련 하드웨어 전체를 신뢰할 수 없게 만들어 반드시 reset해야 하는 오류이다.","Data Link Level Retry로 항상 복구되는 correctable error이다.","보고 메커니즘이 정의되어 있지 않아 소프트웨어에만 남기는 오류이다.","특정 transaction을 신뢰할 수 없게 만들지만, Link 자체는 완전히 동작하는 uncorrectable error이다."],["An error that makes the entire Link and related hardware unreliable and always requires a reset.","A correctable error that Data Link Level Retry always recovers.","An error with no defined reporting mechanism, left only to software.","An uncorrectable error that causes a particular transaction to be unreliable but leaves the Link otherwise fully functional."],3,"Fatal과 Non-Fatal을 가르면, 한 건의 transaction 문제와 Link 자체의 신뢰성 상실을 구분해 대응할 수 있습니다.","Isolating Non-Fatal from Fatal lets logic distinguish a bad transaction from a Link that is no longer trustworthy.","§6.2.2.2.2"],["p8q05","p8_1",2,"C","Baseline error reporting과 AER(Advanced Error Reporting)에 대한 설명으로 옳은 것은?","Which statement about baseline error reporting and AER is correct?",["AER는 모든 PCI Express device에 필수이고, baseline은 Root Port에만 적용된다.","VF가 AER을 구현하면, 연관 PF는 AER을 구현하지 않아야 한다.","Baseline capability는 모든 PCI Express device에 필수이고, AER Extended Capability는 선택이다. SR-IOV Device에서 PF가 AER을 구현하지 않으면 연관 VF에도 AER을 구현하면 안 된다.","Baseline과 AER은 서로 배타적이어서, AER을 구현한 Function은 baseline status bit를 구현하지 않는다."],["AER is required of every PCI Express device, and baseline reporting applies only to Root Ports.","If a VF implements AER, its associated PF must not implement AER.","Baseline capability is required of all PCI Express devices, and the AER Extended Capability is optional. In an SR-IOV Device, if a PF does not implement AER, its associated VFs must not implement AER either.","Baseline and AER are mutually exclusive, so a Function with AER does not implement baseline status bits."],2,"PF가 AER을 구현하면 VF에서의 AER은 선택입니다. SIOV Device도 baseline은 필수이고 AER은 선택입니다. 레거시 소프트웨어를 위해 PCI Express 오류는 기존 PCI 보고 방식으로도 매핑됩니다.","If the PF implements AER, AER remains optional in its VFs. SIOV Devices also require baseline reporting, with AER optional. PCI Express errors are also mapped onto legacy PCI reporting so older software can still see them.","§6.2.1"],["p8q06","p8_2",1,"C","오류를 알리기 위해 정의된 Error Message 세 가지는?","Which three Error Messages are defined for signaling errors?",["ERR_COR, ERR_NONFATAL, ERR_FATAL","ERR_COR, ERR_UR, ERR_CA","ERR_DLLP, ERR_TLP, ERR_PHY","ERR_ADVISORY, ERR_POISON, ERR_TIMEOUT"],["ERR_COR, ERR_NONFATAL, and ERR_FATAL","ERR_COR, ERR_UR, and ERR_CA","ERR_DLLP, ERR_TLP, and ERR_PHY","ERR_ADVISORY, ERR_POISON, and ERR_TIMEOUT"],0,"ERR_COR는 correctable error, ERR_NONFATAL는 Non-fatal uncorrectable, ERR_FATAL는 Fatal uncorrectable를 알릴 때 사용합니다. Role-Based Error Reporting에서는 Non-fatal을 ERR_COR로 알리는 Advisory 경우도 있습니다.","ERR_COR is used for a correctable error, ERR_NONFATAL for a Non-fatal uncorrectable error, and ERR_FATAL for a Fatal uncorrectable error. Under Role-Based Error Reporting, some Non-fatal cases are instead signaled with ERR_COR as advisories.","§6.2.3.2"],["p8q07","p8_2",2,"C","Role-Based Error Reporting을 지원하는 이후 규격에서, Non-fatal error의 알림 방식으로 옳은 것은?","Under later specifications that support Role-Based Error Reporting, how may a non-fatal error be signaled?",["Non-fatal은 항상 ERR_NONFATAL로만, Fatal은 항상 ERR_COR로만 알린다.","탐지 agent의 role과 무관하게 모든 uncorrectable error는 ERR_FATAL로만 알린다.","AER가 없으면 Non-fatal도 항상 ERR_FATAL로 올려야 한다.","경우에 따라 ERR_NONFATAL로 알리거나, ERR_COR로 알리거나, 전혀 알리지 않을 수 있다. 다만 Fatal error는 (enable되어 있으면) 항상 ERR_FATAL로 알린다."],["Non-fatal errors are always signaled only with ERR_NONFATAL, and fatal errors only with ERR_COR.","Every uncorrectable error is signaled only with ERR_FATAL, regardless of the detecting agent's role.","Without AER, a non-fatal error must always be raised as ERR_FATAL.","Depending on the case, it may be signaled with ERR_NONFATAL, with ERR_COR, or not signaled at all. A fatal error, if enabled, is always signaled with ERR_FATAL."],3,"초기에는 이름이 심각도와 1:1로 맞았습니다. 이후에는 탐지 agent의 role에 따라, 다른 agent의 복구를 방해하지 않도록 Non-fatal을 Advisory로 다루는 경로가 생겼습니다. 소프트웨어가 심각도를 Fatal로 올리면 탐지 agent는 ERR_FATAL로 알립니다.","Early revisions matched message type to severity one-for-one. Later rules let the detecting agent's role use an advisory path so another agent is not blocked from recovering. If software escalates severity to fatal, the detecting agent signals ERR_FATAL.","§6.2.3.2"],["p8q08","p8_2",2,"C","평소 Non-fatal인 uncorrectable error의 심각도를 소프트웨어가 Fatal로 올렸을 때, 탐지 agent(enable된 경우)의 동작은?","If software escalates a normally non-fatal uncorrectable error to fatal, how does an enabled detecting agent signal it?",["항상 ERR_COR로만 알린다.","agent의 role과 관계없이 항상 ERR_FATAL로 알린다.","항상 ERR_NONFATAL로만 알린다.","Error Message를 보내지 않고 Status bit만 세운다."],["It always signals the error only with ERR_COR.","It always signals the error with ERR_FATAL, regardless of the agent's role.","It always signals the error only with ERR_NONFATAL.","It sets only a status bit and sends no Error Message."],1,"AER의 Uncorrectable Error Severity register로 각 uncorrectable error를 Fatal 또는 Non-Fatal로 프로그래밍할 수 있습니다. Fatal로 올리면 Advisory Non-Fatal 경로를 쓰지 않습니다.","The AER Uncorrectable Error Severity register lets each uncorrectable error be programmed as Fatal or Non-Fatal. Once raised to fatal, the advisory Non-Fatal path is not used.","§6.2.3.2.1"],["p8q09","p8_2",3,"P","ERR_COR Subclass(ECS) 사용에 대한 설명으로 옳은 것은?","Which statement about the ERR_COR Subclass (ECS) field is correct?",["ECS 값은 Error Message를 항상 Root Complex에서 폐기할지 여부만 나타낸다.","ECS SIG_OS는 Link correctable error나 Advisory Non-Fatal Error 같은 AER 이벤트를 OS에 알리는 용도이고, ECS SIG_SFW는 system firmware에 알리는 용도이다. ECS를 지원하지 않는 adapter의 ERR_COR는 Legacy로 분류된다.","ECS SIG_OS는 오직 Fatal error에만 쓰이고, SIG_SFW는 Correctable error에만 쓰인다.","모든 ERR_COR는 ECS 필드가 없으며, Subclass는 ERR_FATAL에만 정의된다."],["The ECS value only tells the Root Complex whether to discard the Error Message.","ECS SIG_OS is intended to signal the OS for AER events such as Link correctable errors and Advisory Non-Fatal Errors, while ECS SIG_SFW is intended to signal system firmware. ERR_CORs from adapters that do not support ECS are classified as Legacy.","ECS SIG_OS is used only for Fatal errors, and SIG_SFW only for Correctable errors.","ERR_COR has no ECS field; a subclass is defined only for ERR_FATAL."],1,"DPC signaling에 쓰이는 ERR_COR도 firmware를 겨냥할 수 있고, SFI capability 역시 ECS 필드로 그 의도를 표시해야 합니다. 구체적인 사용 요약을 스펙이 표로 정리해 둡니다.","An ERR_COR used for DPC signaling may also be aimed at firmware, and the SFI capability must indicate that intent through the ECS field. The specification summarizes these uses in a short table.","§6.2.2.1"],["p8q10","p8_3",2,"C","Advisory Non-Fatal Error를 탐지한 agent의 기본 알림 방식은?","How does a detecting agent signal an Advisory Non-Fatal Error by default?",["AER 유무와 관계없이 항상 ERR_NONFATAL을 보낸다.","AER가 있는 agent는 ERR_FATAL을 보내고, 없는 agent는 ERR_COR를 보낸다.","모든 agent가 Completion Status로만 알리고 Error Message는 금지된다.","AER가 있는 agent는 (enable된 경우) ERR_COR Message를 보내고, AER이 없는 agent는 이 경우에 Error Message를 보내지 않는다."],["Every agent always sends ERR_NONFATAL, with or without AER.","An agent with AER sends ERR_FATAL, and an agent without AER sends ERR_COR.","Every agent may signal only via Completion Status; Error Messages are forbidden.","If AER is present and reporting is enabled, the agent sends ERR_COR. Without AER it sends no Error Message in these cases."],3,"AER가 없으면 수신 소프트웨어가 ERR_COR를 Link 건전성용 correctable error와 구분할 수 없습니다. 소프트웨어가 해당 uncorrectable error의 심각도를 Fatal로 올리면 Advisory가 아니라 ERR_FATAL로 알립니다.","Without AER, software receiving ERR_COR could not tell an advisory case from a Link-integrity correctable error. If software escalates that uncorrectable error to fatal, the agent signals ERR_FATAL instead of treating it as advisory.","§6.2.3.2.4"],["p8q11","p8_3",2,"C","Completer가 Non-Posted 또는 UIO Request에 대해 UR 또는 CA Completion을 보낼 때, 해당 오류 심각도가 Non-fatal이면?","When a Completer returns a Completion with UR or CA Status for a Non-Posted or UIO Request, and the error severity is non-fatal, how must the Completer handle the case?",["Advisory Non-Fatal Error로 처리해야 한다. 실제 오류 보고(필요 시)는 UR/CA Completion을 받은 Requester가 Requester-specific 방식으로 수행한다.","반드시 ERR_FATAL을 보내 Link를 내려야 한다.","Completion을 보내지 않고 TLP를 조용히 폐기해야 한다.","항상 Poisoned Completion으로 바꿔 보내야 한다."],["It must handle the case as an Advisory Non-Fatal Error. If the error needs to be reported, the Requester that received the UR/CA Completion does so through a requester-specific mechanism.","It must send ERR_FATAL and take the Link down.","It must silently drop the TLP and send no Completion.","It must always convert the Completion into a poisoned Completion."],0,"해당 transaction에는 uncorrectable error가 있었지만, Completer가 ERR_NONFATAL까지 올리면 일부 플랫폼에서 System Error가 되어 Requester 측 복구를 방해할 수 있습니다.","Even though this specific transaction had an uncorrectable error, an extra ERR_NONFATAL from the Completer can become a System Error on some platforms and interfere with recovery at the Requester.","§6.2.3.2.4.1"],["p8q12","p8_3",2,"C","Switch가 자신이 최종 목적지가 아닌 TLP에서 poison 또는 잘못된 ECRC를 탐지한 경우(심각도 Non-fatal)의 처리는?","If a Switch, not the ultimate destination of a TLP, detects poison or a bad ECRC and the severity is non-fatal, how must it handle the error?",["TLP 전달을 즉시 중단하고 ERR_FATAL만 보내야 한다.","ECRC를 재계산해 고친 뒤 오류를 보고하지 않아야 한다.","intermediate Receiver로서 Advisory Non-Fatal Error로 처리해야 한다. 최종 Receiver가 자신의 설정에 따라 더 적절히 다루도록 하기 위해서이다.","무조건 ERR_NONFATAL을 보내고 TLP header를 폐기해야 한다."],["It must stop forwarding the TLP immediately and send only ERR_FATAL.","It must recompute and repair the ECRC and report no error.","It must handle the case as an Advisory Non-Fatal Error as an intermediate Receiver, so the ultimate Receiver can handle the error according to its own settings.","It must always send ERR_NONFATAL and discard the TLP header."],2,"같은 Memory Write poison이라도, 어떤 Completer는 mask해서 신호를 안 보낼 수 있고 다른 Completer는 ERR_NONFATAL로 알릴 수 있습니다. intermediate Receiver가 먼저 ERR_NONFATAL을 올리면 그 선택이 막힐 수 있습니다.","One Completer might mask a poisoned Memory Write, while another Completer in the same hierarchy might signal ERR_NONFATAL. If an intermediate Receiver raised ERR_NONFATAL first, that later choice could be blocked.","§6.2.3.2.4.2"],["p8q13","p8_3",2,"C","Unexpected Completion을 수신했고 해당 오류의 심각도가 Non-fatal일 때 Receiver의 처리는?","When a Receiver gets an Unexpected Completion and the Unexpected Completion error severity is non-fatal, how must it handle the error?",["항상 ERR_FATAL로 올려 Link를 disable해야 한다.","해당 Completion을 정상 Completion으로 변환해 사용해야 한다.","AER 유무와 관계없이 Error Message를 보내면 안 된다.","Advisory Non-Fatal Error로 처리해야 한다."],["It must always raise ERR_FATAL and disable the Link.","It must convert the Completion into a successful Completion and use it.","It must never send an Error Message, with or without AER.","It must handle the case as an Advisory Non-Fatal Error."],3,"잘못된 라우팅 때문에 Unexpected Completion이 생겼다면, 원래 Requester에서 Completion Timeout이 나고 복구를 시도할 수 있습니다. 수신 측에서 ERR_NONFATAL을 올리면 그 복구를 방해할 수 있습니다.","If the unexpected Completion was caused by misrouting, the true Requester may later see a Completion Timeout and try to recover. Signaling ERR_NONFATAL at this Receiver can interfere with that recovery.","§6.2.3.2.4.5"],["p8q14","p8_3",3,"C","Requester가 Completion Timeout을 만났을 때(Root Port PIO가 아닌 일반 경우), Advisory Non-Fatal 처리가 되는 조건은?","For a Requester other than a Root Port doing PIO, when is a Completion Timeout handled as an Advisory Non-Fatal Error?",["심각도와 복구 시도와 무관하게 항상 Advisory로만 처리한다.","심각도가 Non-fatal이고, Requester가 새 Request를 발행해 복구를 시도하기로 한 경우이다. 더 이상 복구를 시도하지 않을 때에는 (enable되어 있으면) uncorrectable error Message로 알려야 한다.","복구를 포기할 때에만 Advisory로 처리하고 ERR_COR만 보낸다.","Completion Timeout은 항상 Fatal이며 Advisory가 될 수 없다."],["It is always handled as advisory, regardless of severity or any recovery attempt.","If severity is Non-Fatal and the Requester decides to recover by sending a fresh Request. When it will not try again, an enabled Requester must raise an uncorrectable Error Message.","It is advisory only when recovery is abandoned, and only ERR_COR is sent in that case.","A Completion Timeout is always Fatal and can never be advisory."],1,"복구 시도 횟수는 0회, 1회, 또는 유한한 여러 번이 허용됩니다. 심각도가 Fatal이면 Advisory가 아니며 ERR_FATAL로 알려야 하고, 이때의 복구 시도는 스펙이 강하게 말립니다.","The Requester may attempt recovery zero, one, or a finite number of times. If severity is fatal, the case is not advisory and must be signaled with ERR_FATAL; recovery is strongly discouraged then.","§6.2.3.2.4.4"],["p8q15","p8_4",1,"C","AER Uncorrectable Error Severity register에서 해당 비트의 의미는?","In the AER Uncorrectable Error Severity register, what does each error's severity bit mean?",["비트가 Set이면 해당 오류를 mask하고, Clear이면 항상 Fatal이다.","비트가 Set이면 Correctable로 재분류하고, Clear이면 보고를 금지한다.","비트가 Set이면 해당 오류를 Fatal로 보고하고, Clear이면 Non-fatal로 본다.","이 register는 Root Port에서만 읽을 수 있으며 비트 의미는 vendor-defined이다."],["A Set bit masks the error, and a Clear bit always makes it Fatal.","A Set bit reclassifies the error as Correctable, and a Clear bit forbids reporting.","The error is reported as fatal when the corresponding bit is Set, and is considered non-fatal when the bit is Clear.","Only a Root Port can read this register, and bit meanings are vendor-defined."],2,"AER가 없는 Function은 기본 심각도 매핑을 쓰며 재프로그래밍할 수 없습니다. AER가 있으면 소프트웨어가 이 register로 각 uncorrectable error의 심각도를 바꿀 수 있습니다.","Functions without AER use the default severity mapping and cannot reprogram it. With AER, software can change each uncorrectable error's severity through this register.","§7.8.4.4"],["p8q16","p8_4",1,"C","AER의 Uncorrectable/Correctable Error Mask register 역할은?","What is the role of the AER Uncorrectable and Correctable Error Mask registers?",["각 오류 조건을 독립적으로 mask할 수 있게 한다. 특정 오류의 Message가 mask되면 해당 오류에 대한 Error Message는 보내지 않는다.","mask 비트가 Set된 오류만 Header Log에 기록한다.","모든 오류를 한 비트로 한꺼번에 끄며, 개별 mask는 제공하지 않는다.","Severity를 mask 비트로 직접 Fatal/Non-fatal로 바꾼다."],["Each error can be masked on its own. When a given error is masked, the Function does not send an Error Message for it.","Only errors whose mask bits are Set are recorded in the Header Log.","A single bit disables all errors at once; per-error masking is not provided.","The mask bit itself switches severity between Fatal and Non-fatal."],0,"Severity와 Mask는 별도 register입니다. 탐지 시 status bit는 여전히 세워질 수 있지만, mask된 오류는 보고 Message가 나가지 않도록 동작이 바뀝니다.","Severity and Mask are separate registers. Detection may still set a status bit, but a masked error does not generate a reporting Message.","§6.2.3.2.2"],["p8q17","p8_4",2,"C","AER First Error Pointer 필드의 역할은?","What does the AER First Error Pointer field identify?",["Uncorrectable Error Status register에서 처음으로 보고된 오류의 비트 위치를 가리킨다.","다음에 발생할 correctable error의 예상 비트 위치를 가리킨다.","Header Log register의 남은 바이트 수를 가리킨다.","Root Port가 선택한 ERR_COR Subclass 값을 가리킨다."],["It identifies the bit position of the first error reported in the Uncorrectable Error Status register.","It points at the expected bit position of the next correctable error.","It holds the number of remaining bytes in the Header Log register.","It holds the ERR_COR Subclass value selected by the Root Port."],0,"이후 오류가 더 생겨도, 첫 오류의 header/prefix 로그와 First Error Pointer는 소프트웨어가 처리할 때까지 유지되는 것이 기본 모델입니다(Multiple Header Recording이 켜진 경우는 예외적으로 추가 기록이 가능).","Later errors may occur, but the basic model keeps the first error's header/prefix log and the First Error Pointer until software handles them (unless Multiple Header Recording is enabled and extra records are kept).","§7.8.4.7"],["p8q18","p8_4",2,"C","SR-IOV Device에서 AER Header Log 공간에 대한 규칙으로 옳은 것은?","Which rule about AER Header Log space in an SR-IOV Device is correct?",["모든 VF가 PF의 Header Log를 반드시 공유해야 하며, PF 전용 공간은 금지된다.","VF는 Header Log를 구현할 수 없고, 오류 header는 항상 폐기된다.","PF의 Header Log 공간은 연관 VF의 것과 독립이며 전용 저장 공간으로 구현해야 한다. AER를 구현한 VF들은 하나의 PF에 연관된 VF들끼리 Header Log 공간을 공유할 수 있다.","공유 Header Log를 읽으면 항상 all 0을 반환해야 한다."],["Every VF must share the PF's Header Log, and dedicated PF storage is forbidden.","A VF cannot implement a Header Log, and error headers are always discarded.","A PF must have its own, dedicated Header Log storage, separate from any Header Log used by its VFs. VFs that implement AER are allowed to share one Header Log among the VFs of a single PF.","A shared Header Log must always return all 0s when read."],2,"공유 시 공간이 부족하면 해당 오류의 header를 못 남길 수 있습니다. 이 경우 Header Log를 읽으면 overflow를 알리기 위해 all 1s를 반환해야 합니다.","When space is shared, there may be no room to log a header for an error. In that case, a read of the Header Log register must return all 1s to indicate overflow.","§6.2.4.2.1"],["p8q19","p8_4",2,"C","ECRC 생성/검사 capability와 AER의 관계로 옳은 것은?","Which statement about ECRC capability and AER is correct?",["ECRC를 지원하는 device는 AER를 구현해서는 안 된다.","device가 ECRC 생성/검사를 지원하면, 그 device의 Function 중 적어도 하나는 AER를 지원해야 한다. 실제 생성/검사는 소프트웨어가 enable한다.","ECRC enable 비트는 PCI Express Capability의 Device Control에만 있고 AER와는 무관하다.","ECRC 검사는 AER Header Log가 있는 Root Port에서만 허용된다."],["A device that supports ECRC must not implement AER.","A device that can generate or check ECRC must implement AER in at least one Function. Software turns generation and checking on.","The ECRC enable bits exist only in the PCI Express Capability Device Control register and are unrelated to AER.","ECRC checking is permitted only on a Root Port that has an AER Header Log."],1,"ECRC Generation/Check Capable 및 Enable 비트는 Advanced Error Capabilities and Control register(§7.8.4.7)에 있습니다. 생성 enable이면 해당 Function이 출발시키는 모든 TLP에 ECRC를 붙여야 합니다.","The ECRC Generation/Check Capable and Enable bits live in the Advanced Error Capabilities and Control register (section 7.8.4.7). If generation is enabled, the Function must apply ECRC to every TLP it originates.","§2.7.1"],["p8q20","p8_5",2,"C","ECRC 계산에 쓰이는 다항식과 seed, 그리고 최종 처리로 옳은 것은?","Which statement correctly describes the ECRC polynomial, seed, and final treatment of the result?",["16-bit CRC-CCITT이며, seed는 0000h이고 결과는 complement하지 않는다.","32-bit이며 다항식은 1EDC6F41h, seed는 00000000h이고 결과는 그대로 사용한다.","8-bit checksum을 header에만 적용하고 seed는 요구되지 않는다.","32-bit ECRC이며, 다항식 계수는 04C11DB7h, seed는 FFFFFFFFh이고, 계산 결과를 complement한 뒤 TLP의 ECRC 필드에 넣는다."],["It is 16-bit CRC-CCITT, the seed is 0000h, and the result is not complemented.","It is 32-bit with polynomial 1EDC 6F41h and seed 0000 0000h, used without complementing.","It is an 8-bit checksum over the header only, and no seed is required.","It is a 32-bit ECRC. The polynomial coefficients are 04C1 1DB7h, the seed is FFFF FFFFh, and the calculated result is complemented before it is mapped into the TLP ECRC field."],3,"계산은 byte 0의 bit 0부터 각 byte의 bit 0→7 순으로 진행됩니다. 비트 배치 매핑은 Table 2-55를 따릅니다.","The CRC walks each TLP byte from the least-significant bit to the most-significant bit, beginning at the first byte. Table 2-55 maps the complemented result into the 32-bit field.","§2.7.1"],["p8q21","p8_5",2,"C","Function이 ECRC 검사가 enable되어 있을 때, ECRC가 없는 TLP를 최종 Receiver로서 받은 경우의 처리는?","If ECRC checking is enabled, how must a Function treat a received TLP that has no ECRC, when it is the ultimate Receiver?",["반드시 ECRC Check Failed로 보고하고 TLP를 폐기한다.","Unsupported Request로 완료해야 한다.","정상적으로 처리하며, 이것은 오류가 아니다.","Malformed TLP로 보고하고 Link를 disable해야 한다."],["It must report ECRC Check Failed and drop the TLP.","It must complete the TLP as an Unsupported Request.","It processes the TLP normally — this is not an error.","It must report a Malformed TLP and disable the Link."],2,"검사가 enable되어 있으면, ECRC가 붙어 있고 자신이 최종 PCI Express Receiver인 TLP에 대해서는 검사를 해야 합니다. ECRC가 없는 TLP는 그 대상이 아닙니다.","When checking is enabled, the Function must check every TLP that has ECRC and for which it is the ultimate PCI Express Receiver. A TLP without ECRC is simply not in that set.","§2.7.1"],["p8q22","p8_5",2,"C","Switch의 ECRC 전달/검사 규칙으로 옳은 것은? (non-IDE, FM/NFM translation이 없는 경우)","Which Switch rule for ECRC is correct for non-IDE TLPs that do not require FM/NFM translation?",["Ingress에서 Egress로 ECRC를 그대로 통과시켜야 한다. 통과 TLP에 대한 ECRC 검사는 선택이며, 탐지한 오류는 보고하지만 TLP의 통과 자체를 바꿔서는 안 된다.","모든 통과 TLP의 ECRC를 제거하고 재생성해야 한다.","ECRC 오류가 있으면 해당 TLP를 반드시 폐기해야 한다.","Switch는 ECRC를 검사하거나 전달해서는 안 된다."],["The Switch must pass TLPs with ECRC unchanged from Ingress to Egress. Checking ECRC on forwarded TLPs is optional; a detected error is reported but must not alter the TLP's passage through the Switch.","The Switch must strip and regenerate ECRC on every forwarded TLP.","The Switch must drop any TLP that fails ECRC.","A Switch must never check or forward ECRC."],0,"IDE TLP에는 ECRC가 지원되지 않습니다. FM/NFM translation이 필요하면 변환된 TLP에 ECRC를 적용하되, Ingress–Egress 사이 오류 검출 능력은 유지해야 합니다. Multicast의 MC_Overlay는 예외로 따로 규정됩니다.","ECRC is not supported on IDE TLPs. If FM/NFM translation is required, the Switch must apply ECRC to the translated TLP while preserving end-to-end error detection between Ingress and Egress. Multicast MC_Overlay is a documented exception.","§2.7.1"],["p8q23","p8_5",3,"C","ECRC 계산에 포함되는 범위와 Variant bit 처리로 옳은 것은?","Which statement about the coverage of the ECRC calculation and Variant bits is correct?",["Local TLP Prefix만 포함하고 header와 payload는 제외한다. Variant bit는 수신 값 그대로 사용한다.","Flit Mode Trailer까지 항상 포함하며 Variant bit는 Clear로 취급한다.","오직 data payload만 포함하고 prefix와 header는 제외한다.","header, End-End TLP Prefix/OHC, data payload는 포함하고, Local TLP Prefix는 포함하지 않는다. 모든 Variant bit는 계산 시 Set으로 취급한다."],["Only Local TLP Prefixes are included; the header and payload are excluded. Variant bits are used as received.","The Flit Mode Trailer is always included, and Variant bits are treated as Clear.","Only the data payload is included; prefixes and the header are excluded.","The header, End-End TLP Prefixes/OHC, and data payload are included; Local TLP Prefixes are not. All Variant bits must be treated as Set for the calculation."],3,"Variant bit에는 Type 필드의 bit 0(Type 1→Type 0 변환 때 바뀜)과 EP bit(또는 Reserved)가 들어갑니다. 위치는 Non-Flit Mode와 Flit Mode에서 header symbol이 다릅니다. Flit Mode에서는 Trailer를 ECRC 입력에 넣지 않습니다.","Variant bits include bit 0 of the Type field (which changes when a Type 1 Configuration Request becomes Type 0) and the EP bit (or a Reserved bit). Their header-symbol positions differ between Non-Flit Mode and Flit Mode. In Flit Mode the Trailer is not part of the ECRC input.","§2.7.1"],["p8q24","p8_5",2,"C","Non-Flit Mode와 Flit Mode에서 32-bit ECRC 값이 놓이는 위치는?","Where is the 32-bit ECRC value placed in Non-Flit Mode versus Flit Mode?",["두 Mode 모두 TLP header의 첫 DW에 놓인다.","Non-Flit Mode에서는 TLP Digest 필드에, Flit Mode에서는 TLP Trailer에 놓인다.","Non-Flit Mode에서는 Trailer에, Flit Mode에서는 Local Prefix에 놓인다.","두 Mode 모두 DLLP에 실어 별도로 보낸다."],["In both modes it is placed in the first DW of the TLP header.","Non-Flit Mode stores the 32-bit value in the TLP Digest that follows the TLP. Flit Mode stores it in the Trailer.","In Non-Flit Mode it is placed in a Trailer, and in Flit Mode in a Local Prefix.","In both modes it is sent separately in a DLLP."],1,"최종 Receiver가 end-to-end 무결성 검사를 지원하면, 받은 TLP(Digest/해당 필드 제외)에 같은 알고리즘을 적용해 비교하고, 불일치 시 ECRC Error를 보고합니다. 이 오류는 Receiving Port와 연관됩니다.","A Receiver that supports end-to-end checking applies the same algorithm to the received TLP, excluding the Digest (or equivalent) field, and reports an ECRC Error on a mismatch. That reported error is associated with the Receiving Port.","§2.7.1"],["p8q25","p8_6",2,"P","DPC(Downstream Port Containment)의 기본 enable 조건과 Trigger Enable 필드 의미로 옳은 것은?","Which statement about DPC enablement and the DPC Trigger Enable field is correct?",["DPC는 모든 Downstream Port에서 항상 enable되어 있고 Trigger Enable 필드는 없다.","DPC는 기본적으로 disable이며, 소프트웨어가 DPC Trigger Enable로 켜기 전에는 trigger되지 않는다. 01b이면 unmasked uncorrectable error 또는 ERR_FATAL 수신 시, 10b이면 여기에 ERR_NONFATAL 수신까지 포함해 trigger된다.","Trigger Enable 01b는 correctable error만, 10b는 Advisory error만 trigger한다.","DPC는 Upstream Port 전용 기능이며 Downstream Port에는 구현할 수 없다."],["DPC is always enabled on every Downstream Port and has no Trigger Enable field.","DPC is disabled by default and cannot be triggered until software enables it with the DPC Trigger Enable field. When that field is 01b, DPC triggers on an unmasked uncorrectable error or an ERR_FATAL Message. When it is 10b, receipt of ERR_NONFATAL also triggers DPC.","Trigger Enable 01b triggers only on correctable errors, and 10b only on advisory errors.","DPC is an Upstream Port-only feature and cannot be implemented in a Downstream Port."],1,"DPC는 Downstream Port의 optional normative 기능이며, DPC Extended Capability(§7.9.14)로 지원 여부와 제어/상태를 나타냅니다. 소프트웨어/펌웨어가 직접 trigger하는 경로(§6.2.11.4)도 있습니다.","DPC is an optional normative Downstream Port feature. A DPC Extended Capability (section 7.9.14) carries its controls and status. Software or firmware can also trigger DPC (section 6.2.11.4).","§6.2.11"],["p8q26","p8_6",2,"P","DPC가 trigger된 직후 Downstream Port의 Link/LTSSM 동작으로 옳은 것은?","Right after DPC is triggered, what happens to the Downstream Port's Link and LTSSM?",["LTSSM을 즉시 L0로 강제하고 Configuration을 다시 시작한다.","LTSSM을 Loopback으로 보내고, Trigger Status는 Clear된 뒤에만 Disabled로 간다.","Link는 그대로 L0를 유지하고, 소프트웨어가 Link Disable을 쓸 때만 내려간다.","DPC Trigger Status를 Set하고 LTSSM을 Disabled state로 보낸다. LTSSM은 DPC Trigger Status가 Clear될 때까지 Disabled에 머문다. 소프트웨어는 Data Link Layer Link Active가 0b가 될 때까지 DPC에 남겨 두어야 하며, 그렇지 않으면 결과는 undefined이다."],["The LTSSM is forced immediately to L0 and Configuration is restarted.","The LTSSM is sent to Loopback, and only later to Disabled after Trigger Status is Cleared.","The Link stays in L0 until software uses Link Disable.","The Port Sets DPC Trigger Status and directs the LTSSM to Disabled. The LTSSM remains in Disabled until DPC Trigger Status is Cleared. Software must leave the Port in DPC until Data Link Layer Link Active reads 0b; otherwise the result is undefined."],3,"RP Extensions for DPC를 지원하는 Root Port는 DPC RP Busy가 1인 동안에도 소프트웨어가 DPC를 해제하면 안 됩니다. 해제 후에는 다른 disable 조건이 없는 한 LTSSM이 Detect로 가며 retraining을 시도합니다.","On a Root Port with RP Extensions for DPC, software must also wait until DPC RP Busy reads 0b. After release, the LTSSM must go to Detect and try to retrain, unless some other condition keeps the Link disabled.","§6.2.11"],["p8q27","p8_6",3,"P","DPC가 uncorrectable error Message 수신으로 trigger된 경우, 그 Message와 원래 uncorrectable 보고에 대한 규칙으로 옳은 것은?","If DPC is triggered by receipt of an uncorrectable error Message, what happens to that Message and to uncorrectable error signaling?",["Message의 Requester ID는 DPC Error Source ID Register에 기록되고, 그 Message는 discard되어 Upstream으로 전달되지 않는다. DPC를 trigger한 unmasked uncorrectable error는 uncorrectable Error Message로 알리지 않는다. 대신 enable되어 있으면 interrupt나 ERR_COR를 쓸 수 있다.","그 Message는 그대로 Upstream으로 전달되고, 추가로 항상 ERR_FATAL을 한 번 더 보낸다.","Requester ID는 기록하지 않고, 해당 Message만 반복 재전송한다.","DPC가 trigger되면 모든 이전 AER 로그가 지워지고 Error Message 보고는 금지된다."],["The Port logs that Message's Requester ID in DPC Error Source ID, then drops the Message instead of forwarding it Upstream. The unmasked uncorrectable error that caused DPC is not reported with an uncorrectable Error Message. If enabled, DPC may still raise an interrupt or an ERR_COR.","The Message is forwarded Upstream unchanged, and an extra ERR_FATAL is always sent as well.","The Requester ID is not recorded, and only that Message is retried repeatedly.","Triggering DPC clears all prior AER logs, and Error Messages are forbidden afterward."],0,"이렇게 하면 이미 containment가 시작된 뒤, 같은 사건을 uncorrectable Message로 다시 올려 상위 계층을 이중으로 자극하는 일을 피합니다. 소프트웨어는 ERR_COR나 interrupt로 DPC 사실을 알 수 있습니다.","This avoids a second uncorrectable Message continuing Upstream after containment has already started. Software can still learn that DPC triggered through an interrupt or an ERR_COR.","§6.2.11"],["p8q28","p8_6",2,"P","DPC 중에 Downstream Port가 받은 Non-Posted Request 또는 UIO Request에 대한 응답 규칙은?","During DPC, how does a Downstream Port respond to a Non-Posted Request or a UIO Request it needs to complete?",["항상 Successful Completion과 all 0 data를 반환한다.","Completion을 보내지 않고 Timeout만 기다린다.","Request를 silently discard하고 Completion을 반환한다. DPC Completion Control이 Set이면 UR, Clear이면 CA Completion Status를 쓴다. Completer ID는 그 Downstream Port의 값을 넣는다.","DPC Completion Control이 Set이면 CA, Clear이면 UR를 반환한다."],["The Port always returns a Successful Completion with all-0 data.","The Port sends no Completion and only waits for a timeout.","The Port silently discards the Request and returns a Completion. If DPC Completion Control is Set, the Completion Status is UR; if it is Clear, the Status is CA. The Completer ID must be the Downstream Port's value.","If DPC Completion Control is Set the Status is CA, and if it is Clear the Status is UR."],2,"그 밖의 Posted Request와 Completion은 silently discard합니다. 구현 노트는 CER(Containment Error Recovery) 전략에 따라 UR(종종 all 1's 합성) 또는 CA를 고르라고 안내합니다. 극성(Set=UR, Clear=CA)을 반대로 외우지 않는 것이 퀴즈 포인트입니다.","All other Posted Requests and Completions are silently discarded. An implementation note discusses choosing UR (often with an all-1's PIO synthesis) or CA based on the platform's Containment Error Recovery policy. The polarity — Set means UR, Clear means CA — is a common point of confusion.","§2.9.3"],["p8q29","p8_6",3,"P","DL_ACTIVE ERR_COR signaling에 대한 설명으로 옳은 것은?","Which statement about DL_ACTIVE ERR_COR signaling is correct?",["DL_Active 진입 시 항상 ERR_FATAL을 보낸다.","이 기능은 Data Link Layer State Changed interrupt와 동시에 사용하는 것이 금지된다.","ERR_COR를 보낼 때 반드시 Correctable Error Detected bit를 Set해야 한다.","해당 enable 조건이 맞으면, Link가 DL_Active로 들어갈 때마다 ERR_COR Message를 보내야 한다. 이 signaling은 오류로 다루지 않으므로 Device Status의 Correctable Error Detected bit를 Set하면 안 된다."],["The Port always sends ERR_FATAL on entry to DL_Active.","This feature must not be used at the same time as Data Link Layer State Changed interrupts.","Sending this ERR_COR must also Set the Correctable Error Detected bit.","Under the listed enables, every entry into DL_Active produces an ERR_COR. Device Status.Correctable Error Detected stays clear because this event is not treated as an error."],3,"지원 여부는 DPC Capability의 DL_Active ERR_COR Signaling Supported로, enable은 DPC Control의 DL_ACTIVE ERR_COR Enable로 표시됩니다. DLL State Changed interrupt와는 독립이며 동시 사용이 허용됩니다. DPC 해제 후 Link가 다시 올라왔는지 소프트웨어가 보는 수단입니다.","Support is indicated by DL_Active ERR_COR Signaling Supported, and the feature is enabled by DL_ACTIVE ERR_COR Enable. It is managed independently of Data Link Layer State Changed interrupts, and both may be used together. It tells software when the Link has come back up after DPC is released.","§6.2.11.5"],["p8q30","p8_7",2,"P","Surprise Down error의 기본 심각도와 탐지 시 동작(관련 검사가 켜져 있을 때)으로 옳은 것은?","What is the default severity of a Surprise Down error, and what action is taken when checking is enabled?",["기본 심각도는 Correctable이며, 항상 ERR_COR만 보낸다.","기본 심각도는 Fatal이다(AER Severity bit 기본값 1b). 검사가 켜져 있으면 ERR_FATAL을 Root Complex로 보낸다.","기본 심각도는 Non-Fatal이며, 항상 Advisory로만 처리한다.","Surprise Down은 status bit만 있고 Error Message는 정의되어 있지 않다."],["The default severity is Correctable, and only ERR_COR is ever sent.","The default severity is Fatal (the AER Severity bit defaults to 1b). If checking, the agent sends ERR_FATAL to the Root Complex.","The default severity is Non-Fatal, and the case is always handled as advisory.","Surprise Down has only a status bit; no Error Message is defined."],1,"Table 6-4의 Data Link Layer 오류 목록에 Surprise Down이 들어 있고, 참조는 §3.2.1입니다. AER Uncorrectable Error Severity의 Surprise Down Error Severity 기본값이 1b(Set이면 Fatal)인 점으로도 기본 심각도를 확인할 수 있습니다.","Table 6-4 lists Surprise Down among Data Link Layer errors, citing section 3.2.1. The AER Uncorrectable Error Severity bit for Surprise Down defaults to 1b, and a Set severity bit means Fatal.","§6.2.7"],["p8q31","p8_7",2,"P","Surprise Down Error Reporting Capable인 Downstream Port는, 어떤 Link 상태 전이를 Surprise Down error로 다루어야 하나요? (예외 조건은 §3.2.1에 따름)","A Downstream Port that is Surprise Down Error Reporting Capable must treat which Link-state transition as a Surprise Down error (subject to the exceptions in section 3.2.1)?",["L0에서 L0s로의 전이","Detect.Quiet에서 Detect.Active로의 전이","DL_Active에서 DL_Inactive로의 전이","Configuration에서 L0로의 전이"],["The transition from L0 to L0s","The transition from Detect.Quiet to Detect.Active","The transition from DL_Active to DL_Inactive","The transition from Configuration to L0"],2,"정상적인 disable, hot-plug 제거 시퀀스 등에는 예외가 적용됩니다. 능력 비트는 Link Capabilities의 Surprise Down Error Reporting Capable(bit 19)로 나타냅니다. AER Status bit 5가 해당 오류의 status입니다.","Exceptions cover cases such as an orderly disable or a hot-plug removal sequence. Capability is advertised by Surprise Down Error Reporting Capable (bit 19) in Link Capabilities. AER status bit 5 is the corresponding error status.","§3.2.1"],["p8q32","p8_7",3,"P","Slot Capabilities의 Hot-Plug Surprise 비트가 Set되어 있으면, Surprise Down 보고와 DPC에 어떤 영향이 있나요?","When Slot Capabilities has Hot-Plug Surprise Set, how does that affect Surprise Down reporting and DPC?",["Surprise Down error 보고가 막혀, 이 중요한 오류로 DPC가 trigger되는 것이 차단된다. 두 메커니즘을 모두 지원하는 slot은 스펙의 관련 지침을 따라야 한다.","Surprise Down의 기본 심각도가 Correctable로 바뀐다.","DPC Trigger Enable이 하드웨어적으로 10b로 고정된다.","Surprise Down이 발생하면 자동으로 Attention Indicator만 깜빡이고 보고는 그대로이다."],["Surprise Down reporting is suppressed, so DPC will not fire on that event. A slot that implements both features should follow the guidance in the specification.","The default severity of Surprise Down changes to Correctable.","DPC Trigger Enable is hard-wired to 10b.","A Surprise Down event only blinks the Attention Indicator, and reporting is unchanged."],0,"Hot-Plug Surprise는 ‘예고 없이 제거될 수 있는 폼팩터’를 나타내는 비트라, 그 자체로 Surprise Down을 오류로 보고하지 않게 만듭니다. DPC의 핵심 가치 중 하나가 갑작스러운 Link down의 containment이므로, 두 기능을 함께 쓸 때는 §6.7.4.5 지침이 중요합니다.","Hot-Plug Surprise marks a form factor that can be removed without notice, and it therefore suppresses Surprise Down as a reported error. One of DPC's main benefits is containing a sudden Link down, so section 6.7.4.5 matters when both features are present.","§6.2.11"],["p8q33","p8_8",2,"P","Flit Logging Extended Capability의 구현 위치와 Mode에 대한 규칙으로 옳은 것은?","Which rule about where Flit Logging Extended Capability is implemented, and in which mode it is used, is correct?",["Flit Mode를 지원하는 Port와 RCRB에는 이 capability를 반드시 구현해야 한다. Upstream Port의 Function들에서는 Function 0에만 구현해야 하고 다른 Function에는 구현하면 안 된다. Non-Flit Mode에서는 효과가 없다.","모든 Function(Function 0 포함 여부와 무관)에 반드시 구현해야 하며 Non-Flit Mode에서만 동작한다.","Root Port에만 선택적으로 구현하며 Endpoint에는 구현할 수 없다.","Switch Downstream Port에서만 필수이고, Upstream Port에는 구현하면 안 된다."],["Every Port or RCRB that supports Flit Mode is required to include this capability. On an Upstream Port it belongs only in Function 0 — other Functions of that Port must not have it. In Non-Flit Mode it does nothing.","It MUST be implemented in every Function regardless of Function 0, and it operates only in Non-Flit Mode.","It is optional and only on Root Ports; Endpoints must not implement it.","It is required only on Switch Downstream Ports and must not be implemented on an Upstream Port."],0,"Extended Capability ID는 0032h이고, 이 버전에서 Capability Version은 1h여야 합니다. Flit Mode 오류(FEC/CRC)를 소프트웨어가 볼 수 있게 하는 로그/카운터/FBER 측정 register를 제공합니다.","The Extended Capability ID is 0032h, and the Capability Version must be 1h for this version of the specification. The structure gives software log, counter, and FBER measurement registers for Flit Mode FEC/CRC events.","§7.7.9"],["p8q34","p8_8",2,"P","Flit Error Log 1/2 Register가 기록하는 내용과 로그 구조의 특징으로 옳은 것은?","What do the Flit Error Log 1 and 2 registers record, and how is the log structured?",["송신 측에서만 계산한 ECRC 실패 header를 하나만 저장하는 Function-level register이다.","AER Header Log의 별칭이며, TLP header 16바이트만 저장한다.","수신 Flit에서 FEC 및/또는 CRC가 교정하거나 탐지한 Flit error 정보를 담는 Link-level register이다. Flit Error Log는 구현이 정하는 크기의 FIFO이며, 크기 1도 허용된다. 이 register들은 가장 오래된 항목을 보여 준다.","LTSSM state 이력을 순환 버퍼에 무한히 저장하며 FIFO가 아니다."],["They are Function-level registers that store only one ECRC-failure header computed on the transmit side.","They are an alias of the AER Header Log and store only 16 bytes of TLP header.","These Link-level registers capture Flit errors that FEC and/or CRC corrected or detected. The log is a FIFO whose depth is implementation-defined and may be only one entry. The registers show the oldest recorded item.","They are an infinite circular buffer of LTSSM state history, not a FIFO."],2,"Flit Error Log Valid에 1을 쓰면 가장 오래된 항목이 제거되고, 다음 항목이 있으면 그 값이 load됩니다. More Entries 비트가 그 여부를 알려 줍니다.","Writing 1b to Flit Error Log Valid removes the oldest entry and, if another entry exists, loads these registers with the next oldest one. The More Entries bit indicates whether another entry is waiting.","§7.7.9.2"],["p8q35","p8_8",3,"P","Flit Error Log 1의 Flit Error Link Width 필드 인코딩으로 옳은 것은?","Which encoding of the Flit Error Link Width field in Flit Error Log 1 is correct?",["000b=x16, 001b=x8, 010b=x4, 011b=x2, 100b=x1이며 L0p와 무관하다.","000b=x1, 001b=x2, 010b=x4, 011b=x8, 100b=x16 (나머지는 Reserved). L0p로 좁아진 폭을 반영한다.","필드 값 자체가 lane 수와 같아서 1=x1, 16=x16이다.","이 필드는 항상 000b로 hardwired이며 폭 정보를 제공하지 않는다."],["000b = x16, 001b = x8, 010b = x4, 011b = x2, 100b = x1, ignoring L0p.","x1 is encoded 000b, x2 is 001b, x4 is 010b, x8 is 011b, and x16 is 100b; any other encoding is Reserved. The field reflects width after any L0p narrowing.","The field value equals the lane count directly, so 1 means x1 and 16 means x16.","The field is hard-wired to 000b and never reports width."],1,"속성은 ROS이고 기본값은 0입니다. 오류가 난 순간의 Link 폭을 남겨, 나중에 FBER/로그를 해석할 때 폭 변화를 고려할 수 있게 합니다.","The field is ROS and defaults to zero. It records the Link width at the time of the error so later analysis of the log or FBER data can take width changes into account.","§7.7.9.2"],["p8q36","p8_8",2,"P","FBER Measurement Status 3부터 10 Register의 Lane 번호에 대한 스펙의 권고는?","What does the specification strongly recommend about the Lane numbers in FBER Measurement Status registers 3 through 10?",["항상 Logical Lane 0만 기록해야 한다.","소프트웨어가 임의로 부여한 virtual lane ID여야 한다.","이 register들은 Lane 번호를 포함해서는 안 된다.","Physical Lane Number일 것을 강하게 권고한다."],["They must always record only Logical Lane 0.","They must be a software-assigned virtual lane ID.","These registers must not contain a Lane number.","They are strongly recommended to be the Physical Lane Number."],3,"Flit Logging 구조에는 FBER Measurement Control과 Status 1–10이 포함됩니다. Physical Lane Number를 쓰면, L0p나 lane reversal 이후에도 측정치를 실제 물리 lane과 대응하기 쉽습니다.","The Flit Logging structure includes FBER Measurement Control and Status 1–10. Using the Physical Lane Number makes it easier to relate measurements to real lanes after L0p or lane reversal.","§7.7.9"],["c8q01","c8_1",1,"X","CXL RAS 기능 표에서 CXL Isolation은 어떻게 분류되나요?","In the CXL RAS feature table, how is CXL Isolation classified?",["CXL.cache/CXL.mem에는 optional, CXL.io에는 해당 없음(N/A)","CXL.io에서만 required","CXL.cache/CXL.mem에서 required, CXL.io에서 optional","CXL.io와 CXL.cache/CXL.mem 모두 required"],["Optional for CXL.cache/CXL.mem, not applicable (N/A) to CXL.io","Required only for CXL.io","Required for CXL.cache/CXL.mem, optional for CXL.io","Required for both CXL.io and CXL.cache/CXL.mem"],0,"Isolation은 CXL.cache/CXL.mem 전용 기능이고 선택 사항이에요. CXL.io 쪽 칸은 N/A예요.","Isolation is a CXL.cache/CXL.mem-only feature and it is optional. The CXL.io column says N/A.","§12.1"],["c8q02","c8_1",1,"C","CXL.io와 CXL.cache/CXL.mem 양쪽에서 모두 required로 표시된 링크 신뢰성 기능은 무엇인가요?","Which link reliability feature is marked required for both CXL.io and CXL.cache/CXL.mem?",["CXL Isolation","ECRC","Link CRC and Retry","eDPC"],["CXL Isolation","ECRC","Link CRC and Retry","eDPC"],2,"Link CRC/Retry와 Link Retraining은 두 쪽 모두 required예요. PCIe 링크에도 같은 개념이 있어요. ECRC와 eDPC는 optional 또는 N/A이고, Isolation은 cachemem 전용이에요.","Link CRC/Retry and link retraining are required on both sides, as on a PCIe link. ECRC and eDPC are optional or N/A, and Isolation is cachemem-only.","§12.1"],["c8q03","c8_1",1,"C","CXL.io와 CXL.cache/CXL.mem 모두에서 required인 데이터 containment 수단은 무엇인가요?","Which data containment mechanism is required for both CXL.io and CXL.cache/CXL.mem?",["CXL Isolation","Viral","ECRC","Data Poisoning"],["CXL Isolation","Viral","ECRC","Data Poisoning"],3,"Data Poisoning은 PCIe와 CXL 모두에 있는 개념이고, 표에서 양쪽 다 required예요. Viral은 cachemem에서만 required이고 CXL.io는 N/A예요.","Data poisoning exists in both PCIe and CXL and is required on both sides. Viral is required only for cachemem; CXL.io is N/A.","§12.1"],["c8q04","c8_1",2,"X","PCIe의 ECRC는 CXL에서 어떻게 적용되나요?","How does PCIe ECRC apply in CXL?",["CXL.io와 CXL.cache/CXL.mem 모두 required","CXL.cache/CXL.mem에서만 required","CXL.io에서는 optional, CXL.cache/CXL.mem에는 해당 없음","CXL에서는 사용이 금지됨"],["Required for both CXL.io and CXL.cache/CXL.mem","Required only for CXL.cache/CXL.mem","Optional for CXL.io, not applicable to CXL.cache/CXL.mem","Prohibited in CXL"],2,"ECRC는 TLP 단위 기능이라 CXL.io에서만 의미가 있고 optional이에요. cachemem 칸은 N/A예요.","ECRC is a TLP-level feature, so it only makes sense for CXL.io, where it is optional. The cachemem column is N/A.","§12.1"],["c8q05","c8_1",2,"X","CXL RAS 표에 따르면 Hot-Plug 지원은 어떻게 되나요?","According to the CXL RAS table, what is the Hot-Plug support?",["RCD mode에서만 지원","CXL.cache/CXL.mem은 Hot-Plug를 지원하지 않고 CXL.io만 지원","RCD mode에서는 지원하지 않고, CXL VH mode에서는 managed Hot-Plug를 지원","모든 mode에서 surprise Hot-Plug가 필수"],["Supported only in RCD mode","Only CXL.io supports Hot-Plug; CXL.cache/CXL.mem do not","Not supported in RCD mode; managed Hot-Plug supported in CXL VH mode","Surprise Hot-Plug is mandatory in every mode"],2,"RCD mode는 Hot-Plug를 지원하지 않아요. CXL VH mode는 managed Hot-Plug를 지원하고, cachemem 쪽도 CXL.io와 같아요.","RCD mode does not support Hot-Plug. CXL VH mode supports managed Hot-Plug, and cachemem follows CXL.io.","§12.1"],["c8q06","c8_2",1,"X","CXL 장치와 Host는 protocol/link error를 어떻게 주고받나요?","How do a CXL device and the Host exchange protocol/link errors?",["SMBus 같은 sideband로만 전달한다","CXL.mem 응답의 전용 error opcode로만 전달한다","CXL.io 위의 메시지로 전달한다 (전용 error pin은 없음)","장치와 Host 사이의 전용 error pin으로 전달한다"],["Only through a sideband such as SMBus","Only through dedicated error opcodes in CXL.mem responses","Through messages over CXL.io; there are no dedicated error pins","Through dedicated error pins between device and Host"],2,"CXL에는 Host와 장치를 잇는 error pin이 없어요. 오류는 CXL.io 메시지로 Host에 전달돼요.","CXL has no error pins between Host and device. Errors reach the Host as CXL.io messages.","§12.2.1"],["c8q07","c8_2",2,"C","CXL VH에 속한 component가 검출한 CXL protocol/link error는 어떻게 보고되나요?","How are CXL protocol/link errors detected by a component in a CXL VH reported?",["CXL 전용 인터럽트 선으로 Host에 직접 알린다","CXL.io 위에서 PCIe 표준 오류 보고(AER)로 UIE/CIE로 보고한다","Viral만 보내고 AER는 쓰지 않는다","장치 내부에만 기록하고 Host에는 보고하지 않는다"],["Through a CXL-specific interrupt wire straight to the Host","As UIEs/CIEs via standard PCIe error reporting (AER) over CXL.io","Only Viral is sent; AER is not used","Logged inside the device only, never reported to the Host"],1,"VH에서는 PCIe 오류 보고 체계를 그대로 써요. CXL 오류는 uncorrectable/correctable internal error로 AER에 올라가요.","In a VH the PCIe error reporting scheme is reused. CXL errors show up in AER as uncorrectable/correctable internal errors.","§12.2.1"],["c8q08","c8_2",1,"X","RCD mode에서 RCiEP가 만든 오류는 어디로 보내지나요?","In RCD mode, where are errors generated by an RCiEP sent?",["Switch USP의 Mailbox CCI","장치 Mailbox에만 기록되고 끝난다","Fabric Manager","해당 RCEC (RCiEP 하나는 RCEC 최대 하나와 연결)"],["The Mailbox CCI of a switch USP","Only the device Mailbox, and nowhere else","The Fabric Manager","The corresponding RCEC (each RCiEP is tied to at most one RCEC)"],3,"RCD RCiEP 오류는 대응하는 RCEC로 가요. RCiEP 하나는 RCEC를 하나까지만 가질 수 있어요. VH component 오류는 CXL Root Port에 기록돼요.","RCD RCiEP errors go to the matching RCEC, and each RCiEP has at most one RCEC. VH component errors are logged in the CXL Root Port.","§12.2.3.3"],["c8q09","c8_2",3,"X","RCH Downstream Port가 검출한 오류가 RCEC에 기록될 때, RCEC Error Source Identification register에는 무엇이 남나요?","When an RCH Downstream Port-detected error is logged at the RCEC, what does the RCEC Error Source Identification register hold?",["항상 0","RCEC 자신의 Bus/Device/Function 번호 (RCH DP에는 BDF가 없기 때문)","RCH Downstream Port의 BDF","장치의 LD-ID"],["Always zero","The RCEC's own Bus/Device/Function numbers, since the RCH DP has none","The BDF of the RCH Downstream Port","The device's LD-ID"],1,"RCH DP에는 BDF가 없어서 RCEC 자기 BDF가 기록돼요. 그래서 이 값만으로는 원인 포트를 알 수 없고, OS는 RDPAS 구조를 참고할 수 있어요.","The RCH DP has no BDF, so the RCEC logs its own. That alone cannot identify the source port; the OS may use RDPAS structures.","§12.2.1.1"],["c8q10","c8_3",1,"X","CXL 장치가 demand read 중 uncorrected memory error를 만나면 무엇을 해야 하나요?","A CXL device hits an uncorrected memory error on a demand read. What must it do?",["항상 Viral을 발생시킨다","요청을 조용히 버린다","데이터를 poison 표시해서 돌려준다","정상 데이터처럼 돌려주고 나중에 MSI로 알린다"],["Always raise Viral","Silently drop the request","Return the data marked as poisoned","Return it as good data and notify later via MSI"],2,"demand access의 uncorrected 오류는 poison으로 돌려주고, 처리는 요청자(core 등) 몫이에요. poison과 함께 별도 uncorrected error를 알리지 않는 것이 권고예요.","For a demand access, the device returns poisoned data and the requester handles it. It should not also signal an uncorrected error alongside the poison.","§12.2.3.1"],["c8q11","c8_3",1,"X","CXL 장치는 받은 poison 데이터를 어떤 단위로 추적해야 하나요?","At what granularity must a CXL device track poisoned data it receives?",["4 KB page","256B flit","1 byte","64 byte"],["4 KB pages","256B flits","1 byte","64 bytes"],3,"장치는 받은 poison 데이터를 64 byte 단위로 추적해야 해요. 무시하면 Silent Data Corruption이 생길 수 있어요.","The device must track received poison at 64-byte granularity. Ignoring it can lead to silent data corruption.","§12.2.3"],["c8q12","c8_3",2,"X","Memory Error Logging and Signaling Enhancements를 지원하지 않는 장치에서, scrub logic이 찾은 non-demand uncorrected error는 어떻게 알려지나요?","On a device without Memory Error Logging and Signaling Enhancements, how is a non-demand uncorrected error found by scrub logic signaled?",["장치 MSI/MSI-X로 device driver에 알린다","항상 ERR_FATAL로 platform에 알린다","Viral로 모든 하위 장치에 전파한다","알리지 않는다"],["To the device driver via device MSI/MSI-X","Always reported to the platform as ERR_FATAL","Propagated via Viral to all downstream devices","It is not reported"],0,"이 경우 오류는 MSI/MSI-X로 device driver에 가요. platform firmware나 OS가 직접 다루지 않아요.","In this case the error goes to the device driver via MSI/MSI-X. Platform firmware and the OS do not handle it directly.","§12.2.3.1"],["c8q13","c8_3",2,"X","장치 오류 분류 표에서 containment 위험이 있는 Uncorrected Fatal 오류(예: command/parity error)의 signaling은?","In the device error table, how is an Uncorrected Fatal error that risks containment (e.g., command/parity error) signaled?",["Device driver에 MSI만 보낸다","PCIe AER Internal Error와 Viral","Poison만 붙이고 따로 알리지 않는다","Correctable error로 기록한다"],["Only an MSI to the device driver","PCIe AER Internal Error plus Viral","Only poison, with no separate signal","Logged as a correctable error"],1,"Fatal 행은 AER Internal Error에 Viral이 더해지고, system FW/SW Viral flow로 처리돼요.","The Fatal row uses AER Internal Error plus Viral and is handled by the system FW/SW Viral flow.","§12.2.3"],["c8q14","c8_3",3,"X","HDM Decoder를 구현하지 않은 component가 positive decode하지 못한 CXL.mem 요청을 받으면?","A component without HDM Decoders gets a CXL.mem request it cannot positively decode. What happens?",["링크를 Isolation 상태로 바꾼다","write는 버리고, read에는 모두 1을 돌려준다","read와 write 모두 poison과 Viral을 발생시킨다","다음 component로 그대로 forwarding한다"],["The link is put into Isolation","Writes are dropped and reads return all 1s","Both reads and writes raise poison and Viral","It is forwarded unchanged to the next component"],1,"HDM Decoder가 없으면 decode되지 않은 write는 버리고 read에는 all 1s를 돌려줘요. Decoder가 있는 경우의 처리는 §8.2.4.20.2에 있어요.","Without HDM Decoders, an undecoded write is dropped and a read returns all 1s. The case with decoders is in §8.2.4.20.2.","§12.2.3.1"],["c8q15","c8_4",1,"X","Memory Error Logging 기능이 있는 장치에서 Get Event Records로 오류 레코드를 읽으면, 그 레코드는 어떻게 되나요?","On a device with Memory Error Logging, what happens to an error record after it is read with Get Event Records?",["장치에 남아 있고, Clear Event Records로 명시적으로 지워야 한다","읽는 순간 자동으로 지워진다","다음 FLR 때 자동으로 지워진다","Host 메모리로 자동 이동된다"],["It stays on the device until explicitly cleared with Clear Event Records","It is deleted automatically when read","It is deleted automatically at the next FLR","It is moved to Host memory automatically"],0,"읽기만으로는 지워지지 않아요. Host가 Clear Event Records로 handle을 주고 지워야 해요.","Reading does not delete a record. The Host must clear it with Clear Event Records, passing the handles.","§12.2.3.2"],["c8q16","c8_4",2,"X","장치에 저장된 오류 레코드와 reset의 관계로 맞는 것은?","Which statement about device error records and resets is correct?",["hot reset, FLR, CXL Reset 중 어느 것으로도 초기화·수정되면 안 된다 (sticky)","FLR이 레코드를 초기화한다","CXL Reset이 레코드를 초기화한다","hot reset이 레코드를 초기화한다"],["None of hot reset, FLR, or CXL Reset may initialize or modify them (sticky)","FLR initializes the records","CXL Reset initializes the records","Hot reset initializes the records"],0,"오류 레코드는 장치 reset에 대해 sticky여야 해요. aux power를 쓰는 장치는 warm/cold reset에서도 유지해야 해요.","Error records must be sticky across device resets. Devices using aux power must also keep them across warm and cold reset.","§12.2.3.2"],["c8q17","c8_5",1,"X","CXL.cache/CXL.mem Isolation은 어느 component의 기능인가요?","CXL.cache/CXL.mem Isolation is a capability of which component?",["Fabric Manager","CXL Root Port (optional)","Switch DSP (mandatory)","모든 Endpoint (mandatory)"],["The Fabric Manager","The CXL Root Port (optional)","The switch DSP (mandatory)","Every Endpoint (mandatory)"],1,"Isolation은 CXL Root Port의 optional normative 기능이에요. 걸리면 해당 프로토콜 트래픽을 멈추고 Root Port가 응답을 대신 만들어요.","Isolation is an optional normative CXL Root Port capability. Once triggered, it halts that protocol and the Root Port synthesizes responses.","§12.3"],["c8q18","c8_5",2,"X","스펙이 정의한 Isolation trigger 두 가지는 무엇인가요?","What are the two Isolation triggers defined by the spec?",["Viral 수신, 그리고 Poison 수신","Link Down, 그리고 (설정했다면) transaction timeout","GPF Phase 1, 그리고 Phase 2","Correctable error 누적 횟수, 그리고 FLR"],["Receiving Viral, and receiving Poison","Link Down, and transaction timeout if configured","GPF Phase 1 and Phase 2","A correctable error count, and FLR"],1,"Isolation을 켜 두면 Link Down은 무조건 trigger예요. timeout은 Root Port가 지원하고 설정했을 때 trigger가 돼요.","With Isolation enabled, Link Down always triggers it. A timeout triggers it only if the Root Port supports and is configured for that.","§12.3"],["c8q19","c8_5",2,"X","Root Port가 CXL.mem Isolation 상태일 때 Host의 read 요청은 어떻게 처리되나요?","While the Root Port is in CXL.mem Isolation, how is a Host read request handled?",["링크가 다시 올라올 때까지 무기한 대기한다","정상 데이터 0을 돌려주는 것이 필수다","Root Port가 synchronous exception 응답을 만든다 (예: poison 데이터)","장치로 그대로 보낸다"],["It waits indefinitely until the link comes back","It must return good data of all zeros","The Root Port synthesizes a synchronous exception response (e.g., poisoned data)","It is still sent to the device"],2,"Isolation 중 read는 Root Port가 synchronous exception으로 끝내요. 방식은 구현마다 다르고, poison 데이터가 예시예요. write는 NDR 같은 응답을 만들어요.","During Isolation the Root Port ends reads with a synchronous exception. The method is implementation specific; poisoned data is one example. Writes get a synthesized response such as NDR.","§12.3.2"],["c8q20","c8_5",3,"X","CXL.cache Isolation 중 Host snoop이 생겼고, Host는 장치가 그 line의 exclusive owner일 수 있다고 추적하고 있어요. 어떻게 되나요?","During CXL.cache Isolation a Host snoop occurs, and the Host tracks the device as a possible exclusive owner of the line. What happens?",["장치 cache를 Invalid로 보고 poison 없이 끝낸다","line을 Shared로 강등하고 정상 데이터를 쓴다","장치가 응답할 때까지 snoop을 보류한다","그 데이터를 poison으로 처리한다"],["The device cache is taken as Invalid with no poison","The line is demoted to Shared and treated as good data","The snoop is held until the device answers","The data is treated as poisoned"],3,"장치가 exclusive일 수 있으면 데이터가 장치 안에서 바뀌었을 수 있어 poison으로 처리해요. Shared/Invalid만 가능하면 Invalid로 보고 poison이 필요 없어요.","If the device may own the line exclusively, it may hold modified data, so the data is poisoned. If it can only be Shared/Invalid, the line is taken as Invalid and no poison is needed.","§12.3.1"],["c8q21","c8_5",3,"X","Root Port가 Isolation에서 빠져나와 장치를 복구하려면 무엇이 필요한가요?","What is needed for a Root Port to leave Isolation and recover the device?",["SW가 Isolation status bit를 명시적으로 clear하고, 링크가 Link Down을 거친 뒤 재열거한다","Viral 상태를 clear하면 빠져나온다","장치에 FLR을 보내면 바로 빠져나온다","일정 시간이 지나면 자동으로 빠져나온다"],["Software explicitly clears the Isolation status bits, and the link passes through Link Down before re-enumeration","Clearing the Viral state exits it","Sending an FLR to the device exits it immediately","It exits automatically after a time-out"],0,"Isolation은 SW가 status bit를 지워야 풀려요. 재열거와 복구 전에 링크가 Link Down을 거쳐야 해요. Timeout과 Isolation은 기본이 disabled예요.","Software must clear the status bits to exit Isolation, and the link must go through Link Down before re-enumeration. Timeout and Isolation are disabled by default.","§12.3"],["c8q22","c8_6",1,"X","Viral이 켜져 있을 때 Viral indication은 언제 생기나요?","When Viral is enabled, when is a Viral indication generated?",["Correctable error가 날 때마다","Uncorrected_Fatal error가 검출될 때","링크가 retrain할 때","Poison 데이터를 받을 때마다"],["On every correctable error","When an Uncorrected_Fatal error is detected","When the link retrains","Whenever poisoned data is received"],1,"Viral은 Uncorrected_Fatal 오류를 계기로 생겨요. Uncorrected_Fatal을 보고할 수 있는 entity는 Viral도 만들 수 있어야 해요.","Viral is triggered by an Uncorrected_Fatal error. Any entity that can report Uncorrected_Fatal must also be able to raise Viral.","§12.4"],["c8q23","c8_6",1,"X","PCIe AER와 CXL Viral의 관계로 맞는 것은?","Which describes the relationship between PCIe AER and CXL Viral?",["Viral이 AER를 대체한다","Viral은 PCIe Poisoned TLP의 다른 이름이다","Viral은 CXL.io 전용 기능이다","Viral은 AER를 대체하지 않는 추가 containment 수단이다 (검출자가 AER 보고와 Viral을 둘 다 한다)"],["Viral replaces AER","Viral is another name for a PCIe poisoned TLP","Viral is a CXL.io-only feature","Viral is an extra containment mechanism, not a replacement; the detector reports via AER and also raises Viral"],3,"Viral은 기존 오류 보고를 대체하지 않아요. 오류를 찾은 쪽이 AER로 보고하고 Viral도 만들어요. CXL.io 칸에서 Viral은 N/A예요.","Viral does not replace error reporting. The detector reports via AER and also raises Viral. Viral is N/A for CXL.io.","§12.4"],["c8q24","c8_6",2,"X","Viral 상태를 지우는 reset은 무엇인가요?","Which reset clears the Viral condition?",["Conventional Reset (모든 종류)","FLR","FLR과 CXL Reset 둘 다","CXL Reset"],["Conventional Reset (all types)","FLR","Both FLR and CXL Reset","CXL Reset"],0,"모든 Conventional Reset은 Viral을 지워요. CXL Reset과 FLR은 Viral 상태에 영향이 없어요.","Every Conventional Reset clears Viral. CXL Reset and FLR have no effect on it.","§12.4"],["c8q25","c8_7",1,"X","한 Switch 안의 VCS 하나가 Viral 상태가 되면 같은 Switch의 다른 VCS는 어떻게 되나요?","When one VCS inside a switch enters Viral, what happens to the other VCSs in that switch?",["영향이 없다 (Viral 상태는 VCS 단위)","모두 Isolation 상태가 된다","Switch 전체가 reset된다","모두 같이 Viral 상태가 된다"],["They are not affected; Viral is per VCS","They all enter Isolation","The whole switch is reset","They all enter Viral too"],0,"Viral은 VCS 단위예요. 다른 VCS에는 영향이 없고, Viral VCS도 트래픽 forwarding은 계속해요.","Viral is scoped per VCS. Other VCSs are unaffected, and even the Viral VCS keeps forwarding traffic.","§12.4.1"],["c8q26","c8_7",2,"X","Viral 상태의 VCS가 MLD port를 가지고 있으면, Viral은 MLD 안의 LD에 어떻게 전달되나요?","If a VCS in Viral has an MLD port, how is Viral passed to LDs inside the MLD?",["MLD의 모든 LD에 PERST#를 건다","FM이 Unbind vPPB로 LD를 떼어낸다","MLD에는 Viral을 전달하지 않는다","그 VCS에 속한 LD의 Viral LD-ID Vector bit를 set한다"],["By asserting PERST# to every LD in the MLD","The FM detaches the LD with Unbind vPPB","Viral is not passed to MLDs","By setting the Viral LD-ID Vector bits for the LDs in that VCS"],3,"MLD 링크는 여러 VCS가 공유하므로, 해당 VCS의 LD만 Viral LD-ID Vector로 골라 알려요.","An MLD link is shared by several VCSs, so only that VCS's LDs are flagged through the Viral LD-ID Vector.","§12.4.1"],["c8q27","c8_7",3,"X","Viral을 감지한 장치가 해야 하는 동작은?","Which action must a device take after detecting Viral?",["snoop 응답을 멈춘다","persistent HDM으로 가는 write는 버리고, Completion 응답은 항상 돌려준다","read를 보류해 Host가 timeout 나게 한다","GPF flow 뒤 Shutdown State를 clean으로 바꾼다"],["Stop answering snoops","Drop writes to persistent HDM, and always return a Completion","Withhold reads so the Host times out","Set the Shutdown State to clean after a GPF flow"],1,"Viral의 목표는 나쁜 데이터가 영구 저장소에 남지 않게 하면서 Host가 계속 진행하게 하는 거예요. 그래서 persistent write는 버리고, 응답과 snoop 처리는 계속하고, Shutdown State를 clean으로 바꾸지 않아요.","Viral aims to keep bad data out of permanent storage while letting the Host make progress. So persistent writes are dropped, responses and snoops continue, and the Shutdown State is not set to clean.","§12.4.2"],["c8q28","c8_8",2,"X","68B Flit mode의 CXL.cachemem link layer는 Viral 상태를 상대에게 어떻게 알리나요?","How does the 68B Flit mode CXL.cachemem link layer tell the link partner about Viral?",["다음 flit에 CRC 오류를 일부러 내고, 이어지는 RETRY.Ack에 Viral 정보를 담는다","CXL.io의 ERR_FATAL 메시지로만 알린다","PERST#를 assert한다","모든 protocol flit에 전용 Viral bit를 둔다"],["It forces a CRC error on the next flit and carries Viral in the following RETRY.Ack","Only via a CXL.io ERR_FATAL message","It asserts PERST#","Every protocol flit has a dedicated Viral bit"],0,"68B에서는 CRC 오류로 retry를 일으키고 RETRY.Ack에 Viral을 실어요. 그래서 protocol flit에 bit를 따로 둘 필요가 없고 data 경로와의 race도 줄어요.","In 68B mode the link forces a retry with a CRC error and carries Viral in RETRY.Ack. No flit bit is needed and races with the data path are reduced.","§4.2.9"],["c8q29","c8_8",3,"X","MLD 링크에서 Viral LD-ID Vector 값이 모두 0이면 무슨 뜻인가요?","On an MLD link, what does an all-0s Viral LD-ID Vector mean?",["Vector가 무효이므로 메시지를 버린다","FM-owned LD만 Viral","모든 LD-ID가 Viral 상태 (모두 1과 같은 의미)","어떤 LD도 Viral이 아님"],["The vector is invalid, so the message is dropped","Only the FM-owned LD is in Viral","All LD-IDs are in Viral, the same as all 1s","No LD is in Viral"],2,"MLD에서는 all 0s가 all 1s와 같게 '모든 LD가 Viral'이라는 뜻이에요. SLD 링크에서는 이 vector가 Reserved예요.","For an MLD, all 0s means every LD is in Viral, the same as all 1s. On an SLD link the vector is Reserved.","§4.2.9"],["c8q30","c8_8",2,"X","256B Flit mode에서 header를 이미 보낸 뒤 그 data를 poison하려면 송신 측은 어떻게 하나요?","In 256B Flit mode, the header is already sent and the Tx now wants to poison its data. What does it do?",["Viral을 발생시킨다","header를 다시 보낸다","data를 보내지 않고 버린다","Poison subtype의 in-band Error control message로 대상 data offset을 알린다"],["Raise Viral","Resend the header","Drop the data without sending it","Send an in-band Error control message of the Poison subtype that names the data offset"],3,"이것이 Late Poison이에요. header를 보내기 전이면 header에 poison을 넣고, 보낸 뒤면 Poison control message로 offset을 지정해요. 대상은 active data message 최대 8개 중 하나예요.","This is Late Poison. Before the header is sent, poison goes in the header; after, a Poison control message names the offset, targeting one of up to eight active data messages.","§4.3.6.3"]],"9":[["p9q01","p9_1",1,"C","PCI Express Switch의 논리 구조에 대한 설명으로 옳은 것은?","Which description of a PCI Express Switch's logical structure is correct?",["여러 개의 virtual PCI-to-PCI Bridge device를 모아 놓은 논리 집합으로 정의된다. 구성 소프트웨어에는 둘 이상의 logical PCI-to-PCI Bridge로 보인다.","하나의 Type 0 Endpoint로만 보이며, Port마다 별도의 Configuration Space는 없다.","Root Complex Event Collector들의 집합으로 정의된다.","하나의 Flat memory-mapped switch fabric으로만 보이며 Bridge header를 사용하지 않는다."],["Logically, a Switch is a collection of virtual PCI-to-PCI Bridge devices. Configuration software sees it as two or more of those logical Bridges.","It appears only as a single Type 0 Endpoint and has no per-Port Configuration Space.","It is defined as an assembly of Root Complex Event Collectors.","It appears only as a flat memory-mapped switch fabric and does not use a Bridge header."],0,"Figure 1-3은 Upstream Port와 각 Downstream Port가 각각 virtual PCI-to-PCI Bridge로 표현되는 모습을 보여 줍니다. 각 Link는 이 virtual Bridge 구조에 매핑되고 Logical Bus가 연관됩니다.","Figure 1-3 shows the Upstream Port and each Downstream Port represented as a virtual PCI-to-PCI Bridge. Each Link is mapped through that virtual Bridge structure and has a Logical Bus associated with it.","§1.3.3"],["p9q02","p9_1",2,"C","Switch의 internal bus에 Endpoint가 보이는 방식에 대한 규칙으로 옳은 것은?","Which rule about Endpoints on a Switch's internal bus is correct?",["모든 Endpoint는 Switch internal bus에서 Downstream Port virtual Bridge의 peer로 반드시 보여야 한다.","internal bus에는 Type 0 Function만 둘 수 있고 virtual Bridge는 둘 수 없다.","Type 00h Configuration Space header로 표현되는 Endpoint는, Switch Downstream Port를 나타내는 virtual PCI-to-PCI Bridge의 peer로서 Switch internal bus에 보이면 안 된다.","Switch는 internal bus 개념이 없으므로 이 규칙은 적용되지 않는다."],["Every Endpoint must appear on the Switch's internal bus as a peer of the Downstream Port virtual Bridges.","The internal bus may contain only Type 0 Functions, never a virtual Bridge.","A Type 00h Endpoint must not show up, to configuration software, on the Switch internal bus as a peer of the virtual Bridges that stand for the Downstream Ports.","A Switch has no internal-bus concept, so the rule does not apply."],2,"소프트웨어가 Switch를 여러 Type 1 Bridge의 나무로 보게 하려는 모델입니다. Downstream Port들의 secondary/subordinate bus 아래에 Endpoint가 놓입니다.","The model is that software sees the Switch as a tree of Type 1 Bridges. Endpoints sit below the secondary/subordinate buses of the Downstream Ports.","§1.3.3"],["p9q03","p9_1",2,"C","Switch의 packet forwarding에 대한 규칙으로 옳은 것은?","Which rule about packet forwarding in a Switch is correct?",["Switch는 항상 Max_Payload_Size의 절반 단위로 packet을 쪼개야 한다.","Switch는 packet을 더 작은 packet으로 쪼개면 안 된다. 예를 들어 payload 256바이트인 단일 packet을 128바이트 두 개로 나누면 안 된다.","Switch는 Memory Write만 쪼갤 수 있고, Completion은 쪼개면 안 된다.","Switch는 Routing ID를 유지하는 한 packet을 자유롭게 재조립·분할할 수 있다."],["A Switch must always split packets into halves of Max_Payload_Size.","A Switch must keep each packet intact. For example, one 256-byte-payload packet must not become two 128-byte-payload packets.","A Switch may split Memory Writes but must never split Completions.","A Switch may freely segment or reassemble packets as long as the Routing ID is preserved."],1,"문서에 달리 적힌 경우를 제외하면, Switch는 어떤 Port 집합 사이에서든 모든 유형의 TLP를 전달해야 합니다. Root Complex는 일반적으로 routing 시 packet을 더 작게 나누는 것이 허용됩니다.","Except as noted in the specification, a Switch must forward all types of TLPs between any set of Ports. When a Root Complex routes traffic, it is generally allowed to break a packet into smaller ones.","§1.3.3"],["p9q04","p9_1",2,"C","Switch Port의 Flow Control과 Locked Request에 대한 설명으로 옳은 것은?","Which statement about Flow Control and Locked Requests on a Switch is correct?",["Switch Port는 Flow Control이 면제되며, Locked Request는 모든 Downstream Port가 initiate해야 한다.","Switch는 Locked Request를 전달해서는 안 되며 Flow Control은 Upstream Port에만 적용된다.","Flow Control은 Multicast TLP에만 적용되고 Locked Request는 ACS가 켜져 있을 때만 허용된다.","enable된 각 Switch Port는 Flow Control 규격을 준수해야 한다. Locked Request는 §6.5에 따라 지원해야 하지만, Downstream Port가 Locked Request의 initiating Port가 될 필요는 없다."],["Switch Ports are exempt from Flow Control, and every Downstream Port must initiate Locked Requests.","A Switch must not forward Locked Requests, and Flow Control applies only to the Upstream Port.","Flow Control applies only to Multicast TLPs, and Locked Requests are allowed only when ACS is enabled.","Every enabled Switch Port has to follow the Flow Control rules. Locked Requests are required per section 6.5, yet a Switch need not let its Downstream Ports be the initiator of a Locked Request."],3,"Ingress Port들 사이의 arbitration은 같은 Virtual Channel에서 경합이 나면 round robin 또는 weighted round robin으로 구현할 수 있습니다.","If several Ingress Ports contend for the same Virtual Channel, arbitration may be plain or weighted round-robin.","§1.3.3"],["p9q05","p9_1",1,"C","virtual PCI-to-PCI Bridge 구조가 쓰이는 Port 종류로 옳은 것은?","Which Ports use a virtual PCI-to-PCI Bridge structure to map a PCI Express Link?",["Endpoint Function과 RCiEP만","Root Complex Event Collector만","PCI Express Root Complex Port(Root Port), Switch Upstream Port, Switch Downstream Port","Retimer와 Cable adapter만"],["Only Endpoint Functions and RCiEPs","Only a Root Complex Event Collector","A PCI Express Root Complex Port (Root Port), a Switch Upstream Port, or a Switch Downstream Port","Only Retimers and cable adapters"],2,"각 PCI Express Link는 virtual PCI-to-PCI Bridge 구조를 통해 매핑되고 Logical Bus가 연관됩니다. Root Port는 PCI Express hierarchy를 시작하는 virtual Bridge입니다.","Every PCI Express Link is associated with a Logical Bus and is represented by a virtual PCI-to-PCI Bridge. A Root Port is the virtual Bridge that starts a hierarchy.","§1.3.3"],["p9q06","p9_2",1,"C","TLP routing의 세 가지 주요 메커니즘은?","What are the three principal mechanisms for TLP routing?",["address, ID, implicit","TC, VC, Routing ID","BAR, Capability, Extended Capability","Posted, Non-Posted, Completion"],["Address, ID, and implicit","TC, VC, and Routing ID","BAR, Capability, and Extended Capability","Posted, Non-Posted, and Completion"],0,"§2.2.4는 address와 ID routing 규칙을 정의합니다. Implicit routing은 Message Request에만 쓰이며 §2.2.8에서 다룹니다.","Address and ID routing rules are in section 2.2.4. Only Message Requests use implicit routing, which is described in section 2.2.8.","§2.2.4"],["p9q07","p9_2",2,"C","Address based routing이 사용되는 TLP 유형과, Non-Flit Mode에서의 주소 형식은?","Which TLPs use address-based routing, and which address formats exist in Non-Flit Mode?",["Configuration Request와 Completion에만 사용되며, Non-Flit Mode에서는 16-bit 형식만 있다.","Message Request에만 사용되며 header는 항상 1 DW이다.","모든 TLP가 address routing을 쓰며, Flit Mode에서는 32-bit 형식만 허용된다.","Memory Request, I/O Request, Address Routed Message에 사용된다. Non-Flit Mode에서는 32-bit(3 DW header)와 64-bit(4 DW header)의 두 형식이 있다."],["It is used only with Configuration Requests and Completions, and Non-Flit Mode has only a 16-bit format.","It is used only with Message Requests, and the header is always 1 DW.","Every TLP uses address routing, and Flit Mode allows only the 32-bit format.","Memory, I/O, and Address Routed Messages use it. Non-Flit Mode has two layouts: 32-bit addresses in a 3 DW header, and 64-bit addresses in a 4 DW header."],3,"Flit Mode에서는 주소 형식이 다섯 가지입니다(32-bit 3 DW, 그리고 64-bit 4/5/6/7 DW). AT 필드는 Memory Read/Write, DMWr, AtomicOp와, Flit Mode의 Address Routed Message에서 의미를 가집니다.","Flit Mode specifies five address formats: a 32-bit 3 DW form and 64-bit forms with 4, 5, 6, or 7 DW headers. The AT field is defined for Memory Read, Memory Write, DMWr, and AtomicOp Requests, and for Address Routed Messages in Flit Mode.","§2.2.4.1"],["p9q08","p9_2",2,"C","ID based routing이 사용되는 TLP와, ARI Routing ID의 구성으로 옳은 것은?","Which TLPs use ID-based routing, and how is an ARI Routing ID formed?",["Memory Write에만 사용되며, ARI는 16-bit Device Number를 추가한다.","Configuration Request, ID Routed Message, Completion에 사용된다. ARI Routing ID는 Bus Number와 8-bit Function Number로 구성된다(Device Number 필드가 따로 없다).","I/O Request에만 사용되며, ARI는 Segment Number만 사용한다.","모든 Message에만 사용되며, ARI는 Function Number를 없앤다."],["It is used only with Memory Writes, and ARI adds a 16-bit Device Number.","It is used with Configuration Requests, ID Routed Messages, and Completions. An ARI Routing ID is formed from the Bus Number and an 8-bit Function Number (there is no separate Device Number field).","It is used only with I/O Requests, and ARI uses only a Segment Number.","It is used only with Messages, and ARI removes the Function Number."],1,"non-ARI Routing ID는 Bus, Device, 3-bit Function Number를 씁니다. 스펙은 몇 가지 ID Routed Message를 정의하고, 다른 스펙이 추가 ID Routed Message를 정의하는 것도 허용합니다.","A non-ARI Routing ID uses Bus, Device, and a 3-bit Function Number. This specification defines several ID-routed Messages, and other specifications may define more.","§2.2.4.2"],["p9q09","p9_2",3,"C","Flit Mode에서, 출발 hierarchy와 다른 destination hierarchy로 가는 Completion 또는 ID Routed Message의 routing은?","In Flit Mode, how is a Completion or ID-Routed Message routed when its destination hierarchy differs from the hierarchy in which it originates?",["항상 Broadcast로 Root Complex에만 보낸다.","먼저 Destination Segment 필드로 destination hierarchy까지 라우팅한 뒤, 그 hierarchy 안에서는 destination Bus, Device, Function Number로 라우팅한다.","Destination Segment는 무시하고 Requester ID만으로 라우팅한다.","다른 hierarchy로는 보낼 수 없어 무조건 UR로 끝낸다."],["It is always broadcast only to the Root Complex.","First use the Destination Segment field to reach the target hierarchy, then use the destination Bus, Device, and Function Numbers inside that hierarchy.","The Destination Segment is ignored, and only the Requester ID is used.","It cannot leave its hierarchy and must always end as an UR."],1,"Non-Flit Mode의 ID routing 형식은 3 DW와 4 DW header 두 가지이고, Flit Mode에서는 3–7 DW의 다섯 가지 형식이 있습니다.","Non-Flit Mode specifies two ID-routing formats (3 DW and 4 DW headers). Flit Mode specifies five formats, with 3 through 7 DW headers.","§2.2.4.2"],["p9q10","p9_3",2,"C","Configuration Request의 전파 방향에 대한 규칙으로 옳은 것은?","Which rule about the direction of Configuration Request propagation is correct?",["Endpoint가 다른 Endpoint로 Configuration Request를 직접 peer-to-peer로 보내는 것이 필수이다.","Switch는 수신한 Type 0 Request를 항상 Upstream으로 재전달해야 한다.","Root Port만 Configuration Request를 수신할 수 있고 Switch는 전달할 수 없다.","Downstream에서 Upstream으로의 전파와 peer-to-peer는 지원되지 않는다. Configuration Request는 Host Bridge가 개시한다(SFI CAM을 통해 전달되는 것 포함)."],["An Endpoint must be able to send Configuration Requests peer-to-peer directly to another Endpoint.","A Switch must always re-forward a received Type 0 Request Upstream.","Only a Root Port may receive Configuration Requests; a Switch cannot forward them.","A Configuration Request cannot travel Downstream-to-Upstream or peer-to-peer. Only the Host Bridge originates them, including ones that pass through the SFI CAM."],3,"구성 접근은 호스트가 hierarchy를 내려가며 수행하는 모델입니다. Switch/Root Port는 Type 1을 받아 대상 Port로 넘기거나 Type 0으로 변환합니다.","Configuration access is modeled as the host walking down the hierarchy. A Switch or Root Port takes a Type 1 Request and either forwards it or converts it to Type 0 toward the target Port.","§7.3.3"],["p9q11","p9_3",2,"C","Switch 또는 Root Complex가 Type 1 Configuration Request를 받았을 때, Bus/Device Number가 어느 Downstream Port의 secondary bus(및 decode되는 Device Number)와 같으면?","When a Switch or Root Complex receives a Type 1 Configuration Request whose Bus and Device Numbers match a Downstream Port's assigned secondary bus (and decoded Device Numbers), what must it do?",["Type 필드를 바꿔 Request를 Type 0으로 변환한 뒤, 다른 필드는 그대로 두고 그 Downstream Port로 전달한다.","Request를 수정 없이 Upstream으로 되돌린다.","항상 Unsupported Request로 끝낸다.","Type 1을 I/O Request로 변환한다."],["It must transform the Request to Type 0 by changing the Type[4:0] field, leave all other fields unchanged, and forward the Request to that Downstream Port.","It must return the Request Upstream without modification.","It must always terminate the Request as an Unsupported Request.","It must convert the Type 1 Request into an I/O Request."],0,"Bus Number가 어느 Downstream Port의 정확한 secondary와는 다르지만 그 Port에 할당된 bus 범위 안이면, Request를 수정 없이 그 Port로 전달합니다. 어느 쪽도 아니면 유효하지 않으므로 UR 규칙을 따릅니다. FPB Routing ID 메커니즘이 적용되면 그 결과도 따릅니다.","If the Bus Number is not equal to any Downstream Port's secondary bus, but still falls in the range assigned to a Downstream Port, the Request is forwarded to that Port without modification. Otherwise the Request is invalid and is handled as an Unsupported Request. The FPB Routing ID mechanism is also applied when required.","§7.3.3"],["p9q12","p9_3",3,"C","Endpoint가 Type 1 Configuration Request를 받았을 때(해당 TLP가 Secure 상태 Selective IDE Stream의 IDE TLP가 아닌 경우)의 처리는?","How does an Endpoint handle a Type 1 Configuration Request, other than an IDE TLP that belongs to a Selective IDE Stream already in Secure?",["Type 1을 Type 0으로 변환해 내부 Function에 전달한다.","항상 Successful Completion과 all 1 data를 반환한다.","그 TLP가 device가 capture한 Bus Number를 대상으로 하면, Unsupported Request 처리 규칙을 따른다.","그 Request를 Upstream Port로 재전달한다."],["It converts the Type 1 Request to Type 0 and delivers it to an internal Function.","It always returns a Successful Completion with all-1 data.","If it targets the Device's captured Bus Number, the Endpoint follows the rules for handling Unsupported Requests.","It re-forwards the Request toward the Upstream Port."],2,"예외는 Type 1이면서 Secure 상태 Selective IDE Stream에 연관된 IDE TLP인 경우로, 이때는 Type 0과 같이 로컬 Configuration Space가 유효한지 보고 처리합니다. 일반 Endpoint가 평범한 Type 1을 자신의 captured bus에서 받는 것은 프로그래밍 오류에 가깝습니다.","One exception is a Type 1 IDE TLP that belongs to a Selective IDE Stream already in Secure: that TLP is handled like Type 0 when it targets valid local Configuration Space. Any ordinary Type 1 aimed at the Endpoint's captured bus is otherwise an Unsupported Request.","§7.3.3"],["p9q13","p9_3",2,"C","구현되지 않은 Configuration register에 대한 Configuration Read/Write의 기본 처리로 옳은 것은?","How must Configuration Reads and Writes to unimplemented registers be handled, unless some other error must be reported?",["항상 Completer Abort를 반환한다.","Read는 all 1, Write는 UR를 반환한다.","해당 Request를 silently discard하고 Completion을 보내지 않는다.","오류로 보지 않는다. Successful Completion을 반환하며, Read는 all 0 data를, Write는 data를 버리고 효과 없이 끝낸다."],["They must always return Completer Abort.","Reads must return all 1s, and writes must return UR.","The Request must be silently dropped with no Completion.","They are not considered errors. The Request must return a Completion with Successful Completion status, with reads returning all 0s and writes discarding the write data without effect."],3,"이 규칙은 모든 device 유형에 적용됩니다. 다른 절에서 정의된 오류가 탐지되어 보고해야 하는 경우에는 그 오류 처리가 우선합니다.","This rule applies to all device types. If an error defined elsewhere is detected and needs to be reported, that error handling takes precedence.","§7.3.3"],["p9q14","p9_4",1,"C","ACS(Access Control Services)의 기본 enable 상태와 적용 범위로 옳은 것은?","Which statement about ACS default enablement and applicability is correct?",["ACS는 모든 Downstream Port에서 reset 직후 자동 enable된다.","ACS 하드웨어 기능은 기본적으로 disable이며, ACS를 아는 소프트웨어가 enable한다. ACS는 RC, Switch, Multi-Function Device에 적용된다.","ACS는 Endpoint Type 0에만 적용되고 Switch에는 적용되지 않는다.","ACS는 항상 Multicast TLP에만 적용된다."],["ACS is automatically enabled on every Downstream Port immediately after reset.","ACS hardware starts out disabled; only software that understands ACS turns it on. It applies to Root Complexes, Switches, and Multi-Function Devices.","ACS applies only to Type 0 Endpoints and never to Switches.","ACS always applies only to Multicast TLPs."],1,"SR-IOV 또는 SIOV를 지원하는 Single-Function Device는 VF/SDI가 enable되면 사실상 Multi-Function처럼 동작하므로, ACS 요구에서는 Multi-Function Device로 다루어야 합니다. Source Validation을 제외하면 ACS 제어는 Multicast TLP에 적용되지 않습니다.","A Single-Function Device that is SR-IOV or SIOV capable must be treated as a Multi-Function Device for ACS, because it essentially behaves as one after VFs or SDIs are enabled. Except for ACS Source Validation, ACS controls do not apply to Multicast TLPs.","§6.12"],["p9q15","p9_4",2,"C","ACS를 구현해서는 안 되는 Function 유형은?","Which Function types must never implement an ACS Extended Capability structure?",["Switch Downstream Port와 Root Port","SR-IOV를 지원하는 Multi-Function Endpoint","PCI Express to PCI Bridge Function과 Root Complex Event Collector Function","ACS P2P Request Redirect를 지원하는 Root Port"],["A Switch Downstream Port and a Root Port","A Multi-Function Endpoint that supports SR-IOV","A PCI Express to PCI Bridge Function and a Root Complex Event Collector Function","A Root Port that supports ACS P2P Request Redirect"],2,"ACS는 이 두 유형에 적용되지 않으며 Extended Capability를 구현하면 안 됩니다. 구성 요소는 적용 가능한 Function의 일부, 전부, 또는 하나도 ACS를 구현하지 않을 수 있고, 지원 범위는 각 ACS Extended Capability의 capability bit로 전달됩니다.","ACS is never applicable to those two Function types, and they must never implement the Extended Capability. Components may implement ACS in some, none, or all applicable Functions; capability bits in each ACS structure describe what is present.","§6.12.1"],["p9q16","p9_4",2,"C","Switch Downstream Port 또는 Root Port에서 ACS Source Validation이 enable된 경우의 동작은?","When ACS Source Validation is enabled on a Switch Downstream Port or Root Port, what does the Port do?",["수신한 각 Upstream Request의 Requester ID Bus Number가 해당 virtual Bridge 이차 측 aperture(Secondary–Subordinate, 또는 FPB Routing ID) 안에 있는지 검사한다. 벗어나면 ACS Violation이다. Completion은 Source Validation의 영향을 받지 않는다.","모든 Downstream Request의 Completer ID를 검사하고, 실패 시 TLP를 수정해 통과시킨다.","Translated address를 가진 Memory Request만 검사하고 Completion은 무조건 폐기한다.","Requester ID 검사는 하지 않고 AT 필드만 확인한다."],["It tests the Bus Number in the Requester ID of each received Upstream Request against the Port's secondary-side aperture (the Secondary–Subordinate Bus Number range, and/or the FPB Routing ID mechanism). A miss is an ACS Violation associated with the Receiving Port. Completions are never affected by ACS Source Validation.","It checks the Completer ID of every Downstream Request and, on a miss, repairs the TLP and forwards it.","It checks only Memory Requests with a Translated address, and it always drops Completions.","It does not check the Requester ID; it only inspects the AT field."],0,"구현 노트는, Bus Number를 아직 할당받기 전에 Upstream Message를 보내는 Function이 있을 수 있고, 이때 Requester ID Bus Number가 00h라 Source Validation이 ACS Violation으로 잡을 수 있다고 경고합니다. ACS는 FM TLP의 Segment Number를 검사하도록 규정되어 있지 않습니다.","An implementation note warns that a Function may send Upstream Messages before it has a Bus Number, so a Requester ID Bus Number of 00h can look like an ACS Violation if Source Validation is enabled. ACS is not architected to check Segment Numbers in FM TLPs.","§6.12.1.1"],["p9q17","p9_4",2,"C","ACS Translation Blocking이 Downstream Port에서 enable된 경우의 동작은?","When ACS Translation Blocking is enabled on a Downstream Port, what does the Port check?",["수신한 각 Upstream Memory Request의 AT 필드(Flit Mode에서는 Upstream Address Routed Message도)가 00b(Untranslated)가 아니면 ACS Violation이다. 이 오류는 ACS Upstream Forwarding 및 적용 가능한 ACS P2P 제어보다 우선한다. Completion은 영향받지 않는다.","AT가 10b(Translated)가 아닌 Downstream Completion만 차단한다.","I/O Request의 AT 필드만 검사한다.","AT와 무관하게 모든 Memory Request를 Upstream으로 되돌린다."],["It checks the AT field of each Upstream Memory Request, and in Flit Mode of each Upstream Address Routed Message. If AT is not 00b (Untranslated), that is an ACS Violation. This error has priority over ACS Upstream Forwarding and over any ACS P2P controls that would otherwise apply. Completions are not affected.","It blocks only Downstream Completions whose AT is not 10b (Translated).","It checks the AT field only on I/O Requests.","It redirects every Memory Request Upstream regardless of the AT field."],0,"이 제어의 의도는, 아직 번역되지 않아야 할 경로로 Translated address가 Upstream으로 들어오는 것을 막는 것입니다. Downstream Port에서 이 기능은 반드시 구현되어야 합니다.","The intent is to stop a Translated address from coming Upstream on a path that should only see Untranslated addresses. A Downstream Port that implements ACS must implement this control.","§6.12.1.1"],["p9q18","p9_4",3,"C","Downstream Port가 아닌, SR-IOV/SIOV/Multi-Function Device Function에서의 ACS 구현 요구로 옳은 것은?","Which ACS implementation requirement is correct for Functions in SR-IOV, SIOV, and Multi-Function Devices, other than Downstream Port Functions?",["Source Validation과 Translation Blocking을 반드시 구현해야 한다.","ACS Extended Capability 전체를 구현하면 안 된다.","ACS Source Validation과 ACS Translation Blocking은 구현하면 안 된다. 다른 Function과 peer-to-peer를 지원하는 Function(VF 포함)은 ACS P2P Request Redirect를 구현해야 한다.","P2P Request Redirect는 구현하면 안 되며 Source Validation만 필수이다."],["Source Validation and Translation Blocking must be implemented.","The entire ACS Extended Capability must not be implemented.","Source Validation and Translation Blocking must not be present. Any Function that supports P2P traffic with other Functions — VFs included — must implement P2P Request Redirect.","P2P Request Redirect must not be implemented, and only Source Validation is required."],2,"ACS가 enable된 비-RCiEP Multi-Function Device에서는 Function 사이 peer-to-peer Request가 RC 쪽으로 Upstream redirect되어야 합니다. SIOV Device는 SDI가 시작한 P2P가 연관 PF의 정책을 따르게 해야 합니다.","In a non-RCiEP Multi-Function Device with P2P Request Redirect enabled, Requests between Functions must be sent Upstream toward the RC. An SIOV Device must make SDI-initiated P2P traffic obey the associated PF's policy.","§6.12.1.2"],["p9q19","p9_4",3,"C","ACS Violation이 탐지되었을 때 Completer의 처리로 옳은 것은?","When an ACS Violation is detected, how must the Completer handle it?",["항상 Successful Completion을 보내고 ACS Violation은 로그하지 않는다.","Non-Posted 및 UIO Request에 대해서는 Completer Abort(CA) Status의 Completion을 생성해야 한다. 로그/신호는 Completer Abort error가 아니라 ACS Violation으로 남긴다. 심각도가 Non-fatal이고 CA Completion을 보내는 경우 Advisory Non-Fatal로 처리해야 한다.","항상 ERR_FATAL만 보내고 Completion은 생성하지 않는다.","UR Completion을 보내면서 Completer Abort status bit만 세운다."],["It must always return a Successful Completion and must not log an ACS Violation.","On Non-Posted and UIO Requests, the Completer returns CA. The event is logged and signaled as an ACS Violation, not as Completer Abort. If that Violation is Non-Fatal and a CA Completion is sent, treat the case as Advisory Non-Fatal.","It must send only ERR_FATAL and must not generate a Completion.","It must send a UR Completion and set only the Completer Abort status bit."],1,"AER prefix/header logging이 원인 Request를 분석하는 데 권장됩니다. 한 가지 예외는, RC의 Redirected Request Validation이 redirect된 Request를 거절하는 경우로, 그때는 해당 Root Port(또는 RCiEP면 RCEC)가 Completer 역할을 합니다.","AER prefix/header logging is recommended so the offending Request can be identified. In one exception, when Root Complex Redirected Request Validation disallows a redirected Request, that Root Port (or the associated RCEC, if the Request came from an RCiEP) operates as the Completer.","§6.12.5"],["p9q20","p9_5",2,"C","Switch Downstream Port에서 ACS P2P Request Redirect가 enable된 경우의 동작은?","If a Switch Downstream Port has ACS P2P Request Redirect enabled, how must peer-to-peer Requests be handled?",["peer-to-peer Request는 대상 Egress Port로 그대로 보내고, Completion만 Upstream으로 보낸다.","모든 Request와 Completion을 Broadcast한다.","peer-to-peer Request는 항상 ACS Violation으로 폐기한다.","peer-to-peer Request는 RC 쪽으로 Upstream redirect되어야 한다. Downstream으로 가는 Request는 redirect하지 않는다. Completion은 이 제어의 영향을 받지 않는다."],["Peer-to-peer Requests are sent straight to the peer Egress Port, and only Completions are sent Upstream.","Every Request and Completion is broadcast.","Peer-to-peer Requests are always dropped as ACS Violations.","Those P2P Requests must be sent Upstream toward the RC. A Downstream Port does not redirect Requests that are already going Downstream. This control does not apply to Completions."],3,"이 기능은 Switch Downstream Port에는 반드시 구현되어야 하고, 다른 Root Port와 P2P를 지원하는 Root Port에도 구현되어야 합니다. Root Port에서 enable되면, redirect된 Request는 RC 내부의 Redirected Request Validation 논리로 보내집니다.","Switch Downstream Ports must implement this control, as must Root Ports that support peer-to-peer traffic with other Root Ports. When it is enabled in a Root Port, redirected Requests go to Redirected Request Validation logic inside the RC.","§6.12.1.1"],["p9q21","p9_5",3,"C","Switch Downstream Port에서 ACS P2P Completion Redirect가 enable된 경우, 어떤 Completion이 redirect되나요?","If a Switch Downstream Port has ACS P2P Completion Redirect enabled, which P2P Completions have to be redirected?",["Relaxed Ordering bit가 Set된 Completion만 redirect하고, 나머지는 그대로 peer로 보낸다.","모든 Completion을 항상 redirect하고 Request는 그대로 둔다.","Relaxed Ordering Attribute bit가 Set되어 있지 않은 peer-to-peer Completion은 RC 쪽으로 Upstream redirect되어야 한다. 그 밖의 peer-to-peer Completion은 redirect하면 안 된다.","Completion Redirect는 Memory Read Completion에만 적용되고 AtomicOp Completion에는 적용되지 않는다."],["Only Completions with Relaxed Ordering set are redirected; all others go directly to the peer.","Every Completion is always redirected, and Requests are left alone.","P2P Completions whose Relaxed Ordering bit is not Set must be sent Upstream toward the RC. All other P2P Completions must take the direct path.","Completion Redirect applies only to Memory Read Completions, never to AtomicOp Completions."],2,"의도는 Request가 redirect되는 동안 Completion과의 ordering 규칙 위반을 피하는 것입니다. Relaxed Ordering이 있으면 그 Completion은 원래 경로로 가도 됩니다. 이 제어는 Request를 규율하는 ACS 제어와 상호작용하지 않습니다.","The goal is to keep Completion-versus-Request ordering intact after Requests have been sent Upstream. A Completion with Relaxed Ordering may take the direct path. This control does not interact with the ACS controls that govern Requests.","§6.12.1.1"],["p9q22","p9_5",2,"C","ACS P2P Egress Control에 대한 설명으로 옳은 것은?","Which statement about ACS P2P Egress Control is correct?",["구현은 선택이다. Switch에서는 Ingress Port(보내는 쪽)의 제어가 peer-to-peer Request를 막을지 결정하고, 막으면 그 Ingress Port가 ACS Violation을 처리한다. Completion은 영향받지 않는다.","모든 Downstream Port에 필수이며, Egress Port가 Completion을 선택적으로 폐기한다.","Root Port에서는 구현이 금지된다.","enable되면 모든 P2P Request를 자동으로 Translated address로 변환한다."],["Implementation is optional. In Downstream Ports, controls in the Ingress (sending) Port determine whether a peer-to-peer Request is blocked, and if so that Ingress Port handles the ACS Violation. Completions are never affected.","It is required on every Downstream Port, and the Egress Port selectively drops Completions.","Implementation is forbidden in Root Ports.","When enabled, it automatically converts every P2P Request to a Translated address."],0,"소프트웨어는 Downstream Port(또는 Root Port/Hierarchy Domain) 단위로, 어느 Port가 다른 Port로 P2P Request를 보낼 수 있는지 선택적으로 열거나 닫을 수 있습니다.","Software can configure, on a per-Downstream-Port or per-Root-Port (hierarchy domain) basis, whether none or only a subset of Ports may send peer-to-peer Requests to others.","§6.12.1.1"],["p9q23","p9_5",3,"C","ACS Direct Translated P2P가 Downstream Port에서 enable된 경우의 동작은?","When ACS Direct Translated P2P is enabled in a Downstream Port, how are peer-to-peer Requests handled?",["Translated address Request는 항상 Upstream으로 redirect되고, Untranslated만 직접 전달된다.","모든 P2P Request가 AT 값과 무관하게 직접 전달된다.","Direct Translated P2P는 Completion의 AT 필드만 검사한다.","AT 필드가 Translated address를 나타내는 peer-to-peer Memory Request(Flit Mode에서는 Address Routed Message도)는, ACS P2P Request Redirect 및 P2P Egress Control 설정과 관계없이 peer Egress Port로 직접 라우팅되어야 한다. 나머지 P2P Request는 그 설정들의 적용을 받는다. Completion은 영향받지 않는다."],["Translated-address Requests are always redirected Upstream, and only Untranslated Requests go direct.","Every P2P Request goes direct, regardless of the AT value.","Direct Translated P2P inspects only the AT field of Completions.","A P2P Memory Request — and in Flit Mode a P2P Address Routed Message — whose AT says Translated goes straight to the peer Egress, ignoring Request Redirect and Egress Control. Every other P2P Request still follows those two controls. Completions are untouched."],3,"이 기능은 Switch Downstream Port에 필수입니다. ATS를 지원하고 다른 Root Port와 P2P를 지원하는 Root Port에도 필수입니다. 이미 번역된 주소의 P2P는 IOMMU를 다시 거치지 않고 직접 가게 하려는 경로입니다.","Switch Downstream Ports must implement this control, as must Root Ports that support ATS and peer-to-peer traffic with other Root Ports. The idea is to let already-translated P2P traffic go direct without being sent back through the IOMMU path.","§6.12.1.1"],["p9q24","p9_5",3,"C","ACS Upstream Forwarding이 Switch Downstream Port에서 enable된 경우, Ingress가 ‘자기 Egress를 대상’으로 하는 Upstream Request/Completion을 받으면?","If ACS Upstream Forwarding is on at a Switch Downstream Port, and Ingress sees an Upstream Request or Completion that targets that same Port's Egress, what must the Port do?",["그 TLP를 자기 Egress로 루프백해야 한다.","그 TLP를 RC 쪽으로 Upstream forwarding해야 한다.","그 TLP를 항상 silently discard해야 한다.","그 TLP를 Malformed TLP로 보고해야 한다."],["The Port must loop the TLP back out its own Egress.","It must send that TLP Upstream toward the RC rather than out its own Egress.","The Port must always silently discard the TLP.","The Port must report the TLP as a Malformed TLP."],1,"enable되어 있지 않은데 같은 상황이 발생하면 처리는 undefined입니다. Root Port에서 enable된 경우, Request는 P2P Request Redirect와 같이, Completion은 P2P Completion Redirect와 같이 다룹니다. 지원 요구는 Redirected Request Validation을 지원하는 Root Port와 Switch Downstream Port에 적용됩니다.","If Upstream Forwarding is not enabled and the same situation occurs, handling is undefined. When it is enabled in a Root Port, a Request is handled like a P2P Request Redirect, and a Completion like a P2P Completion Redirect. Root Ports need this feature when the RC implements Redirected Request Validation, and Switch Downstream Ports need it as well.","§6.12.1.1"],["p9q25","p9_6",2,"P","Multicast Hit가 발생하기 위한 조건으로 옳은 것은?","Which conditions must all be true for a Multicast Hit to occur?",["어떤 Memory Read든 주소가 MC_Base_Address 이상이면 항상 Hit이다.","MC_Enable이 Set이고, TLP가 non-UIO Memory Write Request 또는 Address Routed Message(둘 다 non-UIO Posted Request)이며, 주소가 Multicast address 범위 안에 있어야 한다.","MC_Enable과 무관하게 모든 Posted TLP가 Hit이다.","Configuration Write의 Bus Number가 Multicast Group과 같으면 Hit이다."],["Any Memory Read whose address is at or above MC_Base_Address is always a Hit.","MC_Enable is Set, the TLP is a non-UIO posted Memory Write or a non-UIO posted Address Routed Message, and the address lies inside the Multicast window.","Every Posted TLP is a Hit regardless of MC_Enable.","A Configuration Write is a Hit when its Bus Number equals a Multicast Group."],1,"범위는 AddressTLP >= MC_Base_Address 이고, AddressTLP < (MC_Base_Address + (2^MC_Index_Position * (MC_Num_Group + 1))) 입니다. Non-Posted Memory Request가 Multicast Window를 치더라도 Multicast Hit는 발생하지 않고, 기본 스펙대로 unicast로 처리됩니다.","The range is AddressTLP >= MC_Base_Address and AddressTLP < (MC_Base_Address + (2 raised to MC_Index_Position) times (MC_Num_Group + 1)). A Non-Posted Memory Request that lands in a Multicast Window is still handled as ordinary unicast; that is not a Multicast Hit.","§6.14.1"],["p9q26","p9_6",2,"P","Multicast Hit가 발생했을 때 routing과 ACS에 대한 규칙으로 옳은 것은?","When a Multicast Hit occurs, which statement about routing and ACS is correct?",["Hit 이후에도 보통의 address routing만 따르고 ACS는 모두 그대로 적용된다.","Hit이면 TLP를 항상 Root Port로만 보낸다.","ACS P2P Request Redirect만 적용되고 Source Validation은 무시된다.","보통의 address routing 규칙은 적용되지 않고, 주소에서 Multicast Group을 추출해 처리한다. 이때 여전히 적용될 수 있는 ACS 제어는 ACS Source Validation뿐이다."],["Normal address routing still applies after a Hit, and every ACS control still applies.","A Hit means the TLP is always sent only to a Root Port.","Only ACS P2P Request Redirect applies, and Source Validation is ignored.","Ordinary address routing is suspended. The address yields a Multicast Group, and the TLP is handled from that group. Of the ACS controls, only Source Validation may still apply."],3,"특히 ACS P2P Request Redirect와 ACS P2P Egress Control은 Multicast Hit 중의 동작에 영향을 주지 않습니다. Switch는 Multicast에 관여할 때를 제외하면 PCI Bridge 방식(예: address-based routing)으로 전달합니다.","During a Multicast Hit, P2P Request Redirect and P2P Egress Control do not apply. Outside Multicast, a Switch still forwards with ordinary PCI Bridge mechanisms such as address routing.","§6.14.1"],["p9q27","p9_6",3,"P","Multicast Group(MCG) 추출 식과, 소프트웨어가 Switch Function들을 구성할 때 지켜야 할 사항은?","How is the Multicast Group (MCG) extracted, and what must software keep consistent across Functions of a Switch?",["MCG = ((AddressTLP - MC_Base_Address) >> MC_Index_Position) & 3Fh 이다. 소프트웨어는 Switch의 모든 Function(그리고 Multi-Function Upstream Port의 모든 Function)에서 MC_Enable, MC_Base_Address, MC_Index_Position, MC_Num_Group을 같은 값으로 구성해야 한다.","MCG는 항상 Requester ID의 하위 6비트이고, Function마다 다른 MC_Enable을 권장한다.","MCG는 TC 필드와 같고, Switch는 Function마다 다른 base address를 써야 한다.","MCG는 Completer ID에서 얻으며, 구성 일관성은 요구되지 않는다."],["MCG is ((AddressTLP - MC_Base_Address) shifted right by MC_Index_Position) then masked with 3Fh. Software must program every Function of a Switch — and every Function of a Multi-Function Upstream Port — with identical MC_Enable, base, index, and group-count values.","MCG is always the low 6 bits of the Requester ID, and different MC_Enable values per Function are recommended.","MCG equals the TC field, and each Function of a Switch should use a different base address.","MCG is taken from the Completer ID, and software need not keep the fields consistent."],0,"일관되지 않으면 결과는 indeterminate입니다. 컴포넌트는 이 단계에서 아무 Function의 해당 필드 값이든 사용할 수 있습니다. 이후 Ingress Port의 MC_Block_All / MC_Block_Untranslated로 해당 MCG의 TLP를 막을 수 있습니다.","Results are indeterminate if those fields are not configured consistently. In this step a component may use any Function's values of those fields. The Ingress Port can still block the TLP for that MCG with MC_Block_All or MC_Block_Untranslated.","§6.14.1"],["p9q28","p9_6",2,"P","MC_Block_All 또는 MC_Block_Untranslated가 해당 MCG에 대해 Set된 경우의 처리는?","If MC_Block_All or MC_Block_Untranslated is Set for the group taken from the address, how is the TLP handled?",["해당 비트는 로그만 남기고 TLP는 항상 모든 Egress로 복제된다.","Blocked TLP는 Successful Completion으로 바뀐다.","MC_Block_All이 Set이면 그 TLP는 MC Blocked TLP로 다루어진다. MC_Block_Untranslated가 Set이고 TLP가 Untranslated Address를 담고 있으면 역시 MC Blocked TLP로 다루어진다.","이 비트들은 Endpoint에만 있고 Switch Ingress에는 적용되지 않는다."],["Those bits only create a log entry, and the TLP is always replicated to every Egress.","A blocked TLP is converted into a Successful Completion.","A Set MC_Block_All bit for that group makes the TLP an MC Blocked TLP. A Set MC_Block_Untranslated bit does the same when the TLP still carries an Untranslated Address.","These bits exist only in Endpoints and do not apply at a Switch Ingress Port."],2,"Switch와 Root Port는 Ingress Port의 해당 register로 검사하고, Endpoint Function은 자신이 보내려는 Multicast TLP를 자신의 register로 검사합니다. PIO Write는 보통 Untranslated이므로, Switch USP에서 PIO를 Multicast하려면 해당 MC_Block_Untranslated를 Clear해야 할 수 있습니다.","Switches and Root Ports check Multicast TLPs in the Ingress Port's registers. Endpoint Functions check Multicast TLPs they are about to send. PIO Writes generally have Untranslated addresses, so software may need to clear MC_Block_Untranslated in a Switch Upstream Port if that Switch must multicast PIO Writes.","§6.14.1"],["p9q29","p9_7",1,"C","PCI Express Native Hot-Plug가 다루는 작업과, Table 6-7에 나열된 요소의 예로 옳은 것은?","What operations does PCI Express Native Hot-Plug cover, and which items are examples of the elements listed in Table 6-7?",["hot-add만 지원하며, 유일한 요소는 Power Indicator이다.","케이블 제거만 지원하고 add-in card는 다루지 않는다.","운영체제와 무관한 강제 reset만 정의하며 물리적 요소는 없다.","hot-add와 hot-removal을 모두 지원한다. 요소 예로는 Indicators, MRL, MRL Sensor, Electromechanical Interlock, Attention Button, Software User Interface, Slot Numbering, Power Controller, Out-of-band Presence Detect가 있다."],["It supports only hot-add, and the only element is the Power Indicator.","It supports only cable removal and does not cover add-in cards.","It defines only a forced reset with no physical elements.","It supports both hot-add and hot-removal. Example elements include Indicators, an MRL, an MRL Sensor, an Electromechanical Interlock, an Attention Button, a Software User Interface, Slot Numbering, a Power Controller, and Out-of-band Presence Detect."],3,"이 인프라는 운영체제와 절차를 맞추는 순차 추가/제거뿐 아니라, OS와 lock-step으로 동기화하지 않는 async removal도 구현할 수 있게 합니다. 어떤 요소가 필수인지는 form factor 스펙이 정합니다.","The toolbox can implement orderly add/remove coordinated with the OS, and also async removal that does not stay in lock-step with the OS. A form factor specification decides which elements are required.","§6.7"],["p9q30","p9_7",2,"C","Attention Indicator와 Power Indicator의 색 및 상태 의미로 옳은 것은?","Which statement about Attention and Power Indicator colors and states is correct?",["두 Indicator 모두 파란색이어야 하고, On만 정의되며 Blinking은 금지된다.","Attention Indicator는 노란색 또는 호박색이어야 하고, Off=Normal, On=해당 slot의 운영 문제, Blinking=Locate이다. Power Indicator는 녹색이어야 하며, Off는 삽입/제거 허용, On은 전원 인가 완료, Blinking은 전원이 올라가는/내려가는 중을 뜻한다.","Attention은 녹색, Power는 빨간색이며, Off는 항상 고장이다.","색은 vendor-defined이고, On은 항상 제거 가능을 뜻한다."],["Both indicators must be blue, only On is defined, and blinking is forbidden.","The Attention Indicator must be yellow or amber: Off means Normal, On means an operational problem at the slot, and Blinking means Locate. The Power Indicator must be green: Off means insertion or removal is permitted, On means the hot-plug operation is complete and main power is on, and Blinking means the slot is powering up or down.","Attention must be green and Power must be red, and Off always means a fault.","Colors are vendor-defined, and On always means the adapter may be removed."],1,"Attention의 Blinking은 사용자가 slot을 찾도록 소프트웨어가 식별하는 동작입니다. Power의 Blinking은 Attention Button을 눌렀을 때 시각적 피드백도 제공합니다. 검증 실패(권한, 전력 예산 등)를 Attention On으로 보고하는 용도는 아닙니다.","A blinking Attention Indicator is system software identifying the slot so an operator can find it. A blinking Power Indicator also gives visual feedback when the Attention Button is pressed. Validation failures, such as permission or power-budget checks, are not reported by turning Attention On.","§6.7.1.1"],["p9q31","p9_7",2,"C","Hot-plug Indicator의 제어 주체와 깜빡임 특성으로 옳은 것은?","Who controls the hot-plug indicators, and what are the blinking requirements?",["각 Endpoint Function이 자기 Indicator를 직접 구동하며, 빈도는 10 Hz 고정이다.","Root Complex Event Collector만 Indicator를 제어하고, 깜빡임은 금지된다.","논리적 제어는 Link의 Upstream 구성 요소에 있는 Downstream Port가 한다. 깜빡임 빈도는 1–2 Hz, duty cycle은 50%(±5%)여야 한다. 소프트웨어가 명령하지 않는 한 Port는 상태를 바꾸면 안 된다(stuck-on power fault 시 Power Indicator를 On으로 강제하는 예외 가능).","Indicator는 하드웨어가 임의 주기로 자율 제어하며 소프트웨어는 읽기만 한다."],["Each Endpoint Function drives its own indicators directly, at a fixed 10 Hz.","Only a Root Complex Event Collector controls indicators, and blinking is forbidden.","The Downstream Port on the Link's Upstream side owns the logical control. Blink rate must stay between 1 and 2 Hz at a 50% duty cycle, plus or minus 5%. That Port changes an indicator only when software tells it to, except a platform may force Power Indicator on during a stuck-on power fault.","Hardware freely blinks at any rate, and software has read-only access."],2,"Port 사이 깜빡임이 동기이거나 위상이 맞을 필요는 없습니다. Indicator의 물리적 위치는 chassis 또는 adapter일 수 있고, form factor 스펙이 위치를 정합니다.","Blinking indicators need not be synchronous or in phase between Ports. Physically, an indicator may be on the chassis or on the adapter; the form factor specification locates it.","§6.7.1.1"],["p9q32","p9_7",2,"C","Attention Button의 동작으로 옳은 것은?","Which statement about the Attention Button is correct?",["slot 옆 또는 adapter에 있는 순간 접촉 push button으로, 사용자는 이 버튼으로 hot-add와 hot-remove를 모두 시작할 수 있어야 한다. Power Indicator가 깜빡이기 시작하면 5초의 abort 구간이 있어, 그 안에 버튼을 다시 누르면 작업이 취소된다.","버튼을 한 번 누르면 즉시 전원이 차단되고 abort는 불가능하다.","이 버튼은 hot-remove 전용이며 add는 소프트웨어 UI로만 한다.","버튼은 MRL이 열린 뒤에만 동작하고, abort 구간은 60초이다."],["It is a momentary-contact push button beside each hot-plug slot or on the adapter. The user must be able to start either a hot-add or a hot-remove with it. After the Power Indicator starts blinking, a 5-second abort window is open, and a second press in that window cancels the operation.","A single press immediately cuts power, and abort is impossible.","The button is only for hot-remove; add can be started only from a software UI.","The button works only after the MRL is opened, and the abort interval is 60 seconds."],0,"시스템 소프트웨어가 요청을 수락하면 Power Indicator가 깜빡이며 사용자에게 피드백을 줍니다. Attention Button Pressed 상태는 Slot Status에, enable은 Slot Control에 있습니다.","If system software accepts the request, the Power Indicator blinks as feedback to the operator. Attention Button Pressed lives in Slot Status, and the corresponding enable is in Slot Control.","§6.7.1.5"],["p9q33","p9_8",1,"C","Message의 implicit routing이란 무엇이며, 라우팅 값은 어디에서 읽나요?","What is implicit routing for Messages, and where is the routing value taken from?",["주소나 ID가 목적지를 지정하지 않고, routing type이 목적지를 암시한다. Message routing은 Type 필드의 r[2:0] sub-field로 결정된다.","항상 Destination Segment만으로 라우팅하며 r[2:0]은 Reserved이다.","implicit routing은 Completion에만 쓰이며 Requester ID의 상위 3비트를 사용한다.","모든 Message는 BAR 주소로만 라우팅되고 Type 필드는 무시된다."],["No address or ID specifies the destination; the destination is implied by the routing type. The r[2:0] bits inside the Type field select the Message routing.","Routing is always by Destination Segment alone, and r[2:0] is Reserved.","Implicit routing is used only with Completions and takes the top 3 bits of the Requester ID.","Every Message is routed only by a BAR address, and the Type field is ignored."],0,"값은 Table 2-20에 정의되어 있고, Message별로 허용 값이 정해집니다. Message Request는 posted이며 Completion이 필요 없고, ordering은 Memory Write Request와 같습니다.","The values are defined in Table 2-20, and each Message has a permitted set. Message Requests are posted, do not require a Completion, and follow the same ordering rules as Memory Write Requests.","§2.2.8"],["p9q34","p9_8",2,"C","Table 2-20의 Message Routing r[2:0] 인코딩으로 옳은 것은?","Which encoding of Message Routing r[2:0] from Table 2-20 is correct?",["000b=Broadcast, 001b=Local, 010b=Gathered, 011b=Address, 100b=ID, 101b–111b=Routed to Root Complex","r[2:0]은 항상 000b여야 하며 다른 값은 Malformed TLP이다.","000b=Routed to Root Complex, 001b=Routed by Address+AT(Flit Mode), 010b=Routed by ID, 011b=Broadcast from Root Complex, 100b=Local - Terminate at Receiver, 101b=Gathered and routed to Root Complex, 110b–111b=Reserved - Terminate at Receiver","000b=Routed by ID, 111b=Broadcast이며 나머지는 모두 Upstream으로만 간다."],["000b = Broadcast, 001b = Local, 010b = Gathered, 011b = Address, 100b = ID, and 101b–111b = Routed to Root Complex","r[2:0] must always be 000b, and any other value is a Malformed TLP.","000b = Routed to Root Complex, 001b = Routed by Address + AT in Flit Mode, 010b = Routed by ID, 011b = Broadcast from Root Complex, 100b = Local - Terminate at Receiver, 101b = Gathered and routed to Root Complex, and 110b–111b = Reserved - Terminate at Receiver","000b = Routed by ID, 111b = Broadcast, and every other value goes only Upstream."],2,"000b/011b/100b/101b/Reserved 값에서는 bytes 8–15가 Reserved입니다. 010b는 ID routing 규칙을 따릅니다. 001b는 Flit Mode에서 주소를 사용합니다.","For 000b, 011b, 100b, 101b, and the Reserved values, bytes 8 to 15 are Reserved. 010b follows the ID-routing rules. 001b uses the address in Flit Mode.","§2.2.8"],["p9q35","p9_8",2,"C","모든 Message Request에 적용되는 규칙으로 옳은 것은?","Which rule applies to all Message Requests?",["Message Code의 상위 4비트만 decode하면 되고, 하위 비트는 무시해도 된다.","Message Code 필드는 완전히 decode해야 하며 aliasing은 허용되지 않는다. 모든 Message Request는 Msg 또는 MsgD TLP Type을 사용한다.","Message Request는 항상 Non-Posted이며 Completion이 필수이다.","Message Request는 Attr[1:0]을 항상 00b에서 11b로 순환시켜야 한다."],["Only the upper 4 bits of Message Code need be decoded; the lower bits may be ignored.","Message Code has to be decoded in full; aliasing of Codes is not allowed. Every Message Request uses TLP Type Msg or MsgD.","Message Requests are always Non-Posted and require a Completion.","A Message Request must cycle Attr[1:0] from 00b through 11b."],1,"추가 필드로 Requester ID와 Message Code가 있으며, data가 있는 Message만 EP가 poison을 나타냅니다. INTx, Power Management, Error Signaling, Vendor-Defined, IDE Messages 등 여러 그룹이 정의되어 있습니다.","Message Requests also include a Requester ID and a Message Code. EP indicates a poisoned payload only for Messages that have data. Defined groups include INTx, Power Management, Error Signaling, Vendor-Defined, and IDE Messages, among others.","§2.2.8"],["p9q36","p9_8",3,"C","Flit Mode에서 Route by ID Message와 Destination Segment에 대한 규칙으로 옳은 것은?","In Flit Mode, which rule about Route-by-ID Messages and the Destination Segment is correct?",["Route by ID가 아니면 DSV를 반드시 Set해야 하고 Destination Segment는 FFh여야 한다.","OHC-A4는 Route by Address Message에만 허용되며 ID routing에는 금지된다.","DSV는 Non-Flit Mode에서만 정의되고 Flit Mode에서는 무시된다.","Destination Segment가 Requester Segment와 다르면 OHC-A4가 있어야 하고 그 byte 0에 Destination Segment를 담으며 DSV를 Set해야 한다. Route by ID가 아니면 DSV는 Clear해야 하고, 이때 Destination Segment는 00h여야 한다."],["When Route by ID is not used, DSV must be Set and the Destination Segment must be FFh.","OHC-A4 is permitted only on Route-by-Address Messages and is forbidden for ID routing.","DSV is defined only in Non-Flit Mode and is ignored in Flit Mode.","When Destination Segment and Requester Segment differ, OHC-A4 is required, byte 0 of that prefix holds the Destination Segment, and DSV is Set. If the Message is not Route-by-ID, DSV is Clear and Destination Segment must be 00h."],3,"Destination Segment가 Requester Segment와 같아도 DSV를 Set하는 것은 허용됩니다. PASID가 필요한 Route by ID Message에는 OHC-A4가 있어야 하고, PASID·ER·PMR가 필요한 Routed to Root Complex Message에는 OHC-A1이 있어야 합니다.","DSV is also permitted to be Set when the Destination Segment equals the Requester Segment. A Route-by-ID Message that needs PASID must include OHC-A4. A Routed-to-Root-Complex Message that needs PASID, ER, or PMR must include OHC-A1.","§2.2.8"],["c9q01","c9_1",1,"X","Single VCS 규칙으로 맞는 것은?","Which statement matches the Single VCS rules?",["DSP는 CXL mode만 지원하면 된다","USP 1개와 DSP 1개 이상으로 이루어지며, Fabric Manager는 optional","Fabric Manager가 반드시 있어야 한다","USP가 2개 이상이어야 한다"],["DSPs only need to support CXL mode","One USP plus one or more DSPs; the Fabric Manager is optional","A Fabric Manager is mandatory","It needs two or more USPs"],1,"Single VCS는 USP 하나와 DSP 하나 이상이에요. DSP는 CXL mode와 PCIe mode를 모두 지원해야 하고, FM은 없어도 돼요.","A Single VCS has one USP and one or more DSPs. DSPs must support both CXL and PCIe mode, and no FM is needed.","§7.1.1"],["c9q02","c9_1",1,"X","Multiple VCS switch에서 Fabric Manager가 반드시 필요한 경우는?","In a Multiple VCS switch, when is a Fabric Manager required?",["PCIe 장치를 연결할 때","USP가 2개일 때는 항상","bind/unbind가 필요하거나 MLD port를 지원할 때","FM은 Multiple VCS에서 금지된다"],["When a PCIe device is attached","Always, whenever there are two USPs","When bind/unbind is needed or MLD ports are supported","An FM is prohibited in Multiple VCS"],2,"Multiple VCS에서도 FM 자체는 optional이에요. 하지만 bind/unbind나 MLD port가 필요하면 FM이 있어야 해요.","The FM is optional even for Multiple VCS, but it becomes required once bind/unbind or MLD ports are needed.","§7.1.2"],["c9q03","c9_1",2,"X","Multiple VCS with MLD Ports 구성에서 MLD-capable DSP 하나는 USP 몇 개까지 연결될 수 있나요?","In a Multiple VCS with MLD Ports, up to how many USPs can one MLD-capable DSP connect to?",["4개","4096개","16개","1개"],["4","4096","16","1"],2,"MLD-capable DSP는 최대 16개 USP에 연결될 수 있어요. MLD의 host용 LD가 최대 16개인 것과 맞물려요. SLD DSP는 VCS 하나에만 bind돼요.","An MLD-capable DSP can connect to up to 16 USPs, matching the up-to-16 host LDs of an MLD. An SLD DSP binds to only one VCS.","§7.1.3"],["c9q04","c9_1",3,"X","DSP vPPB가 65개이고 USP vPPB의 Bus Number가 3인 switch가 있어요. vPPB 순서 규칙에 따르면 vPPB #33의 PCIe ID는?","A switch has 65 DSP vPPBs and its USP vPPB has Bus Number 3. By the vPPB ordering rule, what is the PCIe ID of vPPB #33?",["4:1.1","3:0.1","4:0.1","4:1.0"],["4:1.1","3:0.1","4:0.1","4:1.0"],2,"순서는 USP vPPB(#0) 다음, 모든 Device의 Function 0을 Device 번호 순으로 놓고, 그다음 Function 1로 넘어가요. #1~#32가 4:0.0~4:31.0이라 #33은 4:0.1이에요.","Order is the USP vPPB (#0), then Function 0 of every Device in Device order, then Function 1. #1-#32 are 4:0.0-4:31.0, so #33 is 4:0.1.","§7.1.4"],["c9q05","c9_2",1,"X","Static으로 초기화된 CXL switch의 특징은?","What is a characteristic of a statically initialized CXL switch?",["MLD port와 다른 VCS로의 rebinding을 지원하지 않고, FM이 필요 없다","PCIe mode를 지원하지 않는다","Host가 boot한 뒤에야 VCS가 정의된다","MLD port를 지원하고 FM이 필수다"],["No MLD ports and no rebinding to another VCS; no FM is required","It does not support PCIe mode","VCSs are defined only after the Host boots","It supports MLD ports and requires an FM"],0,"Static switch는 vendor 방식(예: SPI Flash 설정)으로 VCS와 binding을 boot 때 정해요. MLD와 rebinding이 없고 FM도 필요 없어요.","A static switch fixes VCSs and bindings at boot by vendor means, such as an SPI flash config. No MLD, no rebinding, and no FM.","§7.2.1.1"],["c9q06","c9_2",1,"X","어떤 physical port에도 bind되지 않은(unbound) vPPB는 Host에게 어떻게 보이나요?","How does a vPPB that is not bound to any physical port appear to the Host?",["Host에게 아예 보이지 않는다 (열거되지 않음)","Link Down 상태이고 Presence Detect 표시가 없다","Presence Detect는 있지만 Link Down","Link Up인데 장치가 없는 상태"],["Not visible to the Host at all (not enumerated)","Link Down, with no Presence Detect","Presence Detect set but Link Down","Link Up but with no device"],1,"unbound vPPB는 열거는 되지만 Link Down이고 Presence Detect가 없어요. PCIe 스위치의 빈 슬롯처럼 보이는 상태예요.","An unbound vPPB is still enumerated, but it is Link Down with no Presence Detect, much like an empty slot on a PCIe switch.","§7.2.3.1"],["c9q07","c9_2",2,"X","FM이 SLD port에 연결된 vPPB를 unbind하면 switch는 무엇을 하나요?","When the FM unbinds a vPPB attached to an SLD port, what does the switch do?",["그 port에 Link Disable을 걸고, port는 FM-owned가 되어 PPB 설정을 따른다","port를 그대로 두고 Host 트래픽을 계속 보낸다","장치에 CXL Reset을 자동으로 보낸다","port를 다른 VCS에 자동으로 bind한다"],["It asserts Link Disable on the port, and the port becomes FM-owned under its PPB settings","It leaves the port as is and keeps sending Host traffic","It automatically sends CXL Reset to the device","It automatically binds the port to another VCS"],0,"SLD unbind는 Link Disable을 걸어요. 그 뒤 port는 FM-owned가 되고, FM이 필요하면 FLR이나 CXL Reset으로 rebinding을 준비해요.","Unbinding an SLD asserts Link Disable. The port becomes FM-owned, and the FM may prepare it for rebinding with FLR or CXL Reset.","§7.2.3.1"],["c9q08","c9_2",1,"X","FM이 unbound physical port를 Host 쪽 vPPB에 bind하는 데 성공하면 Host는 무엇을 보나요?","When the FM successfully binds an unbound physical port to a Host's vPPB, what does the Host see?",["아무 변화 없음 (다음 boot까지)","hot-add indication (이후 열거는 일반 hot-add와 같다)","Host 전체 reset","surprise removal 오류"],["Nothing until the next boot","A hot-add indication; enumeration then works like a normal hot-add","A reset of the whole Host","A surprise removal error"],1,"bind가 성공하면 switch가 Host에 hot-add를 알려요. 그 뒤 열거와 설정은 장치를 hot-add했을 때와 같아요.","After a successful bind the switch signals hot-add to the Host. Enumeration and setup then match a normal device hot-add.","§7.2.3.1"],["c9q09","c9_2",3,"X","MLD 안의 LD 하나를 bind 또는 unbind할 때 금지되는 것은?","What is prohibited when binding or unbinding one LD inside an MLD?",["FM API 명령 사용","FM이 LD 메모리 할당을 바꾸는 것","PERST#, Hot Reset, Link Disable 같은 physical link에 영향을 주는 동작","bind 뒤 Host에 hot-add를 알리는 것"],["Using FM API commands","The FM changing LD memory allocation","Anything that affects the physical link, such as PERST#, Hot Reset, or Link Disable","Signaling hot-add to the Host after binding"],2,"MLD 링크는 여러 VCS가 같이 쓰므로, LD 하나의 bind/unbind가 링크나 다른 VCS 트래픽에 영향을 주면 안 돼요.","Several VCSs share the MLD link, so binding or unbinding one LD must not disturb the link or other VCSs' traffic.","§7.2.3.2"],["c9q10","c9_2",2,"X","MLD port의 physical PPB는 누가 소유하나요?","Who owns the physical PPB of an MLD port?",["소유자가 없다","그 MLD를 처음 열거한 Host","LD-ID 0이 bind된 VCS","항상 FM (link control, AER, DPC 등을 FM API로 관리)"],["No one owns it","The Host that first enumerated the MLD","The VCS bound to LD-ID 0","Always the FM, which manages link control, AER, DPC, and so on via the FM API"],3,"MLD port의 PPB는 항상 FM 소유예요. 물리 port의 설정과 오류 처리를 FM이 맡아요. FM은 PCIe Root Port가 아니라서 FMLD 열거는 switch가 대신해요.","The PPB of an MLD port is always FM-owned, and the FM handles the physical port's setup and errors. The FM is not a Root Port, so the switch enumerates the FMLD.","§7.2.3.2"],["c9q11","c9_2",3,"X","FM의 CXL.io 접근 규칙으로 맞는 것은?","Which is a correct rule about FM CXL.io access?",["FM-owned SLD port나 FM-owned LD에는 CXL.io로 접근할 수 있지만, bound port/LD에는 접근이 금지되고, FM API로 CXL.cache/CXL.mem을 만들 수는 없다","bound port에도 언제든 CXL.io로 접근할 수 있다","FM은 CXL.io로는 어떤 port에도 접근할 수 없다","FM API로 CXL.mem read/write를 생성할 수 있다"],["It may use CXL.io to FM-owned SLD ports and FM-owned LDs, not to bound ones, and the FM API cannot generate CXL.cache/CXL.mem","It may access bound ports over CXL.io at any time","It cannot reach any port over CXL.io","It can generate CXL.mem reads and writes through the FM API"],0,"switch는 FM이 bound SLD port나 bound LD에 CXL.io로 접근하는 것을 막아요. FM API는 CXL.cache/CXL.mem 트랜잭션을 만들지 않아요.","The switch blocks FM CXL.io access to bound SLD ports and bound LDs. The FM API never generates CXL.cache/CXL.mem transactions.","§7.2.3.1"],["c9q12","c9_3",1,"X","MLD가 Type 3 장치로만 한정되는 이유는?","Why are MLDs limited to Type 3 devices?",["Type 3만 256B Flit을 지원하기 때문","LD-ID가 CXL.io와 CXL.mem에만 있고 CXL.cache에는 없기 때문","FM이 Type 3만 관리할 수 있기 때문","Type 1/2는 PCIe Configuration Space가 없기 때문"],["Only Type 3 supports 256B Flit","LD-ID exists only in CXL.io and CXL.mem, not in CXL.cache","The FM can only manage Type 3","Type 1/2 have no PCIe Configuration Space"],1,"LD-ID 필드는 CXL.io와 CXL.mem에만 있어요. CXL.cache를 쓰는 Type 1/2는 LD로 나눌 수 없어서 MLD는 Type 3 전용이에요.","The LD-ID field exists only in CXL.io and CXL.mem. Type 1/2 rely on CXL.cache and cannot be split into LDs, so MLD is Type 3-only.","§2.4"],["c9q13","c9_3",1,"X","MLD component의 LD 구성으로 맞는 것은?","Which describes the LD makeup of an MLD component?",["FMLD를 포함해 LD 최대 16개","host용 LD 최대 4096개","FM 전용 LD(FMLD) 1개와, host에 bind할 수 있는 LD 최대 16개","FMLD 없이 LD 최대 8개"],["Up to 16 LDs including the FMLD","Up to 4096 LDs for hosts","One FM-owned LD (FMLD) plus up to 16 LDs for host binding","Up to 8 LDs and no FMLD"],2,"MLD에는 FM용 FMLD가 따로 있고, host binding용 LD가 최대 16개예요. 16개에 FMLD를 넣어 세면 틀려요.","An MLD has a separate FMLD for the FM plus up to 16 LDs for host binding. Counting the FMLD inside the 16 is wrong.","§2.4"],["c9q14","c9_3",2,"X","LD-ID 폭에 대한 설명으로 맞는 것은?","Which statement about LD-ID width is correct?",["필드는 16-bit지만 CXL.mem은 하위 4-bit만 써서 링크당 16개 값, CXL.io는 16-bit 전체를 나른다","LD-ID는 CXL.cache에서만 쓴다","CXL.mem은 12-bit, CXL.io는 4-bit를 쓴다","CXL.mem과 CXL.io 모두 16-bit 전체를 써서 65536개 LD를 구분한다"],["The field is 16-bit, but CXL.mem uses only the low 4 bits (16 values per link) while CXL.io carries all 16 bits","LD-ID is used only in CXL.cache","CXL.mem uses 12 bits and CXL.io uses 4 bits","Both CXL.mem and CXL.io use all 16 bits to tell 65536 LDs apart"],0,"LD-ID 자체는 16-bit 정의예요. CXL.mem은 하위 4-bit만 지원해서 링크당 16개이고, CXL.io는 16-bit를 모두 실어요.","LD-ID is defined as 16 bits. CXL.mem supports only the low 4 bits, so 16 per link; CXL.io carries all 16 bits.","§2.4.1"],["c9q15","c9_3",2,"X","CXL.io에서 LD-ID FFFFh는 무엇에 쓰이나요?","In CXL.io, what is LD-ID FFFFh used for?",["모든 LD에 보내는 broadcast","LD-ID가 없는 SLD 표시","예약 값으로, 항상 FM이 쓴다 (switch는 FM만 쓰도록 보장)","오류가 난 LD 표시"],["A broadcast to all LDs","A marker for an SLD with no LD-ID","It is reserved and always used by the FM; the switch ensures only the FM uses it","A marker for a failed LD"],2,"FFFFh는 FM 전용이에요. FM만 접근하는 MLD DVSEC도 이 LD-ID로 접근해요. broadcast 뜻은 없어요.","FFFFh is reserved for the FM, and the FM-only MLD DVSEC is reached with it. It does not mean broadcast.","§2.4.1.2"],["c9q16","c9_3",2,"X","FMLD의 bus mastering 능력은 어떻게 제한되나요?","How is the bus-mastering capability of the FMLD limited?",["제한이 없다","host memory에 DMA를 자유롭게 할 수 있다","CXL.cache 요청을 만들 수 있다","오류 메시지 생성만 가능하고, 그 메시지는 FM으로만 route된다"],["It has no limits","It can freely DMA into host memory","It can issue CXL.cache requests","It can only generate error messages, which are routed only to the FM"],3,"FMLD는 오류 메시지만 만들 수 있고, 그 메시지는 FM에만 가야 해요.","The FMLD can only generate error messages, and those must go only to the FM.","§2.4"],["c9q17","c9_3",3,"X","MLD에서 AER 이벤트는 LD 사이에서 어떻게 보고되나요?","In an MLD, how are AER events reported across LDs?",["항상 모든 LD에 똑같이 보고한다","LD는 AER를 구현하지 않는다","항상 FMLD에서만 보고한다","MLD 전체에 uncorrectable인 이벤트는 모든 LD에 보고하고, 한 LD에만 해당하면 그 LD에만 격리한다"],["Always reported identically in every LD","LDs do not implement AER","Always reported only in the FMLD","An event uncorrectable to the whole MLD is reported in all LDs; an LD-specific one is kept to that LD"],3,"AER는 LD마다 지원돼요. MLD 전체 문제면 모든 LD에 보이고, 특정 LD 문제면 그 LD로 격리돼요.","AER is supported per LD. A whole-MLD problem shows in every LD, while an LD-specific one stays in that LD.","§2.4.2"],["c9q18","c9_4",1,"X","pooled FAM과 Shared FAM의 차이로 맞는 것은?","Which correctly separates pooled FAM from Shared FAM?",["둘은 같은 말이다","pooled는 여러 host가 동시에 쓰고, Shared는 host 하나 전용이다","pooled는 각 HDM region을 host 하나에 전용으로 주고, Shared는 여러 host가 한 region에 동시에 접근한다","Shared FAM은 G-FAM에서만, pooled는 MLD에서만 가능하다"],["They mean the same thing","Pooled is concurrent multi-host access; Shared is one host only","Pooled dedicates each HDM region to one host; Shared lets several hosts access one region concurrently","Shared FAM exists only on G-FAM and pooled only on MLDs"],2,"pooled memory는 region 하나가 host 하나 전용이에요. Shared FAM은 여러 host가 같은 region에 동시에 접근해요. LD-FAM과 G-FAM 모두 둘 다 지원할 수 있어요.","In pooled memory each region belongs to one host. In Shared FAM several hosts access the same region at once. Both LD-FAM and G-FAM can support either.","§2.4.3"],["c9q19","c9_4",1,"X","LD로 노출되는 FAM과 PBR 링크로 더 크게 노출되는 FAM을 각각 무엇이라 부르나요?","What are FAM exposed through LDs and FAM exposed more scalably over PBR links called?",["SLD와 MLD","LD-FAM과 G-FAM","GIM과 PDM","HDM-H와 HDM-DB"],["SLD and MLD","LD-FAM and G-FAM","GIM and PDM","HDM-H and HDM-DB"],1,"여러 host를 지원하는 장치의 HDM을 FAM이라 해요. LD로 나누면 LD-FAM, PBR로 크게 확장하면 G-FAM이에요.","HDM from a multi-host device is FAM. Exposed through LDs it is LD-FAM; scaled out over PBR it is G-FAM.","§2.4.3"],["c9q20","c9_4",2,"X","공유되는 HDM-DB region의 coherency model은 누가, 무엇 중에서 정하나요?","Who sets the coherency model of a shared HDM-DB region, and what are the options?",["FM이 multi-host hardware coherency와 software-managed coherency 중에서 정한다","Host OS가 HDM-D와 HDM-H 중에서 정한다","장치가 boot할 때 Device Bias와 Host Bias 중에서 정한다","스펙이 hardware coherency로 고정한다"],["The FM picks multi-host hardware coherency or software-managed coherency","The Host OS picks HDM-D or HDM-H","The device picks Device Bias or Host Bias at boot","The spec fixes it to hardware coherency"],0,"Shared HDM-DB region마다 FM이 model을 정해요. hardware 방식은 장치가 snoop filter나 directory로 host 상태를 추적하고, software 방식은 그런 추적이 없어요.","The FM sets the model per shared HDM-DB region. In the hardware model the device tracks host state with a snoop filter or directory; the software model has no such tracking.","§2.4.4"],["c9q21","c9_4",3,"X","Shared FAM의 hardware coherency region에 대한 MemWr 규칙은?","What is the MemWr rule for a hardware-coherent Shared FAM region?",["SnpType을 No-Op으로 두어야 하므로, host가 먼저 M2S Req로 ownership을 얻은 뒤 쓰는 2단계 write가 된다","snoopable 1단계 write만 허용된다","SnpType은 자유롭게 고를 수 있다","MemWr는 금지되고 UIO만 쓴다"],["SnpType must be No-Op, so the host first gains ownership on the M2S Req channel, making a two-phase write","Only single-phase snoopable writes are allowed","Any SnpType may be used","MemWr is banned and only UIO is used"],0,"deadlock을 피하려고 MemWr의 SnpType은 No-Op이어야 해요. 그래서 ownership 획득과 write가 나뉜 2단계가 돼요. 공유하지 않는 단일 host HDM-DB는 1단계 snoopable write를 쓸 수 있어요.","To avoid deadlock, MemWr must use SnpType No-Op, so ownership and the write are two phases. A non-shared, single-host HDM-DB region can use single-phase snoopable writes.","§2.4.4"],["c9q22","c9_4",2,"X","Shared FAM을 HDM-H로 노출하면 host 사이 coherence는 어떻게 되나요?","If Shared FAM is exposed as HDM-H, how is coherence between hosts handled?",["software coherence model만 지원한다","BISnp로 hardware coherency를 맞춘다","hardware coherency가 자동으로 지원된다","HDM-H는 Shared FAM에 쓸 수 없다"],["Only the software coherence model is supported","BISnp keeps hardware coherency","Hardware coherency is supported automatically","HDM-H cannot be used for Shared FAM"],0,"HDM-H에는 BI 채널이 없어서 host 사이 hardware coherency를 만들 수 없어요. 그래서 software coherence만 돼요.","HDM-H has no BI channel, so it cannot provide hardware coherency between hosts. Only software coherence works.","§2.4.4"],["c9q23","c9_5",1,"X","Multi-Headed Device에 대한 설명으로 맞는 것은?","Which statement describes a Multi-Headed Device?",["x16 링크를 x4 네 개로 bifurcation한 Type 1 장치","PBR switch의 다른 이름","CXL.cache를 여러 host에 나누는 Type 2 장치","CXL port(head)가 여러 개인 Type 3 장치로, MH-SLD와 MH-MLD 두 종류가 있다"],["A Type 1 device that bifurcates x16 into four x4 links","Another name for a PBR switch","A Type 2 device that splits CXL.cache across hosts","A Type 3 device with several CXL ports (heads), in MH-SLD and MH-MLD forms"],3,"Multi-Headed Device는 port(head)가 여러 개인 Type 3예요. 모든 head에 SLD를 보이면 MH-SLD, head에 MLD를 보일 수 있으면 MH-MLD예요.","A Multi-Headed Device is a Type 3 with several ports (heads). Showing SLDs on all heads makes it an MH-SLD; showing MLDs on heads makes it an MH-MLD.","§2.5"],["c9q24","c9_5",2,"X","Multi-Headed Device의 head에 매핑된 LD 수에 따른 규칙은?","What is the rule tied to the number of LDs mapped to a head of a Multi-Headed Device?",["head마다 LD 1~16개, LD 1개면 SLD로, 2개 이상이면 MLD로 보인다","한 LD를 여러 head에 동시에 매핑할 수 있다","LD 수와 상관없이 항상 MLD로 보인다","head마다 LD는 정확히 16개여야 한다"],["Each head has 1 to 16 LDs; one LD presents as an SLD, more than one as an MLD","One LD can be mapped to several heads at once","It always presents as an MLD regardless of LD count","Every head must have exactly 16 LDs"],0,"head에는 LD가 1개 이상 16개 이하로 매핑돼요. 1개면 SLD, 여러 개면 MLD로 보여요. LD는 head 하나에만 매핑돼요.","A head has between 1 and 16 LDs. With one it shows as an SLD, with more as an MLD. Each LD maps to a single head.","§2.5"],["c9q25","c9_5",3,"X","MH-MLD의 LD pool과 LD-ID에 대한 설명으로 맞는 것은?","Which statement about the LD pool and LD-IDs of an MH-MLD is correct?",["각 head의 FMLD는 장치의 모든 LD를 직접 관리한다","모든 head가 같은 장치 전체 LD-ID를 그대로 쓴다","LD pool은 장치 전체에서 최대 16개다","LD pool은 16개보다 많을 수 있고, 각 head는 0부터 n-1까지 head 기준 LD-ID를 써서 장치 전체 index로 매핑한다"],["Each head's FMLD directly manages every LD in the device","Every head uses the same device-wide LD-IDs directly","The pool holds at most 16 LDs device-wide","The pool may exceed 16 LDs; each head uses head-relative LD-IDs 0 to n-1 that map to device-wide indexes"],3,"MH-MLD의 LD pool은 16개를 넘을 수 있어요. head는 자기 LD만 0~n-1로 부르고, 장치가 이를 pool index로 바꿔요. 다른 head의 LD는 Tunnel Management로 LD Pool CCI를 거쳐야 보여요.","An MH-MLD's pool may exceed 16 LDs. Each head numbers its own LDs 0 to n-1 and the device maps them to pool indexes. Other heads' LDs are reached through the LD Pool CCI via Tunnel Management.","§2.5.1"],["c9q26","c9_6",1,"C","VCS 안에서 CXL.io TLP는 어떻게 route되나요?","How are CXL.io TLPs routed inside a VCS?",["LD-ID 순서대로 broadcast된다","PID 기반 PBR로만 route된다","다른 VCS의 PPB로도 자유롭게 P2P가 된다","PCIe Base Spec의 switch 규칙을 따르고, 같은 VCS 안의 PPB로만 route된다"],["Broadcast in LD-ID order","Only by PID-based PBR","Free P2P to PPBs in other VCSs too","By PCIe Base Spec switch rules, only to PPBs in the same VCS"],3,"VCS 안의 CXL.io는 PCIe switch의 request/completion·decode 규칙을 그대로 따라요. switch 안 P2P는 같은 VCS로 제한돼요.","CXL.io inside a VCS follows PCIe switch request, completion, and decode rules. P2P within the switch is limited to the same VCS.","§7.3.1.1"],["c9q27","c9_6",2,"X","CXL.cache multi-device scaling 기능이 없는 switch에서 Type 1/2 장치용으로 enable할 수 있는 SLD port는 VCS당 몇 개인가요?","On a switch without CXL.cache multi-device scaling, how many SLD ports per VCS can be enabled for Type 1/2 devices?",["16개","1개","제한 없음","2개"],["16","One","Unlimited","Two"],1,"scaling 기능이 없으면 VCS당 CXL.cache 장치는 하나뿐이에요. 그래서 이런 switch는 CXL.cache용 decode register가 따로 필요 없어요.","Without the scaling feature, a VCS can have only one CXL.cache device, so such switches need no extra CXL.cache decode registers.","§7.3.2"],["c9q28","c9_6",2,"X","VH 아래에 Type 1/Type 2 장치를 최대 16개까지 두려면 Type 2 장치는 무엇을 써야 하나요?","To place up to 16 Type 1/Type 2 devices below a VH, what must Type 2 devices use?",["PBR 링크","HDM coherence에 CXL.cache","HDM coherence에 CXL.mem의 BISnp 채널","Device Bias 모드만"],["A PBR link","CXL.cache for HDM coherence","The CXL.mem BISnp channel for HDM coherence","Device Bias mode only"],2,"16개 확장에는 BISnp가 필요해요. CXL.cache로 HDM-D coherence를 하는 Type 2는 Host bridge당 1개로 제한돼요.","Scaling to 16 needs BISnp. A Type 2 that uses CXL.cache for HDM-D coherence is limited to one per Host bridge.","§2.6"],["c9q29","c9_6",3,"X","switch가 256B flit 메시지의 Reserved bit를 다룰 때의 규칙은?","What is the switch rule for Reserved bits in 256B flit messages?",["항상 0으로 지운다","256B 포트 사이(HBR↔PBR 변환 포함)에서는 보존해 forwarding하고, 68B 포트로 보낼 때는 0으로 지운다","Reserved bit가 1이면 메시지를 버린다","68B 포트로도 그대로 forwarding한다"],["Always clear them to 0","Preserve and forward them between 256B ports, including HBR/PBR translation; clear them to 0 toward a 68B port","Drop the message if any Reserved bit is 1","Forward them unchanged to 68B ports too"],1,"Reserved bit forwarding 덕분에 switch를 바꾸지 않고 새 기능을 쓸 수 있어요. 새 기능은 256B에만 추가될 예정이라 68B 쪽은 지워요.","Forwarding Reserved bits lets new features work without changing switches. New features are expected only in 256B formats, so they are cleared toward 68B.","§7.3.2.1"],["c9q30","c9_6",2,"X","Host가 보낸 GPF Phase 1 요청은 switch에서 어떻게 처리되나요?","How does a switch handle a Host's GPF Phase 1 request?",["FM이 받아서 처리한다","switch는 무시하고 장치로 보내지 않는다","switch를 그대로 통과해 장치까지 간다","USP에서 끝나고, switch가 VCS 안 모든 port로 다시 만들어 보내며, 장치 응답은 모아서 하나로 돌려준다"],["The FM receives and handles it","The switch ignores it and does not forward it","It passes through the switch unchanged to devices","It terminates at the USP; the switch regenerates it to every port in the VCS and consolidates device responses"],3,"CXL VDM은 Local-Terminate at Receiver 유형이에요. switch가 aggregation을 맡아 하류로 다시 보내고 응답을 합쳐요.","CXL VDMs are Local-Terminate at Receiver. The switch aggregates: it regenerates them downstream and consolidates the responses.","§7.4.3"],["c9q31","c9_6",1,"C","Host가 장치에 FLR을 쓰면 CXL switch는 어떻게 관여하나요?","When the Host writes FLR to a device, how does the CXL switch take part?",["해당 VCS를 Viral 상태로 만든다","Switch 전체를 reset한다","해당 port에 PERST#를 건다","관여하지 않는다 (non-pooled, pooled 모두)"],["It puts that VCS into Viral","It resets the whole switch","It asserts PERST# on that port","It does not take part, for both non-pooled and pooled devices"],3,"FLR은 Function 단위 reset이라 switch가 개입하지 않아요. PCIe switch에서도 같아요.","FLR is a per-Function reset, so the switch is not involved, just as on a PCIe switch.","§7.5"],["c9q32","c9_7",1,"X","Fabric Manager(FM)에 대한 설명으로 맞는 것은?","Which statement about the Fabric Manager (FM) is correct?",["반드시 전용 BMC 칩이어야 한다","switch 안의 hardware state machine만 가능하다","PCIe Root Port의 한 종류다","재구성을 결정하고 명령을 내리는 논리적 프로세스로, host SW, BMC, switch/장치 firmware, state machine 등 어떤 형태든 될 수 있다"],["It must be a dedicated BMC chip","It can only be a hardware state machine inside a switch","It is a type of PCIe Root Port","A logical process that decides on and issues reconfiguration; it can be host software, a BMC, switch or device firmware, a state machine, and so on"],3,"FM은 형태가 정해지지 않은 논리적 프로세스예요. 언제 재구성할지 정하고 FM API 명령을 보내는 주체예요.","The FM is a logical process with no fixed form. It decides when to reconfigure and sends the FM API commands.","§7.6.1"],["c9q33","c9_7",2,"X","FM은 CXL 장치에 FM API 명령을 어떤 통로로 보내나요?","Through what path does the FM send FM API commands to CXL devices?",["PERST#와 같은 sideband 신호로","CCI를 통해서. CCI는 Mailbox register나 MCTP-capable interface로 노출된다","CXL.mem의 MemWr로만","PCIe Configuration Write로만"],["Through sideband signals such as PERST#","Through a CCI, exposed via Mailbox registers or an MCTP-capable interface","Only through CXL.mem MemWr","Only through PCIe configuration writes"],1,"FM API는 CCI로 전달돼요. CCI는 Mailbox register나 MCTP 인터페이스(SMBus, I3C, PCIe VDM 등)로 열려요. MCTP binding은 DMTF DSP0234예요.","The FM API rides a CCI, exposed via Mailbox registers or an MCTP interface such as SMBus, I3C, or PCIe VDM. The MCTP binding is DMTF DSP0234.","§7.6.2"],["c9q34","c9_7",2,"X","FM API에서 Bind vPPB와 Unbind vPPB의 opcode는?","What are the FM API opcodes for Bind vPPB and Unbind vPPB?",["5201h와 5202h","5300h와 5301h","5400h와 5402h","5100h와 5101h"],["5201h and 5202h","5300h and 5301h","5400h and 5402h","5100h and 5101h"],0,"Virtual Switch command set(52xxh)에 Bind 5201h, Unbind 5202h가 있어요. 5100h/5101h는 Physical Switch, 5300h는 Tunnel Management, 54xxh는 MLD Component 명령이에요.","In the Virtual Switch set (52xxh), Bind is 5201h and Unbind is 5202h. 5100h/5101h are Physical Switch, 5300h is Tunnel Management, and 54xxh are MLD Component commands.","§7.6.7.2.2"],["c9q35","c9_7",1,"X","CXL Switch Mailbox CCI에 대한 설명으로 맞는 것은?","Which statement about the CXL Switch Mailbox CCI is correct?",["Type 1 header를 가진 PPB로 노출된다","모든 switch에 필수다","DSP에만 둘 수 있다","optional이며, Type 0 configuration space를 가진 PCIe Endpoint로 노출된다"],["It appears as a PPB with a Type 1 header","Every switch must have one","It can only be placed on a DSP","It is optional and appears as a PCIe Endpoint with a Type 0 configuration space"],3,"Switch Mailbox CCI는 optional이에요. USP의 추가 function으로 두거나, vPPB 없는 VCS에서 유일한 function으로 둘 수 있어요.","The Switch Mailbox CCI is optional. It can be an extra function of the USP or the only function in a VCS with no vPPBs.","§7.2.9"],["c9q36","c9_8",1,"X","CXL PBR fabric에서 Edge Port를 구분하는 ID와 최대 수는?","In a CXL PBR fabric, what ID identifies Edge Ports, and up to how many?",["12-bit PID(SPID/DPID), 최대 4096개","16-bit BDF, 최대 65536개","4-bit LD-ID, 최대 16개","8-bit Bus Number, 최대 256개"],["12-bit PIDs (SPID/DPID), up to 4096","16-bit BDFs, up to 65536","4-bit LD-IDs, up to 16","8-bit Bus Numbers, up to 256"],0,"PBR은 12-bit PID로 Edge Port를 최대 4096개까지 구분해요. 이 기능은 CXL 3.0에서 들어왔고 4.0 신규가 아니에요.","PBR uses 12-bit PIDs to identify up to 4096 Edge Ports. It came in CXL 3.0 and is not new in 4.0.","§7.7"],["c9q37","c9_8",1,"X","CXL에서 'HBR switch'는 무엇을 가리키나요?","In CXL, what does 'HBR switch' refer to?",["CXL 4.0에서 새로 생긴 128 GT/s 전용 switch","PID로 route하는 fabric switch","CXL 2.0에서 도입되어 이후 확장된 Hierarchy Based Routing switch","PCIe 전용 switch로 CXL을 지원하지 않는 것"],["A new 128 GT/s-only switch in CXL 4.0","A fabric switch that routes by PID","The Hierarchy Based Routing switch introduced in CXL 2.0 and extended since","A PCIe-only switch with no CXL support"],2,"HBR은 CXL 2.0부터 있던 VCS 기반 switch의 줄임말이에요. PBR은 PID로 route하는 fabric switch예요.","HBR is shorthand for the VCS-based switches from CXL 2.0. PBR switches route by PID.","§7.7.5"],["c9q38","c9_8",2,"X","Downstream Port가 PBR flit을 enable할 수 있는 조건은?","Under what condition may a Downstream Port enable PBR flits?",["PCIe Flit mode가 enable되어 있어야 한다","Sync Header bypass가 켜져 있을 때만","68B Flit mode일 때만","링크 속도가 128 GT/s일 때만"],["PCIe Flit mode must be enabled","Only with Sync Header bypass on","Only in 68B Flit mode","Only at 128 GT/s"],0,"PBR flit은 Flex Bus 협상에서 정해지고, PCIe Flit mode가 꺼져 있으면 enable하면 안 돼요. PBR 메시지는 256B flit 체계 위에 있어요.","PBR flits are negotiated in Flex Bus and must not be enabled unless PCIe Flit mode is on. PBR messages build on the 256B flit scheme.","§6.4.1.1"],["c9q39","c9_8",2,"X","HBR/PBR switch 연결 규칙으로 맞는 것은?","Which HBR/PBR switch connection rule is correct?",["GFD는 HBR DSP에도 연결할 수 있다","HBR USP는 host RP에만 연결할 수 있다","GFD는 PBR DSP에만 연결할 수 있고, PBR USP는 host RP에만 연결할 수 있다","PBR USP를 HBR DSP 아래에 연결할 수 있다"],["A GFD may also attach to an HBR DSP","An HBR USP may attach only to a host RP","A GFD may attach only to a PBR DSP, and a PBR USP only to a host RP","A PBR USP may sit below an HBR DSP"],2,"GFD는 PBR DSP에만 붙어요. PBR USP는 host RP에만 붙고 HBR DSP 아래는 안 돼요. 반대로 HBR USP는 host RP, PBR DSP, HBR DSP 모두에 붙을 수 있어요.","A GFD attaches only to a PBR DSP. A PBR USP attaches only to a host RP, never below an HBR DSP. An HBR USP can attach to a host RP, a PBR DSP, or an HBR DSP.","§7.7.5"],["c9q40","c9_8",2,"X","PBR fabric에 연결된 Host는 fabric을 어떻게 보나요?","How does a Host attached to a PBR fabric see the fabric?",["PCIe Base Spec을 따르는 단순한 switch topology로 보며, 중간 fabric switch는 숨겨지고 Edge Switch는 최대 두 층까지만 보인다","4096개 PID가 모두 Bus Number로 보인다","fabric 전용 discovery driver가 있어야 한다","모든 fabric switch가 PCIe switch로 하나씩 보인다"],["As a simple PCIe-compliant switch topology; intermediate fabric switches are hidden and at most two layers of Edge Switches show","All 4096 PIDs appear as Bus Numbers","A fabric-specific discovery driver is required","Every fabric switch appears as its own PCIe switch"],0,"Host는 Host ES와, 필요하면 Downstream ES까지만 봐요. 중간 switch는 vDSP-vUSP 사이의 링크 하나로 보이고, 중간 ISL이 끊기면 그 vPPB에 surprise Link Down이 보고돼요.","The Host sees the Host ES and, if bound, a Downstream ES. Intermediate switches collapse into one vDSP-vUSP link, and an ISL failure is reported as a surprise Link Down on that vPPB.","§7.7.6.1"],["c9q41","c9_8",3,"X","PBR switch의 message format 변환에 대한 설명으로 맞는 것은?","Which statement about PBR switch message format conversion is correct?",["PBR format은 LD-ID를 16-bit로 확장한 것이다","HBR 장치도 12-bit PID를 직접 만들어 보내야 한다","변환은 GFD 안에서만 일어난다","HBR 메시지의 4-bit LD-ID·4-bit CacheID 같은 non-PID 공간을 12-bit PID 기반 PBR format으로 바꾸고, fabric에서 HBR 쪽으로 나갈 때는 되돌린다"],["PBR format is just LD-ID widened to 16 bits","HBR devices must generate 12-bit PIDs themselves","Conversion happens only inside GFDs","It maps non-PID spaces such as the 4-bit LD-ID and 4-bit CacheID of HBR messages to 12-bit PID-based PBR format, and back toward HBR targets"],3,"fabric을 모르는 host와 장치는 HBR format을 써요. Edge의 PBR switch가 이를 PID 기반 PBR format으로 바꾸고, 응답은 다시 CacheID, BI-ID, LD-ID로 돌려요.","Hosts and devices that do not know the fabric use HBR format. The edge PBR switch converts to PID-based PBR, and converts back to CacheID, BI-ID, or LD-ID toward them.","§7.7.6.6"],["c9q42","c9_8",2,"X","PBR switch의 static routing과 dynamic routing에 대한 설명으로 맞는 것은?","Which statement about static and dynamic routing in PBR switches is correct?",["모든 메시지가 항상 dynamic routing을 쓴다","ordering을 지키려면 static routing이 필요하고, payload를 나르는 메시지에는 여러 링크로 분산하는 dynamic routing이 특히 선호된다","dynamic routing은 vDSP/vUSP binding 메시지에만 쓴다","static routing은 금지된다"],["All messages always use dynamic routing","Static routing is needed where ordering must be kept; dynamic routing, which spreads traffic over links, is preferred for payload-carrying messages","Dynamic routing is used only for vDSP/vUSP binding messages","Static routing is prohibited"],1,"message class마다 static/dynamic이 정해져요. ordering 규칙이 있는 곳은 static이고, vDSP/vUSP binding 메시지도 항상 static이에요. data가 큰 메시지는 dynamic이 유리해요.","Each message class has its own routing. Ordering-sensitive traffic is static, and vDSP/vUSP binding messages are always static. Payload-heavy messages benefit from dynamic routing.","§7.7.6.2"],["c9q43","c9_9",1,"X","G-FAM device(GFD)는 메모리 용량을 어떻게 관리하나요?","How does a G-FAM device (GFD) manage memory capacity?",["static capacity만 사용한다","Dynamic Capacity 메커니즘만 사용한다","static과 Dynamic Capacity를 섞어 쓴다","Host BIOS가 boot 때 고정한다"],["Only through static capacity","Only through the Dynamic Capacity mechanism","A mix of static and Dynamic Capacity","The Host BIOS fixes it at boot"],1,"GFD에는 legacy static capacity가 없어요. 용량은 모두 Dynamic Capacity(DC Region, Extent, Block)로 관리해요.","A GFD has no legacy static capacity. All capacity is managed through Dynamic Capacity: DC Regions, Extents, and Blocks.","§2.8"],["c9q44","c9_9",2,"X","MLD와 비교한 GFD의 주소 공간 특징은?","How does a GFD's address space differ from an MLD's?",["GFD도 LD마다 DPA 공간이 따로 있다","GFD는 모든 host와 peer가 공통으로 쓰는 DPA 공간 하나를 두고, requester별 decoder로 HPA를 DPA로 바꾼다","GFD는 HPA를 그대로 DPA로 쓴다","GFD는 host 하나만 접근할 수 있다"],["A GFD also has a separate DPA space per LD","A GFD has one DPA space shared by all hosts and peers, and translates HPA to DPA with per-requester decoders","A GFD uses HPA directly as DPA","Only one host can access a GFD"],1,"MLD는 LD마다 DPA 공간이 있지만, GFD는 DPA 공간이 하나예요. 서로 다른 requester의 HPA 범위를 같은 DPA 범위에 매핑하면 공유 메모리가 돼요. GFD에는 PCIe configuration space도 없어요.","An MLD has a DPA space per LD; a GFD has just one. Mapping different requesters' HPA ranges to one DPA range creates shared memory. A GFD also has no PCIe configuration space.","§7.7.2.1"],["c9q45","c9_9",3,"X","G-FAM 메모리를 여러 GFD에 interleave할 때 허용되는 범위는?","When interleaving G-FAM memory across GFDs, what is allowed?",["최대 8개 GFD, granularity 1MB 이상","최대 16개 GFD, granularity 64B 고정","2~256개 사이의 2의 거듭제곱 개 GFD, granularity 256B~16KB","3개를 포함한 아무 개수, granularity 4KB 고정"],["Up to 8 GFDs, with 1MB or larger granularity","Up to 16 GFDs, with a fixed 64B granularity","A power-of-two count from 2 to 256 GFDs, with 256B to 16KB granularity","Any count including 3, with a fixed 4KB granularity"],2,"G-FAM interleave는 2의 거듭제곱 개(2~256) GFD에 걸 수 있고, granularity는 256B, 512B, 1KB, 2KB, 4KB, 8KB, 16KB 중 하나예요.","G-FAM can interleave across a power-of-two number of GFDs from 2 to 256, at 256B, 512B, 1KB, 2KB, 4KB, 8KB, or 16KB granularity.","§7.7.2.1"],["c9q46","c9_9",2,"X","Global Integrated Memory(GIM)에 접근할 때 쓰는 트랜잭션은?","What transactions are used to access Global Integrated Memory (GIM)?",["BISnp","Unordered I/O(UIO). CXL.mem이나 CXL.cache는 쓰면 안 된다","CXL.mem MemRd/MemWr","CXL.cache D2H Req"],["BISnp","Unordered I/O (UIO); CXL.mem and CXL.cache must not be used","CXL.mem MemRd/MemWr","CXL.cache D2H Req"],1,"GIM은 다른 host domain의 메모리를 내 HPA에 매핑한 거예요. cross-domain 접근은 UIO로만 하고 I/O coherent예요. 주로 RDMA와 메시징용이고 memory pooling용이 아니에요.","GIM maps another host domain's memory into local HPA. Cross-domain access uses UIO only and is I/O coherent. It is meant for RDMA and messaging, not memory pooling.","§7.7.3"]],"10":[["p10q01","p10_1",1,"P","IDE(Integrity and Data Encryption)가 TLP에 제공하는 보호는?","What protection does Integrity and Data Encryption (IDE) provide for TLPs?",["두 Port 사이에서 송수신되는 TLP에 대해 confidentiality, integrity, replay protection을 제공한다.","Physical Layer 심볼의 전기적 잡음만 보정하며, TLP 내용의 기밀성은 제공하지 않는다.","Configuration Space register의 write-protect만 제공한다.","Correctable error를 자동 복구하는 FEC 전용 기능이다."],["Between two Ports, it keeps TLP contents confidential, protects their integrity, and guards against replay.","It only compensates electrical noise on Physical Layer symbols and does not protect TLP contents.","It only write-protects Configuration Space registers.","It is an FEC-only feature that automatically repairs correctable errors."],0,"위협 모델은 Link에 대한 물리적 공격, interposer, malicious Extension Device, TLP 내용 관찰·수정, 재정렬·삭제를 포함합니다. Selective IDE를 쓰면 Switch를 통과하는 구간까지 TLP를 보호할 수 있습니다.","The security model includes physical attacks on Links, interposers, malicious Extension Devices, inspection or modification of TLP contents, and reordering or deletion of TLPs. Selective IDE can keep TLPs protected as they transit Switches.","§6.33"],["p10q02","p10_1",2,"P","Link IDE Stream과 Selective IDE Stream의 차이로 옳은 것은?","Which statement correctly distinguishes a Link IDE Stream from a Selective IDE Stream?",["Link IDE는 Memory Write에만, Selective IDE는 Completion에만 적용된다.","둘은 같은 Link에서 동시에 사용할 수 없으며 항상 하나만 고른다.","Selective IDE Stream은 이 절의 association 규칙으로 선정된 TLP에 적용된다. Link IDE Stream은 특정 TC로 송신되는 TLP 중, Selective IDE Stream에 연관되지 않은 모든 TLP에 적용된다.","Selective IDE는 Downstream 방향에만, Link IDE는 Upstream 방향에만 쓸 수 있다."],["Link IDE applies only to Memory Writes, and Selective IDE only to Completions.","The two types cannot be used on the same Link; exactly one must be chosen.","A Selective IDE Stream covers the TLPs picked by this section's association rules. A Link IDE Stream covers every TLP sent on a given TC, except those already tied to a Selective IDE Stream.","Selective IDE can be used only Downstream, and Link IDE only Upstream."],2,"두 Port가 직접 연결된 경우 둘을 함께 쓸 수 있습니다. 그때 Selective IDE에 연관된 TLP는 그 Stream의 key set으로, 나머지 TLP는 Link IDE key set으로 보호됩니다. 두 유형 사이에 필수 관계는 없습니다.","Both may be used between two directly connected Ports. TLPs associated with the Selective IDE Stream use that Stream's key set, and all other TLPs use the Link IDE key set. There is no required relationship or restriction between the two types.","§6.33"],["p10q03","p10_1",2,"P","IDE Stream State Machine에서 Insecure, Secure, Enable 비트의 관계로 옳은 것은?","In the IDE Stream State Machine, how are Insecure, Secure, and the Stream Enable bit related?",["Enable 비트를 Clear해도 Stream은 항상 Secure에 남는다.","Insecure는 필요한 단계가 끝나지 않았거나, 이전에 동작하던 Stream이 종료된 상태이다. 해당 Link/Selective IDE Stream Enable 비트가 Clear되면 Secure에서 Insecure로 전이해야 한다. 보안을 해치는 조건이 탐지되면 역시 Insecure로 가야 한다.","Insecure에서는 하드웨어가 자동으로 모든 TLP를 IDE로 봉인해야 한다.","Secure 상태는 Key가 없어도 Enable만 Set이면 즉시 진입한다."],["Clearing the Enable bit leaves the Stream in Secure indefinitely.","Insecure means setup is incomplete, or that a Stream that had been running was torn down. Clearing the matching Link or Selective IDE Stream Enable bit forces a move from Secure to Insecure. Detecting a condition that compromises the Stream also forces Insecure.","In Insecure, hardware must automatically seal every TLP with IDE.","The Secure state is entered immediately when Enable is Set, even if no key exists."],1,"Ready는 Insecure의 conceptual sub-state로, 필요한 구성이 끝났을 때 firmware/software가 추적합니다. 하드웨어가 Ready 전이를 추적할 필요는 없습니다. Secure가 아니면, 보안되어야 할 전송은 Port가 내부적으로 막아야 합니다.","Ready is a conceptual sub-state of Insecure, entered when all necessary configuration has been performed; firmware or software must track that condition. Hardware is not required to track the transition into Ready. If the machine is not in Secure, the Port must internally block transmissions that are intended to be secure.","§6.33.1"],["p10q04","p10_1",2,"P","IDE가 사용하는 암호 모드와 MAC 크기로 옳은 것은?","Which cryptographic mode does IDE use, and what is the required MAC size?",["AES-CBC만 사용하며 MAC은 32비트이다.","SHA-1 HMAC만 사용하며 payload는 암호화하지 않는다.","ChaCha20-Poly1305를 의무로 쓰며 MAC은 128비트이다.","AES-GCM(Galois/Counter Mode)을 사용한다. IDE TLP에서 Message Authentication Code(MAC) 크기는 96비트여야 한다."],["IDE uses only AES-CBC, and the MAC is 32 bits.","IDE uses only SHA-1 HMAC and does not encrypt the payload.","ChaCha20-Poly1305 is mandatory, and the MAC is 128 bits.","IDE uses Galois/Counter Mode (GCM) as defined for AES-GCM. For IDE TLPs, the Message Authentication Code (MAC) size must be 96 bits."],3,"TLP data payload가 GCM의 Plaintext(P)가 되고, TLP Header와 규정된 일부 요소가 Additional Authenticated Data(A)가 됩니다. 암호 강도는 산업 관행에 맞추고 요구가 바뀌면 확장할 수 있게 되어 있습니다.","The TLP data payload forms the GCM Plaintext (P), and the TLP Header plus certain other defined elements form the Additional Authenticated Data (A). The cryptographic mechanisms are aligned to industry practice and can be extended as requirements evolve.","§6.33.4"],["p10q05","p10_1",2,"P","IDE가 보장하는 보안의 범위(terminal Port 안쪽)에 대한 설명으로 옳은 것은?","Which statement about the scope of IDE security, inside the terminal Ports, is correct?",["IDE는 Switch fabric 전체와 CPU 캐시까지  inclusive하게 암호화한다.","Selective IDE는 terminal Port 내부 register까지 하드웨어가 의무적으로 암호화해야 한다.","IDE는 두 terminal Port의 경계 너머 보안을 수립하지 않는다. 구성 요소 내부에서 보안 트래픽을 보호·격리하는 방법은 이 문서의 범위를 벗어난다. Link IDE가 Switch를 hop-by-hop으로 지날 때 Switch 내부 보안을 어떻게 유지할지도 범위를 벗어난다.","IDE는 Root Complex 메모리 컨트롤러 내부까지 동일한 key로 보호해야 한다."],["IDE encrypts the entire Switch fabric and the CPU cache, inclusively.","For Selective IDE, hardware must also encrypt registers inside the terminal Port.","Protection stops at the two terminal Ports. How a Component isolates secure traffic inside itself is not specified here. Likewise, when Link IDE is applied hop-by-hop through Switches, keeping the path safe inside those Switches is left to the implementation.","IDE must protect inside the Root Complex memory controller with the same key."],2,"그래서 Figure 6-52처럼, Switch를 통과하는 Selective IDE Stream은 그 구간이 보호되지만, terminal Port 너머 구성 요소 내부는 구현 고유 수단이 필요합니다.","As in Figure 6-52, a Selective IDE Stream that transits a Switch is protected on that path, but past each terminal Port the Component still needs implementation-specific protection.","§6.33"],["p10q06","p10_2",2,"P","IDE Key Management(IDE_KM)의 기반과, 보안되지 않은 객체 수신 시 규칙으로 옳은 것은?","What does IDE Key Management (IDE_KM) build on, and what is the rule if a data object was not transferred securely?",["IDE_KM은 SPDM과 Secured-SPDM 위에 구축되며 여러 transport로 쓸 수 있다. 수신한 IDE_KM 객체가 Secured-SPDM에 따라 안전하게 전달된 것이 아니면, 그 객체를 key management에 사용하면 안 되고, request라면 response를 만들어도 안 된다.","IDE_KM은 평문 Vendor-Defined Message로만 전달하며, 보안 세션은 금지된다.","보안되지 않은 객체라도 key를 즉시 설치하고 ERR_COR만 보낸다.","IDE_KM은 DLLP로만 전달되며 SPDM과는 무관하다."],["IDE_KM sits on top of SPDM and Secured-SPDM and may ride several transports. An IDE_KM object that did not arrive through a Secured-SPDM session must not be used to manage keys, and a request of that kind must not be answered.","IDE_KM is sent only in plaintext Vendor-Defined Messages; a secure session is forbidden.","An insecure object is still installed immediately as a key, and only ERR_COR is sent.","IDE_KM is carried only in DLLPs and is unrelated to SPDM."],0,"Requester는 SPDM VENDOR_DEFINED_REQUEST 형식을, Responder는 VENDOR_DEFINED_RESPONSE 형식을 써야 합니다. VendorID는 PCI-SIG에 할당된 0001h여야 합니다. 객체는 다시 Secured Message의 Application Data가 됩니다.","The Requester must use the SPDM VENDOR_DEFINED_REQUEST format, and the Responder the VENDOR_DEFINED_RESPONSE format. The VendorID field must contain 0001h, assigned to PCI-SIG. Those objects in turn form the Application Data of a Secured Message.","§6.33.3"],["p10q07","p10_2",2,"P","IDE Stream을 초기화하는 개념적 단계의 순서로 가장 가까운 것은?","Which sequence best matches the conceptual steps for initializing an IDE Stream?",["먼저 모든 TLP를 평문으로 보낸 뒤, 소프트웨어가 MAC만 나중에 붙인다.","Stream Enable만 Set하면 키 교환과 인증은 생략된다.","항상 Switch가 중간에서 키를 생성해 두 Port에 배포해야 한다.","두 Partner Port(IDE Terminus)를 담은 구성 요소의 진정성과 신원을 확인하고, IDE Stream key를 수립하며(IDE_KM이 한 방법), Secure Connection을 구성한 뒤, 마지막으로 Stream 수립을 trigger한다. 일부 단계는 합치거나 순서를 바꿀 수 있다."],["First send every TLP in the clear, then have software attach a MAC later.","Setting Stream Enable alone skips both key exchange and authentication.","A Switch must always generate the keys and distribute them to both Ports.","Establish the authenticity and identity of the components that contain the two Partner Ports (the IDE Terminuses), establish the IDE Stream keys (IDE_KM is one way), configure the Secure Connection, and finally trigger establishment of the Stream. Some steps can be merged or reordered."],3,"직접 연결된 Endpoint–Root Complex의 한 예는, DOE를 통한 IDE_KM으로 host firmware/software가 양쪽 Port에 키를 안전하게 프로그래밍하는 것입니다. 구성 요소 인증은 CMA-SPDM, 구현 고유 수단, 또는 어떤 경우에는 암묵적으로 수행할 수 있습니다.","For an Endpoint connected directly to the Root Complex, one example is to use IDE_KM via DOE so host firmware or software can program keys into both Ports securely. Establishing authenticity may use CMA-SPDM, implementation-specific means, or in some cases may be implicit.","§6.33.1"],["p10q08","p10_2",3,"P","peer-to-peer로 통신하는 두 Endpoint 사이에 IDE를 세우는 방법으로 스펙이 드는 예는?","Which example does the specification give for establishing IDE between two Endpoints communicating peer-to-peer?",["두 Endpoint는 반드시 Root Port를 통해서만 평문 Configuration Write로 키를 교환해야 한다.","두 Endpoint가 MCTP 및 Secured-MCTP로 직접 통신하고, 한쪽이 Requester, 다른 쪽이 Responder 역할을 한 뒤 IDE_KM flow로 키를 안전하게 수립할 수 있다. 관리 컨트롤러가 sideband로 IDE_KM을 적용하는 방법도 있다.","P2P IDE는 금지되어 있으며 항상 Link IDE만 허용된다.","키는 양쪽 Endpoint의 Device Serial Number를 XOR해 하드웨어가 자동 생성해야 한다."],["The two Endpoints must exchange keys only as plaintext Configuration Writes through a Root Port.","The two Endpoints can communicate directly via MCTP and Secured-MCTP, with one taking the Requester role and the other the Responder role, and then apply the IDE_KM flow for secure key establishment. It is also possible for a management controller to apply IDE_KM over a sideband management connection.","Peer-to-peer IDE is forbidden; only Link IDE is allowed.","Hardware must auto-generate the key by XORing the two Device Serial Numbers."],1,"관리 컨트롤러가 Root Complex에 키를 넣는 구체적 방법은 이 문서의 범위를 벗어납니다. 플랫폼에서 요소 간 trust를 세우는 정책도 IDE의 범위 밖이며, 어떤 정책은 IDE를 먼저 세운 뒤에 적용하는 편이 나을 수 있습니다.","How a management controller programs keys into a Root Complex is outside the scope of this document. How a platform decides trust among its elements is also outside IDE's scope, and sometimes the Stream is set up first and policy is applied later.","§6.33"],["p10q09","p10_2",2,"P","IDE_KM 객체의 크기 검사 규칙으로 옳은 것은?","Which rule about checking the size of an IDE_KM data object is correct?",["크기가 달라도 앞부분만 잘라 항상 키로 사용해야 한다.","VendorDefinedReqPayload/VendorDefinedRespPayload의 크기는 정의된 데이터 객체 크기와 일치해야 한다. 일치하지 않으면 그 객체는 key management에 사용하면 안 되고, request라면 response를 만들어도 안 된다.","Responder는 크기와 무관하게 항상 SUCCESS를 반환해야 한다.","크기는 4바이트 단위로 패딩되면 검사하지 않는다."],["If the size differs, the object must still be used as a key after truncating the front.","VendorDefinedReqPayload and VendorDefinedRespPayload must be exactly the defined object length. A size mismatch means the object is ignored for key management, and a request with the wrong size gets no response.","The Responder must always return SUCCESS regardless of size.","Size is not checked if the payload is padded to a 4-byte multiple."],1,"StandardID 필드는 SPDM에서 PCI-SIG를 식별하도록 할당된 값을 담아야 합니다. 보안 세션의 암호 강도는 IDE 자체에 선택된 강도 이상일 것이 강하게 권장됩니다.","The StandardID field must contain the value assigned in SPDM to identify PCI-SIG. It is strongly recommended that the cryptographic strength of the secure session be at least as strong as that selected for IDE itself.","§6.33.3"],["p10q10","p10_3",2,"P","Non-Flit Mode와 Flit Mode에서 IDE TLP를 표시하는 방법은?","How must an IDE TLP be marked in Non-Flit Mode versus Flit Mode?",["두 Mode 모두 Local TLP Prefix만 사용하고 End-End prefix는 금지된다.","Flit Mode에서는 IDE prefix가 필수이고, Non-Flit Mode에서는 OHC-C가 필수이다.","IDE TLP는 별도의 DLLP로만 표시되며 TLP prefix는 사용하지 않는다.","Non-Flit Mode에서는 모든 IDE TLP가 IDE prefix를 사용해야 하고, 이 prefix는 다른 모든 End-End TLP prefix보다 앞에 와야 한다. Flit Mode에서는 모든 IDE TLP가 OHC-C를 포함해야 한다."],["Both modes use only a Local TLP Prefix; End-End prefixes are forbidden.","In Flit Mode the IDE prefix is required, and in Non-Flit Mode OHC-C is required.","IDE TLPs are indicated only by a separate DLLP and do not use a TLP prefix.","Non-Flit Mode requires the IDE prefix on every IDE TLP, and that prefix comes before any other End-End prefix. Flit Mode requires OHC-C on every IDE TLP."],3,"Flit Mode에서 MAC 및/또는 PCRC의 존재는 TS 필드로 나타내고, K/XT/T, Sub-Stream, Stream_ID, PR_Sent_Counter는 OHC-C에 들어가며 Non-Flit IDE Prefix에서와 같은 의미입니다.","In Flit Mode, the presence of a MAC and/or PCRC is indicated by the TS field. The K, XT, and T bits, Sub-Stream, Stream_ID, and PR_Sent_Counter are carried in OHC-C with the same meaning as in the Non-Flit IDE Prefix.","§6.33.4"],["p10q11","p10_3",3,"P","IDE Prefix(또는 OHC-C)의 M bit, P bit, K bit 규칙으로 옳은 것은?","Which rules for the M, P, and K bits in the IDE Prefix (or OHC-C) are correct?",["M bit가 Set이면 해당 TLP에 MAC이 포함된다. aggregation을 쓰지 않으면 모든 IDE TLP에서 M bit를 Set해야 한다. P bit(PCRC)는 M bit도 Set된 경우에만 Set할 수 있다. K bit는 사용한 key set을 나타내고, Transmitter가 어느 Sub-Stream에서 K를 toggle한 뒤에는 같은 Stream의 다른 Sub-Stream도 새 K 값을 써야 한다.","P bit는 M bit와 무관하게 항상 Set해야 하고, K bit는 매 TLP마다 토글해야 한다.","M bit는 Correctable error 표시이고, P bit는 Posted TLP 표시이다.","K bit는 Stream_ID의 별칭이며 key set과 무관하다."],["When M is Set, the TLP includes a MAC. When aggregation is not used, M must be Set for all IDE TLPs. P, which indicates PCRC, must only be Set when M is also Set. K indicates the key set; after a Transmitter sends a TLP with K toggled for any Sub-Stream, later Transmissions for other Sub-Streams of the same Stream must also use the new K value.","P must always be Set regardless of M, and K must toggle on every TLP.","M marks a correctable error, and P marks a Posted TLP.","K is an alias of Stream_ID and is unrelated to the key set."],0,"Receiver는 K가 toggle된 TLP를 받으면 그 Sub-Stream에 대해 새 key와 IV로 옮기고, 이전 key/IV는 재프로그래밍될 때까지 invalid로 표시해야 합니다. 이 전이가 다른 Sub-Stream에 영향을 주면 안 됩니다.","After receiving a TLP with K toggled, the Receiver must switch to the new key and IV for that TLP and later TLPs of that Sub-Stream, and must mark the old key and IV invalid until they are reprogrammed. The transition must not affect other Sub-Streams of the Stream.","§6.33.4"],["p10q12","p10_3",3,"P","PR_Sent_Counter 필드가 사용되는 TLP 유형은?","For which TLP types must the PR_Sent_Counter field be used as specified, and for which is it Reserved?",["모든 Posted Request에서만 필수이고, Completion에서는 Reserved이다.","Message Request에서만 사용하고 Memory Request에서는 Reserved이다.","non-UIO Non-Posted Request와 Completion에서는 규정된 규칙에 따라 값을 정해야 한다. Posted Request와 UIO Request/Completion에서는 이 필드가 Reserved이다.","모든 IDE TLP에서 항상 0이어야 한다."],["It is required only on Posted Requests and is Reserved on Completions.","It is used only on Message Requests and is Reserved on Memory Requests.","On non-UIO Non-Posted Requests and Completions, the field is filled per the stated rules. On Posted Requests and on UIO Requests or Completions it is Reserved.","It must be 0 on every IDE TLP."],2,"이 카운터는 Non-Posted 경로에서 재정렬이나 삭제를 탐지하는 데 쓰입니다. Stream_ID는 8비트이고, Sub-Stream은 3비트입니다(이전 버전에서는 Sub-Stream이 4비트였습니다).","The counter is used to help detect reordering or deletion on the Non-Posted path. Stream_ID is 8 bits, and Sub-Stream is 3 bits (it was 4 bits in earlier versions of the specification).","§6.33.4"],["p10q13","p10_3",3,"P","IDE TLP와 ECRC의 관계, 그리고 IDE Check Failed 시 동작으로 옳은 것은?","Which statement about IDE TLPs versus ECRC, and about IDE Check Failed, is correct?",["IDE TLP는 항상 ECRC를 포함해야 하고, IDE Check Failed는 correctable로만 보고한다.","IDE Check Failed는 Advisory Non-Fatal로만 처리되며 Stream은 Secure에 남는다.","Switch는 IDE TLP의 ECRC를 재계산해 오류를 복구해야 한다.","IDE TLP에는 ECRC가 지원되지 않으며 FM/NFM translation도 불가능하다. IDE Check Failed가 나면 Receiving IDE Terminus는 Insecure로 들어가, 이후 그 Stream의 IDE TLP를 MAC check failure로 다루고, ERR_FATAL을 보내며, Partner Port로 IDE Fail Message를 보낸다."],["Every IDE TLP must include ECRC, and IDE Check Failed is reported only as correctable.","IDE Check Failed is handled only as Advisory Non-Fatal, and the Stream stays Secure.","A Switch must recompute ECRC on IDE TLPs and repair any error.","ECRC is not supported for IDE TLPs, and FM/NFM translation is not possible for them. On IDE Check Failed, the receiving IDE Terminus enters Insecure, treats all subsequent IDE TLPs on that Stream as having a MAC check failure, sends ERR_FATAL to the Root Complex, and transmits an IDE Fail Message to the Partner Port."],3,"Table 6-5는 이 오류를 uncorrectable로 다루고 prefix/header를 로그하라고 합니다. 이와 별도로 PCRC Check Failed는 기본 Non-Fatal 쪽이며, 최종 목적지에서 계속 운용이 가능하면 Advisory Non-Fatal이 될 수 있습니다(§6.2.3.2.4.3).","Table 6-5 treats IDE Check Failed as an uncorrectable case and requires logging the prefix/header. PCRC Check Failed is separate: its default severity is Non-Fatal, and at the ultimate destination it may be handled as Advisory Non-Fatal if continued operation is possible (section 6.2.3.2.4.3).","§6.33.4"],["p10q14","p10_4",1,"P","TDISP(TEE Device Interface Security Protocol)의 목적과, 기반으로 삼는 기존 능력으로 옳은 것은?","What is TDISP for, and which existing capabilities does TEE-I/O build upon?",["Physical Layer 이퀄라이제이션 계수를 TEE에서만 설정하는 절차이다.","host와 device가 TEE-I/O에 참여하기 위한 아키텍처를 정의한다. SR-IOV/SIOV와 ATS 같은 기존 직접 할당 능력을 바탕으로 TVM(Trusted Execution Environment VM)을 세운다.","CXL.mem 전용 캐시 일관성 프로토콜을 대체한다.","모든 VM이 반드시 VMM을 신뢰하도록 강제하는 모델이다."],["It is a procedure for programming Physical Layer equalization coefficients only inside a TEE.","It defines an architecture for hosts and devices to participate in TEE-I/O. TEE-I/O builds upon existing capabilities for direct assignment, such as SR-IOV and SIOV and ATS, to establish Trusted Execution Environment VMs (TVMs).","It replaces the cache-coherence protocol used by CXL.mem.","It is a model that forces every VM to trust the VMM."],1,"TVM이 아닌 VM은 legacy VM입니다. TEE-I/O에서는 VMM 자체를 TVM이 신뢰하지 않을 수 있고, TVM이 기반 하드웨어에 대해 trust decision을 내리도록 하는 메커니즘이 제공됩니다. VMM은 자원 할당과 시스템 관리를 계속 수행하되, 그 결과를 검증할 수 있는 방식으로 합니다.","Any VM that is not a TVM is a legacy VM. Under TEE-I/O a TVM is allowed not to trust the VMM, and it can decide whether to trust the hardware underneath. The VMM still does allocation and management, but in a form whose results can be checked.","§11"],["p10q15","p10_4",2,"P","TDI의 TDISP 상태와, locked/unlocked 구분으로 옳은 것은?","Which statement about TDISP states for a TDI, and about locked versus unlocked, is correct?",["상태는 SECURE와 INSECURE 두 가지만 있고, 둘 다 locked이다.","기본 상태는 RUN이며, CONFIG_UNLOCKED는 정의되어 있지 않다.","상태는 CONFIG_UNLOCKED(기본값), CONFIG_LOCKED, RUN, ERROR가 있다. CONFIG_LOCKED와 RUN은 locked, ERROR와 CONFIG_UNLOCKED는 unlocked로 본다.","ERROR만 locked이고 나머지 상태는 모두 unlocked이다."],["There are only two states, SECURE and INSECURE, and both are locked.","The default state is RUN, and CONFIG_UNLOCKED is not defined.","The states are CONFIG_UNLOCKED (the default), CONFIG_LOCKED, RUN, and ERROR. A TDI is considered locked in CONFIG_LOCKED and RUN, and unlocked in ERROR and CONFIG_UNLOCKED.","Only ERROR is locked; every other state is unlocked."],2,"TSM이 TDI를 이 상태들을 따라 옮기며, TVM에 할당하기 전에 구성을 lock하고, 운용 상태로 전이하고, TVM에서 분리하는 생명주기를 관리합니다.","The TSM steps the TDI through these states as it locks a configuration before assigning the TDI to a TVM, moves it to the operational state, and later detaches it from a TVM.","§11.2"],["p10q16","p10_4",2,"P","TDISP 상태 전이를 일으키는 메시지 매핑으로 옳은 것은?","Which mapping of TDISP messages to state transitions is correct?",["STOP_INTERFACE_REQUEST는 다른 어떤 상태에서든 CONFIG_UNLOCKED로 들어가게 한다. LOCK_INTERFACE_REQUEST는 CONFIG_LOCKED로, START_INTERFACE_REQUEST는 RUN으로 가는 데 쓰인다.","START_INTERFACE_REQUEST만으로 ERROR를 포함한 모든 상태에서 CONFIG_UNLOCKED로 간다.","LOCK_INTERFACE_REQUEST는 항상 ERROR로 보낸다.","STOP_INTERFACE_REQUEST는 RUN에서만 허용되고 다른 상태에서는 무시된다."],["STOP_INTERFACE_REQUEST causes a transition to CONFIG_UNLOCKED from any other state. LOCK_INTERFACE_REQUEST is used to enter CONFIG_LOCKED, and START_INTERFACE_REQUEST is used to enter RUN.","START_INTERFACE_REQUEST alone moves every state, including ERROR, to CONFIG_UNLOCKED.","LOCK_INTERFACE_REQUEST always forces ERROR.","STOP_INTERFACE_REQUEST is allowed only in RUN and is ignored in every other state."],0,"CONFIG_UNLOCKED로 올 때 DSM은 그 TDI 맥락에서 device가 보유한 TVM 기밀 데이터가 device 밖으로 plaintext로 노출되지 않게 해야 하며, 가능한 한 그 데이터와 연관된 ciphertext도 노출되지 않게 해야 합니다.","On entry to CONFIG_UNLOCKED, the DSM must keep any TVM secrets held for that TDI from appearing as plaintext outside the device, and should also prevent related ciphertext from leaking as far as practical.","§11.2"],["p10q17","p10_4",3,"P","INTERFACE_ID의 구성과, CONFIG_LOCKED 및 RUN에서의 Bus/Segment 규칙으로 옳은 것은?","How is INTERFACE_ID composed, and what is the rule for Bus and Segment Numbers while a TDI is in CONFIG_LOCKED or RUN?",["INTERFACE_ID는 FUNCTION_ID(4바이트: Requester ID, Requester Segment, Valid 비트 등)와 8바이트 Reserved로 구성된다. CONFIG_LOCKED와 RUN에서는 그 TDI의 Bus Number와 Segment Number를 바꾸면 안 된다.","INTERFACE_ID는 16바이트 Device Serial Number만으로 구성되고, Bus Number는 언제든지 바꿀 수 있다.","FUNCTION_ID는 Completer ID만 담고, Segment는 항상 FFh로 고정된다.","INTERFACE_ID는 Stream_ID와 동일하며 lock 상태에서만 재할당해야 한다."],["INTERFACE_ID is composed of a 4-byte FUNCTION_ID (Requester ID, Requester Segment, a valid bit, and reserved bits) and an 8-byte Reserved field. While a TDI is in CONFIG_LOCKED or RUN, its Bus Number and Segment Number are not allowed to change.","INTERFACE_ID is only a 16-byte Device Serial Number, and the Bus Number may change at any time.","FUNCTION_ID holds only a Completer ID, and the Segment is always hard-wired to FFh.","INTERFACE_ID is identical to Stream_ID and must be reallocated only while locked."],0,"FUNCTION_ID 안의 Function/Device Number는 device/DSM이 할당하고, Bus/Segment는 시스템 enumeration 때 할당됩니다. TDI는 해당 DSM 도메인에서 고유한 INTERFACE_ID로 TSM/DSM 메시지에서 식별됩니다.","Within FUNCTION_ID, the Function and Device Numbers are assigned by the device or DSM, while the Bus and Segment Numbers are assigned during system enumeration. Within a DSM's domain, each TDI has a unique INTERFACE_ID used in all TSM/DSM messages.","§11.2"],["p10q18","p10_4",3,"P","CONFIG_UNLOCKED 상태에서의 보안 속성과 legacy VM 할당에 대한 설명으로 옳은 것은?","Which statement about security properties in CONFIG_UNLOCKED, and about assigning a TDI to a legacy VM, is correct?",["CONFIG_UNLOCKED에서도 T bit가 Set된 Request만 의무적으로 수락해야 한다.","Legacy VM 할당 시 TDI는 반드시 RUN이어야 한다.","이 상태에서 TDI는 들어온 기밀 데이터를 보호할 의무가 없으므로, TVM은 이 상태에 기밀 데이터를 넣지 않아야 한다. T bit가 Set된 Memory Request는 이 상태에서 reject해야 한다. Legacy VM에 할당되는 TDI는 CONFIG_UNLOCKED에 머물며, TSM은 그 TDI가 Legacy VM에서 제거되어 재준비될 때까지 그 상태를 유지해야 한다.","이 상태에서는 모든 TLP를 IDE 없이 통과시키고 reject 규칙은 없다."],["In CONFIG_UNLOCKED, only Requests with the T bit Set must be accepted.","A TDI assigned to a legacy VM must be in RUN.","In this state the TDI need not protect secrets placed in it, so a TVM should not put confidential data there. Memory Requests that come from a TVM (T bit Set) must be rejected. When the TDI is given to a legacy VM, the VMM does so in CONFIG_UNLOCKED, and the TSM holds that state until the TDI is taken back and prepared for a new assignment.","In this state every TLP is passed without IDE, and there is no reject rule."],2,"TDISP에 묶인 IDE Stream으로 non-TDISP TLP를 보내는 것은 허용되지만, 그런 TLP의 XT와 T bit는 송신에서 Clear해야 하고 수신에서는 무시해야 하며, DSM은 그 TLP가 TVM 기밀 데이터에 접근하지 못하게 해야 합니다.","IDE Streams bound for TDISP may also carry non-TDISP TLPs, but for those TLPs the XT and T bits must be Clear on transmit and ignored on receive, and the DSM must ensure those TLPs cannot access TVM confidential data.","§11.2"],["p10q19","p10_5",1,"C","SR-IOV의 PF와 VF에 대한 설명으로 옳은 것은?","Which description of an SR-IOV Physical Function (PF) and Virtual Function (VF) is correct?",["VF는 Type 1 Bridge header를 갖고 PF와 다른 class여야 한다.","PF는 SR-IOV Extended Capability를 지원하는 PCIe Function으로, SR-PCIM·VI 또는 SI가 접근한다. VF는 가벼운 virtual device interface로, Type 0 header를 가진 비가상화 Function의 Configuration Space 부분집합을 가지며, 연관 PF와 같은 device type 및 class여야 한다.","PF는 Configuration Space가 없고 VF만 Type 0 header를 갖는다.","VF는 SDI와 같이 Configuration Space와 BAR가 전혀 없다."],["A VF has a Type 1 Bridge header and must be a different class from its PF.","A PF is a PCIe Function with the SR-IOV Extended Capability, reachable by an SR-PCIM, a VI, or an SI. A VF is a light-weight virtual interface. Its Configuration Space is a subset of an ordinary Type 0 Function, and every VF of a PF must share that PF's device type and class.","A PF has no Configuration Space, and only VFs have a Type 0 header.","A VF, like an SDI, has no Configuration Space and no BAR at all."],1,"VF는 VF BAR의 한 구간으로 register와 memory를 SI에 노출합니다. 이와 달리 SDI는 자기 Configuration Space나 BAR가 없고, device type이 PF와 같아야 한다는 제한도 없습니다.","A VF exposes registers and memory to an SI through a section of a Virtual Function BAR. By contrast, an SDI has no Configuration Space or BAR of its own and is not limited to the same device type as the PF.","§9.1"],["p10q20","p10_5",2,"C","VF Enable 비트의 동작으로 옳은 것은?","What does the VF Enable bit do?",["Clear여도 VF는 항상 보이며 Memory Write만 금지된다.","Set이면 PF가 사라지고 VF만 남는다.","VF Enable은 VF가 자기 Configuration Space에서 직접 제어하는 비트이다.","Set이면 연관 VF들이 PCI Express fabric에서 접근 가능하고, Endpoint Function 규칙에 따라 transaction을 수신·발행할 수 있다. Clear이면 VF는 disable되어 보이지 않고, 그 VF로의 Request는 UR를 받으며, 그 VF는 transaction을 발행하면 안 된다."],["Even when Clear, VFs remain visible and only Memory Writes are forbidden.","When Set, the PF disappears and only VFs remain.","VF Enable is a bit that each VF controls directly in its own Configuration Space.","When Set, the VFs associated with the PF are accessible in the fabric and may issue and respond to transactions following Endpoint Function rules. When Clear, the VFs are disabled and not visible; Requests to those VFs shall receive UR, and those VFs shall not issue PCI Express transactions."],3,"NumVFs는 해당 PF의 VF Enable이 Clear일 때에만 변경할 수 있습니다. ARI Capable Hierarchy는 Device의 모든 PF에서 VF Enable이 Clear일 때에만 바꿀 수 있습니다.","NumVFs of a PF may be changed only when that PF's VF Enable is Clear. ARI Capable Hierarchy may be changed only when VF Enable is Clear in all PFs of the Device.","§9.4.3.3.1"],["p10q21","p10_5",3,"C","VF Enable을 Clear에서 Set으로 바꾼 뒤, 시스템에 적용되는 대기 규칙으로 옳은 것은?","After VF Enable is changed from Clear to Set, which waiting rules apply to the system?",["대기 시간은 없고, Set 즉시 모든 Request가 필수이다. RRS는 금지된다.","항상 10초를 기다린 뒤에만 Configuration Request를 보낼 수 있다.","다음 중 하나가 참이 될 때까지, 그 비트로 enable된 VF에 Request를 발행하면 안 된다: 최소 100 ms가 지남, 해당 PF로부터 Reason Code가 VF Enabled인 FRS Message를 수신, 또는 적어도 VF Enable Time이 경과. 또한 Root Complex/소프트웨어는 VF Enable을 Set한 뒤 최소 1.0 s가 지나기 전에는, 유효한 Configuration Request에 Successful Completion을 못 돌려주는 VF를 고장으로 단정하면 안 된다.","FRS Message가 오기 전에는 어떤 대기도 인정되지 않으며 100 ms 규칙은 없다."],["There is no wait; every Request is required immediately after Set, and RRS is forbidden.","Configuration Requests may be sent only after a fixed wait of 10 seconds.","No Request may be issued to the VFs turned on by that bit until 100 ms have elapsed, or the PF has sent an FRS Message with Reason Code VF Enabled, or VF Enable Time has elapsed. After Setting VF Enable, the Root Complex or system software must also wait at least 1.0 s before treating a VF as broken just because a valid Configuration Request has not yet completed successfully.","No wait is recognized until an FRS Message arrives, and there is no 100 ms rule."],2,"그 1.0 s 한도까지 VF는 Configuration RRS를 반환할 수 있습니다. PF가 VF Enabled FRS를 보낸 뒤에는, VF disable이나 다른 유효한 reset 없이 연관 VF가 Configuration RRS를 반환하면 안 됩니다. VF Enable Time은 해당 VF의 Readiness Time Reporting 값 또는 시스템 software/firmware가 정한 값입니다.","Until that 1.0 s limit, a VF may return Configuration RRS. After the PF sends an FRS Message with Reason Code VF Enabled, no associated VF may return Configuration RRS without an intervening VF disable or other valid reset. VF Enable Time is either the Reset Time in the VF's Readiness Time Reporting Capability, or a value determined by system software or firmware.","§9.4.3.3.1"],["p10q22","p10_5",2,"C","VF MSE(Memory Space Enable)에 대한 설명으로 옳은 것은?","Which statement about VF MSE (Memory Space Enable) is correct?",["VF에는 MSE 비트가 없고, 모든 Active VF의 memory space enable은 PF의 SR-IOV Extended Capability에 있는 VF MSE가 제어한다. 기본값은 0b이다. VF Enable이 Set일 때 memory space는 VF MSE가 Set된 경우에만 응답한다.","각 VF가 자신의 Command register MSE로 독립 제어하며, PF의 VF MSE는 존재하지 않는다.","VF MSE 기본값은 1b이고, VF Enable이 Clear여도 memory space는 항상 응답한다.","VF MSE는 I/O Space만 제어하고 memory space와는 무관하다."],["VFs do not have an MSE bit; memory space enable for all Active VFs associated with the PF is controlled by VF MSE in the PF's SR-IOV Extended Capability. The default is 0b. When VF Enable is Set, VF memory space responds only when VF MSE is Set.","Each VF independently controls MSE in its own Command register, and the PF has no VF MSE bit.","VF MSE defaults to 1b, and VF memory space always responds even when VF Enable is Clear.","VF MSE controls only I/O Space and has no effect on memory space."],0,"VF Enable이 Clear이면 VF memory space는 Unsupported Request로 응답하므로, 그때 VF MSE는 don't care입니다. 소프트웨어는 VF BARn을 프로그래밍한 뒤 VF Enable을 Set하기 전에 VF MSE를 Set할 수 있습니다. VF Migration 관련 비트는 deprecated된 MR-IOV와 연관되어, 신규 설계는 0b로 hardwire하는 것이 좋습니다.","When VF Enable is Clear, VF memory space responds with Unsupported Request, so VF MSE is don't-care in that case. Software may Set VF MSE after programming the VF BARn registers and before Setting VF Enable. The VF Migration bits are associated with deprecated MR-IOV; new designs should hardwire them to 0b.","§9.4.3.3.4"],["p10q23","p10_6",2,"C","VF Routing ID를 계산하는 방식(Table 9-1)으로 옳은 것은?","Which formula correctly computes a VF Routing ID, as in Table 9-1?",["VF N의 Routing ID는 항상 PF Routing ID와 같고 Function Number만 1로 고정된다.","VF Routing ID는 (Device Number << 16) + N 이며 modulo는 쓰지 않는다.","첫 VF만 First VF Offset을 쓰고, 이후 VF는 PF Bus Number를 재사용한다.","VF N의 Routing ID는 (PF Routing ID + First VF Offset + (N-1) * VF Stride) modulo 2^16 이다. 산술은 16-bit unsigned이며 carry는 버린다. 모든 PF와 VF의 Routing ID는 서로 달라야 한다."],["Every VF Routing ID equals the PF Routing ID, with the Function Number hard-wired to 1.","A VF Routing ID is (Device Number << 16) + N, with no modulo.","Only the first VF uses First VF Offset; later VFs reuse the PF Bus Number.","VF N's Routing ID equals (the PF Routing ID plus First VF Offset plus (N-1) times VF Stride), reduced modulo 2 to the 16. The add is 16-bit unsigned and drops carries. Every PF and VF Routing ID must be unique."],3,"First VF Offset과 VF Stride는 16-bit Routing ID offset입니다. NumVFs 값과(해당 PF의), Device에서 번호가 가장 낮은 PF의 ARI Capable Hierarchy 값이 이 offset들에 영향을 줄 수 있습니다.","First VF Offset and VF Stride are 16-bit Routing ID offsets. A PF's NumVFs, and ARI Capable Hierarchy in the lowest-numbered PF of the Device, may affect those offset values.","§9.2.1.2"],["p10q24","p10_6",3,"C","VF의 Bus/Device Number 배치 제한으로 옳은 것은?","Which placement restriction on a VF's Bus and Device Numbers is correct?",["VF는 항상 PF보다 하나 작은 Bus Number에 있어야 한다.","VF는 연관 PF보다 숫자적으로 더 작은 Bus Number에 있으면 안 된다. PF와 같은 Bus Number에 있는 VF는, PF보다 숫자적으로 더 작은 Device Number에 있으면 안 된다. 모든 PF는 Device가 capture한 Bus Number에 있어야 한다.","VF의 Device Number는 항상 0보다 작아야 한다.","PF는 capture된 Bus와 다른 Bus에 있을 수 있고, VF는 그보다 작은 Bus에 있어야 한다."],["A VF must always sit on a Bus Number one less than its PF.","A VF's Bus Number must not be numerically less than its PF's. If they share a Bus Number, the VF's Device Number must not be numerically less than the PF's. Every PF sits on the Bus Number the Device captured.","A VF's Device Number must always be less than 0.","A PF may sit on a different Bus than the captured Bus, and VFs must sit on a smaller Bus."],1,"First VF Offset이 예를 들어 0100h이면 VF가 PF와 다른 Bus Number에 있을 수 있습니다. Downstream Port 바로 아래의 SR-IOV Device는 Device Number가 항상 0이라 이 조건을 자동으로 만족합니다. SR-IOV Device는 Type 0 Configuration Write에서 Bus Number를 capture하고, Type 1에서는 capture하지 않습니다.","A VF may reside on a different Bus Number than its PF, for example if First VF Offset is 0100h. An SR-IOV Device immediately below a Downstream Port always has Device Number 0, so it satisfies the Device Number rule automatically. SR-IOV Devices associated with an Upstream Port capture the Bus Number from a Type 0 Configuration Write, not from Type 1.","§9.2.1.2"],["p10q25","p10_6",2,"C","VF BAR에 대한 규칙으로 옳은 것은?","Which rule about VF BARs is correct?",["각 VF BAR는 반드시 I/O Space를 표시해야 한다.","VF는 I/O Space를 지원하지 않으므로 VF BAR는 I/O Space를 표시하면 안 된다. VF BAR는 각 VF의 aperture를 기술하고, 크기는 보통 PCI BAR처럼 all 1을 쓴 뒤 읽어서 알아낸다. System Page Size는 Supported Page Sizes 중 하나여야 한다.","VF BAR는 PF BAR의 alias일 뿐 크기를 탐지할 수 없다.","System Page Size는 Supported Page Sizes 밖의 임의의 값이어야 한다."],["Every VF BAR must indicate I/O Space.","VFs do not support I/O Space, so VF BARs shall not indicate I/O Space. A VF BAR describes the aperture for each VF. Its size is determined as with an ordinary PCI Memory BAR, by writing all 1s and reading it back. The System Page Size value must be one of the Supported Page Sizes.","A VF BAR is only an alias of a PF BAR and its size cannot be probed.","System Page Size must be a value outside the Supported Page Sizes."],1,"보통 PCI BAR는 Function 하나의 aperture를 기술하지만, VF BAR는 각 VF에 대한 aperture를 기술합니다. 첫 VF의 시작 주소는 VF BAR에 쓴 값이 되고, 이후 VF들은 그 aperture 크기만큼 이어집니다. System Page Size는 각 VF BAR aperture를 시스템 페이지 경계에 맞추는 데 쓰입니다.","An ordinary PCI BAR describes one Function's aperture, whereas a VF BAR describes the aperture for each VF. The address written into each VF BAR is the start of the first VF, and later VFs follow at that aperture size. System Page Size is used to align each VF BAR aperture to a system page boundary.","§9.2.1.1.1"],["p10q26","p10_6",2,"C","SIOV의 SDI(Scalable Device Interface)와 SR-IOV VF의 차이로 옳은 것은?","Which difference between an SIOV Scalable Device Interface (SDI) and an SR-IOV VF is correct?",["SDI는 VF보다 더 많은 Configuration Space를 가지며 독립 Type 1 header가 필수이다.","SDI는 반드시 PF와 동일한 class를 Configuration Space에 광고해야 한다.","SDI는 Routing ID를 가지지 않으며 Function과 완전히 동일하게 취급된다.","SDI는 자기 Configuration Space와 BAR가 없다. 구성은 연관 PF의 SIOV Extended Capability와 SR-PCIM에 의존하고, 페이지 매핑은 PF BAR, host RAM, 또는 VI가 합성한 페이지일 수 있다. SDI는 PF와 같은 device type/class여야 한다는 제한이 없다."],["An SDI has more Configuration Space than a VF and must have its own Type 1 header.","An SDI must advertise the same class as the PF in its own Configuration Space.","An SDI has no Routing ID and is treated as completely identical to a Function.","An SDI has no Configuration Space and no BAR of its own. It is configured via the SIOV Extended Capability in the associated PF together with SR-PCIM, and the VI may map pages from the PF's BARs, host RAM, or pages the VI synthesizes. An SDI is not limited to exposing the same device type and class as the PF."],3,"SDI는 RID를 가지지만 Function의 정의는 충족하지 않습니다. 이 스펙의 Function 요구는, 따로 명시되지 않는 한 SDI에 적용되지 않습니다. SIOV는 가상화의 더 많은 부분을 시스템 소프트웨어에 맡겨, 가상 인터페이스당 하드웨어 비용을 낮추려는 접근입니다.","An SDI has a RID but does not meet the definition of a Function, so Function requirements in this specification do not apply to SDIs unless specifically called out. SIOV leaves more of the virtualization model to system software, with the intent of lowering the hardware cost of each virtual interface.","§9.1"],["p10q27","p10_7",1,"C","ATS(Address Translation Services)의 기본 모델로 옳은 것은?","Which statement describes the basic ATS model?",["Device와 Root Complex(안의 Translation Agent, TA) 사이의 Request–Completion 프로토콜로 주소 번역을 제공한다. Device의 ATC가 번역을 캐시할 수 있고, Memory Request의 AT 필드로 주소가 번역된 것인지 나타낸다.","Switch가 모든 주소를 로컬에서 번역하며 RC는 참여하지 않는다.","ATS는 I/O Request에만 사용되고 Memory Request에는 AT 필드가 없다.","번역은 항상 software-only이며 TLP 프로토콜은 정의되어 있지 않다."],["It is a Request–Completion protocol between a Device and a Root Complex (specifically the Translation Agent, or TA) that provides address translations. A Device may cache translations in its ATC, and the AT field in a Memory Request indicates whether the address has been translated.","A Switch translates every address locally, and the RC does not take part.","ATS is used only with I/O Requests; Memory Requests have no AT field.","Translation is always software-only, and no TLP protocol is defined."],0,"ATS Translation Request는 이 스펙의 다른 TLP와 같은 routing·ordering 규칙을 따릅니다. 여러 Request를 outstanding으로 둘 수 있고, 연관된 Translation Completion은 같은 TC(같은 ordering domain)를 써야 합니다.","An ATS Translation Request follows the same routing and ordering rules as other TLPs in this specification. Multiple Requests may be outstanding, and the associated Translation Completion must use the same TC, which is the same ordering domain.","§10.1.1"],["p10q28","p10_7",2,"C","AT[1:0] 필드 인코딩(Table 10-1)으로 옳은 것은?","Which AT[1:0] encoding from Table 10-1 is correct?",["00b=Translated, 01b=Reserved, 10b=Untranslated, 11b=Translation Request이다.","AT 필드는 2비트가 아니라 4비트이며 11b는 Successful을 뜻한다.","00b=Untranslated, 01b=Translation Request, 10b=Translated, 11b=Reserved이다. 01b는 explicit Translation Request(Memory Read)에서만 의미가 있고, 다른 Memory Request에 01b가 오면 TA는 UR를 알린다. 11b가 온 Memory Request에도 TA는 UR를 알린다.","00b만 정의되어 있고 다른 값은 Malformed TLP이다."],["00b = Translated, 01b = Reserved, 10b = Untranslated, and 11b = Translation Request.","The AT field is 4 bits, not 2, and 11b means Successful.","00b = Untranslated, 01b = Translation Request, 10b = Translated, and 11b = Reserved. 01b is meaningful only on an explicit Translation Request (a Memory Read); if a TA receives 01b on any other Memory Request, it signals UR. A Memory Request with 11b also causes the TA to signal UR.","Only 00b is defined, and any other value is a Malformed TLP."],2,"Untranslated(00b)이면 TA는 그 주소를 virtual 또는 physical로 다룰 수 있습니다. Translated(10b)인데 해당 Function이 physical address를 제시할 권한이 없으면, TA는 이를 UR로 다룰 수 있습니다. AT 필드는 Memory Request와, Flit Mode의 Address Routed Message에만 정의됩니다.","If AT is Untranslated (00b), a TA may treat the address as either virtual or physical. If AT is Translated (10b) but the Function is not allowed to present physical addresses, the TA may treat the Request as UR. The AT field is defined only for Memory Requests and, in Flit Mode, Address Routed Messages.","§10.2.1"],["p10q29","p10_7",2,"C","ATS가 지원해야 하는 페이지 크기 규칙으로 옳은 것은?","Which page-size rule must ATS support?",["페이지 크기는 항상 512바이트로 고정이다.","페이지 크기는 임의 정렬된 3의 배수여야 한다.","최소 페이지 크기는 1MB이고 4KB는 금지된다.","페이지 크기는 2의 거듭제곱이고 naturally aligned여야 한다. 지원해야 하는 최소 페이지 크기는 4096바이트이며, ATS capable 구성 요소는 이 최소 크기를 지원해야 한다."],["The page size is fixed at 512 bytes.","Page sizes must be multiples of 3 and may be arbitrarily aligned.","The minimum page size is 1 MB, and 4 KB is forbidden.","A page size must be a power of two and naturally aligned. The smallest size that must be supported is 4096 bytes, and every ATS-capable component has to handle that size."],3,"다양한 ATPT와 processor 구현을 수용하려고 여러 페이지 크기를 지원해야 합니다. Function은 자신이 지원해야 할 최소 translation 또는 invalidate 크기를 통지받아야 합니다.","ATS has to support a range of page sizes to accommodate different ATPT and processor implementations. The Function has to be informed of the smallest translation or invalidate size it will be expected to handle.","§10.1.1"],["p10q30","p10_7",2,"C","Translation Agent(TA)가 ATS Translation Request를 받았을 때 수행하는 기본 단계로 옳은 것은?","Which basic steps does a Translation Agent (TA) perform when it receives an ATS Translation Request?",["요청을 항상 Broadcast한 뒤, 권한 검사 없이 물리적 주소를 돌려준다.","해당 Function이 ATS Translation Request를 내도록 구성되어 있는지 확인하고, 요청된 memory에 대한 접근 권한을 판단한 뒤, 번역을 제공할 수 있으면 Function에 translation을 발행한다.","Switch가 로컬에서 번역하고 TA는 Request를 폐기한다.","TA는 Configuration Request로만 번역하며 Memory Read는 거부한다."],["It always broadcasts the Request and returns a physical address with no permission check.","It checks that the Function is enabled to issue ATS Translation Requests, decides whether that Function may touch the requested memory with the right access permissions, and, when a translation can be given, returns it to the Function.","A Switch translates the address locally and the TA drops the Request.","The TA translates only Configuration Requests and rejects Memory Reads."],1,"Function은 구현 고유 방법으로, ATC에 번역을 캐시하는 것이 이득인지 판단합니다. 자주 오래 접근하는 주소 범위나 work/completion queue, 낮은 지연 통신 버퍼 같은 예가 있습니다.","A Function uses an implementation-specific method to decide whether caching a translation in its ATC would help, for example for address ranges that will be accessed frequently over a long period, or for work and completion queues and low-latency buffers.","§10.1.1"],["p10q31","p10_7",3,"C","Flit Mode Address Routed Message의 AT 필드에서, Memory Request와 달라지는 점은?","For the AT field of an Address Routed Message in Flit Mode, what differs from Memory Requests?",["AT 필드는 없고 항상 Untranslated로 간주한다.","11b만 허용되고 나머지는 UR이다.","인코딩은 Table 10-1을 따르되, 01b 값은 Reserved이다.","01b는 Message에도 Translation Request를 보내는 데 쓰인다."],["There is no AT field, and the address is always treated as Untranslated.","Only 11b is permitted, and any other value is UR.","The AT field is encoded as in Table 10-1, except that the value 01b is Reserved.","01b is also used on Messages to issue a Translation Request."],2,"Address routing 규칙(§2.2.4.1)이 이 점을 명시합니다. Translation Request(01b)는 Memory Read 형식의 explicit Translation Request에만 의미가 있으므로, Address Routed Message에는 예약됩니다. 그 밖의 Request에서 AT는 달리 명시되지 않으면 Reserved입니다.","The address-routing rules in section 2.2.4.1 state this exception. Translation Request (01b) is meaningful only on an explicit Translation Request, which is a Memory Read, so it is Reserved for Address Routed Messages. For all other Requests, AT is Reserved unless explicitly stated otherwise.","§2.2.4.1"],["p10q32","p10_8",2,"C","Page Request Interface(PRI)의 목적과, ATS와의 관계로 옳은 것은?","What is the purpose of the Page Request Interface (PRI), and how does it relate to ATS?",["DMA에 쓰일 모든 데이터를 미리 pin하지 않고도 DMA를 시작할 수 있게 한다. PRI는 ATS의 다른 측면과는 기능적으로 독립이라, ATS를 지원하는 device가 PRI를 지원하지 않아도 되지만, PRI는 ATS의 능력에 의존한다.","PRI는 ATS를 대체하며, PRI만 있으면 ATC는 금지된다.","PRI는 Configuration Request의 페이지 폴트만 다루고 DMA와는 무관하다.","PRI를 지원하면 ATS Translation Request는 사용할 수 없다."],["PRI lets DMA operations start without requiring that all of the data to be moved into or out of system memory be pinned. PRI is functionally independent of the other aspects of ATS: a device that supports ATS need not support PRI, but PRI depends on ATS's capabilities.","PRI replaces ATS, and an ATC is forbidden if PRI is present.","PRI handles only page faults for Configuration Requests and is unrelated to DMA.","If PRI is supported, ATS Translation Requests cannot be used."],0,"pinning의 오버헤드는 작을 수 있지만, 큰 메모리 영역을 pageable pool에서 빼면 시스템 성능에 부담이 됩니다. 장치가 없는 페이지를 필요할 때 page fault로 요청하면, host와의 결합은 더 유연해집니다.","The overhead of pinning can be modest, but pulling large amounts of memory out of the pageable pool can hurt system performance. Letting a device page-fault for memory that is not present gives a more flexible coupling to the host.","§10.1.2"],["p10q33","p10_8",2,"C","Page Request Services에서 device와 host가 주고받는 기본 메시지 쌍은?","What is the basic message pair used between a device and the host for Page Request Services?",["device가 보내는 Page Request Message와, host가 보내는 Page Request Group Response Message이다.","Memory Read와 Completer Abort뿐이다.","ERR_COR와 PME Message뿐이다.","Lock/Unlock DLLP 쌍이다."],["The device sends a Page Request Message, and the host returns a Page Request Group Response Message.","Only Memory Reads and Completer Aborts are used.","Only ERR_COR and PME Messages are used.","Only a Lock/Unlock DLLP pair is used."],0,"이 메시지 형식과 Extended Capability(Page Request Control/Status, Outstanding Page Request Capacity 및 Allocation)는 §10.4와 §10.5.2에 정의되어 있습니다. 장치가 이 인터페이스를 어떻게 쓰는지는 매우 device-specific합니다.","These message formats and the Page Request Extended Capability (Control, Status, Outstanding Page Request Capacity, and Allocation) are defined in sections 10.4 and 10.5.2. How a device uses the interface is very device-specific.","§10.4"],["p10q34","p10_8",3,"C","writable page의 dirty 표시와 관련해, PRI를 쓰는 Function이 받을 수 있는 불이익을 스펙이 경고하는 이유는?","Why does the specification warn that Functions using PRI can pay a significant penalty related to dirty flags on writable pages?",["PRI Function은 dirty bit를 하드웨어가 항상 Clear해야 하므로 write가 금지된다.","TA는 PRI를 쓰면 dirty 표시를 할 수 없어 모든 write를 UR로 끝낸다.","추가 hint가 없으면 TA는 Function에 write 권한을 줄 때 그 권한을 실제로 사용할 것이라고 보수적으로 가정해, 번역을 주기 전에 해당 페이지를 dirty로 표시해야 할 수 있다. PRI Function은 메모리를 pin하지 않고 동작하므로, 쓰기 권한이 있는 모든 페이지를 dirty로 보면 대가를 치를 수 있다.","PRI는 dirty bit를 Configuration Space에 복제하므로 BAR 크기가 두 배가 된다."],["PRI Functions must have the dirty bit cleared by hardware, so writes are forbidden.","With PRI a TA cannot mark pages dirty, so every write ends as UR.","Without extra hints, a TA would need to assume conservatively that when it grants a Function permission to write a page, the Function will use that permission, so such writable pages would need to be marked dirty before their translated addresses are given to the Function. Functions that support PRI operate without pinning and can pay a significant penalty if every writable page is treated as dirty.","PRI copies the dirty bit into Configuration Space, doubling BAR size."],2,"pinning을 쓰는(페이징을 지원하지 않는) Function에서는 페이지가 고정되어 있어, clean 페이지를 메모리에 다시 저장하는 비용이 거의 발생하지 않을 수 있습니다. PRI에서는 speculative page request도 가능하므로, dirty 정책을 너무 보수적으로 쓰면 불필요한 write-back이 늘어납니다.","For Functions that do not support paging, pages are pinned, so the cost of writing a clean page back to memory is seldom paid. PRI Functions may also issue speculative page requests, so an overly conservative dirty policy can cause a lot of unnecessary write-back.","§10.1.2"],["p10q35","p10_8",2,"C","고속 LAN device를 예로 들어, PRI가 시스템 메모리를 더 효율적으로 쓰게 하는 방식으로 스펙이 설명하는 것은?","Using the specification's high-speed LAN example, how can PRI help a device use system memory more efficiently?",["장치는 수신 가능한 최대 대역폭만큼의 모든 페이지를 항상 pin해야 한다.","장치는 자신의 burst rate를 알고 있으므로, 어떤 시간 구간 안에 수신할 수 있는 양만큼의 물리 버퍼만 확보하면 된다. unpin된 virtual memory page들의 vector를 장치에 제공하고, 장치는 burst window를 유지하는 데 필요한 만큼 요청한다.","LAN device는 PRI를 사용할 수 없고 ATS Translation Request만 써야 한다.","모든 inbound 프레임은 Configuration Space BAR로만 복사해야 한다."],["The device must always pin every page equal to its maximum possible receive bandwidth.","Because the device knows its burst rate, it only needs enough resident buffer for what it can receive in a short interval. It can be given a list of unpinned virtual pages and then request residency as needed to keep that burst window covered.","A LAN device cannot use PRI and must use only ATS Translation Requests.","Every inbound frame must be copied only into a Configuration Space BAR."],1,"이렇게 하면 장치의 필수 메모리 footprint가 줄고 host와의 인터페이스도 단순해지면서, 성능에는 큰 손해를 주지 않을 수 있습니다. pinning이 device 관점에서는 가장 좋은 성능을 주지만, 장치가 건드릴 수 있는 모든 메모리를 상주시키는 일은 host에 부담이 됩니다.","This can shrink the device's required memory footprint and simplify the host interface without a large performance penalty. Pinning still has the best performance from the device's point of view, but guaranteeing residency for everything the device might touch can be costly for the host.","§10.1.2"],["p10q36","p10_4",1,"P","TDISP에서 TSM과 DSM의 역할로 옳은 것은?","In TDISP, what roles do the TEE Security Manager (TSM) and the Device Security Manager (DSM) play?",["DSM이 항상 Requester이고 TSM은 Completion만 생성한다.","TSM과 DSM은 같은 구성 요소의 다른 이름일 뿐이며 역할 구분이 없다.","TSM은 Switch에만, DSM은 Root Port에만 존재한다.","TSM은 Requester이고, DSM은 Responder이다. 각 TDI는 특정 DSM이 관리하며, 그 도메인 안에서 INTERFACE_ID로 식별된다."],["The DSM is always the Requester, and the TSM only generates Completions.","TSM and DSM are just two names for the same component, with no role split.","The TSM exists only in a Switch, and the DSM only in a Root Port.","The TSM is the Requester, and the DSM is the Responder. Each TDI is managed by a specific DSM and is identified within that domain by an INTERFACE_ID."],3,"스펙은 Requester 요구를 TSM에, Responder 요구를 DSM에 두었습니다. host 쪽 TSM이 TDI 생명주기 메시지를 보내고, device 쪽 DSM이 그에 응답하며 TDI 상태 기계를 다룹니다.","The specification states Requester requirements for the TSM and Responder requirements for the DSM. The host-side TSM sends TDI lifecycle messages, and the device-side DSM responds and runs the TDI state machine.","§11.2"],["c10q01","c10_1",1,"C","CXL IDE가 CXL 링크를 지나는 데이터에 제공하는 보호는?","What protection does CXL IDE give data crossing a CXL link?",["링크 대역폭 보장(QoS)","Confidentiality, Integrity, Replay protection","장치 내부에 저장된 key 보호","Denial-of-service 방어"],["Link bandwidth guarantees (QoS)","Confidentiality, integrity, and replay protection","Protection of keys stored inside the device","Denial-of-service defense"],1,"IDE는 PCIe IDE처럼 링크 위 데이터의 기밀성, 무결성, replay 방지를 제공해요. DoS 방어와 장치 내부 key 보호는 범위 밖이에요.","Like PCIe IDE, it provides confidentiality, integrity, and replay protection on the link. DoS defense and on-device key protection are out of scope.","§11.1"],["c10q02","c10_1",2,"X","Host와 Endpoint 사이에 CXL switch가 있을 때, CXL.cachemem IDE 관점에서 그 switch는?","With a CXL switch between Host and Endpoint, how does CXL.cachemem IDE treat that switch?",["IDE를 지원해야 하고, TCB 안에 들어간다 (point-to-point 보호이므로)","switch가 있으면 CXL.cachemem IDE를 쓸 수 없다","switch를 투명하게 통과하는 end-to-end 보호라 switch는 TCB 밖이다","switch는 key 없이 암호문을 forwarding만 한다"],["It must support IDE and is inside the TCB, because protection is point-to-point","CXL.cachemem IDE cannot be used with a switch","Protection is end-to-end through the switch, so the switch is outside the TCB","The switch only forwards ciphertext without keys"],0,"CXL.cachemem IDE는 링크마다(point-to-point) 보호해요. 경로의 switch도 IDE를 지원해야 하고 TCB에 포함돼요.","CXL.cachemem IDE protects each link point to point. A switch on the path must support it and becomes part of the TCB.","§11.1"],["c10q03","c10_2",1,"C","CXL.io IDE는 무엇을 기반으로 정의되나요?","What is CXL.io IDE defined on?",["TSP","PCIe IDE 정의 (key 설정 포함), CXL 스펙은 차이와 제약만 적는다","DMTF PLDM","CXL.cachemem IDE와 같은 flit 단위 체계"],["TSP","The PCIe IDE definition, including key setup; the CXL spec lists only differences and limits","DMTF PLDM","The same flit-based scheme as CXL.cachemem IDE"],1,"CXL.io IDE는 PCIe IDE를 그대로 따르고, key 설정도 PCIe IDE 기반이에요. CXL 스펙은 Table 11-1에 제약과 차이만 정리해요.","CXL.io IDE follows PCIe IDE, including key setup. The CXL spec only lists constraints and differences in Table 11-1.","§11.2"],["c10q04","c10_2",1,"C","PCIe IDE의 stream 종류 중 CXL.io가 지원하는 것은?","Which PCIe IDE stream types does CXL.io support?",["Selective IDE stream만","Link IDE stream과 Selective IDE stream 둘 다","Link IDE stream만","둘 다 지원하지 않고 CXL 전용 stream만 쓴다"],["Only Selective IDE streams","Both Link IDE and Selective IDE streams","Only Link IDE streams","Neither; only a CXL-specific stream"],1,"Table 11-1에서 Link IDE stream과 Selective IDE stream 모두 Supported예요. Aggregation과 PCRC도 지원돼요.","Table 11-1 marks both Link IDE and Selective IDE streams as supported, along with aggregation and PCRC.","§11.2"],["c10q05","c10_2",1,"X","Selective IDE stream은 CXL의 어떤 트래픽에 적용되나요?","To which CXL traffic does a Selective IDE stream apply?",["ARB/MUX ALMP에만","CXL.io, CXL.cache, CXL.mem 모두","CXL.io에만","CXL.cache와 CXL.mem에만"],["Only ARB/MUX ALMPs","All of CXL.io, CXL.cache, and CXL.mem","Only CXL.io","Only CXL.cache and CXL.mem"],2,"Selective IDE stream은 CXL.io 전용이에요. CXL.cachemem은 링크 단위의 자체 IDE를 써요.","Selective IDE streams are CXL.io-only. CXL.cachemem uses its own per-link IDE.","§11.2"],["c10q06","c10_2",2,"X","PCIe IDE의 reserved sub-stream encoding 중 CXL.cachemem용으로 할당된 값은?","Which reserved PCIe IDE sub-stream encoding is assigned to CXL.cachemem?",["1000b","1111b","0111b","0000b"],["1000b","1111b","0111b","0000b"],0,"1000b가 CXL.cachemem에 할당됐어요. 이 값은 CXL.cachemem IV의 고정 필드 상위 bit에도 들어가요.","1000b is assigned to CXL.cachemem, and it also appears in the top bits of the fixed field of the CXL.cachemem IV.","§11.2"],["c10q07","c10_3",1,"C","CXL.cachemem IDE가 쓰는 암호 알고리즘과 key 길이는? (PCIe IDE와 같아요)","What cipher and key size does CXL.cachemem IDE use? (Same as PCIe IDE.)",["ChaCha20-Poly1305, 256-bit key","AES-CBC, 128-bit key","AES-XTS, 512-bit key","AES-GCM, 256-bit key"],["ChaCha20-Poly1305 with a 256-bit key","AES-CBC with a 128-bit key","AES-XTS with a 512-bit key","AES-GCM with a 256-bit key"],3,"기밀성, 무결성, replay 보호에 AES-GCM 256-bit key를 써요(NIST SP 800-38D). PCIe IDE도 AES-GCM 256을 써요.","It uses AES-GCM with a 256-bit key (NIST SP 800-38D) for confidentiality, integrity, and replay protection. PCIe IDE uses AES-GCM 256 too.","§11.3"],["c10q08","c10_3",2,"X","PCIe IDE는 TLP 단위로 보호해요. CXL.cachemem IDE는 어떤 단위로 동작하나요?","PCIe IDE protects per TLP. At what granularity does CXL.cachemem IDE work?",["4KB page 단위","cacheline 하나마다 MAC 하나","TLP 단위","flit 단위, 여러 flit을 MAC epoch로 묶어 MAC 하나를 계산"],["Per 4KB page","One MAC per cacheline","Per TLP","Per flit, with several flits grouped into a MAC epoch under one MAC"],3,"CXL.cachemem에는 TLP가 없어서 flit 단위로 암호화해요. MAC은 Aggregation Flit Count만큼의 flit 묶음(MAC epoch)마다 하나예요.","CXL.cachemem has no TLPs, so it encrypts per flit. One MAC covers a MAC epoch, a group of flits sized by the Aggregation Flit Count.","§11.3.1"],["c10q09","c10_3",2,"X","CXL.cachemem IDE의 MAC 길이는?","How long is the CXL.cachemem IDE MAC?",["128 bit","64 bit","96 bit","256 bit"],["128 bits","64 bits","96 bits","256 bits"],2,"MAC(authentication tag)은 96 bit예요. 68B Flit mode에서는 Slot 0의 H6 header에 실리고, MAC 자체는 암호화되지 않아요.","The MAC (authentication tag) is 96 bits. In 68B Flit mode it rides in a Slot 0 H6 header, and the MAC itself is not encrypted.","§11.3.1"],["c10q10","c10_3",2,"X","CXL.cachemem IDE에서 Link CRC와 복호화의 순서는?","In CXL.cachemem IDE, what is the order of Link CRC and decryption?",["CRC는 암호화된 flit 위에서 계산하고, 수신 측은 retry를 먼저 끝낸 뒤 CRC를 통과한 flit만 복호화하고 무결성을 검사한다","복호화가 실패하면 link retry로 다시 받는다","CRC는 평문 위에서 계산하고 복호화 뒤에 검사한다","IDE가 켜지면 Link CRC를 쓰지 않는다"],["CRC is computed over the encrypted flit; the receiver finishes retries first, then decrypts and checks only flits that passed CRC","A decryption failure is recovered by link retry","CRC is computed over plaintext and checked after decryption","Link CRC is not used once IDE is on"],0,"링크 오류 복구는 암호와 분리돼요. CRC는 암호문 위에 있고, retry가 먼저 끝난 뒤 통과한 flit만 복호화해요. IDE는 CRC 처리나 retry flow를 바꾸지 않아요.","Link error recovery is kept apart from crypto. CRC covers ciphertext, retries finish first, and only good flits are decrypted. IDE does not change CRC handling or the retry flow.","§11.3"],["c10q11","c10_3",3,"X","CXL.cachemem IDE의 Default IV Construction에 대한 설명으로 맞는 것은?","Which statement about the CXL.cachemem IDE Default IV Construction is correct?",["96-bit IV 중 하위 64-bit invocation field는 1에서 시작해 IV를 쓸 때마다 증가하고, 송신과 수신 key는 달라야 한다","invocation field는 0에서 시작하고 rollover를 반드시 감지해야 한다","송신과 수신에 같은 key를 쓴다","IV는 매번 난수로 만든다"],["In the 96-bit IV, the low 64-bit invocation field starts at 1 and increments per use, and Tx and Rx keys must differ","The invocation field starts at 0 and rollover must be detected","Tx and Rx use the same key","The IV is random every time"],0,"상위 고정 필드에는 sub-stream 1000b가 있고, 하위 64-bit는 1부터 세는 counter예요. 64-bit라 rollover 감지는 필요 없어요. 송수신 key는 서로 달라야 해요.","The fixed upper field holds sub-stream 1000b, and the low 64 bits are a counter starting at 1. With 64 bits, rollover detection is not required. Tx and Rx keys must be distinct.","§11.3.4"],["c10q12","c10_4",1,"X","CXL.cachemem IDE에서 모든 장치가 지원해야 하는 mode는?","Which CXL.cachemem IDE mode must every device support?",["둘 다 optional","Containment와 Skid 둘 다","Containment mode","Skid mode"],["Both are optional","Both Containment and Skid","Containment mode","Skid mode"],2,"Containment mode는 필수 지원이고, Skid mode는 선택이에요.","Containment mode is mandatory; Skid mode is optional.","§11.3.5.1"],["c10q13","c10_4",2,"X","Skid mode의 특징으로 맞는 것은?","Which describes Skid mode?",["무결성 검사 전에 데이터를 먼저 내보내 지연이 거의 없지만, 변조된 데이터가 잠시 쓰일 수 있고 나중에 검출된다","무결성 검사를 통과한 뒤에만 데이터를 내보낸다","MAC을 아예 보내지 않는다","모든 장치가 반드시 지원해야 한다"],["Data is released before the integrity check for near-zero latency; tampered data may be used briefly and is caught later","Data is released only after the integrity check passes","No MAC is ever sent","Every device must support it"],0,"Skid는 지연과 대역폭 부담이 작지만, 짧은 시간 창 안에서 변조 데이터가 소비될 수 있어요. 그래서 SW가 그 창을 견뎌야 해요.","Skid has low latency and bandwidth cost, but tampered data may be consumed within a short window, so software must tolerate that window.","§11.3.5"],["c10q14","c10_4",3,"X","256B Flit mode에서 Containment mode를 쓸 때 Aggregation Flit Count는?","What is the Aggregation Flit Count for Containment mode in 256B Flit mode?",["32","128","5","2"],["32","128","5","2"],3,"Containment는 68B에서 5, 256B에서 2예요. Skid는 68B에서 128, 256B에서 32예요.","Containment uses 5 in 68B mode and 2 in 256B mode. Skid uses 128 in 68B and 32 in 256B.","§11.3.5"],["c10q15","c10_4",2,"X","현재 MAC epoch의 flit 수가 Aggregation Flit Count보다 적을 때 (예: link가 idle로 가려 할 때) 송신 측은?","The current MAC epoch has fewer flits than the Aggregation Flit Count, for example as the link goes idle. What can the transmitter do?",["epoch를 일찍 끝내고 IDE.TMAC(Truncated MAC) control flit으로 MAC을 보낸다","IDE를 끄고 다시 켠다","빈 protocol flit을 채워 epoch를 채운다","MAC 없이 다음 epoch로 넘긴다"],["End the epoch early and send its MAC in an IDE.TMAC (Truncated MAC) control flit","Turn IDE off and on again","Pad with empty protocol flits to fill the epoch","Move on to the next epoch with no MAC"],0,"Early MAC termination이에요. flit 수가 AFC보다 적을 때만 허용되고, MAC은 IDE.TMAC flit 하나로 따로 보내요.","This is early MAC termination. It is allowed only when the flit count is below the AFC, and the MAC is sent alone in an IDE.TMAC flit.","§11.3.6"],["c10q16","c10_5",2,"X","CXL_K_SET_GO를 받은 송신 측이 새 key로 전환하는 절차는?","After receiving CXL_K_SET_GO, how does a transmitter switch to the new key?",["IDE.Stop을 보내고 새 key를 쓴다","바로 다음 flit부터 아무 표시 없이 새 key를 쓴다","링크를 reset한 뒤 새 key를 쓴다","IDE.Start control flit을 보내고, Tx Key Refresh Time만큼 IDE.Idle flit을 보낸 뒤 새 key로 protocol flit을 보낸다"],["Send IDE.Stop, then use the new key","Use the new key from the next flit with no marker","Reset the link, then use the new key","Send an IDE.Start control flit, then IDE.Idle flits for the Tx Key Refresh Time, then protocol flits under the new key"],3,"프로그래밍된 key는 pending 상태로 있다가 IDE.Start로 활성화돼요. IDE.Idle 구간은 수신 측이 새 key를 준비할 시간이에요.","Programmed keys wait as pending until IDE.Start activates them. The IDE.Idle period gives the receiver time to prepare for the new key.","§11.3.7"],["c10q17","c10_5",3,"X","수신 측이 MAC epoch 중간에 IDE.Start를 받으면?","What happens if the receiver gets IDE.Start in the middle of a MAC epoch?",["즉시 새 key로 바꾼다","epoch를 둘로 나눠 각각 다른 key로 검사한다","IDE.Start를 버린다 (Establishment Security error를 기록하고 Insecure로 갈 수도 있다)","link retry를 요청한다"],["It switches to the new key at once","It splits the epoch and checks each half with a different key","It drops the IDE.Start, and may log an Establishment Security error and go Insecure","It requests a link retry"],2,"한 MAC epoch에는 key 하나만 써야 해요(AES-GCM 요구). 그래서 송신 측은 epoch 중간에 IDE.Start를 보내면 안 되고, 받으면 수신 측이 버려요.","A MAC epoch must use a single key, as AES-GCM requires. So the transmitter must not send IDE.Start mid-epoch, and the receiver drops one if it arrives.","§11.3.7"],["c10q18","c10_5",1,"X","CXL.cachemem IDE stream이 Insecure state가 되면?","What happens when a CXL.cachemem IDE stream enters the Insecure state?",["버퍼된 protocol flit과 이후 protocol 트래픽이 link reset 전까지 모두 버려진다","평문으로 계속 통신한다","CXL.io만 끊기고 CXL.cachemem은 계속된다","다음 MAC epoch에서 자동 복구된다"],["Buffered protocol flits and all later protocol traffic are dropped until the link is reset","Traffic continues in plaintext","Only CXL.io is cut and CXL.cachemem continues","It recovers automatically at the next MAC epoch"],0,"무결성 실패 같은 오류로 Insecure가 되면 보안 트래픽을 모두 버려요. 복구에는 link reset이 필요하고, key나 데이터가 새지 않게 막아야 해요.","Errors such as an integrity failure send the stream Insecure, and all secure traffic is dropped. Recovery needs a link reset, and keys and data must not leak.","§11.3.8"],["c10q19","c10_6",1,"X","CIKMA는 무엇인가요?","What is the CIKMA?",["링크 양 끝 port에 CXL.cachemem IDE key, Initial IV, 설정을 맞춰 넣는 SW/FW 주체","TSP의 target 장치","PCIe IDE의 Selective stream 이름","장치 안의 암호 엔진"],["The software/firmware entity that programs matching CXL.cachemem IDE keys, initial IV, and settings into both link ports","The target device in TSP","The name of a PCIe IDE selective stream","The crypto engine inside a device"],0,"CIKMA는 CXL.cachemem IDE Key Management Agent예요. partner port(RP-USP, RP-EP, DSP-EP)에 key를 프로그래밍하는 SW/FW예요.","CIKMA is the CXL.cachemem IDE Key Management Agent, the SW/FW that programs keys into partner ports (RP-USP, RP-EP, or DSP-EP).","§11.4"],["c10q20","c10_6",2,"X","CXL_IDE_KM 메시지는 어떤 형식으로 전달되나요?","In what form are CXL_IDE_KM messages carried?",["PCIe Configuration Write로만 전달된다","SPDM vendor-defined request/response로, CIKMA가 만든 SPDM secure session으로 보호된다","IDE.Start flit 안에 key를 실어 보낸다","CXL.mem MemWr로 평문 전달된다"],["Only via PCIe configuration writes","As SPDM vendor-defined requests/responses, protected by an SPDM secure session set up by the CIKMA","With the key carried inside the IDE.Start flit","In plaintext via CXL.mem MemWr"],1,"CIKMA는 먼저 DOE나 MCTP로 SPDM secure session을 만들고, 그 세션으로 CXL_IDE_KM 메시지(CXL_QUERY, CXL_KEY_PROG, CXL_K_SET_GO 등)를 보내요.","The CIKMA first sets up an SPDM secure session over DOE or MCTP, then sends CXL_IDE_KM messages such as CXL_QUERY, CXL_KEY_PROG, and CXL_K_SET_GO through it.","§11.4.1"],["c10q21","c10_6",3,"X","multi-VCS switch에서 어느 한 root port라도 CXL IDE를 켜면, IDE를 지원하는 MLD로 가는 switch 하류 링크는?","In a multi-VCS switch, once any root port enables CXL IDE, what about the downstream link to an IDE-capable MLD?",["MLD 링크에는 IDE를 쓸 수 없다","Link IDE를 켜야 한다 (IDE를 켜지 않은 root port의 트래픽도 switch-장치 구간은 보호된다)","IDE를 켠 root port의 트래픽만 암호화한다","root port 모두가 IDE를 켤 때까지 끈 채로 둔다"],["IDE cannot be used on MLD links","It must have Link IDE enabled, so even traffic from a root port without IDE is protected between switch and device","Only traffic from the IDE-enabled root port is encrypted","It stays off until every root port enables IDE"],1,"MLD 링크는 여러 VCS가 공유하는 링크 하나라서, 한 root port가 IDE를 켜면 그 링크 전체에 Link IDE를 켜야 해요.","The MLD link is one link shared by several VCSs, so once any root port enables IDE, Link IDE must be on for the whole link.","§11.3.9"],["c10q22","c10_6",3,"X","CXL.cachemem IDE에서 in-band LLCTRL Poison 메시지를 무결성 보호하는 이유와 방법은?","Why and how does CXL.cachemem IDE integrity-protect the in-band LLCTRL Poison message?",["injection을 막으려고 payload를 암호화한다","LLCTRL 메시지는 보호하지 않는다","삭제나 변조되면 poison돼야 할 데이터가 조용히 쓰일 수 있어서, 그 payload를 AAD로 무결성 계산에 넣는다","Poison 메시지에 별도 MAC을 붙인다"],["Its payload is encrypted to block injection","LLCTRL messages are never protected","Deleting or altering it could let data that should be poisoned be used silently, so its payload is added to the integrity calculation as AAD","A separate MAC is attached to each Poison message"],2,"IDE는 보통 LLCTRL 메시지를 보호하지 않아요. Poison 메시지는 예외라서 payload를 AAD로 다음 protocol flit 계산에 넣어요. injection은 가용성 문제일 뿐이라 큰 위협으로 보지 않아요.","IDE normally leaves LLCTRL messages unprotected. Poison is the exception: its payload joins the next protocol flit's calculation as AAD. Injection only hurts availability, so it is not the main concern.","§11.3.11"],["c10q23","c10_7",1,"X","CXL TSP의 목적으로 맞는 것은?","What is the purpose of CXL TSP?",["PCIe TDISP를 대체한다","직접 연결된 CXL 메모리 장치를 TVM의 trust boundary 안에 넣어 confidential computing을 지원한다 (PCI-SIG TDISP를 보완)","링크 위 트래픽을 암호화하는 CXL.cachemem IDE의 다른 이름이다","switch 뒤 MLD를 여러 host가 안전하게 공유하게 한다"],["To replace PCIe TDISP","To bring directly attached CXL memory devices inside the TVM trust boundary for confidential computing, complementing PCI-SIG TDISP","It is another name for CXL.cachemem IDE link encryption","To let many hosts safely share an MLD behind a switch"],1,"IDE는 링크를 지나는 트래픽을 보호하고, TSP는 장치 메모리를 TEE 경계에 넣는 프로토콜이에요. TSP는 TDISP를 대체하지 않고 보완해요.","IDE protects traffic on the link; TSP brings device memory inside the TEE boundary. TSP complements TDISP rather than replacing it.","§11.5.1"],["c10q24","c10_7",2,"X","다음 중 TSP 범위에 포함되는 것은?","Which of these is within TSP scope?",["68B flit format","CXL switch 뒤에 연결된 장치(MLD, GFD 포함)","Memory pooling (여러 initiator가 같은 장치 메모리를 쓰되 동시에 공유하지는 않음)","Memory sharing (여러 initiator가 동시에 공유)"],["68B flit format","Devices behind a CXL switch, including MLDs and GFDs","Memory pooling (multiple initiators use one device's memory without sharing it concurrently)","Memory sharing (multiple initiators sharing concurrently)"],2,"TSP 범위에는 pooling, HDM-H, HDM-DB, DCD, 256B·PBR flit이 들어가요. sharing, 68B, switch 경유 장치, HDM-D는 빠져요.","TSP covers pooling, HDM-H, HDM-DB, DCDs, and 256B/PBR flits. It excludes sharing, 68B, devices behind switches, and HDM-D.","§11.5.2"],["c10q25","c10_8",1,"X","TE State에 따른 접근 규칙으로 맞는 것은?","Which access rule follows from TE State?",["TE State는 링크 IDE key를 고르는 값이다","TEE는 exclusive와 non-exclusive 메모리 모두 접근할 수 있고, non-TEE는 TEE 전용이 아닌 메모리만 접근할 수 있다","non-TEE도 TEE 전용 메모리를 읽을 수 있다","TEE는 TEE 전용 메모리만 접근할 수 있다"],["TE State selects the link IDE key","TEEs may access exclusive and non-exclusive memory; non-TEE entities only memory not reserved for a TEE","Non-TEE entities may also read TEE-exclusive memory","TEEs may access only TEE-exclusive memory"],1,"TE State는 메모리 내용이 TEE용인지 표시해요. initiator는 요청마다 TEE Intent를 TEE용 M2S opcode로 표현하고, target은 이를 TE State와 비교해요.","TE State marks whether memory holds TEE data. Initiators express TEE Intent per request with TEE-specific M2S opcodes, and the target checks it against TE State.","§11.5.4.5"],["c10q26","c10_8",1,"X","TSP에서 Transport Security(링크 보호)는?","In TSP, what is the status of Transport Security (link protection)?",["TSP에서는 IDE를 쓸 수 없다","항상 필수다","TSP 전용 새 암호 링크 프로토콜을 쓴다","optional이며, 켜면 CXL-approved IDE(현재는 hop-by-hop CXL IDE)를 써야 한다"],["IDE cannot be used with TSP","Always mandatory","A new TSP-only link cipher protocol is used","Optional; when enabled, a CXL-approved IDE must be used, currently hop-by-hop CXL IDE"],3,"Transport Security는 optional이지만, 꺼 두면 장치 탈착이나 중간자 공격에 더 노출돼요. 켜려면 CXL IDE를 써요.","Transport Security is optional, but leaving it off adds exposure to device removal and man-in-the-middle attacks. When used, it is CXL IDE.","§11.5.4.7"],["c10q27","c10_8",3,"X","TSP의 target-based memory encryption에 대한 설명으로 맞는 것은?","Which statement about target-based memory encryption in TSP is correct?",["CKID-based와 Range-based를 동시에 켜야 한다","Range-based는 transaction의 CKID field를 쓴다","CKID-based와 Range-based 두 방식이 있고, Host는 둘 중 하나만 켤 수 있으며 target은 둘 다 켜려는 시도를 거부한다","target은 반드시 memory encryption을 구현해야 한다"],["CKID-based and Range-based must be enabled together","Range-based uses the transaction's CKID field","There are CKID-based and Range-based methods; the Host may enable only one, and the target rejects enabling both","Targets must implement memory encryption"],2,"target 쪽 암호화는 optional이에요. CKID-based는 transaction의 CKID로 key를 고르고, Range-based는 주소 범위 register로 key를 정해요. 둘을 같이 켤 수 없어요.","Target-side encryption is optional. CKID-based picks the key from the transaction's CKID; Range-based ties keys to address-range registers. The two cannot be enabled together.","§11.5.4.6.2"],["c10q28","c10_9",1,"X","PCIe SR-IOV와 비교한 CXL MLD의 특징으로 맞는 것은?","Compared with PCIe SR-IOV, which describes a CXL MLD?",["LD는 Routing ID로만 구분되고 LD-ID는 없다","LD 수는 PF의 SR-IOV Capability(NumVFs)로 정한다","MLD는 SR-IOV VF를 CXL에서 부르는 다른 이름이다","FM이 각 LD를 서로 다른 VCS(다른 host)에 bind할 수 있다"],["LDs are told apart only by Routing ID; there is no LD-ID","The LD count is set through the PF's SR-IOV capability (NumVFs)","An MLD is just CXL's name for SR-IOV VFs","The FM can bind each LD to a different VCS, and so to a different host"],3,"SR-IOV는 한 PF 아래 VF를 만드는 PCIe 기능이에요. MLD는 Type 3 장치를 LD로 나누고, FM이 MLD DSP를 통해 각 LD를 최대 16개 host(VCS)에 bind해요.","SR-IOV is a PCIe feature that creates VFs under one PF. An MLD splits a Type 3 device into LDs, and the FM binds each LD through the MLD DSP to up to 16 hosts (VCSs).","§2.4, §7.1.3"],["c10q29","c10_9",2,"X","MLD에서 각 LD로 가는 요청과 응답은 무엇으로 구분하나요?","In an MLD, what identifies requests and responses for each LD?",["SR-IOV VF Routing ID만","PCIe Bus Number","PBR의 12-bit PID만","LD-ID (CXL.io는 Vendor Defined Local TLP Prefix로, CXL.mem은 header 필드로 나름)"],["Only SR-IOV VF Routing IDs","The PCIe Bus Number","Only 12-bit PBR PIDs","The LD-ID, carried by a Vendor Defined Local TLP Prefix in CXL.io and by a header field in CXL.mem"],3,"MLD로 가고 오는 모든 요청과 응답에는 LD-ID가 있어야 해요. CXL.io는 VendPrefixL0 TLP Prefix로 16-bit를, CXL.mem은 4-bit를 실어요. software에게 LD-ID는 보이지 않아요.","Every MLD request and response carries an LD-ID: 16 bits in a VendPrefixL0 TLP prefix for CXL.io and 4 bits for CXL.mem. The LD-ID is invisible to software.","§2.4.1"],["c10q30","c10_9",2,"X","SR-IOV에서는 Host SW가 PF를 통해 VF를 설정해요. MLD에서 LD 자원 할당은 누가 하나요?","In SR-IOV, host software configures VFs through the PF. Who allocates LD resources in an MLD?",["PCIe Root Complex가 자동으로 한다","FM이 FMLD와 FM API(예: Set LD Allocations)로 한다, 또는 static하게 미리 정해진다","LD-ID 0의 driver가 한다","LD에 bind된 Host OS가 직접 한다"],["The PCIe Root Complex does it automatically","The FM, through the FMLD and FM API (e.g., Set LD Allocations), or it is configured statically","The driver of LD-ID 0 does it","The Host OS bound to the LD does it directly"],1,"MLD는 FM API로 LD를 구성하거나 static하게 구성할 수 있고, 결과는 MLD DVSEC로 알려져요. MLD DVSEC는 FM만 접근해요.","An MLD's LDs are set up via the FM API or statically, and the result is reported through the MLD DVSEC, which only the FM can access.","§2.4, §7.6.7.4.3"]]};
if (typeof module !== "undefined") module.exports = TOWN_Q;
